async function ensureGeminiAuthProfileMaterialized(
  profileId?: string | null,
  options: { includeMcp?: boolean } = {}
): Promise<void> {
  const bridgeCommandStatus = options.includeMcp ? taskwraithMcpBridgeCommandStatus() : null
  await ensureGeminiAuthProfileMaterializedViaProviderAuth(
    profileId,
    options.includeMcp && bridgeCommandStatus?.available
      ? {
          includeMcp: true,
          mcp: {
            serverName: GEMINI_MCP_SERVER_NAME,
            command: bridgeCommandStatus.command,
            args: taskwraithMcpBridgeArgs(geminiMcpSocketPath()),
            includeTools: [...TASKWRAITH_MCP_TOOLS]
          }
        }
      : options
  )
}

/**
 * Re-instantiate the module-scope BridgeApnsPusher after settings
 * changed. Closes the prior pusher's HTTP/2 sessions cleanly so
 * subsequent pushes use the fresh credentials. ApprovalService picks
 * up the new pusher transparently because it accesses the ref via the
 * `getApnsPusher: () => bridgeApnsPusherRef` getter wired at startup.
 */
function rebuildBridgeApnsPusherFromSettings(): void {
  const prior = bridgeApnsPusherRef as (BridgeApnsPusher & { close?: () => void }) | null
  try {
    prior?.close?.()
  } catch {
    // Idempotent close; ignore.
  }
  bridgeApnsPusherRef = buildBridgeApnsPusherFromSettings()
}

// 1.0.6-CRUX15 — cache the (expensive) SuperGrok PTY usage probe so the
// sidebar GrokCreditsMeter and the Settings Provider-Telemetry card share a
// single real probe instead of each spawning the TUI. Only `observed`
// snapshots are cached; non-observed results fall through to a fresh probe.
let grokUsageProbeCache: { snapshot: GrokUsageSnapshot; fetchedAt: number } | null = null

function updateCliProviderSession(
  state: CliProviderStreamState,
  sessionId: string | null | undefined,
  emitRunStarted = false
): boolean {
  const normalized = typeof sessionId === 'string' ? sessionId.trim() : ''
  if (!normalized || normalized === state.providerSessionId) return false
  const sessionMetadataAuthorized = (): boolean =>
    providerRunPersistenceAuthorized(state.provider, state)
  // Native session ids and MCP-profile receipts are provider output. A late
  // frame from an invalidated run must not mutate either durable chat state or
  // the in-memory resume identity after a destructive history boundary.
  if (!sessionMetadataAuthorized()) return false
  if (
    state.provider === 'claude' &&
    !shouldAcceptTaskWraithMcpSessionId({
      nextProviderSessionId: normalized,
      currentProviderSessionId: state.providerSessionId,
      seenProviderSessionIds: state.taskWraithMcpSeenProviderSessionIds
    })
  ) {
    return false
  }

  if (
    state.provider === 'claude' &&
    (!state.appRunId || shouldPersistProviderSessionForRun(state.appRunId)) &&
    state.taskWraithMcpProfileId &&
    state.taskWraithMcpProfileFence &&
    state.taskWraithMcpProfileFence.storeWritable &&
    state.appChatId
  ) {
    const chat = AppStore.getChat(state.appChatId)
    const participant =
      chat?.ensemble && state.ensembleRun?.participantId
        ? chat.ensemble.participants.find(
            (candidate) => candidate.id === state.ensembleRun?.participantId
          ) || null
        : null
    if (chat?.ensemble && !state.ensembleRun?.participantId) return false
    // An ensemble route that lost its exact participant is stale. Do not let
    // its late session frame attach to the solo chat or another seat.
    if (state.ensembleRun?.participantId && !participant) return false
    if (participant && participant.provider !== state.provider) return false
    if (!participant && chat?.provider && chat.provider !== state.provider) return false
    if (chat) {
      const currentStoreSessionId = participant
        ? (participant.linkedProviderSessionId ?? null)
        : (chat.linkedProviderSessionId ?? null)
      const currentReceipt = participant
        ? participant.taskWraithMcpProfileReceipt
        : chat.taskWraithMcpProfileReceipt
      const transition = transitionTaskWraithMcpProfileReceipt({
        provider: 'claude',
        profileId: state.taskWraithMcpProfileId,
        mcpAdvertised: state.taskWraithMcpAdvertised === true,
        nextProviderSessionId: normalized,
        previousRunProviderSessionId: state.providerSessionId,
        expectedStoreIdentity: {
          providerSessionId: state.taskWraithMcpProfileFence.expectedStoreProviderSessionId,
          receiptFingerprint: state.taskWraithMcpProfileFence.expectedStoreReceiptFingerprint
        },
        currentStoreSessionId,
        currentReceipt
      })
      if (!transition.accepted) return false
      const updated: ChatRecord = participant
        ? {
            ...chat,
            ensemble: {
              ...chat.ensemble!,
              participants: chat.ensemble!.participants.map((candidate) =>
                candidate.id === participant.id
                  ? {
                      ...candidate,
                      linkedProviderSessionId: normalized,
                      ...(transition.receipt
                        ? { taskWraithMcpProfileReceipt: transition.receipt }
                        : { taskWraithMcpProfileReceipt: undefined })
                    }
                  : candidate
              )
            },
            updatedAt: Date.now()
          }
        : {
            ...chat,
            linkedProviderSessionId: normalized,
            taskWraithMcpProfileReceipt: transition.receipt,
            updatedAt: Date.now()
          }
      const persisted = persistAuthorizedProviderSessionMetadata({
        isAuthorized: sessionMetadataAuthorized,
        readCurrent: () => updated,
        buildUpdate: (candidate) => candidate,
        saveAndPublish: saveAndBroadcastChat
      })
      if (!persisted) return false
      const nextIdentity = taskWraithMcpProfileStoreIdentity({
        providerSessionId: normalized,
        receipt: transition.receipt
      })
      state.taskWraithMcpProfileFence = {
        ...state.taskWraithMcpProfileFence,
        expectedStoreProviderSessionId: nextIdentity.providerSessionId,
        expectedStoreReceiptFingerprint: nextIdentity.receiptFingerprint
      }
    }
  }

  state.taskWraithMcpSeenProviderSessionIds ??= new Set<string>()
  state.taskWraithMcpSeenProviderSessionIds.add(normalized)
  state.providerSessionId = normalized
  if (state.appRunId) {
    runManager.registerProviderSession(state.appRunId, normalized)
    runManager.setState(state.appRunId, state)
  }
  if (emitRunStarted) {
    sendAgentCompatLine(
      state.sender,
      state.provider,
      {
        type: 'init',
        session_id: normalized,
        model: state.model,
        timestamp: new Date().toISOString(),
        provider: state.provider,
        fallback: state.fallback
      },
      state
    )
  }
  return true
}

/** Persist the fact that this Kimi seat was born under the current durable ACP
 * containment generation. The exact posture marker gates session/resume; the
 * legacy boolean remains decode/UI compatibility only. */
function persistKimiAcpNativeSession(state: CliProviderStreamState, sessionId: string): void {
  if (!state.appChatId || !sessionId) return
  const sessionMetadataAuthorized = (): boolean => providerRunPersistenceAuthorized('kimi', state)
  if (!sessionMetadataAuthorized()) return
  if (executionGraphOwnsAttemptRunId(state.appRunId)) return
  if (state.appRunId && !shouldPersistProviderSessionForRun(state.appRunId)) return
  const participantId = state.ensembleRun?.participantId
  const target = providerSeatStoreTarget(state.appChatId, 'kimi', participantId)
  if (!target) return
  const { chat } = target
  const updated: ChatRecord = participantId
    ? {
        ...chat,
        ensemble: {
          ...chat.ensemble!,
          participants: chat.ensemble!.participants.map((participant) =>
            participant.id === participantId
              ? {
                  ...participant,
                  linkedProviderSessionId: sessionId,
                  kimiAcpNativeSession: true,
                  kimiAcpPostureVersion: KIMI_ACP_PRODUCTION_POSTURE_VERSION
                }
              : participant
          )
        },
        updatedAt: Date.now()
      }
    : {
        ...chat,
        linkedProviderSessionId: sessionId,
        providerMetadata: {
          ...(chat.providerMetadata || {}),
          kimiAcpNativeSession: true,
          kimiAcpPostureVersion: KIMI_ACP_PRODUCTION_POSTURE_VERSION
        },
        updatedAt: Date.now()
      }
  persistAuthorizedProviderSessionMetadata({
    isAuthorized: sessionMetadataAuthorized,
    readCurrent: () => updated,
    buildUpdate: (candidate) => candidate,
    saveAndPublish: saveAndBroadcastChat
  })
}

function claudeProgrammaticUsageWarning(
  runtime: 'sdk' | 'cli-print',
  usesApiKey: boolean
): string | null {
  const runtimeLabel =
    runtime === 'sdk' ? 'Claude Agent SDK' : 'Claude Code CLI print mode (`claude -p`)'
  if (!usesApiKey) return null
  return `${runtimeLabel} is using the saved Anthropic API key for this run, so usage is billed through API/PAYG rather than the Claude Code login session.`
}

// Recover a single tool-call identifier from a bridge tool payload, regardless
// of which field the provider populates. A `ToolCall` notification keys it `id`;
// the matching `ToolResult` echoes it under `tool_call_id` (and some shapes use
// `call_id` / `tool_id`). Resolving both branches through the SAME ordered
// lookup guarantees the call and its result share one id, so the renderer
// coalesces them into one inline card instead of stacking each event. Mirrors
// the multi-field lookup Grok's mapper already uses (GrokStreamingJson). Falls
// back to a unique generated id only when no identifier is present at all (which
// keeps two genuinely id-less calls from merging).

function providerEventIsToolResultLike(event: unknown): boolean {
  if (!isRecord(event)) return false
  const params = nestedRecord(event, 'params')
  const directType = String(event.type || event.method || params.type || '').toLowerCase()
  if (
    directType === 'tool_result' ||
    directType === 'tool_output' ||
    directType === 'tool_response' ||
    directType === 'toolresult'
  ) {
    return true
  }
  const message = nestedRecord(event, 'message')
  const contentItems = Array.isArray(message.content)
    ? message.content
    : Array.isArray(event.content)
      ? event.content
      : []
  return contentItems.some(
    (item) => isRecord(item) && String(item.type || '').toLowerCase() === 'tool_result'
  )
}

function emitCliProviderMediaRefs(state: CliProviderStreamState, event: unknown): void {
  if (providerEventIsToolResultLike(event)) return
  const blocks = extractProviderImageBlocksFromRawEvent(event)
  if (blocks.length === 0) return
  const store = getTranscriptMediaAssetStore()
  const refs = persistAuthorizedProviderMedia({
    isAuthorized: () => providerRunPersistenceAuthorized(state.provider, state),
    persist: () =>
      createOwnedToolResultMediaRefs({
        store,
        appChatId: state.appChatId,
        messageId: state.appRunId || state.runId || `${state.provider}-${state.startedAt}`,
        runId: state.appRunId || state.runId || undefined,
        toolName: `${state.provider} output`,
        source: 'generated',
        blocks
      }),
    revokeOnLostAuthority: async () => {
      const chatIds = [state.appChatId].filter((id): id is string => Boolean(id))
      if (chatIds.length > 0) await store.revokeChatOwnershipStrict(chatIds)
    }
  })
  if (refs.length === 0) return
  const seen = state.providerMediaRefKeys ?? new Set<string>()
  state.providerMediaRefKeys = seen
  const fresh = refs.filter((ref) => {
    const key = ref.sha256 || ref.assetId || ref.id
    if (!key || seen.has(key)) return false
    seen.add(key)
    return true
  })
  if (fresh.length === 0) return
  sendAgentCompatLine(
    state.sender,
    state.provider,
    {
      type: 'media_refs',
      mediaRefs: fresh,
      provider: state.provider
    },
    state
  )
}

function emitCliProviderToolEvent(state: CliProviderStreamState, event: unknown): void {
  if (!isRecord(event)) return
  const params = nestedRecord(event, 'params')
  const payload = isRecord(params.payload)
    ? params.payload
    : isRecord(event.payload)
      ? event.payload
      : {}
  const message = nestedRecord(event, 'message')
  const contentItems = Array.isArray(message.content)
    ? message.content
    : Array.isArray(event.content)
      ? event.content
      : []

  for (const item of contentItems) {
    if (!isRecord(item)) continue
    if (item.type === 'tool_use') {
      sendAgentCompatLine(
        state.sender,
        state.provider,
        {
          type: 'tool_use',
          tool_id: typeof item.id === 'string' ? item.id : `tool-${Date.now()}`,
          tool_name: typeof item.name === 'string' ? item.name : 'tool',
          parameters: isRecord(item.input) ? item.input : {},
          provider: state.provider
        },
        state
      )
    }
    if (item.type === 'tool_result') {
      sendAgentCompatLine(
        state.sender,
        state.provider,
        {
          type: 'tool_result',
          tool_id: typeof item.tool_use_id === 'string' ? item.tool_use_id : `tool-${Date.now()}`,
          status: item.is_error ? 'error' : 'success',
          output: contentPartsToText(item.content || item),
          provider: state.provider
        },
        state
      )
    }
  }

  if (event.method === 'event' && params.type === 'ToolCall') {
    const toolFunction = nestedRecord(payload, 'function')
    // Kimi tool calls must COALESCE with their matching ToolResult into one
    // inline card (the way Codex/Claude/Grok do). The renderer pairs a result
    // back to its call by `tool_id`, so the call and the result MUST resolve to
    // the SAME stable id. Kimi keys the call identifier as `id` here, but the
    // result echoes it under `tool_call_id` (see the ToolResult branch + the
    // wire-protocol approval echo in ApprovalService, `request_id: payload.id`).
    // Mirror Grok's multi-field id lookup (GrokStreamingJson) so the same value
    // is recovered regardless of which field Kimi populates on each side.
    const toolCallId = cliProviderToolId(payload, 'tool')
    // Moonshot/OpenAI function-calling sends `function.arguments` as a
    // JSON-ENCODED STRING, so the old `isRecord(...)` check dropped them to `{}`
    // — that's why the card never showed the target filename. normalizeMcpTool-
    // Arguments parses the string (or passes an object through) so ToolParser
    // can surface `file_path`/`path` in the card label.
    const rawToolArgs = toolFunction.arguments ?? payload.arguments
    sendAgentCompatLine(
      state.sender,
      state.provider,
      {
        type: 'tool_use',
        tool_id: toolCallId,
        tool_name:
          typeof toolFunction.name === 'string'
            ? toolFunction.name
            : typeof payload.name === 'string'
              ? payload.name
              : 'tool',
        parameters: normalizeMcpToolArguments(rawToolArgs),
        provider: state.provider
      },
      state
    )
  }

  if (event.method === 'event' && params.type === 'ToolResult') {
    const returnValue = nestedRecord(payload, 'return_value')
    // Same stable-id resolution as the ToolCall branch above so the result
    // pairs back to its call card instead of stacking as a fresh orphan.
    const toolResultId = cliProviderToolId(payload, 'tool')
    sendAgentCompatLine(
      state.sender,
      state.provider,
      {
        type: 'tool_result',
        tool_id: toolResultId,
        status: returnValue.is_error ? 'error' : 'success',
        output: contentPartsToText(returnValue.output || returnValue.message || ''),
        provider: state.provider
      },
      state
    )
  }

  if (event.method === 'event' && params.type === 'PlanDisplay') {
    sendAgentCompatLine(
      state.sender,
      state.provider,
      {
        type: 'tool_use',
        tool_id: typeof payload.id === 'string' ? payload.id : `plan-${Date.now()}`,
        tool_name: `${state.provider}_plan`,
        parameters: { title: 'Plan', kind: 'plan' },
        provider: state.provider
      },
      state
    )
    sendAgentCompatLine(
      state.sender,
      state.provider,
      {
        type: 'tool_result',
        tool_id: typeof payload.id === 'string' ? payload.id : `plan-${Date.now()}`,
        status: 'success',
        output: contentPartsToText(payload.content || payload.plan || payload),
        provider: state.provider
      },
      state
    )
  }
}

function emitCliProviderThinkingEvent(
  state: CliProviderStreamState,
  text: string,
  options: { cumulative?: boolean } = {}
) {
  // Chronological segmentation (1.0.7): thinking is emitted as a SEQUENCE of
  // trace activities. When transcript-visible output (assistant text, tool
  // calls, progress cards…) landed since the last chunk — marked on the state
  // by sendAgentCompatLine — the next chunk opens a fresh activity with a
  // per-segment id, so late reasoning renders at its true transcript position
  // instead of growing the turn's first trace card in place.
  const advance = advanceCliProviderThinkingSegments(state, text, options)
  if (!advance) return
  const toolId = cliProviderThinkingSegmentToolId(
    state.provider,
    state.appRunId,
    advance.segmentSeq
  )
  if (advance.startedNewActivity) {
    sendAgentCompatLine(
      state.sender,
      state.provider,
      {
        type: 'tool_use',
        tool_id: toolId,
        tool_name: `${state.provider}_thinking`,
        parameters: { title: `${providerLabel(state.provider)} thinking`, kind: 'reasoning' },
        provider: state.provider
      },
      state
    )
  }
  sendAgentCompatLine(
    state.sender,
    state.provider,
    {
      type: 'tool_result',
      tool_id: toolId,
      tool_name: `${state.provider}_thinking`,
      status: 'success',
      output: advance.text,
      provider: state.provider
    },
    state
  )
}

// 1.0.6-G3g — Grok's streaming-json is its own shape (`{type,data}` tokens +
// a terminal `{type:'end',sessionId}`), parsed by the unit-tested
// src/main/grok/GrokStreamingJson.ts mapper. Translate each normalized event
// onto the existing CLI run-event sink (content → assistant text, thought →
// the shared thinking trace, end → captured session id for resume).
// Map one normalized Grok run event onto the existing CLI run-event sink.
// Shared by the headless (G3) and ACP (G4) paths. The `result` event is
// intentionally NOT emitted here — each path synthesizes the canonical result
// + exit on process close.
// Fallback tool-id counter for Grok tool events that arrive without an id —
// keeps each tool card distinct (so two id-less calls don't merge into one).
let grokFallbackToolSeq = 0
const grokCanvasEvalDiagnosticSanitizers = new WeakMap<
  CliProviderStreamState,
  ReturnType<typeof createCanvasEvalCompatSanitizer>
>()

function grokCanvasEvalDiagnosticSanitizer(state: CliProviderStreamState) {
  let sanitizer = grokCanvasEvalDiagnosticSanitizers.get(state)
  if (!sanitizer) {
    sanitizer = createCanvasEvalCompatSanitizer()
    grokCanvasEvalDiagnosticSanitizers.set(state, sanitizer)
  }
  return sanitizer
}

function applyGrokRunEvent(state: CliProviderStreamState, evt: NormalizedGrokRunEvent) {
  if (evt.sessionId) updateCliProviderSession(state, evt.sessionId)
  if (evt.type === 'content' && evt.text) {
    state.assistantText = `${state.assistantText || ''}${evt.text}`
    sendAgentCompatLine(
      state.sender,
      'grok',
      { type: 'content', text: evt.text, provider: 'grok' },
      state
    )
  } else if (evt.type === 'thinking' && evt.text) {
    emitCliProviderThinkingEvent(state, evt.text)
  } else if (evt.type === 'tool_use') {
    const toolId = evt.toolId || `grok-tool-${++grokFallbackToolSeq}`
    const toolName = evt.toolName || 'tool'
    const diagnosticToolName =
      sanitizeCanvasEvalProviderText(toolName) === toolName ? toolName : 'canvas_eval'
    // Keep an independent correlation lane for delayed diagnostics. The
    // transcript sanitizer consumes its marker when the result is emitted;
    // this second bounded sanitizer ensures grokLastToolError never caches the
    // raw canvas_eval result before that projection runs.
    grokCanvasEvalDiagnosticSanitizer(state).sanitize(
      {
        type: 'tool_use',
        tool_id: toolId,
        tool_name: diagnosticToolName,
        parameters: evt.toolInput || {},
        raw: evt.raw
      },
      undefined,
      `grok:${state.appRunId || state.appChatId || 'unrouted'}:diagnostic`
    )
    // Render Grok's tool invocation as an activity card (same shape the other
    // CLI providers emit, so the renderer is provider-agnostic).
    sendAgentCompatLine(
      state.sender,
      'grok',
      {
        type: 'tool_use',
        tool_id: toolId,
        tool_name: toolName,
        // Canonical ACP kind (read|edit|execute|search|…); lets the renderer
        // resolve the category icon when tool_name is a freeform ACP title.
        tool_kind: evt.toolKind,
        parameters: evt.toolInput || {},
        provider: 'grok'
      },
      state
    )
  } else if (evt.type === 'tool_result') {
    const toolId = evt.toolId || `grok-tool-${grokFallbackToolSeq || ++grokFallbackToolSeq}`
    const diagnosticProjection = grokCanvasEvalDiagnosticSanitizer(state).sanitize(
      {
        type: 'tool_result',
        tool_id: toolId,
        status: evt.toolStatus || 'success',
        output: evt.toolOutput || '',
        raw: evt.raw
      },
      undefined,
      `grok:${state.appRunId || state.appChatId || 'unrouted'}:diagnostic`
    )
    const diagnosticOutput =
      isRecord(diagnosticProjection) && typeof diagnosticProjection.output === 'string'
        ? diagnosticProjection.output
        : ''
    if (evt.toolStatus === 'error') {
      state.grokToolErrorCount = (state.grokToolErrorCount || 0) + 1
      if (evt.toolOutput) state.grokLastToolError = diagnosticOutput
    }
    sendAgentCompatLine(
      state.sender,
      'grok',
      {
        type: 'tool_result',
        tool_id: toolId,
        status: evt.toolStatus || 'success',
        output: evt.toolOutput || '',
        provider: 'grok'
      },
      state
    )
  } else if (evt.type === 'result') {
    // Grok's terminal `end` event. We don't emit the canonical result here (the
    // process-close handler synthesizes it), but we DO remember an abnormal
    // stopReason so close-out can report it honestly — Grok exits 0 even when it
    // self-cancels mid-turn before answering/writing.
    const stopReason = normalizeGrokStopReason(evt.status)
    if (stopReason !== 'success') state.grokStopReason = stopReason
  } else if (evt.type === 'provider_warning' && evt.text) {
    sendAgentCompatError(state.sender, 'grok', evt.text, state)
  }
}

// 1.0.6-G5d — Opt-in raw-stream capture. Grok's headless tool-event wire shape
// is still undocumented; set TASKWRAITH_GROK_DEBUG=1 to append every parsed Grok
// streaming-json object to <tmpdir>/taskwraith-grok-stream.jsonl so the real shape
// can be captured from a live in-app run. Off by default; never throws.
let grokDebugLogPath: string | null = null
function maybeLogGrokRawEvent(event: unknown): void {
  const flag = process.env.TASKWRAITH_GROK_DEBUG
  if (flag !== '1' && flag !== 'true' && flag !== 'yes') return
  let serialized = ''
  try {
    serialized = JSON.stringify(event)
  } catch {
    return
  }
  // Tagged stderr line so the RAW Grok wire shape shows up in the same dev
  // terminal the user already watches (one-paste capture, no temp-file fishing).
  try {
    process.stderr.write(`[grok-raw] ${serialized}\n`)
  } catch {
    /* ignore */
  }
  try {
    if (!grokDebugLogPath) grokDebugLogPath = join(os.tmpdir(), 'taskwraith-grok-stream.jsonl')
    fsSync.appendFileSync(grokDebugLogPath, `${serialized}\n`)
  } catch {
    // Diagnostics only — never disrupt the run.
  }
}

// 1.0.6-G4d — opt-in raw ACP JSON-RPC frame capture (both directions). With
// TASKWRAITH_GROK_DEBUG=1 each frame prints as `[grok-acp-raw] →/← {…}` in the dev
// terminal (one-paste capture) so the live ACP wire shape can be confirmed —
// crucially whether Grok emits `tool_call` session/updates AND
// `session/request_permission` requests (the precondition for write-over-ACP).
function maybeLogGrokRawAcp(direction: 'in' | 'out', message: unknown): void {
  const flag = process.env.TASKWRAITH_GROK_DEBUG
  if (flag !== '1' && flag !== 'true' && flag !== 'yes') return
  let serialized = ''
  try {
    serialized = JSON.stringify(message)
  } catch {
    return
  }
  try {
    process.stderr.write(`[grok-acp-raw] ${direction === 'out' ? '→' : '←'} ${serialized}\n`)
  } catch {
    /* ignore */
  }
  try {
    if (!grokDebugLogPath) grokDebugLogPath = join(os.tmpdir(), 'taskwraith-grok-stream.jsonl')
    fsSync.appendFileSync(grokDebugLogPath, `${serialized}\n`)
  } catch {
    /* diagnostics only */
  }
}

function handleGrokStreamEvent(state: CliProviderStreamState, event: unknown) {
  maybeLogGrokRawEvent(event)
  for (const evt of grokEventToRunEvents({ json: event as Record<string, unknown> })) {
    applyGrokRunEvent(state, evt)
  }
  // Belt-and-suspenders: also run the shared multi-shape tool recognizer, which
  // handles Claude-style *nested* tool events (message.content[].tool_use) and
  // the bridge ToolCall/ToolResult envelopes. Disjoint from the flattened
  // top-level tool_use/tool_result handled by grokEventToRunEvents above, so no
  // double-emit; a no-op when nothing matches.
  emitCliProviderToolEvent(state, event)
  emitCliProviderMediaRefs(state, event)
}

// Historical Cursor stream decoding retained for old transcripts/fixtures.
// The pure CursorStreamJson mapper turns archived cursor-agent stream-json into
// normalized run events, and applyCursorRunEvent emits the
// provider-agnostic compat lines (content / thinking / tool_use / tool_result)
// the renderer already understands. Cursor reports REAL token usage in its
// terminal result, so (unlike Grok) no projection is needed.
let cursorFallbackToolSeq = 0
function applyCursorRunEvent(state: CliProviderStreamState, evt: NormalizedCursorRunEvent) {
  if (evt.sessionId) updateCliProviderSession(state, evt.sessionId)
  if (evt.type === 'content' && evt.text) {
    state.assistantText = `${state.assistantText || ''}${evt.text}`
    const rawRecord =
      evt.raw && typeof evt.raw === 'object' && !Array.isArray(evt.raw)
        ? (evt.raw as Record<string, unknown>)
        : null
    const isCursorSnapshot = rawRecord?.type === 'assistant'
    sendAgentCompatLine(
      state.sender,
      'cursor',
      {
        type: 'content',
        text: evt.text,
        provider: 'cursor',
        ...(isCursorSnapshot ? { runItemCumulative: true } : {})
      },
      state
    )
  } else if (evt.type === 'thinking' && evt.text) {
    emitCliProviderThinkingEvent(state, evt.text)
  } else if (evt.type === 'tool_use') {
    sendAgentCompatLine(
      state.sender,
      'cursor',
      {
        type: 'tool_use',
        tool_id: evt.toolId || `cursor-tool-${++cursorFallbackToolSeq}`,
        tool_name: evt.toolName || 'tool',
        // Canonical kind (read|edit|execute|search|…) drives the category icon
        // (AD3) even though the Cursor tool name is a machine name.
        tool_kind: evt.toolKind,
        parameters: evt.toolInput || {},
        provider: 'cursor'
      },
      state
    )
  } else if (evt.type === 'tool_result') {
    sendAgentCompatLine(
      state.sender,
      'cursor',
      {
        type: 'tool_result',
        tool_id: evt.toolId || `cursor-tool-${cursorFallbackToolSeq || ++cursorFallbackToolSeq}`,
        status: evt.toolStatus || 'success',
        output: evt.toolOutput || '',
        provider: 'cursor'
      },
      state
    )
  } else if (evt.type === 'result') {
    // Real usage from the terminal result event — record it so the run surfaces
    // in the token dashboard. Cost stays 0 until a verified composer-2.5 rate
    // lands (BAKED_IN_RATES ships an empty models list for now).
    if (evt.usage) {
      state.tokenUsage = {
        ...cursorUsageToStats(evt.usage),
        total_cost_usd: 0
      }
    }
    const outcome = cursorTerminalCompatOutcome(evt)
    if (!outcome) return
    if (outcome.failed) {
      // Cursor may return `is_error:true` and still exit the process with code
      // 0. Feed its terminal text through the same error chokepoint as stderr
      // so ensemble overflow classification sees it before the failed result
      // settles the run.
      sendAgentCompatError(state.sender, 'cursor', cursorTerminalFailureText(evt), state)
    } else if (outcome.text) {
      // The terminal `result` is Cursor's authoritative full answer. Re-emit it
      // as a tagged cumulative snapshot: the shared fold drops an exact repeat,
      // appends only a missing tail, and preserves result-only answers.
      state.assistantText = outcome.text
      sendAgentCompatLine(
        state.sender,
        'cursor',
        {
          type: 'content',
          text: outcome.text,
          provider: 'cursor',
          runItemCumulative: true
        },
        state
      )
    }
    state.terminalResultFailed = outcome.failed
    state.completed = true
    sendAgentCompatLine(
      state.sender,
      'cursor',
      {
        type: 'result',
        status: outcome.status,
        subtype: outcome.subtype,
        stats: {
          ...(state.tokenUsage || {}),
          duration_ms: Date.now() - state.startedAt
        },
        provider: 'cursor',
        providerThreadId: state.providerSessionId || undefined,
        fallback: state.fallback
      },
      state
    )
  } else if (evt.type === 'provider_warning' && evt.text) {
    sendAgentCompatError(state.sender, 'cursor', evt.text, state)
  }
}

// CR — opt-in raw stream capture (TASKWRAITH_CURSOR_DEBUG); mirrors the Grok tap.
let cursorDebugLogPath: string | null = null
function maybeLogCursorRawEvent(event: unknown): void {
  if (!cursorDebugEnabled()) return
  let serialized = ''
  try {
    serialized = JSON.stringify(event)
  } catch {
    return
  }
  process.stderr.write(`[cursor-raw] ${serialized}\n`)
  try {
    if (!cursorDebugLogPath)
      cursorDebugLogPath = join(os.tmpdir(), 'taskwraith-cursor-stream.jsonl')
    fsSync.appendFileSync(cursorDebugLogPath, `${serialized}\n`)
  } catch {
    // Best-effort; never throws.
  }
}

function handleCursorStreamEvent(state: CliProviderStreamState, event: unknown) {
  maybeLogCursorRawEvent(event)
  for (const evt of cursorEventToRunEvents({ json: event as Record<string, unknown> })) {
    applyCursorRunEvent(state, evt)
  }
  // Belt-and-suspenders: also run the shared multi-shape tool recognizer for any
  // nested / bridge tool shapes (disjoint from the flattened events above).
  emitCliProviderToolEvent(state, event)
  emitCliProviderMediaRefs(state, event)
}

/**
 * Grok's CLI reports no token counts, so a Grok run would otherwise record 0
 * tokens and never surface in the token/cost dashboard (Providers tab, Model
 * Comparisons). Estimate a PROJECTED usage (~4 chars/token) from the prompt +
 * accumulated response so Grok appears alongside the other providers. This is
 * an estimate for projection only — NOT real billing: Grok bills via the
 * SuperGrok subscription credit pool (see the "Subscription credits" meter).
 * Paired with the projected xAI rates in ProviderRateService it yields a
 * projected cost. Emits snake_case keys the renderer's usage extractor reads.
 */
// Grok reports no token usage and no cost. We project both so Grok appears in
// the composer tally + dashboard like the other providers. Tokens are a rough
// ~4-chars/token estimate; cost mirrors the current Grok CLI default's projected
// rate constants — NOT a SuperGrok subscription bill. `total_cost_usd` is the
// field the renderer's extractUsageCostUsd reads, so the `· $x` cost surfaces too.

// Claude-native Workflow lifecycle. When Claude runs its own `Workflow` tool the
// Agent SDK streams `type:'system'` task frames (task_started/progress/updated/
// notification). They reach this handler but carry no tool/text content, so we
// translate the workflow telemetry onto its own `workflow_event` compat line —
// the renderer keys it back to the originating `Workflow` tool activity (by
// tool_use id) to drive a Claude workflow card. Scoped to task_type
// 'local_workflow' so plain background `Task` subagents (same lifecycle frames)
// don't masquerade as workflows.
function emitClaudeWorkflowEvent(state: CliProviderStreamState, event: unknown): void {
  const normalized = normalizeClaudeWorkflowEvent(event)
  if (!normalized) return
  const { taskId, toolUseId, taskType, telemetry } = normalized

  const workflowTaskIds = state.claudeWorkflowTaskIds ?? new Set<string>()
  state.claudeWorkflowTaskIds = workflowTaskIds
  if (!shouldEmitClaudeWorkflowTelemetry({ taskId, taskType }, workflowTaskIds)) return
  if (taskType === 'local_workflow' && taskId) workflowTaskIds.add(taskId)

  // The card is anchored to the originating tool activity by its tool_use id;
  // without one there is nowhere to attach the telemetry.
  if (!toolUseId) return

  sendAgentCompatLine(
    state.sender,
    state.provider,
    {
      type: 'workflow_event',
      tool_id: toolUseId,
      workflow: telemetry,
      provider: state.provider
    },
    state
  )
}

// Provider context-window compaction (Claude lane). The claude subprocess
// streams `system/status(compacting|compact_result)` and `system/compact_boundary`
// frames when it compacts — auto mid-turn, or manually when a `/compact` prompt
// is dispatched with `--resume` (probe-verified in print mode AND via the SDK).
// Translate them onto a `compaction_event` compat line: unknown to the run-item
// compat mapper (so it can never leak into the assistant-text dedupe lanes), it
// fans out to the renderer card, the ensemble orchestrator, and a durable
// `context_compaction` run event.
function emitContextCompactionCompatLine(
  sender: Electron.WebContents,
  provider: ProviderId,
  signal: ContextCompactionSignal,
  route?: AgentRunRoute | null
): void {
  const routedChatId =
    route && typeof route.appChatId === 'string' && route.appChatId ? route.appChatId : undefined
  const ensembleParticipantId =
    route &&
    typeof (route as { ensembleRun?: { participantId?: unknown } }).ensembleRun?.participantId ===
      'string'
      ? (route as { ensembleRun: { participantId: string } }).ensembleRun.participantId
      : undefined
  if (routedChatId && !ensembleParticipantId) {
    broadcastContextCompactionSignalProgress({
      chatId: routedChatId,
      provider,
      signal
    })
  }
  sendAgentCompatLine(
    sender,
    provider,
    {
      type: 'compaction_event',
      compaction: {
        kind: signal.kind,
        telemetry: { ...signal.telemetry, provider }
      },
      provider
    },
    route
  )
}

function emitClaudeContextCompactionEvent(state: CliProviderStreamState, event: unknown): void {
  const signal = normalizeClaudeContextCompactionEvent(event)
  if (!signal) return
  const seen = state.contextCompactionSeen ?? new Set<string>()
  state.contextCompactionSeen = seen
  const key = contextCompactionDedupeKey(signal)
  if (seen.has(key)) return
  seen.add(key)
  emitContextCompactionCompatLine(state.sender, state.provider, signal, state)
}

function handleCliProviderJsonEvent(state: CliProviderStreamState, event: any) {
  if (state.provider === 'grok') {
    handleGrokStreamEvent(state, event)
    return
  }
  if (state.provider === 'cursor') {
    handleCursorStreamEvent(state, event)
    return
  }
  if (state.provider === 'claude' && isClaudeWorkflowSystemEvent(event)) {
    // Task-lifecycle frames carry a TASK-scoped usage aggregate, not a turn
    // delta. Returning here both drives the workflow card AND skips the generic
    // extractProviderUsage merge below — which would otherwise double-count the
    // workflow's tokens into the run total — plus the tool/text/result
    // extraction that system frames never carry.
    emitClaudeWorkflowEvent(state, event)
    return
  }
  if (state.provider === 'claude' && isClaudeContextCompactionSystemEvent(event)) {
    // Compaction frames carry CONTEXT sizes (pre/post tokens), not turn usage —
    // early-return so they never reach extractProviderUsage's monotonic merge,
    // and never fall through the generic text/result extraction.
    emitClaudeContextCompactionEvent(state, event)
    return
  }
  const sessionId = extractProviderSessionId(event)
  updateCliProviderSession(state, sessionId)
  const usage = extractProviderUsage(state.provider, event)
  if (usage) {
    state.tokenUsage = mergeProviderUsage(state.provider, state.tokenUsage, usage)
    ensembleOrchestratorRef?.reportParticipantTokenUsage(
      state.appRunId,
      state.tokenUsage as Record<string, unknown> | undefined,
      { provider: state.provider, chatId: state.appChatId }
    )
    // Solo runs aren't registered with the ensemble orchestrator, so surface
    // their live authoritative usage to the same working-telemetry lane the
    // composer footer + working row read from.
    if (!state.ensembleRun) {
      const soloEvent = soloWorkingTokenTelemetry.report({
        runId: state.appRunId,
        chatId: state.appChatId,
        provider: state.provider,
        startedAtMs: state.startedAt,
        stats: state.tokenUsage as Record<string, unknown> | undefined,
        nowMs: Date.now()
      })
      if (soloEvent) broadcastParticipantWorkingTelemetry(soloEvent)
    }
  }
  // Per-occurrence budget kill: feed the LIVE token snapshot. No-op unless this
  // run was registered (solo scheduled run with a budget). Covers Claude (SDK +
  // CLI — both stream through this handler) and Kimi. grok/cursor early-return
  // above (terminal-only tokenUsage → wall-clock enforcement ONLY, no token kill).
  if (state.appRunId) workflowBudgetRegistry.onUsage(state.appRunId, state.tokenUsage)
  emitCliProviderToolEvent(state, event)
  if (state.provider === 'kimi' || state.provider === 'claude') {
    // Claude (SDK + CLI) carries provider-authorized thinking summaries in
    // `thinking` blocks and, with partial messages, `thinking_delta` stream
    // events. Surface only those displayable summaries as reasoning activity;
    // opaque signatures / redacted blocks stay out of the transcript.
    const thinkingText = extractProviderThinkingText(event, state.provider)
    const eventTypeStr = String(event?.type || '')
    emitCliProviderThinkingEvent(state, thinkingText, {
      cumulative:
        eventTypeStr === 'assistant' ||
        eventTypeStr === 'message' ||
        eventTypeStr === 'message_delta'
    })
  }

  const text = extractProviderText(event)
  if (text) {
    let delta = text
    let cumulative = false
    // Dedup: when Claude (without partial messages) or Kimi emits a
    // cumulative envelope that re-states the whole assistant text,
    // slice off the prefix we already streamed and emit only the
    // remainder.
    //
    // 1.0.5-S1 — With `includePartialMessages: true` (see
    // tryRunClaudeSdk), Claude also emits incremental `stream_event`
    // chunks. Those chunks are NOT cumulative, so `text.startsWith(
    // state.assistantText)` is false and the slice doesn't fire —
    // delta stays as the new chunk. When the trailing cumulative
    // `assistant` envelope arrives at end-of-turn, it WILL match the
    // accumulated text exactly, slice to "", and the `if (delta)`
    // guard below drops it — no double-emission.
    if (state.assistantText && text.startsWith(state.assistantText)) {
      delta = text.slice(state.assistantText.length)
    } else if (state.assistantText) {
      // 1.0.6 dup-fix — the slice MISSED but we already streamed text
      // this turn. If this event is the cumulative envelope shape
      // (`assistant` / `message` — a full re-statement of the whole turn,
      // per extractProviderText) it DIVERGED from the streamed deltas
      // (whitespace / block-boundary / thinking interleave), so the slice
      // above couldn't trim it. Forwarding it as a plain delta would make
      // the renderer APPEND the entire turn again, doubling the bubble.
      // Instead emit the authoritative full text tagged `cumulative` so
      // the renderer REPLACES rather than appends. A true incremental
      // chunk is a `stream_event` / `content_block_delta`, never an
      // envelope shape, so it still falls through below as a normal delta.
      const eventTypeStr = String(event?.type || '')
      if (eventTypeStr === 'assistant' || eventTypeStr === 'message') {
        cumulative = true
        delta = text
      }
    }
    if (delta) {
      if (cumulative) {
        state.assistantText = text
      } else {
        state.assistantText += delta
      }
      sendAgentCompatLine(
        state.sender,
        state.provider,
        {
          type: 'content',
          text: delta,
          provider: state.provider,
          providerThreadId: state.providerSessionId || undefined,
          fallback: state.fallback,
          ...(cumulative ? { cumulative: true } : {})
        },
        state
      )
    }
  }

  emitCliProviderMediaRefs(state, event)

  const eventType = String(event?.type || event?.method || event?.params?.type || '')
  if (
    eventType === 'result' ||
    eventType === 'TurnEnd' ||
    (event?.method === 'event' && event?.params?.type === 'TurnEnd')
  ) {
    state.completed = true
    const terminalStatus = event?.status || event?.result?.status || event?.subtype || 'success'
    if (state.deferTerminalResult) {
      const merged = mergeKimiWireTerminalEvidence(
        {
          ...(state.deferredTerminalStatus ? { status: state.deferredTerminalStatus } : {}),
          conflict: state.deferredTerminalConflict ?? false
        },
        bridgeResultTerminalStatus({
          status: terminalStatus,
          error: event?.error,
          is_error: event?.is_error,
          subtype: event?.subtype
        })
      )
      state.deferredTerminalStatus = merged.status
      state.deferredTerminalConflict = merged.conflict
      state.terminalResultFailed = merged.status === 'failed' || merged.conflict
      return
    }
    sendAgentCompatLine(
      state.sender,
      state.provider,
      {
        type: 'result',
        subtype: event?.subtype || terminalStatus,
        status: terminalStatus,
        stats: {
          ...(state.tokenUsage || {}),
          duration_ms: event?.duration_ms || event?.durationMs || Date.now() - state.startedAt,
          cost_usd: event?.cost_usd || event?.total_cost_usd
        },
        provider: state.provider,
        providerThreadId: state.providerSessionId || undefined,
        providerRunId: state.runId || undefined,
        fallback: state.fallback
      },
      state
    )
  }
}

function runCliProviderProcess(
  event: Electron.IpcMainInvokeEvent,
  provider: 'claude' | 'kimi' | 'grok' | 'cursor',
  command: string,
  args: string[],
  payload: AgentRunPayload,
  options: {
    fallback: boolean
    requireExistingRun?: boolean
    warning?: string
    onComplete?: () => Promise<void> | void
  } & (
    | { extraEnv?: Record<string, string>; resolvedEnv?: never }
    | {
        extraEnv?: never
        /** Main-resolved immutable launch authority; never merge or re-resolve it here. */
        resolvedEnv: Readonly<Record<string, string>>
      }
  ) = { fallback: true }
): Promise<void> {
  const route = routeWithRunId(provider, payload)
  const transportClose = createProviderTransportCloseOperation(options.onComplete)
  const existingSession = runManager.get(route.appRunId)
  if (!canStartRunTransport(existingSession?.status, options.requireExistingRun)) {
    transportClose.markTransportClosed()
    return transportClose.operation
  }
  const cwd = payload.workspace!
  const model = normalizeCliProviderModel(provider, payload.model)
  const state: CliProviderStreamState = {
    provider,
    sender: event.sender,
    startedAt: Date.now(),
    model,
    fallback: options.fallback,
    completed: false,
    assistantText: '',
    providerSessionId: payload.providerSessionId || null,
    approvalMode: payload.approvalMode,
    workflowMode: payload.workflowMode,
    sessionTrust: Boolean(payload.sessionTrust),
    externalPathGrants: payload.externalPathGrants,
    runtimeProfileId: payload.runtimeProfileId,
    taskWraithMcpProfileId: payload.taskWraithMcpProfileId,
    taskWraithMcpAdvertised: payload.taskWraithMcpAdvertised,
    taskWraithMcpProfileFence: payload.taskWraithMcpProfileFence,
    taskWraithMcpSeenProviderSessionIds: new Set(
      payload.providerSessionId ? [payload.providerSessionId] : []
    ),
    effectivePermissions: payload.effectivePermissions,
    effectivePermissionsSignature: payload.effectivePermissionsSignature,
    ensembleRun: payload.ensembleRun,
    ...route
  }
  const registeredSession = registerRunSession(
    provider,
    event.sender,
    route,
    payload.scope === 'global' ? undefined : payload.workspace,
    state,
    payload.providerSessionId || null,
    options.requireExistingRun
  )
  if (!registeredSession) {
    transportClose.markTransportClosed()
    return transportClose.operation
  }
  void emitProviderCapabilityWarnings(
    event.sender,
    provider,
    payload.workspace,
    payload.approvalMode,
    state
  )

  if (options.warning) {
    sendAgentCompatLine(
      event.sender,
      provider,
      {
        type: 'provider_warning',
        provider,
        message: options.warning,
        fallback: options.fallback
      },
      state
    )
  }

  sendAgentCompatLine(
    event.sender,
    provider,
    {
      type: 'init',
      session_id: state.providerSessionId || '',
      model,
      timestamp: new Date().toISOString(),
      provider,
      fallback: options.fallback
    },
    state
  )

  // Register the exact close+cleanup operation before the child is exposed to
  // RunManager or any provider-global compatibility handle. Destructive
  // history deletion can therefore never observe an active Claude child
  // without also having a joinable transport authority.
  const transportOperation = providerTransportOperations.track(
    route.appRunId!,
    transportClose.operation
  )
  let child: ChildProcess
  try {
    child = spawn(command, args, {
      cwd,
      shell: false,
      env:
        options.resolvedEnv ??
        createCliProviderRunEnv({
          provider,
          command,
          appRunId: route.appRunId,
          appChatId: route.appChatId,
          scope: payload.scope,
          workspace: payload.workspace,
          runtimeProfileId: payload.runtimeProfileId,
          auditRun: Boolean(payload.auditRun),
          extraEnv: options.extraEnv
        })
    })
  } catch (error) {
    sendAgentCompatError(
      event.sender,
      provider,
      `Failed to start ${providerDisplayName(provider)}: ${error instanceof Error ? error.message : String(error)}`,
      state
    )
    sendAgentCompatExit(event.sender, provider, 1, state)
    runManager.finish(route.appRunId, 'failed')
    transportClose.markTransportClosed()
    return transportOperation
  }
  child.stdin?.end()
  runManager.attachProcess(route.appRunId!, child)
  cliProviderProcesses.set(provider, child)

  let stdoutBuffer = ''
  const cliProviderStderrSanitizer = createCanvasEvalJsonLineSanitizer(
    `${provider}:${route.appRunId || route.appChatId || 'unrouted'}:stderr`
  )
  const emitCliProviderStderr = (text: string): void => {
    if (!text) return
    sendAgentCompatError(event.sender, provider, sanitizeCanvasEvalProviderText(text), state)
  }
  child.stdout?.on('data', (chunk) => {
    stdoutBuffer += chunk.toString()
    const lines = stdoutBuffer.split(/\r?\n/)
    stdoutBuffer = lines.pop() || ''
    for (const line of lines) {
      const trimmed = line.trim()
      if (!trimmed) continue
      try {
        handleCliProviderJsonEvent(state, JSON.parse(trimmed))
      } catch {
        sendAgentCompatLine(
          event.sender,
          provider,
          {
            type: 'content',
            text: sanitizeCanvasEvalProviderText(line + '\n'),
            provider,
            fallback: options.fallback
          },
          state
        )
      }
    }
  })

  // 1.0.5-EW23 — Detect Kimi's content-filter rejection. Moonshot's
  // hosted API can reject prompts upstream with a 400 + a
  // `type: 'content_filter'` payload. Pre-EW23 that bubbled out as a
  // raw stderr line ("Error code: 400 - {'error': {...}}") plus a
  // generic `type:result, status:failed` event, and the user just
  // saw "Kimi failed" on the chip with no idea it was an API-side
  // safety filter rather than an TaskWraith bug. the maintainer hit this with
  // 3x Kimi participants in a global ensemble — first Kimi passed,
  // second Kimi's prompt (which now included the first Kimi's
  // response plus several other panelists' turns + URLs) tripped
  // the filter.
  //
  // We surface a structured provider_warning with a friendly
  // explanation BEFORE forwarding the raw stderr so the user sees
  // the cause inline. The actual run still finalizes as failed —
  // we don't fake a recovery — but the failure reads as
  // "explanation + try this next time" rather than mystery.
  //
  // Deeper investigation (which role names / content shapes trip
  // the filter most often, whether retry policies make sense,
  // whether there's a Moonshot-side sensitivity control) is
  // parked for 1.0.6. This is the small defensive note the maintainer
  // approved for 1.0.5.
  let kimiContentFilterWarned = false
  child.stderr?.on('data', (chunk) => {
    const text = chunk.toString()
    if (provider === 'kimi' && !kimiContentFilterWarned && isKimiContentFilterRejection(text)) {
      kimiContentFilterWarned = true
      sendAgentCompatLine(
        event.sender,
        'kimi',
        {
          type: 'provider_warning',
          provider: 'kimi',
          severity: 'warning',
          title: 'Kimi safety filter rejected this prompt',
          message:
            "Kimi (Moonshot) rejected this turn upstream with a content-filter 400. The other participants saw the same prompt context fine — this is API-side, not an TaskWraith bug. Common triggers: politically-coded role names (e.g. 'Politician'), accumulated transcript content from many preceding turns, or external URLs / quoted material the filter reads as suspicious. Try rephrasing the user prompt, renaming sensitive roles, or starting a fresh round."
        },
        state
      )
    }
    emitCliProviderStderr(cliProviderStderrSanitizer.push(text))
  })

  child.on('error', (error) => {
    emitCliProviderStderr(cliProviderStderrSanitizer.flush())
    sendAgentCompatError(
      event.sender,
      provider,
      `Failed to start ${providerDisplayName(provider)}: ${error.message}`,
      state
    )
    // Node emits `close` after an `error` once the child/stdout lifecycle has
    // actually ended. Keep the exact RunManager and compatibility handles live
    // until that callback publishes the exit, terminalizes the run, and marks
    // the tracked transport operation closed.
  })

  child.on('close', (code) => {
    emitCliProviderStderr(cliProviderStderrSanitizer.flush())
    const trailing = stdoutBuffer.trim()
    if (trailing) {
      try {
        handleCliProviderJsonEvent(state, JSON.parse(trailing))
      } catch {
        sendAgentCompatLine(
          event.sender,
          provider,
          {
            type: 'content',
            text: sanitizeCanvasEvalProviderText(trailing + '\n'),
            provider,
            fallback: options.fallback
          },
          state
        )
      }
    }
    // Grok reports no token usage; record a projected estimate so it appears in
    // the dashboard (see estimateProjectedTokenUsage — projection, not billing).
    if (provider === 'grok' && !state.tokenUsage) {
      state.tokenUsage = estimateProjectedTokenUsage(payload.prompt, state.assistantText)
    }
    // 1.0.6-G5e — Honor Grok's terminal stopReason. Grok exits 0 even when it
    // self-cancels a turn mid-reasoning (stopReason 'Cancelled') before producing
    // an answer or writing files, which otherwise renders as a misleading
    // "Task complete / success". Surface the real reason + a short note instead.
    const grokStopped =
      provider === 'grok' && !!state.grokStopReason && state.grokStopReason !== 'success'
    const effectiveExitCode =
      provider === 'cursor'
        ? cursorEffectiveExitCode(code, state.terminalResultFailed === true)
        : code
    if (grokStopped && !state.completed) {
      sendAgentCompatLine(
        event.sender,
        'grok',
        {
          type: 'provider_warning',
          provider: 'grok',
          severity: 'warning',
          title: `Grok ended this turn early (${state.grokStopReason})`,
          message: `Grok stopped before finishing this turn (stopReason: ${state.grokStopReason}). It may not have produced an answer or written files — any reasoning above is partial. This is Grok's own turn outcome, not an TaskWraith error.`
        },
        state
      )
    }
    if (!state.completed) {
      sendAgentCompatLine(
        event.sender,
        provider,
        {
          type: 'result',
          status: grokStopped
            ? state.grokStopReason!
            : effectiveExitCode === 0
              ? 'success'
              : 'failed',
          stats: {
            ...(state.tokenUsage || {}),
            duration_ms: Date.now() - state.startedAt
          },
          provider,
          providerThreadId: state.providerSessionId || undefined,
          fallback: options.fallback
        },
        state
      )
    }
    sendAgentCompatExit(event.sender, provider, effectiveExitCode, state)
    if (cliProviderProcesses.get(provider) === child) cliProviderProcesses.delete(provider)
    runManager.finish(route.appRunId, effectiveExitCode === 0 ? 'completed' : 'failed')
    transportClose.markTransportClosed()
  })

  return transportOperation
}

async function loadOptionalClaudeSdk(): Promise<any | null> {
  try {
    const importer = new Function('specifier', 'return import(specifier)') as (
      specifier: string
    ) => Promise<any>
    return await importer('@anthropic-ai/claude-agent-sdk')
  } catch {
    return null
  }
}

/**
 * Phase I3 (Claude initiator): assemble the input the TaskWraith MCP
 * helpers need — current `geminiMcpBridgeEnabled` toggle + the same
 * bridge argv Gemini/Codex use, plus user-managed MCP servers.
 * Centralised so SDK and CLI paths build identical config.
 */
function claudeTaskWraithMcpInput(
  route?: AgentRunRoute | null,
  workspacePath?: string | null,
  profileId: NonNullable<ClaudeTaskWraithMcpInput['profileId']> = TASKWRAITH_FULL_MCP_PROFILE_ID,
  taskWraithMcpAdvertised = true
): ClaudeTaskWraithMcpInput {
  const bridgeCommandStatus = taskwraithMcpBridgeCommandStatus()
  const settings = AppStore.getSettings()
  const enabled = Boolean(taskWraithMcpAdvertised && bridgeCommandStatus.available)
  return {
    enabled,
    profileId,
    bridgeBinaryPath: bridgeCommandStatus.command,
    bridgeArgs: taskwraithMcpBridgeArgs(),
    userMcpServers: buildUserMcpLaunchServers(settings.userMcpServers, {
      allowlistPolicy: managedUserMcpLaunchAllowlistPolicy?.(),
      resolveSecretValues: (refs) => AppStore.resolveExtensionSecretValues(refs),
      validatePluginProvenance: validateUserMcpPluginProvenance
    }),
    ...(route?.appRunId ? { appRunId: route.appRunId } : {}),
    ...(route?.appChatId ? { appChatId: route.appChatId } : {}),
    ...(workspacePath ? { workspacePath } : {})
  }
}

function claudeRunRequiresPinnedTaskWraithMcp(payload: AgentRunPayload): boolean {
  return taskWraithMcpRunStartedWithPinnedReceipt({
    providerSessionId: payload.providerSessionId,
    fence: payload.taskWraithMcpProfileFence
  })
}

function claudeAgenticServiceForTool(toolName: string): AgenticServiceId | null {
  const normalized = toolName.trim().toLowerCase()
  if (!normalized) return null
  const taskWraithService = taskWraithToolServiceIfKnown(normalized)
  if (taskWraithService) return taskWraithService
  if (
    normalized === 'bash' ||
    normalized === 'shell' ||
    normalized === 'run_shell_command' ||
    normalized.includes('shell_command') ||
    // Run-Button launch start/stop spawn / terminate processes — shell strictness.
    normalized === 'launch_start' ||
    normalized === 'launch_stop'
  ) {
    return 'shellCommands'
  }
  if (
    normalized === 'write' ||
    normalized === 'edit' ||
    normalized === 'multiedit' ||
    normalized === 'notebookedit' ||
    normalized === 'writefile' ||
    normalized === 'strreplacefile' ||
    normalized === 'replace' ||
    normalized === 'write_file' ||
    normalized.includes('write_file') ||
    normalized.includes('replace_file') ||
    normalized.includes('str_replace')
  ) {
    return 'fileChanges'
  }
  // Canvas click/fill get the dedicated grant bucket on the Claude canUseTool
  // gate too (it fires before previewForGeminiMcpTool), so a prior mcpTools
  // grant can't silently auto-allow app-mutating canvas interactions.
  if (
    normalized.includes('canvas_click') ||
    normalized.includes('canvas_fill') ||
    normalized.includes('canvas_sketch_update')
  ) {
    return 'canvasInteraction'
  }
  // Arbitrary eval (RCE) gets its own signed-elevated bucket on the Claude gate
  // too — never auto-allowed by a grant/preset/YOLO.
  if (normalized.includes('canvas_eval')) {
    return 'canvasEval'
  }
  // Cross-thread reads route to crossThreadRead (grantable) on the Claude gate too.
  if (
    normalized.includes('tw_recall_find') ||
    normalized.includes('tw_recall_read') ||
    normalized.includes('tw_recall_read_events')
  ) {
    return 'crossThreadRead'
  }
  // Audio/video media tools route to the dedicated mediaEditing service on the
  // Claude gate too (mirrors taskWraithToolAgenticService). Canonicalize first so
  // both the bare (`transcode_audio`) and provider-wrapped (`mcp__taskwraith__
  // transcode_audio`) forms hit the same canonical-name membership check before
  // the generic mcp__/__ -> mcpTools fallthrough below.
  if (MEDIA_EDITING_TOOLS.has(canonicalTaskWraithToolName(normalized))) {
    return 'mediaEditing'
  }
  if (normalized.startsWith('mcp__') || normalized.includes('__')) {
    return 'mcpTools'
  }
  return null
}

function normalizeClaudeCanUseToolArgs(
  toolNameOrRequest: unknown,
  input?: unknown
): { toolName: string; input: unknown } {
  if (typeof toolNameOrRequest === 'string') {
    return { toolName: toolNameOrRequest, input }
  }
  if (isRecord(toolNameOrRequest)) {
    const toolName = String(
      toolNameOrRequest.toolName ||
        toolNameOrRequest.tool_name ||
        toolNameOrRequest.name ||
        toolNameOrRequest.tool ||
        'tool'
    )
    return {
      toolName,
      input:
        input ??
        toolNameOrRequest.input ??
        toolNameOrRequest.parameters ??
        toolNameOrRequest.params ??
        {}
    }
  }
  return { toolName: 'tool', input }
}

function previewClaudeToolInput(input: unknown): string {
  try {
    if (typeof input === 'string') return input.slice(0, 2_000)
    return JSON.stringify(input ?? {}, null, 2).slice(0, 2_000)
  } catch {
    return String(input ?? '').slice(0, 2_000)
  }
}

function claudeToolApprovalPreview(
  toolName: string,
  input: unknown,
  service: AgenticServiceId
): any {
  if (service === 'shellCommands') {
    const command = isRecord(input)
      ? String(input.command || input.cmd || input.description || previewClaudeToolInput(input))
      : previewClaudeToolInput(input)
    return {
      kind: 'command',
      command,
      params: input
    }
  }
  if (service === 'fileChanges') {
    const path = planArtifactRawPathFromToolInput(input) || ''
    return {
      kind: 'fileChange',
      toolName,
      ...(path ? { planArtifactRawPath: path } : {}),
      changes: path
        ? [{ kind: toolName.toLowerCase().includes('write') ? 'write' : 'edit', path }]
        : [],
      patchPreview: previewClaudeToolInput(input)
    }
  }
  return {
    kind: 'tool',
    toolName,
    params: input
  }
}

async function resolveNativeSubAgentToolPreference(
  sender: Electron.WebContents,
  provider: ProviderId,
  route: AgentRunRoute,
  payload: AgentRunPayload,
  toolName: string,
  input: unknown,
  updatedInput: Record<string, unknown>
): Promise<
  | { behavior: 'allow'; updatedInput: Record<string, unknown> }
  | { behavior: 'deny'; message: string }
  | null
> {
  if (!isNativeSubAgentToolName(toolName)) return null
  const policy = normalizeNativeSubAgentPolicy(AppStore.getSettings().nativeSubAgentRequests)
  if (policy === 'provider') {
    return { behavior: 'allow', updatedInput }
  }
  const denyMessage = nativeSubAgentRedirectMessage({ provider, toolName, input })
  if (policy === 'taskwraith') {
    return { behavior: 'deny', message: denyMessage }
  }

  const promptPreview = previewNativeSubAgentTask(input)
  const useProviderNative = await requestMainApproval(sender, provider, route, {
    method: 'nativeSubAgent/preference',
    title: 'Choose sub-agent routing',
    body:
      `${providerLabel(provider)} requested its native ${toolName} sub-agent tool.\n\n` +
      'Use Provider Native to continue with the provider tool, or use TaskWraith Sub-thread to ask the model to call delegate_to_subthread instead.\n\n' +
      'Change this later in Settings -> Provider Tools.',
    workspacePath: payload.scope === 'global' ? undefined : payload.workspace,
    actions: ['useProviderNative', 'useTaskWraithSubthread'],
    preview: {
      kind: 'native sub-agent',
      toolName,
      provider,
      task: promptPreview,
      redirectTool:
        provider === 'claude'
          ? 'mcp__TaskWraith__delegate_to_subthread'
          : 'TaskWraith__delegate_to_subthread'
    },
    resolveAction: (action) => {
      if (action === 'useProviderNative') {
        AppStore.updateSettings({ nativeSubAgentRequests: 'provider' })
      } else if (action === 'useTaskWraithSubthread') {
        AppStore.updateSettings({ nativeSubAgentRequests: 'taskwraith' })
      }
    }
  })

  return useProviderNative
    ? { behavior: 'allow', updatedInput }
    : { behavior: 'deny', message: denyMessage }
}

async function canUseClaudeSdkTool(
  sender: Electron.WebContents,
  route: AgentRunRoute,
  payload: AgentRunPayload,
  toolNameOrRequest: unknown,
  input?: unknown
): Promise<
  | { behavior: 'allow'; updatedInput: Record<string, unknown> }
  | { behavior: 'deny'; message: string }
> {
  const denyInactiveRun = (): { behavior: 'deny'; message: string } => ({
    behavior: 'deny',
    message: 'TaskWraith denied this Claude tool because the run is no longer active.'
  })
  const claudeRunAcceptsTools = (): boolean =>
    !historyClearAdmissionBlocked(route.appRunId, payload.workspace, route.appChatId) &&
    !runManager.getClaimedTerminalStatus(route.appRunId) &&
    canStartRunTransport(runManager.get(route.appRunId)?.status, true)
  if (!claudeRunAcceptsTools()) {
    return denyInactiveRun()
  }
  const { toolName, input: normalizedInput } = normalizeClaudeCanUseToolArgs(
    toolNameOrRequest,
    input
  )
  // Coerce the SDK's `input` into a plain record so Zod accepts it.
  // The Claude Agent SDK validates the canUseTool response with Zod:
  // an `allow` response REQUIRES `updatedInput: Record<string, unknown>`
  // (it's the args the SDK forwards to the tool — we pass them through
  // unchanged). Returning `{ behavior: 'allow' }` without `updatedInput`
  // makes Zod report ALL its union-arm failures, which surfaced in the
  // delegated-Claude run as: "Tool permission request failed: ZodError
  // — updatedInput: expected record, received undefined". The error
  // looks like a broken settings.json entry but is actually our
  // canUseTool response missing a required field.
  const updatedInput: Record<string, unknown> =
    typeof normalizedInput === 'object' &&
    normalizedInput !== null &&
    !Array.isArray(normalizedInput)
      ? (normalizedInput as Record<string, unknown>)
      : {}
  const nativeSubAgentDecision = await resolveNativeSubAgentToolPreference(
    sender,
    'claude',
    route,
    payload,
    toolName,
    normalizedInput,
    updatedInput
  )
  if (!claudeRunAcceptsTools()) {
    return denyInactiveRun()
  }
  if (nativeSubAgentDecision) return nativeSubAgentDecision
  // Auto-allow side-effect-free TaskWraith tools before the agentic-
  // service gate. The MCP dispatcher already skips approval for
  // these (line ~14078), but Claude's `canUseTool` callback fires
  // FIRST — without this, the user gets prompted to approve
  // harmless signals like `ensemble_yield`. Claude sees MCP tools
  // with their full prefix (e.g. `mcp__taskwraith__ensemble_yield`),
  // so strip any namespace before checking the allowlist.
  const unprefixedToolName = toolName.replace(/^mcp__/, '').replace(/^taskwraith__/, '')
  const canonicalToolName = canonicalTaskWraithToolName(unprefixedToolName)
  primeNativeCanvasCompatCorrelation({
    provider: 'claude',
    route,
    toolName: canonicalToolName || unprefixedToolName,
    source: toolNameOrRequest
  })
  if (isTaskWraithMcpToolName(canonicalToolName)) {
    const argumentPreflight = validateMcpToolArgumentsBeforeApproval(
      canonicalToolName,
      updatedInput,
      mcpToolDefinitions()
    )
    if (!argumentPreflight.ok) {
      return { behavior: 'deny', message: argumentPreflight.message }
    }
  }
  const approvalPriority = nativeProviderApprovalPriority(
    toolName,
    isMcpAutoAllowedForRun(unprefixedToolName, payload.effectivePermissions, normalizedInput, {
      appRunId: route.appRunId,
      appChatId: route.appChatId
    })
  )
  if (approvalPriority === 'deny-native') {
    // WS-B dual-stack: rather than quarantining native FS/shell to the broker,
    // run the shared canonical workspace preflight. Native FS calls whose paths
    // resolve INSIDE the active workspace are allowed again (reads directly;
    // writes routed through the agentic-service ledger below); out-of-workspace
    // paths are denied. The Claude Agent SDK runs tools with cwd=workspace but
    // provides no hard filesystem/egress sandbox, so native shell stays fail-
    // closed here (runtimeSandboxed:false) — the namespaced broker
    // run_shell_command, which IS workspace-bounded, remains available.
    const nativeWorkspacePreflight = preflightNativeWorkspaceTool({
      toolName,
      rawToolCall: updatedInput,
      workspacePath: payload.scope === 'global' ? undefined : payload.workspace,
      runtimeSandboxed: false
    })
    const nativeDecision = classifyNativeWorkspacePreflightDecision(
      'Claude',
      toolName,
      nativeWorkspacePreflight
    )
    if (nativeDecision.action === 'deny') {
      return { behavior: 'deny', message: nativeDecision.message }
    }
    if (nativeDecision.action === 'allow') {
      return { behavior: 'allow', updatedInput }
    }
    const nativeWorkspaceAllowed = await requestAgenticServiceApproval(
      sender,
      'claude',
      nativeDecision.service,
      payload.scope === 'global' ? undefined : payload.workspace,
      {
        method: 'claude/canUseTool',
        title:
          nativeDecision.service === 'shellCommands'
            ? 'Approve Claude shell command'
            : 'Approve Claude file change',
        body: toolName,
        runId: route.appRunId
      }
    )
    if (!claudeRunAcceptsTools()) {
      return denyInactiveRun()
    }
    return nativeWorkspaceAllowed
      ? { behavior: 'allow', updatedInput }
      : { behavior: 'deny', message: `TaskWraith denied Claude tool ${toolName}.` }
  }
  if (approvalPriority === 'allow-auto') {
    return { behavior: 'allow', updatedInput }
  }
  const service = claudeAgenticServiceForTool(toolName)
  if (!service) {
    return { behavior: 'allow', updatedInput }
  }
  // 1.0.72 — read-only hard-deny for mutating / side-effecting tools (parity with
  // the shared MCP dispatcher). Safe tools were allowed above; a mutating tool
  // under read_only that classifies as the generic mcpTools service must be
  // refused, not prompted — route it to a denied service so the gate denies it.
  const gateService =
    isReadOnlyBlockedTool(unprefixedToolName, payload.effectivePermissions, normalizedInput) &&
    service === 'mcpTools'
      ? 'shellCommands'
      : service
  const externalPathDetection = detectExternalPathForProviderApproval({
    provider: 'claude',
    appChatId: route.appChatId,
    appRunId: route.appRunId,
    toolName,
    method: 'claude/canUseTool',
    params: normalizedInput,
    workspacePath: payload.scope === 'global' ? undefined : payload.workspace
  })
  const approvalPreview = claudeToolApprovalPreview(toolName, normalizedInput, service)
  const exactCanvasEvalScript =
    gateService === 'canvasEval' &&
    isRecord(approvalPreview.params) &&
    typeof approvalPreview.params.script === 'string'
      ? approvalPreview.params.script
      : null
  let claudeCanvasEvalApproval: CanvasEvalApprovalReceipt | undefined
  const allowed = await requestAgenticServiceApproval(
    sender,
    'claude',
    gateService,
    payload.scope === 'global' ? undefined : payload.workspace,
    {
      method: 'claude/canUseTool',
      title:
        service === 'shellCommands'
          ? 'Approve Claude shell command'
          : service === 'fileChanges'
            ? 'Approve Claude file change'
            : 'Approve Claude tool call',
      body: toolName,
      preview: approvalPreview,
      runId: route.appRunId,
      ...(gateService === 'canvasEval' && exactCanvasEvalScript !== null
        ? {
            onApprovalPromptCreated: ({ approvalId }: { approvalId: string }) => {
              claudeCanvasEvalApproval = createCanvasEvalApprovalReceipt(
                exactCanvasEvalScript,
                approvalId
              )
              primeNativeCanvasCompatCorrelation({
                provider: 'claude',
                route,
                toolName: 'canvas_eval',
                source: toolNameOrRequest,
                canvasEvalApproval: claudeCanvasEvalApproval
              })
              return claudeCanvasEvalApproval
            }
          }
        : {}),
      externalPathDetection
    }
  )
  if (!claudeRunAcceptsTools()) {
    return denyInactiveRun()
  }
  return allowed
    ? { behavior: 'allow', updatedInput }
    : { behavior: 'deny', message: `TaskWraith denied Claude tool ${toolName}.` }
}

async function tryRunClaudeSdk(
  event: Electron.IpcMainInvokeEvent,
  payload: AgentRunPayload,
  sdk: any,
  route: AgentRunRoute,
  environmentAuthority: ClaudeEnvironmentAuthoritySnapshot
): Promise<boolean> {
  const query = sdk?.query || sdk?.default?.query
  if (typeof query !== 'function') return false
  const model = normalizeCliProviderModel('claude', payload.model)
  const pathToClaudeCodeExecutable = environmentAuthority.binaryPath || undefined
  if (!canStartRunTransport(runManager.get(route.appRunId)?.status, true)) return true
  const controller = new AbortController()
  cliProviderAbortControllers.set('claude', controller)
  const state: CliProviderStreamState = {
    provider: 'claude',
    sender: event.sender,
    startedAt: Date.now(),
    model,
    fallback: false,
    completed: false,
    assistantText: '',
    providerSessionId: payload.providerSessionId || null,
    approvalMode: payload.approvalMode,
    workflowMode: payload.workflowMode,
    sessionTrust: Boolean(payload.sessionTrust),
    externalPathGrants: payload.externalPathGrants,
    runtimeProfileId: payload.runtimeProfileId,
    taskWraithMcpProfileId: payload.taskWraithMcpProfileId,
    taskWraithMcpAdvertised: payload.taskWraithMcpAdvertised,
    taskWraithMcpProfileFence: payload.taskWraithMcpProfileFence,
    taskWraithMcpSeenProviderSessionIds: new Set(
      payload.providerSessionId ? [payload.providerSessionId] : []
    ),
    effectivePermissions: payload.effectivePermissions,
    effectivePermissionsSignature: payload.effectivePermissionsSignature,
    ensembleRun: payload.ensembleRun,
    ...route
  }
  const registeredSession = registerRunSession(
    'claude',
    event.sender,
    route,
    payload.scope === 'global' ? undefined : payload.workspace,
    state,
    payload.providerSessionId || null,
    true
  )
  if (!registeredSession) {
    controller.abort()
    if (cliProviderAbortControllers.get('claude') === controller) {
      cliProviderAbortControllers.delete('claude')
    }
    return true
  }
  runManager.attachAbortController(route.appRunId!, controller)
  void emitProviderCapabilityWarnings(
    event.sender,
    'claude',
    payload.workspace,
    payload.approvalMode,
    state
  )
  sendAgentCompatLine(
    event.sender,
    'claude',
    {
      type: 'init',
      session_id: state.providerSessionId || '',
      model,
      timestamp: new Date().toISOString(),
      provider: 'claude',
      fallback: false
    },
    state
  )
  const claudeUsageWarning = claudeProgrammaticUsageWarning(
    'sdk',
    environmentAuthority.hasAnthropicApiKey
  )
  if (claudeUsageWarning) {
    sendAgentCompatLine(
      event.sender,
      'claude',
      {
        type: 'provider_warning',
        provider: 'claude',
        message: claudeUsageWarning,
        runtime: 'agent-sdk',
        billingMode: 'api-key-payg',
        fallback: false
      },
      state
    )
  }

  const claudeSdkEffort = normalizeClaudeEffortFlagForModel(payload.claudeReasoningEffort, model)
  const claudeSdkThinking = claudeSdkThinkingConfigForEffort(claudeSdkEffort)
  // Phase I3 (Claude initiator): register the TaskWraith MCP server so
  // the Claude agent sees delegate_to_subthread etc. in its tool list.
  // The TaskWraith bridge is gated on the same `geminiMcpBridgeEnabled`
  // toggle Gemini/Codex use; user-managed MCP servers attach from
  // the dedicated MCP Servers settings page.
  //
  // Phase J3: ALSO pass `allowedTools` here. Previously only the CLI
  // fallback got the pre-approved list via `--allowedTools <names>`;
  // the SDK path passed `mcpServers` but no `allowedTools`, so every
  // MCP call went through the per-tool `canUseTool` approval gate and
  // Claude's reasoning often skipped them entirely. Empirically: 7
  // Claude-parented bridge subprocesses had spawned and zero of them
  // had ever logged a `tools/call` (vs. Gemini-parented bridges which
  // accounted for every tool call in the log). Mirroring the CLI's
  // pre-approval list closes the gap. Only TaskWraith's own bridge
  // tools are pre-approved; arbitrary user MCP server tools still flow
  // through Claude's normal tool-permission path.
  let claudeMcpInput = claudeTaskWraithMcpInput(
    route,
    payload.workspace,
    payload.taskWraithMcpProfileId,
    payload.taskWraithMcpAdvertised === true
  )
  let claudeSdkMcpServers = buildClaudeTaskWraithMcpServers(claudeMcpInput)
  let claudeSdkAllowedTools = claudeMcpInput.enabled
    ? buildClaudeTaskWraithAllowedToolNames(claudeMcpInput.profileId)
    : null
  const claudeSdkSettings =
    typeof payload.claudeFastMode === 'boolean' ? { fastMode: payload.claudeFastMode } : undefined
  // 1.0.71 dogfood fix: make sure the TaskWraith MCP broker socket is actually
  // listening before the SDK spawns Claude's bridge subprocess. Otherwise the
  // subprocess connects to a dead socket and Claude reports "MCP socket is
  // down", then silently degrades to its native read tools. startGeminiMcpBroker
  // is idempotent (no-op once listening), so this is cheap on every run.
  if (claudeMcpInput.enabled) {
    await startGeminiMcpBroker().catch((error) => {
      console.error('[mcp-bridge] broker ensure failed before Claude run', error)
      if (claudeRunRequiresPinnedTaskWraithMcp(payload)) {
        throw new Error(
          `The pinned TaskWraith MCP surface could not be reattached: ${
            error instanceof Error ? error.message : String(error)
          }`
        )
      }
      // The run may continue with Claude's native/user-managed tools, but it
      // must not mint a receipt or retain prompt claims for a TaskWraith server
      // that failed to attach.
      payload.taskWraithMcpAdvertised = false
      state.taskWraithMcpAdvertised = false
      payload.prompt = sanitizeTaskWraithMcpPromptClaims(payload.prompt, {
        advertised: false,
        coreProfile: false
      })
      claudeMcpInput = claudeTaskWraithMcpInput(
        route,
        payload.workspace,
        payload.taskWraithMcpProfileId,
        false
      )
      claudeSdkMcpServers = buildClaudeTaskWraithMcpServers(claudeMcpInput)
      claudeSdkAllowedTools = null
    })
  }
  if (!canStartRunTransport(runManager.get(route.appRunId)?.status, true)) {
    controller.abort()
    if (cliProviderAbortControllers.get('claude') === controller) {
      cliProviderAbortControllers.delete('claude')
    }
    return true
  }
  try {
    const stream = query({
      prompt: payload.prompt,
      options: {
        cwd: payload.workspace!,
        model: model === 'default' ? undefined : model,
        // Spike 8 (docs/ensemble-posture-fanout-preamble-design.md) —
        // Read-Only/Recon seats run in DEFAULT permission mode instead of
        // Claude Code's native plan mode: plan mode installs a plan-shaped
        // system prompt (+ ExitPlanMode) that turns review/recon turns into
        // plan artifacts. Write containment does not change: every tool call
        // (native Edit/Write/Bash included) routes through canUseClaudeSdkTool
        // below, where the run's signed read_only effectivePermissions deny
        // fileChanges/shellCommands hard — and the plan-artifact write
        // carve-out requires workflowMode 'plan', which a recon run never
        // carries. isReconRunPosture reads only post-clamp HMAC-covered
        // fields. The CLI fallback (tryRunClaudeCli) has NO canUseTool and
        // deliberately keeps native plan mode for recon seats.
        permissionMode: isReconRunPosture(payload)
          ? 'default'
          : claudePermissionModeForApproval(payload.approvalMode),
        // Built-ins cannot enforce TaskWraith's signed workspace/path boundary.
        // MCP servers are configured separately and remain available.
        tools: [],
        resume: payload.providerSessionId || undefined,
        abortController: controller,
        canUseTool: (toolNameOrRequest: unknown, input?: unknown) =>
          canUseClaudeSdkTool(event.sender, route, payload, toolNameOrRequest, input),
        // 1.0.5-S1 — Streaming parity with Codex. Without this flag the
        // SDK only yields a single cumulative `SDKAssistantMessage` per
        // turn carrying the entire response — Claude appears to "think
        // silently then dump the answer" while Codex scrolls past
        // token-by-token. With it, the SDK also yields incremental
        // `stream_event` frames (SDKPartialAssistantMessage) whose
        // content_block_delta / text_delta events carry per-chunk text.
        // extractProviderText reads those chunks; the existing dedup at
        // the call site in handleCliProviderJsonEvent harmlessly slices
        // the trailing cumulative `assistant` envelope to empty so we
        // don't double-emit the final response.
        includePartialMessages: true,
        ...(pathToClaudeCodeExecutable ? { pathToClaudeCodeExecutable } : {}),
        ...(payload.imagePaths?.length ? { images: payload.imagePaths } : {}),
        ...(claudeSdkEffort ? { effort: claudeSdkEffort } : {}),
        ...(claudeSdkThinking ? { thinking: claudeSdkThinking } : {}),
        ...(claudeSdkMcpServers ? { mcpServers: claudeSdkMcpServers } : {}),
        ...(claudeSdkAllowedTools && claudeSdkAllowedTools.length > 0
          ? { allowedTools: claudeSdkAllowedTools }
          : {}),
        ...(claudeSdkSettings ? { settings: claudeSdkSettings } : {}),
        env: environmentAuthority.env
      }
    })

    for await (const message of stream) {
      handleCliProviderJsonEvent(state, message)
    }

    if (!state.completed) {
      sendAgentCompatLine(
        event.sender,
        'claude',
        {
          type: 'result',
          status: 'success',
          stats: { ...(state.tokenUsage || {}), duration_ms: Date.now() - state.startedAt },
          provider: 'claude',
          providerThreadId: state.providerSessionId || undefined,
          fallback: false
        },
        state
      )
    }
    sendAgentCompatExit(event.sender, 'claude', 0, state)
    runManager.finish(route.appRunId, 'completed')
    return true
  } catch (error) {
    const decision = decideClaudeSdkFailure({
      error,
      signalAborted: controller.signal.aborted,
      runStatus: runManager.get(route.appRunId)?.status,
      abortErrorConstructor: sdk?.AbortError || sdk?.default?.AbortError
    })
    if (decision === 'cancelled') {
      runManager.finish(route.appRunId, 'cancelled')
      // Preserve the cancelled RunManager status, but still publish the provider
      // exit so scheduled-run, audit, bridge-transcript, and budget cleanup all
      // settle through the shared terminal path.
      sendAgentCompatExit(event.sender, 'claude', 130, state)
      return true
    }
    if (decision === 'terminal') return true
    throw error
  } finally {
    if (cliProviderAbortControllers.get('claude') === controller) {
      cliProviderAbortControllers.delete('claude')
    }
  }
}

async function prepareClaudeRunEnvironmentAuthority(
  payload: AgentRunPayload,
  route: AgentRunRoute,
  sdkAvailable: boolean
): Promise<ClaudeEnvironmentAuthoritySnapshot> {
  try {
    const prepared = resolvePreparedClaudeRunAuthority({
      payload,
      route,
      registryAudit: auditRuntime.registry.get(route.appRunId)
    })
    const resolvedBinary = await resolveCliProviderBinary(
      'claude',
      prepared.runtimeProfile,
      cliProviderRuntimeDeps
    )
    const explicitBinaryResolutionFailed =
      !resolvedBinary.binaryPath &&
      (resolvedBinary.source === 'runtime_profile' || resolvedBinary.source === 'settings')
    if (
      !resolvedBinary.binaryPath &&
      (app.isPackaged || !sdkAvailable || explicitBinaryResolutionFailed)
    ) {
      throw new ClaudeEnvironmentAuthorityError(
        resolvedBinary.error || 'Claude Code CLI was not found for the resolved runtime profile.'
      )
    }
    return prepareClaudeEnvironmentAuthority(
      {
        runtimeProfile: prepared.runtimeProfile,
        binaryPath: resolvedBinary.binaryPath,
        scope: payload.scope,
        workspace: payload.workspace,
        runId: route.appRunId,
        chatId: route.appChatId,
        apiKey: getStoredClaudeApiKey(),
        auditRun: prepared.auditRun
      },
      cliProviderRuntimeDeps
    )
  } catch (error) {
    if (error instanceof ClaudeEnvironmentAuthorityError) throw error
    throw new ClaudeEnvironmentAuthorityError(
      'The Claude launch environment could not be resolved safely.'
    )
  }
}

async function runClaudeProvider(event: Electron.IpcMainInvokeEvent, payload: AgentRunPayload) {
  const route = routeWithRunId('claude', payload)
  const sdk = await loadOptionalClaudeSdk()
  let environmentAuthority: ClaudeEnvironmentAuthoritySnapshot
  try {
    environmentAuthority = await prepareClaudeRunEnvironmentAuthority(payload, route, Boolean(sdk))
  } catch (error) {
    const message =
      error instanceof ClaudeEnvironmentAuthorityError
        ? error.message
        : 'The Claude launch environment could not be resolved safely.'
    runManager.finish(route.appRunId, 'failed')
    sendAgentCompatError(event.sender, 'claude', message, route)
    sendAgentCompatLine(
      event.sender,
      'claude',
      {
        type: 'result',
        status: 'failed',
        stats: {},
        provider: 'claude',
        setupRequired: true,
        fallback: false
      },
      route
    )
    sendAgentCompatExit(event.sender, 'claude', 1, route)
    return
  }
  const startingSession = registerRunSession(
    'claude',
    event.sender,
    route,
    payload.scope === 'global' ? undefined : payload.workspace,
    undefined,
    payload.providerSessionId || null
  )
  if (!startingSession) return
  if (!canStartRunTransport(runManager.get(route.appRunId)?.status, true)) return
  if (sdk) {
    try {
      if (await tryRunClaudeSdk(event, payload, sdk, route, environmentAuthority)) return
    } catch (error) {
      sendAgentCompatError(
        event.sender,
        'claude',
        `Claude Agent SDK failed; falling back to Claude Code CLI. Reason: ${error instanceof Error ? error.message : String(error)}`,
        route
      )
      // The failed SDK attempt may already have reported and pinned a native
      // session id. The CLI fallback still starts fresh from the original null
      // payload session, but its CAS basis must observe that exact SDK write or
      // it will reject the CLI's replacement id as stale. Keep the chosen
      // profile fixed; refresh only the expected AppStore identity.
      refreshTaskWraithMcpProfileFenceStoreIdentity(payload)
    }
    // RC2 — per-occurrence budget kill: if the SDK run was aborted BY the budget
    // kill (cancelProviderRun aborts the SDK controller), tryRunClaudeSdk throws /
    // returns false and execution would otherwise FALL THROUGH to a CLI re-run =
    // DOUBLE SPEND on a run we deliberately killed. The terminal mark already
    // happened in triggerKill; here we settle the run and publish the shared
    // terminal exit (which also clears the budget registry), then SKIP the CLI
    // fallback.
    if (route.appRunId && workflowBudgetRegistry.isKilled(route.appRunId)) {
      runManager.finish(route.appRunId, 'cancelled')
      sendAgentCompatExit(event.sender, 'claude', 130, route)
      return
    }
    // Review fix: a `/compact` dispatch is NOT safely re-runnable — if the SDK
    // stream threw AFTER the compaction executed (user stop, transient stream
    // error), a CLI re-run would compact the freshly-compacted session a
    // second time and grind away preserved detail. Fail the run instead.
    if (payload.prompt.trim() === '/compact') {
      runManager.finish(route.appRunId, 'failed')
      sendAgentCompatExit(event.sender, 'claude', 1, route)
      return
    }
  }

  if (!canStartRunTransport(runManager.get(route.appRunId)?.status, true)) return
  if (!environmentAuthority.binaryPath) {
    runManager.finish(route.appRunId, 'failed')
    sendAgentCompatError(
      event.sender,
      'claude',
      'Claude Agent SDK failed and the resolved environment has no CLI fallback binary.',
      route
    )
    sendAgentCompatLine(
      event.sender,
      'claude',
      {
        type: 'result',
        status: 'failed',
        stats: {},
        provider: 'claude',
        setupRequired: true
      },
      route
    )
    sendAgentCompatExit(event.sender, 'claude', 1, route)
    return
  }

  const model = normalizeCliProviderModel('claude', payload.model)
  const buildBaseArgs = (): string[] => [
    ...buildClaudeCliArgs({
      prompt: payload.prompt,
      // Spike 8 note: UNLIKE the SDK path, recon seats keep native plan mode
      // here — this headless CLI path has no canUseTool callback, so plan
      // mode's own no-write behavior IS the containment. A recon turn that
      // degrades to the CLI fallback accepts plan-shaped output as the
      // tradeoff. Kimi has no equivalent print fallback; managed Kimi is
      // admitted ACP-only.
      permissionMode: claudePermissionModeForApproval(payload.approvalMode),
      model,
      providerSessionId: payload.providerSessionId || null,
      claudeReasoningEffort: payload.claudeReasoningEffort || null,
      claudeFastMode: payload.claudeFastMode,
      imagePaths: payload.imagePaths || null
    }),
    // External grants are consumed only by the TaskWraith broker. Opaque
    // provider CLIs never receive widened native directory authority.
    ...externalPathGrantsToCliAddDirArgs(payload.externalPathGrants)
  ]
  let baseArgs = buildBaseArgs()
  // Phase I3 (Claude initiator): the Claude CLI does not accept the
  // SDK's `mcpServers` object directly — it expects `--mcp-config
  // <path>` pointing at a JSON file. Write a per-run config under the
  // OS temp dir, extend the argv with `--mcp-config` + `--allowedTools`,
  // and clean up the temp file when the run exits. User-managed stdio
  // servers share the same config file but do not get added to
  // --allowedTools.
  let mcpInput = claudeTaskWraithMcpInput(
    route,
    payload.workspace,
    payload.taskWraithMcpProfileId,
    payload.taskWraithMcpAdvertised === true
  )
  if (mcpInput.enabled) {
    try {
      await startGeminiMcpBroker()
    } catch (error) {
      const message = `TaskWraith MCP broker could not start for Claude: ${
        error instanceof Error ? error.message : String(error)
      }`
      if (claudeRunRequiresPinnedTaskWraithMcp(payload)) {
        runManager.finish(route.appRunId, 'failed')
        sendAgentCompatError(event.sender, 'claude', message, route)
        sendAgentCompatExit(event.sender, 'claude', 1, route)
        return
      }
      payload.taskWraithMcpAdvertised = false
      payload.prompt = sanitizeTaskWraithMcpPromptClaims(payload.prompt, {
        advertised: false,
        coreProfile: false
      })
      mcpInput = claudeTaskWraithMcpInput(
        route,
        payload.workspace,
        payload.taskWraithMcpProfileId,
        false
      )
      sendAgentCompatError(
        event.sender,
        'claude',
        `${message} Claude will continue without TaskWraith MCP for this fresh or legacy session.`,
        route
      )
    }
  }
  let mcpConfigPath: string | null = null
  let args = baseArgs
  const configJson = buildClaudeTaskWraithMcpConfigJson(mcpInput)
  if (configJson) {
    mcpConfigPath = claudeTaskWraithMcpConfigPathForRun(route.appRunId || 'unknown')
    try {
      await fs.writeFile(mcpConfigPath, JSON.stringify(configJson), {
        encoding: 'utf8',
        mode: 0o600
      })
      args = extendClaudeCliArgsWithTaskWraithMcp(baseArgs, {
        ...mcpInput,
        configFilePath: mcpConfigPath
      })
    } catch (error) {
      // Failing to write the temp file is not fatal: log + carry on
      // without MCP servers registered. We surface a warning so the
      // user can see why the Claude run does not have the expected MCP
      // tools.
      const message = `Failed to write Claude MCP config (${mcpConfigPath}); MCP servers will not be available for this run. Reason: ${error instanceof Error ? error.message : String(error)}`
      sendAgentCompatError(event.sender, 'claude', message, route)
      if (claudeRunRequiresPinnedTaskWraithMcp(payload)) {
        runManager.finish(route.appRunId, 'failed')
        sendAgentCompatExit(event.sender, 'claude', 1, route)
        return
      }
      payload.taskWraithMcpAdvertised = false
      payload.prompt = sanitizeTaskWraithMcpPromptClaims(payload.prompt, {
        advertised: false,
        coreProfile: false
      })
      mcpConfigPath = null
      baseArgs = buildBaseArgs()
      args = baseArgs
    }
  }
  const claudeUsageWarning = claudeProgrammaticUsageWarning(
    'cli-print',
    environmentAuthority.hasAnthropicApiKey
  )
  const claudeFallbackWarning = sdk
    ? 'Using Claude Code CLI fallback for this run.'
    : 'Claude Agent SDK is not bundled in this app build; using Claude Code CLI stream-json fallback for this run.'
  if (!canStartRunTransport(runManager.get(route.appRunId)?.status, true)) {
    if (mcpConfigPath) {
      await fs.unlink(mcpConfigPath).catch(() => {})
    }
    return
  }
  await runCliProviderProcess(event, 'claude', environmentAuthority.binaryPath, args, payload, {
    fallback: true,
    requireExistingRun: true,
    warning: claudeUsageWarning
      ? `${claudeFallbackWarning} ${claudeUsageWarning}`
      : claudeFallbackWarning,
    resolvedEnv: environmentAuthority.env,
    onComplete: mcpConfigPath
      ? async () => {
          try {
            await fs.unlink(mcpConfigPath!)
          } catch {
            // Best-effort cleanup; ignore missing or permission errors.
          }
        }
      : undefined
  })
}

// Managed Grok runs have one admissible one-shot transport: joined ACP. The
// legacy TASKWRAITH_GROK_ACP=0 headless path was retired because its voided CLI
// child could outlive the provider adapter and history-deletion receipt.
async function runGrokProvider(event: Electron.IpcMainInvokeEvent, payload: AgentRunPayload) {
  if (!grokAcpEnabled()) {
    const route = routeWithRunId('grok', payload)
    runManager.finish(route.appRunId, 'failed')
    sendAgentCompatError(event.sender, 'grok', GROK_ACP_REQUIRED_MESSAGE, route)
    sendAgentCompatLine(
      event.sender,
      'grok',
      {
        type: 'result',
        status: 'failed',
        stats: {},
        provider: 'grok',
        setupRequired: true,
        securityUnavailable: true
      },
      route
    )
    sendAgentCompatExit(event.sender, 'grok', 1, route)
    return
  }
  await runGrokAcpProvider(event, payload)
}

// Cursor launch history lives in git and SECURITY_ENGINEERING_LEDGER.md.
// ── Cursor TaskWraith MCP bridge ("B" mode) ─────────────────────────────────
// cursor-agent headless (`-p`) rejects every MCP tools/call as "User rejected
// MCP" unless ALL THREE hold (live qualification, commit 80b2017d4):
//   1. the broker is registered in the GLOBAL ~/.cursor/mcp.json — a per-run
//      WORKSPACE server never reaches the durable "ready" approval;
//   2. it was approved by NAME via `cursor-agent mcp enable` (the approval
//      survives the per-launch broker socket-token refresh below);
//   3. the run's argv carries `--force` so tool CALLS execute headlessly.
// This wiring was deleted by the known-broken WIP checkpoint 901b8cd5c, which
// is why Cursor seats reported "user rejected" on every broker call while
// TaskWraith policy said mcpTools:allow. Restored here with the contained
// argv (`--sandbox enabled`, prompt `--` guard) kept intact.

// `mcp enable` is spawned at most once per workspace+server per session, and
// only cached on ACTUAL success (a failed enable must not poison the cache —
// the next launch would then skip the one reliable approval recipe and reject
// every MCP call).
const cursorMcpApprovedWorkspaceServers = new Set<string>()
async function ensureCursorMcpApproved(
  binaryPath: string,
  workspace: string,
  serverName: string = CURSOR_MCP_SERVER_NAME
): Promise<void> {
  const key = `${workspace}\0${serverName}`
  if (cursorMcpApprovedWorkspaceServers.has(key)) return
  await new Promise<void>((resolve, reject) => {
    execFile(
      binaryPath,
      ['mcp', 'enable', serverName],
      { cwd: workspace, timeout: 10000 },
      (error, _stdout, stderr) => {
        if (error) {
          const detail = (String(stderr || '').trim() || error.message || '').slice(0, 300)
          reject(
            new Error(`cursor-agent mcp enable ${serverName} failed${detail ? `: ${detail}` : ''}`)
          )
          return
        }
        resolve()
      }
    )
  })
  cursorMcpApprovedWorkspaceServers.add(key)
}

// "B" mode paths: the user's GLOBAL Cursor MCP registry. This is the ONE place
// TaskWraith writes global ~/.cursor for a Cursor run (additive, only its own
// broker entries; user-owned servers are preserved by the merge).
function globalCursorMcpDir(): string {
  return join(app.getPath('home'), '.cursor')
}
function globalCursorMcpPath(): string {
  return join(globalCursorMcpDir(), 'mcp.json')
}

function cursorWorkspaceMcpAliasesGlobalRegistry(mcpPath: string): boolean {
  return canonicalPath(mcpPath) === canonicalPath(globalCursorMcpPath())
}

async function runCursorProvider(event: Electron.IpcMainInvokeEvent, payload: AgentRunPayload) {
  const route = routeWithRunId('cursor', payload)
  // The contained argv never resumes a prior chat, so keep the run state
  // honest rather than letting a stale caller claim a session is resumed.
  payload.providerSessionId = null

  const resolved = await resolveCliProviderBinary('cursor', payload.runtimeProfile)
  if (!resolved.binaryPath) {
    runManager.finish(route.appRunId, 'failed')
    sendAgentCompatError(
      event.sender,
      'cursor',
      resolved.error ||
        'Cursor CLI (cursor-agent) is not configured. Install it and run `cursor-agent login`.',
      route
    )
    sendAgentCompatLine(
      event.sender,
      'cursor',
      { type: 'result', status: 'failed', stats: {}, provider: 'cursor', setupRequired: true },
      route
    )
    sendAgentCompatExit(event.sender, 'cursor', 1, route)
    return
  }

  // ── TaskWraith MCP bridge setup ("B" mode; un-walls Cursor seats) ──
  // Without this, every broker call fails headlessly as "User rejected MCP"
  // even though TaskWraith policy allows it (pass-1 finding). Brokered tools
  // still route through TaskWraith's gateway (workspace guards + approval
  // ledger); NATIVE tools stay callable too, bounded by the argv's
  // `--sandbox enabled` — both stacks stay available, each with its own bound.
  const writeCapable = cursorWriteCapable(payload.approvalMode)
  const mcpToolsDenied = cursorMcpToolsDenied(payload.effectivePermissions)
  const cursorAdvertiseTaskWraithMcp =
    payload.taskWraithMcpAdvertised === true && !mcpToolsDenied && Boolean(payload.workspace)
  let restoreCursorConfig: (() => void) | undefined
  let cursorMcpBridgeActive = false
  if (cursorAdvertiseTaskWraithMcp) {
    try {
      const bridgeCommandStatus = taskwraithMcpBridgeCommandStatus()
      if (!bridgeCommandStatus.available) {
        throw new Error(taskwraithMcpBridgeUnavailableMessage(bridgeCommandStatus))
      }
      await mcpBridgeRuntime.startGeminiMcpBroker()
      const coreSubset = isCoreTaskWraithMcpProfile(payload.taskWraithMcpProfileId)
      const gatewaySubset = isGatewayTaskWraithMcpProfile(payload.taskWraithMcpProfileId)
      // Read-only seat: the safe-subset broker (read tools only; the bridge
      // itself fails non-safe tools/call closed). A plan-preset seat widens to
      // the host-gated plan instruments. Write seat: the full broker.
      const cursorPlanSeat = !writeCapable && payload.effectivePermissions?.presetId === 'plan'
      const brokerInvocation = {
        command: bridgeCommandStatus.command,
        args: taskwraithMcpBridgeArgs(geminiMcpSocketPath(), {
          safeSubset: !writeCapable,
          planSubset: cursorPlanSeat,
          coreSubset,
          gatewaySubset
        }),
        env: {
          [GEMINI_MCP_BRIDGE_ENV]: '1',
          TASKWRAITH_PARENT_PROVIDER: 'cursor',
          TASKWRAITH_RUN_ID: route.appRunId || '',
          TASKWRAITH_CHAT_ID: route.appChatId || '',
          TASKWRAITH_WORKSPACE_PATH: payload.scope === 'global' ? '' : payload.workspace || ''
        }
      }
      // Global registration is the only one cursor-agent durably approves;
      // refreshed each launch (repair-on-stale — the socket token rotates).
      // The legacy scoped read-only name is removed so Cursor never aggregates
      // two TaskWraith tool catalogues.
      // NOTE: the registration env carries THIS run's routing identity; two
      // Cursor seats launching in the same second can overwrite each other's
      // entry before their agent processes read it. Ensemble writer seats are
      // serial today; parallel read-only Cursor lanes are a known residual
      // race (pre-existing in the 80b2017d4 design).
      ensureGlobalCursorBrokerRegistered(
        fsSync,
        globalCursorMcpPath(),
        globalCursorMcpDir(),
        buildCursorBrokerMcpServerEntry(brokerInvocation),
        [CURSOR_SCOPED_MCP_SERVER_NAME]
      )
      // Transient workspace config (restored after the run): allow THIS
      // broker's tools, and strip workspace-registered MCP servers — under
      // `--force` those would execute ungoverned. The native-tool deny-list is
      // seat-scoped: write seats keep native shell/write (sandbox-bounded —
      // the both-stacks directive); read-only seats keep the native mutators
      // denied so read-only holds on the native stack as well as the broker.
      const cursorDir = join(payload.workspace!, '.cursor')
      const mcpPath = join(cursorDir, 'mcp.json')
      restoreCursorConfig = applyCursorWriteModeConfig(
        fsSync,
        join(cursorDir, 'cli.json'),
        cursorDir,
        {
          allowRules: writeCapable
            ? CURSOR_BROKER_MCP_ALLOW_RULES
            : cursorPlanSeat
              ? CURSOR_BROKER_PLAN_MCP_ALLOW_RULES
              : CURSOR_BROKER_READONLY_MCP_ALLOW_RULES,
          mcpConfigPath: mcpPath,
          serverEntry: {},
          ...(cursorWorkspaceMcpAliasesGlobalRegistry(mcpPath)
            ? { preserveExistingMcpServers: true }
            : {})
        },
        { denyRules: writeCapable ? [] : ['Shell(**)', 'Write(**)'] }
      )
      await ensureCursorMcpApproved(resolved.binaryPath, payload.workspace!)
      cursorMcpBridgeActive = true
    } catch (error) {
      // Degrade WITH A VISIBLE WARNING (Grok parity): the seat runs native-only
      // rather than dying — or worse, trying tools that would all reject.
      restoreCursorConfig?.()
      restoreCursorConfig = undefined
      cursorMcpBridgeActive = false
      sendAgentCompatLine(
        event.sender,
        'cursor',
        {
          type: 'provider_warning',
          provider: 'cursor',
          severity: 'warning',
          title: 'Cursor MCP bridge unavailable',
          message: `TaskWraith could not set up the MCP broker; Cursor is running with native tools only. ${
            error instanceof Error ? error.message : String(error)
          }`
        },
        route
      )
    }
  }
  payload.taskWraithMcpAdvertised = cursorMcpBridgeActive
  if (!cursorMcpBridgeActive) {
    payload.prompt = sanitizeTaskWraithMcpPromptClaims(payload.prompt, {
      advertised: false,
      coreProfile: false
    })
  }

  // Cursor is ALWAYS enabled and contained by argv — there is no per-build
  // fingerprint gate (that was brittle: provider auto-updates broke the exact-SHA
  // match and silently disabled Cursor). Containment is the native
  // `--sandbox enabled`, an HONEST PARTIAL backstop: it blocks writes to
  // $HOME-root sensitive dirs (~/.ssh, ~/.aws) for a normal project workspace,
  // but the sandbox grants the workspace's PARENT area, so a workspace placed
  // directly under $HOME leaves $HOME writable. Read-only seats add a read-only
  // `--mode` (a BRIDGED read-only seat instead runs default mode — ask/plan
  // execute no tools headlessly — contained by the transient native-mutator
  // deny-list + safe-subset broker); write-capable seats run in Cursor's
  // default (write+shell) mode, still sandboxed. The contained argv never emits
  // write-widening or sandbox-disabling flags (`--force` only with the bridge)
  // and guards the trailing prompt against flag injection. Path B inherits the
  // user's REAL ~/.cursor login via the process env (headless-verified:
  // apiKeySource "login", no key). The CursorStartupContainment canary is
  // retained as a DEV-only containment check, not a runtime gate.
  const args = writeCapable
    ? buildContainedCursorWriteArgv({
        workspace: payload.workspace!,
        prompt: payload.prompt,
        model: payload.model,
        forceAllowMcpTools: cursorMcpBridgeActive
      })
    : buildContainedCursorReadOnlyArgv({
        workspace: payload.workspace!,
        prompt: payload.prompt,
        model: payload.model,
        mode: cursorMcpBridgeActive ? null : 'ask',
        forceAllowMcpTools: cursorMcpBridgeActive
      })

  // extraEnv (NOT resolvedEnv): createCliEnv inherits the REAL process.env (real
  // HOME + real ~/.cursor → the user's login works) and auto-injects the
  // TASKWRAITH_* keys. `--sandbox enabled` is enforced via argv, not env; no
  // CURSOR_CONFIG_DIR/CURSOR_DATA_DIR override (Path B = real config).
  await runCliProviderProcess(event, 'cursor', resolved.binaryPath, args, payload, {
    fallback: false,
    extraEnv: {},
    onComplete: () => restoreCursorConfig?.()
  })
}

// 1.0.6-G4/G6 — Grok over ACP (`grok agent stdio`, bidirectional
// JSON-RPC). GrokAcpClient drives initialize → session/new → session/prompt and
// streams session/update onto the shared Grok run-event sink
// (applyGrokRunEvent). This is the only managed one-shot Grok transport.
// Write-capable seats receive the brokered TaskWraith MCP server; read-only
// scoped seats use a distinct server name so the permission-allow check below
// can identify safe-subset tool calls.

function normalizeGrokStopReason(status: string | null | undefined): 'success' | string {
  const raw = typeof status === 'string' ? status.trim() : ''
  const normalized = raw.toLowerCase().replace(/[\s_-]+/g, '')
  if (
    !normalized ||
    normalized === 'success' ||
    normalized === 'endturn' ||
    normalized === 'stop'
  ) {
    return 'success'
  }
  return raw || 'failed'
}

function grokAcpNetworkReadRequested(request: {
  toolName?: string
  toolKind?: string
  rawToolCall?: unknown
}): boolean {
  const raw = request.rawToolCall as
    | { rawInput?: { tool_name?: unknown; name?: unknown } }
    | undefined
  const candidates = [
    request.toolKind,
    request.toolName,
    raw?.rawInput?.tool_name,
    raw?.rawInput?.name
  ]
  return candidates.some((candidate) => {
    if (typeof candidate !== 'string') return false
    const normalized = candidate.toLowerCase().replace(/[\s:_-]+/g, '')
    return (
      normalized === 'fetch' ||
      normalized === 'search' ||
      normalized === 'webfetch' ||
      normalized === 'websearch'
    )
  })
}

function grokNetworkAccessAllowed(state: CliProviderStreamState): boolean {
  const policy =
    state.effectivePermissions?.networkAccess ||
    AppStore.getSettings().agenticServices?.networkAccess ||
    'allow'
  return policy !== 'deny'
}

function grokAcpEmptyToolFailureMessage(state: CliProviderStreamState): string {
  const rawDetail = state.grokLastToolError?.trim() || ''
  const detail = rawDetail.length > 500 ? `${rawDetail.slice(0, 497)}...` : rawDetail
  return `Grok ended this turn without producing an assistant response after a tool failed or was rejected.${
    detail ? ` Last tool error: ${detail}` : ''
  }`
}

// Spike 7 — one persistent-seat registry for the app lifetime. Entries are
// keyed `${chatId}:${participantId}`, reaped lazily on acquire (30-min idle
// TTL), and disposed on will-quit.
const grokSeatSessionRegistry = new GrokSeatSessionRegistry()

async function runGrokAcpProvider(event: Electron.IpcMainInvokeEvent, payload: AgentRunPayload) {
  const route = routeWithRunId('grok', payload)
  const resolved = await resolveCliProviderBinary('grok', payload.runtimeProfile)
  if (!resolved.binaryPath) {
    runManager.finish(route.appRunId, 'failed')
    sendAgentCompatError(
      event.sender,
      'grok',
      resolved.error || 'Grok CLI is not configured.',
      route
    )
    sendAgentCompatLine(
      event.sender,
      'grok',
      { type: 'result', status: 'failed', stats: {}, provider: 'grok', setupRequired: true },
      route
    )
    sendAgentCompatExit(event.sender, 'grok', 1, route)
    return
  }
  const binaryPath = resolved.binaryPath
  const model = normalizeCliProviderModel('grok', payload.model)
  const state: CliProviderStreamState = {
    provider: 'grok',
    sender: event.sender,
    startedAt: Date.now(),
    model,
    fallback: false,
    completed: false,
    assistantText: '',
    providerSessionId: payload.providerSessionId || null,
    approvalMode: payload.approvalMode,
    workflowMode: payload.workflowMode,
    sessionTrust: Boolean(payload.sessionTrust),
    externalPathGrants: payload.externalPathGrants,
    runtimeProfileId: payload.runtimeProfileId,
    taskWraithMcpProfileId: payload.taskWraithMcpProfileId,
    taskWraithMcpAdvertised: payload.taskWraithMcpAdvertised,
    taskWraithMcpProfileFence: payload.taskWraithMcpProfileFence,
    effectivePermissions: payload.effectivePermissions,
    effectivePermissionsSignature: payload.effectivePermissionsSignature,
    ensembleRun: payload.ensembleRun,
    ...route
  }
  let grokOwnedProcess: ChildProcess | null = null
  const registeredSession = registerRunSession(
    'grok',
    event.sender,
    route,
    payload.scope === 'global' ? undefined : payload.workspace,
    state,
    payload.providerSessionId || null
  )
  if (!registeredSession) return
  sendAgentCompatLine(
    event.sender,
    'grok',
    {
      type: 'init',
      session_id: state.providerSessionId || '',
      model,
      timestamp: new Date().toISOString(),
      provider: 'grok',
      fallback: false
    },
    state
  )

  if (payload.workspace) {
    try {
      const sweep = sweepGrokProjectTaskWraithMcpRegistrations(
        app.getPath('home'),
        payload.workspace
      )
      if (
        sweep.removed.length > 0 &&
        ['1', 'true', 'yes'].includes(String(process.env.TASKWRAITH_GROK_DEBUG || '').toLowerCase())
      ) {
        process.stderr.write(
          `[grok-mcp] swept stale project MCP registrations ${JSON.stringify(sweep.removed)} from ${sweep.mcpDir || 'unknown'}\n`
        )
      }
    } catch (error) {
      if (
        ['1', 'true', 'yes'].includes(String(process.env.TASKWRAITH_GROK_DEBUG || '').toLowerCase())
      ) {
        process.stderr.write(
          `[grok-mcp] stale registration sweep failed: ${error instanceof Error ? error.message : String(error)}\n`
        )
      }
    }
  }

  // G5b/G6 — advertise TaskWraith MCP tools via ACP `session/new`.
  // Write-capable seats receive the full brokered TaskWraith server: mutating
  // MCP tools still route through executeGeminiMcpTool, which applies the
  // TaskWraith approval ledger, workspace/path checks, and write locks before
  // any side effect. Write-capable Grok seats auto-inject this scoped broker even
  // when the legacy bridge preference is off; read-only seats stay conservative
  // and only receive the safe subset when the preference + read-only advertise
  // flag are explicitly enabled.
  let grokMcpServers: unknown[] = []
  const grokWriteSeat = grokWriteCapable(payload.approvalMode)
  const grokReadOnlySeat = !grokWriteSeat
  const grokReadOnlyAdvertiseFlag = grokReadOnlyMcpAdvertiseEnabled()
  const grokBridgeEnabled = Boolean(AppStore.getSettings().geminiMcpBridgeEnabled)
  const grokAdvertiseTaskWraithMcp = payload.taskWraithMcpAdvertised === true
  const grokMcpDebug = process.env.TASKWRAITH_GROK_DEBUG
  if (grokMcpDebug === '1' || grokMcpDebug === 'true' || grokMcpDebug === 'yes') {
    process.stderr.write(
      `[grok-mcp] bridge gate advertise=${grokAdvertiseTaskWraithMcp} bridgeEnabled=${grokBridgeEnabled} writeSeat=${grokWriteSeat} readOnlyAdvertiseFlag=${grokReadOnlyAdvertiseFlag} writeSeatAutoBridge=${grokWriteSeat && !grokBridgeEnabled} approvalMode=${JSON.stringify(payload.approvalMode)} resume=${Boolean(payload.providerSessionId)}\n`
    )
  }
  if (grokAdvertiseTaskWraithMcp) {
    try {
      const bridgeCommandStatus = taskwraithMcpBridgeCommandStatus()
      if (!bridgeCommandStatus.available) {
        throw new Error(taskwraithMcpBridgeUnavailableMessage(bridgeCommandStatus))
      }
      await mcpBridgeRuntime.startGeminiMcpBroker()
      const safeSubset = grokReadOnlySeat
      // Plan-tier seat: a plan-preset (not read_only) Grok seat widens the safe
      // subset to the plan instruments (canvas actuation + media), which the broker
      // then host-gates (canvasInteraction/mediaEditing = 'ask' under plan). A
      // read_only seat stays on the strict subset. Only meaningful when safeSubset
      // is set (a write-capable seat already advertises the full brokered server).
      const grokPlanSeat = safeSubset && payload.effectivePermissions?.presetId === 'plan'
      // Audit role-run: also advertise the audit_* tool namespace to Grok's
      // per-turn ACP bridge. Grok's bridge env is an explicit ACP list (not
      // inherited), so set BOTH the --audit-subset arg (appended LAST, after the
      // safe-subset flag, so the socket/token index parsing is unaffected) and
      // the matching env entry. (Read-only Grok shares the plan-mode bridge gap;
      // this only takes effect when the bridge is actually advertised above.)
      const grokAuditRun = Boolean(payload.auditRun)
      const coreSubset = isCoreTaskWraithMcpProfile(payload.taskWraithMcpProfileId)
      const gatewaySubset = isGatewayTaskWraithMcpProfile(payload.taskWraithMcpProfileId)
      const grokBridgeArgs = taskwraithMcpBridgeArgs(geminiMcpSocketPath(), {
        safeSubset,
        planSubset: grokPlanSeat,
        coreSubset,
        gatewaySubset
      })
      grokMcpServers = [
        {
          // ACP McpServer is an UNTAGGED enum: the stdio variant is
          // {name, command, args, env} with NO `type` field and env REQUIRED. A
          // stray `type:'stdio'` makes it match no variant (-32602 Invalid
          // params, which also hangs the turn). env carries the routing identity
          // in the ACP EnvVariable shape ({name,value}) so broker calls map to
          // THIS run.
          name: safeSubset ? GROK_SCOPED_MCP_SERVER_NAME : GEMINI_MCP_SERVER_NAME,
          command: bridgeCommandStatus.command,
          args: grokAuditRun ? [...grokBridgeArgs, GEMINI_MCP_AUDIT_SUBSET_ARG] : grokBridgeArgs,
          env: [
            { name: GEMINI_MCP_BRIDGE_ENV, value: '1' },
            { name: 'TASKWRAITH_PARENT_PROVIDER', value: 'grok' },
            { name: 'TASKWRAITH_RUN_ID', value: route.appRunId || '' },
            { name: 'TASKWRAITH_CHAT_ID', value: route.appChatId || '' },
            {
              name: 'TASKWRAITH_WORKSPACE_PATH',
              value: payload.scope === 'global' ? '' : payload.workspace || ''
            },
            ...(grokAuditRun ? [{ name: 'TASKWRAITH_MCP_AUDIT', value: '1' }] : [])
          ]
        }
      ]
    } catch (error) {
      // Broker failed to start → no tools (safe). Grok still runs, just toolless.
      grokMcpServers = []
      payload.taskWraithMcpAdvertised = false
      state.taskWraithMcpAdvertised = false
      payload.prompt = sanitizeTaskWraithMcpPromptClaims(payload.prompt, {
        advertised: false,
        coreProfile: false
      })
      sendAgentCompatLine(
        event.sender,
        'grok',
        {
          type: 'provider_warning',
          provider: 'grok',
          severity: 'warning',
          title: 'Grok MCP bridge unavailable',
          message: `TaskWraith could not start the MCP broker; Grok is running without TaskWraith MCP tools. ${
            error instanceof Error ? error.message : String(error)
          }`
        },
        state
      )
    }
  }

  // Read-only seat: deny Grok's mutating tools at the CLI (Claude-Code-style
  // --deny, single-sourced with the headless path) so Grok never ATTEMPTS them.
  // Without this, Grok tries a write/shell tool, the host gate rejects it, and
  // Grok treats the bare reject as a FATAL turn cancel (stopReason: cancelled /
  // PermissionRejected) — abandoning the turn without answering from the reads
  // it already did. Preventing the attempt is the fix; the onPermissionRequest
  // gate stays as defense-in-depth. Reads stay available. NOTE: deliberately NOT
  // --permission-mode plan here — over ACP that can route exit_plan_mode through
  // a permission request our read-only gate would deny, re-triggering the cancel.
  const grokAcpArgs = buildGrokAcpCliArgs({
    model,
    reasoningEffort: payload.reasoningEffort,
    readOnlySeat: grokReadOnlySeat
  })

  const grokSpawnAcpProcess = (): AcpChildProcess => {
    const child = spawn(binaryPath, grokAcpArgs, {
      cwd: payload.workspace!,
      shell: false,
      env: createCliEnv(
        {
          FORCE_COLOR: '0',
          NO_COLOR: '1',
          TASKWRAITH_PARENT_PROVIDER: 'grok',
          // Spike 7 note: for a persistent SEAT session this run-id env stamp
          // goes stale after the first turn. That is inert by construction —
          // seat sessions are TOOLLESS (no bridge child ever inherits it).
          TASKWRAITH_RUN_ID: route.appRunId || '',
          TASKWRAITH_CHAT_ID: route.appChatId || '',
          TASKWRAITH_WORKSPACE_PATH: payload.scope === 'global' ? '' : payload.workspace || ''
        },
        binaryPath
      )
    })
    // NOTE: do NOT end stdin — ACP keeps the stdio channel open for requests.
    return child as unknown as AcpChildProcess
  }

  // G5c-ACP — client-mediated tool approval. Grok asks before running a
  // permission-requiring tool (shell/edit/…) via session/request_permission;
  // route it through TaskWraith's approval ledger (the same card + policy +
  // audit path Claude/Codex use). Read-only (plan / unset) never allows a
  // tool. requestAgenticServiceApproval resolves the policy (auto-allow on a
  // prior session/workspace grant, else prompt) and returns the boolean.
  // The G5a transport seam turns 'deny' into a rejected outcome, so nothing
  // runs without an explicit allow — no silent shell.
  const grokPermissionHandler = async (request: AcpPermissionRequest) => {
    // Grok may qualify this bridge as taskwraith-grok OR taskwraith-broker.
    // Strip either trusted namespace, then fail closed against the immutable
    // safe set before allowing it on a read-only seat.
    if (grokTaskWraithSafeToolRequested(request)) return 'allow'
    const networkRead = grokAcpNetworkReadRequested(request)
    if (networkRead && !grokNetworkAccessAllowed(state)) return 'deny'
    const nativeWorkspacePreflight = preflightNativeWorkspaceTool({
      toolName: request.toolName,
      toolKind: request.toolKind,
      rawToolCall: request.rawToolCall,
      workspacePath: payload.scope === 'global' ? undefined : payload.workspace,
      // Grok ACP exposes a permission hook but no hard native-shell workspace
      // sandbox. File tools can be path-preflighted; shell stays fail-closed
      // until the runtime can attest a workspace-rooted sandbox.
      runtimeSandboxed: false
    })
    if (nativeWorkspacePreflight.kind === 'deny') return 'deny'
    if (!grokWriteCapable(payload.approvalMode)) {
      if (networkRead) return 'allow'
      if (
        nativeWorkspacePreflight.kind === 'allow' &&
        nativeWorkspacePreflight.access === 'read'
      ) {
        return 'allow'
      }
      // Native shell has already failed closed above because this runtime has
      // no workspace-rooted shell sandbox. Unknown/non-workspace calls stay
      // denied under read-only posture.
      return 'deny'
    }
    const service =
      nativeWorkspacePreflight.kind === 'allow'
        ? nativeWorkspacePreflight.service
        : grokToolKindToService(request.toolKind)
    const allowed = await requestAgenticServiceApproval(
      event.sender,
      'grok',
      service,
      payload.scope === 'global' ? undefined : payload.workspace,
      {
        method: `grok/${request.toolKind || 'tool'}`,
        title: `Grok wants to run: ${request.toolName}`,
        body: `Grok requested a "${request.toolName}" tool call (${service}). Approve to let it run, or deny to block it.`,
        runId: route.appRunId
      }
    )
    return allowed ? 'allow' : 'deny'
  }

  let grokTransportCloseResolved = false
  let resolveGrokTransportClose!: () => void
  const grokTransportClose = new Promise<void>((resolve) => {
    resolveGrokTransportClose = resolve
  })
  const finishGrokAcpTurn = (
    code: number | null,
    turnComplete: boolean,
    terminalStatus?: string
  ): void => {
    try {
      if (!state.completed) {
        state.completed = true
        const stopReason = normalizeGrokStopReason(terminalStatus)
        if (stopReason !== 'success') state.grokStopReason = stopReason
        const emptyAfterToolFailure =
          turnComplete &&
          stopReason === 'success' &&
          state.assistantText.trim().length === 0 &&
          (state.grokToolErrorCount || 0) > 0
        const failed = !turnComplete || stopReason !== 'success' || emptyAfterToolFailure
        if (failed) {
          const message =
            stopReason !== 'success'
              ? `Grok stopped before finishing this turn (stopReason: ${stopReason}). It may not have produced an answer or written files.`
              : grokAcpEmptyToolFailureMessage(state)
          sendAgentCompatError(event.sender, 'grok', message, state)
        }
        // Grok (ACP path too) reports no usage — project tokens + cost so it
        // appears in the composer tally / dashboard, mirroring the headless
        // path's close handler.
        if (!state.tokenUsage) {
          state.tokenUsage = estimateProjectedTokenUsage(payload.prompt, state.assistantText)
        }
        sendAgentCompatLine(
          event.sender,
          'grok',
          {
            type: 'result',
            status: failed ? 'failed' : 'success',
            stats: { ...(state.tokenUsage || {}), duration_ms: Date.now() - state.startedAt },
            provider: 'grok',
            providerThreadId: state.providerSessionId || undefined,
            ...(stopReason !== 'success' ? { stopReason } : {}),
            fallback: false
          },
          state
        )
        sendAgentCompatExit(
          event.sender,
          'grok',
          failed ? 1 : turnComplete ? 0 : (code ?? 1),
          state
        )
      }
      deleteCliProviderProcessIfOwned(cliProviderProcesses, 'grok', grokOwnedProcess)
      grokOwnedProcess = null
      const finalStopReason = normalizeGrokStopReason(terminalStatus)
      const finalFailed =
        !turnComplete ||
        finalStopReason !== 'success' ||
        (state.assistantText.trim().length === 0 && (state.grokToolErrorCount || 0) > 0)
      runManager.finish(route.appRunId!, finalFailed ? 'failed' : 'completed')
    } finally {
      if (!grokTransportCloseResolved) {
        grokTransportCloseResolved = true
        resolveGrokTransportClose()
      }
    }
  }

  const grokProviderPrompt = buildGrokProviderPrompt(
    payload.prompt,
    payload.approvalMode,
    payload.activeGoal,
    {
      taskWraithQuestionToolAvailable: grokMcpServers.length > 0,
      taskWraithShellToolAvailable:
        grokMcpServers.length > 0 && grokWriteCapable(payload.approvalMode)
    }
  )
  // Broker startup and prompt composition await after run registration. A
  // destructive-history fence can terminalize that run while those awaits are
  // pending; never spawn a fresh ACP child after its exact authority is gone.
  if (!providerRunPersistenceAuthorized('grok', state)) return

  // Legacy Spike 7 persistent per-seat ACP session implementation. The gate is
  // hard-disabled until durable child identity + joined history-clear close
  // evidence ships. Eligibility remains deliberately
  // narrow: an ensemble seat (stable participantId to key on), READ-ONLY, and
  // TOOLLESS (grokMcpServers empty — the bridge env bakes TASKWRAITH_RUN_ID
  // into session/new, so a reused session would route broker approvals to a
  // stale run; toolless seats have no consumer of the stale stamp). The
  // fingerprint covers binary + argv (incl. read-only deny rules) + cwd, so a
  // posture/model change disposes the old process instead of riding it.
  const grokSeatParticipantId = payload.ensembleRun?.participantId
  if (
    grokSeatSessionsEnabled() &&
    grokSeatParticipantId &&
    grokReadOnlySeat &&
    grokMcpServers.length === 0
  ) {
    const seatKey = `${route.appChatId || 'chat'}:${grokSeatParticipantId}`
    const seatFingerprint = JSON.stringify([binaryPath, grokAcpArgs, payload.workspace])
    const { session, reused } = grokSeatSessionRegistry.acquire(seatKey, seatFingerprint, () => ({
      cwd: payload.workspace!,
      spawnProcess: grokSpawnAcpProcess,
      onRawFrame: (direction, message) => maybeLogGrokRawAcp(direction, message)
    }))
    const seatProcess = session.process() as unknown as ChildProcess
    runManager.attachProcess(route.appRunId!, seatProcess)
    grokOwnedProcess = seatProcess
    cliProviderProcesses.set('grok', seatProcess)
    if (reused) {
      applyGrokRunEvent(state, {
        type: 'provider_warning',
        text: 'Grok seat session resumed — this turn continues the seat’s live ACP session (provider-native memory).'
      })
    }
    const seatTurnHandle = session.runTurn({
      prompt: grokProviderPrompt,
      onEvent: (evt) => applyGrokRunEvent(state, evt),
      onPermissionRequest: grokPermissionHandler,
      onTurnEnd: (turnComplete, terminalStatus, processExited) =>
        finishGrokAcpTurn(processExited && !turnComplete ? 1 : 0, turnComplete, terminalStatus)
    })
    runManager.attachAbortController(route.appRunId!, createGrokTurnAbortController(seatTurnHandle))
    providerTransportOperations.track(route.appRunId!, grokTransportClose)
    return
  }

  const grokAcpHandle = runGrokAcpTurn({
    // Read-only seat: prepend the read-only steer so Grok answers from
    // read/inspection tools instead of attempting a write the host gate will
    // refuse — a refused write makes Grok hard-cancel and dead-end with no
    // answer. Write-capable seats get the WRITE steer (use Write/Edit, adapt
    // rather than end the turn on a refusal). Every ACP turn opens a fresh
    // session/new (no Grok-side resume threads through here), so the steer must
    // ride each turn's prompt; there's no prior turn for Grok to remember it
    // from, hence no redundant re-injection to avoid.
    prompt: grokProviderPrompt,
    cwd: payload.workspace!,
    mcpServers: grokMcpServers,
    spawnProcess: grokSpawnAcpProcess,
    onProcess: (child) => {
      const proc = child as unknown as ChildProcess
      runManager.attachProcess(route.appRunId!, proc)
      grokOwnedProcess = proc
      cliProviderProcesses.set('grok', proc)
    },
    onPermissionRequest: grokPermissionHandler,
    onEvent: (evt) => applyGrokRunEvent(state, evt),
    onRawFrame: (direction, message) => maybeLogGrokRawAcp(direction, message),
    onClose: finishGrokAcpTurn
  })
  runManager.attachAbortController(route.appRunId!, createGrokTurnAbortController(grokAcpHandle))
  providerTransportOperations.track(route.appRunId!, grokAcpHandle.closed)
  // Keep the adapter invocation itself live from dispatch registration through
  // the real child close. History deletion may begin before the transport
  // operation is published above; its adapter join must cover that setup race.
  await grokAcpHandle.closed
}

/**
 * Phase I3 (Claude initiator): stable per-run path for the temp JSON
 * file consumed by `claude --mcp-config <path>`. Uses `os.tmpdir()`
 * (resolved via `app.getPath('temp')` when Electron is available so
 * macOS sandboxed builds get the right per-app temp dir).
 */
function claudeTaskWraithMcpConfigPathForRun(runId: string): string {
  const tempDir = (() => {
    try {
      return app.getPath('temp')
    } catch {
      return os.tmpdir()
    }
  })()
  const safeRunId = String(runId)
    .replace(/[^A-Za-z0-9._-]/g, '_')
    .slice(0, 80)
  return join(tempDir, `taskwraith-claude-mcp-${safeRunId}.json`)
}

function respondToKimiWireRequest(child: ChildProcess, requestId: string | number, result: any) {
  child.stdin?.write(JSON.stringify({ jsonrpc: '2.0', id: requestId, result }) + '\n')
}

/** Per-run isolated KIMI_CODE_HOME dir path for legacy/non-chat ACP probes. */
function kimiIsolatedHomeDirForRun(runId: string): string {
  const tempDir = (() => {
    try {
      return app.getPath('temp')
    } catch {
      return os.tmpdir()
    }
  })()
  const safeRunId = String(runId)
    .replace(/[^A-Za-z0-9._-]/g, '_')
    .slice(0, 80)
  return join(tempDir, `taskwraith-kimi-home-${safeRunId}-${randomUUID()}`)
}

/**
 * Stable, isolated KIMI_CODE_HOME for one TaskWraith Kimi seat. Kimi Code keeps
 * its resumable context under this root, so solo chats and ensemble participants
 * must never share it. The digest avoids exposing chat titles/ids as filesystem
 * names and bounds the path length. Runtime credentials/config are stripped by
 * KimiAcpHome after every turn; only native session state remains at rest.
 */
function kimiAcpSeatHomeDirForIdentity(chatId: string, participantId = 'solo'): string {
  return kimiAcpSeatStatePath(app.getPath('userData'), chatId, participantId)
}

function kimiAcpSeatHomeDir(payload: AgentRunPayload): string {
  if (isExecutionGraphIsolatedPayload(payload)) {
    return kimiIsolatedHomeDirForRun(payload.appRunId || 'unknown')
  }
  if (!payload.appChatId) return kimiIsolatedHomeDirForRun(payload.appRunId || 'unknown')
  return kimiAcpSeatHomeDirForIdentity(
    payload.appChatId,
    payload.ensembleRun?.participantId || 'solo'
  )
}

/** node fs adapter for the isolated-home builder (KimiAcpHome). */
const kimiHomeFsAdapter: KimiHomeFs = {
  readFile: (path) => fs.readFile(path, 'utf8'),
  writeFile: (path, data, mode) => fs.writeFile(path, data, { encoding: 'utf8', mode }),
  mkdir: async (path) => {
    await fs.mkdir(path, { recursive: true })
  },
  copyFile: (from, to) => fs.copyFile(from, to),
  chmod: (path, mode) => fs.chmod(path, mode),
  exists: async (path) => {
    try {
      await fs.access(path)
      return true
    } catch {
      return false
    }
  },
  rm: (path) => fs.rm(path, { recursive: true, force: true }),
  join: (...parts) => join(...parts),
  readdir: (path) => fs.readdir(path),
  lstat: (path) => fs.lstat(path),
  realpath: (path) => fs.realpath(path),
  acquireOAuthCredentialLease: acquireKimiOAuthCredentialLease
}

/** Node fs adapter for the TaskWraith-owned per-run synthetic Kimi cwd. */
const kimiPrivateCwdFsAdapter: KimiPrivateCwdFs = {
  mkdir: async (path) => {
    await fs.mkdir(path, { recursive: true, mode: 0o700 })
  },
  mkdtemp: (prefix) => fs.mkdtemp(prefix),
  chmod: (path, mode) => fs.chmod(path, mode),
  lstat: (path) => fs.lstat(path),
  realpath: (path) => fs.realpath(path),
  readdir: (path) => fs.readdir(path),
  rm: (path) => fs.rm(path, { recursive: true, force: true })
}

/** Stream an ACP run event from a Kimi ACP turn to the renderer. Mirrors
 *  applyGrokRunEvent (provider-agnostic renderer shape), tagged 'kimi'. */
function flushKimiAcpThinking(state: CliProviderStreamState): void {
  flushKimiThinkingChunks(state, (text) => emitCliProviderThinkingEvent(state, text))
}

function applyKimiAcpRunEvent(state: CliProviderStreamState, evt: NormalizedGrokRunEvent): void {
  if (evt.type !== 'thinking') flushKimiAcpThinking(state)
  if (evt.sessionId) {
    updateCliProviderSession(state, evt.sessionId)
    persistKimiAcpNativeSession(state, evt.sessionId)
    sendAgentCompatLine(
      state.sender,
      'kimi',
      {
        type: 'init',
        session_id: evt.sessionId,
        model: state.model,
        timestamp: new Date().toISOString(),
        provider: 'kimi',
        fallback: false,
        kimi_acp_native_session: true,
        kimi_acp_posture_version: KIMI_ACP_PRODUCTION_POSTURE_VERSION
      },
      state
    )
  }
  if (evt.type === 'content' && evt.text) {
    state.assistantText = `${state.assistantText || ''}${evt.text}`
    state.kimiUsageOutputChars = (state.kimiUsageOutputChars || 0) + evt.text.length
    sendAgentCompatLine(
      state.sender,
      'kimi',
      { type: 'content', text: evt.text, provider: 'kimi' },
      state
    )
  } else if (evt.type === 'thinking' && evt.text) {
    state.kimiUsageOutputChars = (state.kimiUsageOutputChars || 0) + evt.text.length
    queueKimiThinkingChunk(state, evt.text, (text) => emitCliProviderThinkingEvent(state, text))
  } else if (evt.type === 'tool_use') {
    state.kimiUsageOutputChars =
      (state.kimiUsageOutputChars || 0) +
      (evt.toolName || '').length +
      kimiAcpVisiblePayloadChars(evt.toolInput)
    sendAgentCompatLine(
      state.sender,
      'kimi',
      {
        type: 'tool_use',
        tool_id: evt.toolId || `kimi-tool-${randomUUID()}`,
        tool_name: evt.toolName || 'tool',
        tool_kind: evt.toolKind,
        parameters: evt.toolInput || {},
        provider: 'kimi'
      },
      state
    )
  } else if (evt.type === 'tool_result') {
    state.kimiUsageInputChars =
      (state.kimiUsageInputChars || 0) + kimiAcpVisiblePayloadChars(evt.toolOutput)
    sendAgentCompatLine(
      state.sender,
      'kimi',
      {
        type: 'tool_result',
        tool_id: evt.toolId || `kimi-tool-${randomUUID()}`,
        status: evt.toolStatus || 'success',
        output: evt.toolOutput || '',
        provider: 'kimi'
      },
      state
    )
  } else if (evt.type === 'provider_warning' && evt.text) {
    sendAgentCompatError(state.sender, 'kimi', evt.text, state)
  }
  // 'result' terminal status is synthesized by the close handler (mirrors Grok).
}

/**
 * Kimi Code ACP provider (gated behind kimiAcpEnabled()). The provider process
 * and ACP session both receive a TaskWraith-owned empty synthetic cwd, advertise
 * no client fs capability, and statically deny every native fs/exec/egress/
 * fan-out tool. The real workspace is reachable only through the mandatory
 * governed TaskWraith HTTP MCP gateway. Durable native sessions live in the v2
 * seat-home namespace; v1 real-workspace-cwd sessions are never resumed.
 */
async function runKimiAcpProvider(
  event: Electron.IpcMainInvokeEvent,
  payload: AgentRunPayload,
  admittedRuntime: AdmittedKimiRuntime
): Promise<void> {
  const route = routeWithRunId('kimi', payload)
  const graphContextIsolated = isExecutionGraphIsolatedPayload(payload)

  const model = normalizeCliProviderModel('kimi', payload.model)
  const kimiThinkingConfig = kimiAcpThinkingConfigValue(model, payload.reasoningEffort)
  const kimiModelConfig = kimiAcpModelConfigValue(model, payload.serviceTier)

  // Build the isolated home BEFORE registering the run so a fail-closed
  // not-authenticated / build error surfaces as setup-required without a
  // half-started run.
  const preserveKimiSessionState = !graphContextIsolated && Boolean(payload.appChatId)
  const kimiHomeDir = kimiAcpSeatHomeDir(payload)
  const home = await prepareKimiIsolatedHome({
    runId: route.appRunId || 'unknown',
    homeDir: kimiHomeDir,
    boundaryRoot: preserveKimiSessionState
      ? kimiAcpSeatStateRoot(app.getPath('userData'))
      : kimiHomeDir,
    sourceHome: join(os.homedir(), '.kimi-code'),
    // Both current models advertise always_thinking. K3 additionally accepts
    // Low/High/Max, applied to fresh sessions through the isolated config and
    // re-asserted below when resuming a native session.
    thinkingEnabled: true,
    ...(kimiThinkingConfig === 'on' ? {} : { thinkingEffort: kimiThinkingConfig }),
    selectedModelAlias: kimiModelConfig,
    preserveSessionState: preserveKimiSessionState,
    strictCleanup: preserveKimiSessionState,
    fs: kimiHomeFsAdapter
  })
  if (!home.ok) {
    sendAgentCompatError(event.sender, 'kimi', home.message, route)
    sendAgentCompatLine(event.sender, 'kimi', {
      type: 'result',
      status: 'failed',
      stats: {},
      provider: 'kimi',
      setupRequired: home.reason === 'not-authenticated'
    })
    sendAgentCompatExit(event.sender, 'kimi', 1, route)
    runManager.finish(route.appRunId, 'failed')
    return
  }

  let privateCwd: KimiPrivateRunCwd
  try {
    privateCwd = await prepareKimiPrivateRunCwd({
      isolatedHome: home.home,
      fs: kimiPrivateCwdFsAdapter
    })
  } catch (error) {
    await home.cleanup()
    const message = `Kimi's private runtime cwd could not be created; the provider was not started. ${
      error instanceof Error ? error.message : String(error)
    }`
    sendAgentCompatError(event.sender, 'kimi', message, route)
    sendAgentCompatLine(event.sender, 'kimi', {
      type: 'result',
      status: 'failed',
      stats: {},
      provider: 'kimi'
    })
    sendAgentCompatExit(event.sender, 'kimi', 1, route)
    runManager.finish(route.appRunId, 'failed')
    return
  }

  const persistedSeat = providerSeatStoreTarget(
    payload.appChatId,
    'kimi',
    payload.ensembleRun?.participantId
  )
  const persistedPostureVersion = (() => {
    if (!persistedSeat || persistedSeat.linkedProviderSessionId !== payload.providerSessionId) {
      return undefined
    }
    if (persistedSeat.participantId) {
      return persistedSeat.chat.ensemble?.participants.find(
        (participant) => participant.id === persistedSeat.participantId
      )?.kimiAcpPostureVersion
    }
    return persistedSeat.chat.providerMetadata?.kimiAcpPostureVersion
  })()
  const productionSession = buildKimiProductionSessionPlan({
    prompt: payload.prompt,
    resumeFallbackPrompt: payload.resumeFallbackPrompt,
    requestedResumeSessionId: payload.providerSessionId,
    persistedPostureVersion
  })
  if (productionSession.legacyResumeRejected && payload.prompt.trim() === '/compact') {
    await Promise.allSettled([privateCwd.cleanup(), home.cleanup()])
    const message =
      'This Kimi session predates the synthetic-cwd containment boundary and cannot be resumed for native compaction. Start a new Kimi turn first.'
    sendAgentCompatError(event.sender, 'kimi', message, route)
    sendAgentCompatLine(event.sender, 'kimi', {
      type: 'result',
      status: 'failed',
      stats: {},
      provider: 'kimi'
    })
    sendAgentCompatExit(event.sender, 'kimi', 1, route)
    runManager.finish(route.appRunId, 'failed')
    return
  }

  const state: CliProviderStreamState = {
    provider: 'kimi',
    sender: event.sender,
    startedAt: Date.now(),
    model,
    fallback: false,
    completed: false,
    assistantText: '',
    kimiUsageInputChars: productionSession.prompt.length,
    kimiUsageOutputChars: 0,
    providerSessionId: productionSession.resumeSessionId,
    approvalMode: payload.approvalMode,
    workflowMode: payload.workflowMode,
    sessionTrust: Boolean(payload.sessionTrust),
    externalPathGrants: payload.externalPathGrants,
    runtimeProfileId: payload.runtimeProfileId,
    taskWraithMcpProfileId: payload.taskWraithMcpProfileId,
    effectivePermissions: payload.effectivePermissions,
    effectivePermissionsSignature: payload.effectivePermissionsSignature,
    ensembleRun: payload.ensembleRun,
    ...route
  }
  const registeredSession = registerRunSession(
    'kimi',
    event.sender,
    route,
    payload.scope === 'global' ? undefined : payload.workspace,
    state,
    productionSession.resumeSessionId
  )
  if (!registeredSession) {
    // History clear or an exact terminal claim can land after the outer Kimi
    // dispatch reservation but before contained transport admission. Keep this
    // second registration load-bearing and release credentials/cwd without
    // starting the gateway or provider.
    const cleanup = createJoinedKimiCleanup(
      () => privateCwd.cleanup(),
      () => home.cleanup()
    )
    try {
      await cleanup()
    } catch {
      await cleanup().catch(() => undefined)
    }
    return
  }
  const kimiNativeCompactionStartedAt =
    productionSession.prompt.trim() === '/compact' && productionSession.resumeSessionId
      ? Date.now()
      : null
  if (kimiNativeCompactionStartedAt !== null) {
    emitContextCompactionCompatLine(
      event.sender,
      'kimi',
      { kind: 'started', telemetry: { provider: 'kimi', trigger: 'manual' } },
      state
    )
  }

  if (productionSession.legacyResumeRejected) {
    sendAgentCompatLine(event.sender, 'kimi', {
      type: 'provider_diagnostic',
      provider: 'kimi',
      message:
        'The linked Kimi session was born before the synthetic-cwd containment boundary. TaskWraith started a new safe session with full authorized context instead of resuming it.'
    })
  }

  // Per-tool approval policy for the gateway MCP surface. Every native Kimi
  // fs/exec/egress/fan-out tool is denied statically by the isolated profile;
  // any mutating gateway request still crosses the signed host ledger.
  const kimiWriteCapable = payload.approvalMode !== 'plan'
  const kimiPermissionHandler = async (request: AcpPermissionRequest) => {
    const decision = classifyKimiToolPermission(request, {
      writeCapable: kimiWriteCapable,
      isSafeMcpTool: isKimiSafeMcpTool,
      isReadOnlyShell: grokReadOnlyShellRequestAllowed
    })
    if (decision === 'allow') return 'allow'
    if (decision === 'deny') return 'deny'
    const service = grokToolKindToService(request.toolKind)
    const allowed = await requestAgenticServiceApproval(
      event.sender,
      'kimi',
      service,
      payload.scope === 'global' ? undefined : payload.workspace,
      {
        method: `kimi/${request.toolKind || 'tool'}`,
        title: `Kimi wants to run: ${request.toolName}`,
        body: `Kimi requested a "${request.toolName}" tool call (${service}). Approve to let it run, or deny to block it.`,
        runId: route.appRunId
      }
    )
    return allowed ? 'allow' : 'deny'
  }

  // Publish a joinable authority before gateway admission can reach the Kimi
  // spawn callback. `runKimiAcpTurn` exposes the child synchronously through
  // onProcess, so tracking only after launch returns would leave a deletion
  // window with a live process but no exact transport operation.
  const kimiTransportClose = createProviderTransportCloseOperation()
  const kimiTransportOperation = providerTransportOperations.track(
    route.appRunId!,
    kimiTransportClose.operation
  )
  let handle: ReturnType<typeof runKimiAcpTurn>
  try {
    const launched = await launchKimiProductionAcp({
      taskWraithMcpAdvertised: payload.taskWraithMcpAdvertised !== false,
      privateCwd,
      assertRuntimeReadyForSpawn: async () => {
        const binaryPath = await admittedRuntime.assertReadyForSpawn()
        // Gateway/cwd/runtime admission all await. A destructive-history
        // transaction can terminalize this exact run during those awaits, so
        // re-check its promoted persistence authority after attestation. The
        // synchronous launch callback repeats this check after the await
        // continuation and owns the final no-spawn boundary.
        assertKimiSpawnAuthority(() => providerRunPersistenceAuthorized('kimi', state))
        return binaryPath
      },
      startGateway: async () => {
        const bridge = await startKimiHttpMcpBridge({
          dispatch: createKimiMcpDispatch({
            route,
            workspace: payload.scope === 'global' ? undefined : payload.workspace,
            appVersion: app.getVersion(),
            brokerToken: geminiMcpBrokerToken,
            getMcpToolDefinitions: () => mcpToolDefinitions(),
            dispatchBrokerRequest: (request) =>
              mcpBridgeRuntime.handleGeminiMcpBrokerRequest(request)
          })
        })
        return {
          server: {
            name: 'taskwraith',
            type: 'http',
            url: bridge.url,
            headers: [{ name: bridge.headerName, value: bridge.headerValue }]
          },
          close: () => bridge.close()
        }
      },
      snapshot: {
        appVersion: app.getVersion(),
        prompt: payload.prompt,
        resumeFallbackPrompt: payload.resumeFallbackPrompt,
        requestedResumeSessionId: payload.providerSessionId,
        persistedPostureVersion
      },
      launch: (production, transportCleanup, admittedBinaryPath) => {
        // `launchKimiProductionAcp` resumes from an await before invoking this
        // callback. Repeat the exact check as its first synchronous statement;
        // no microtask can invalidate authority between here and child spawn.
        assertKimiSpawnAuthority(() => providerRunPersistenceAuthorized('kimi', state))
        const teardown = createJoinedKimiCleanup(transportCleanup, () => home.cleanup())
        return runKimiAcpTurn({
          prompt: production.session.prompt,
          resumeSessionId: production.session.resumeSessionId,
          resumeFallbackPrompt: payload.resumeFallbackPrompt,
          // `/compact` only makes sense against the linked native history. Never
          // turn a stale compaction target into a new empty session.
          allowResumeFallback: production.session.prompt.trim() !== '/compact',
          resumeConfigOptions: [
            {
              configId: 'model',
              value: kimiModelConfig
            },
            {
              configId: 'thinking',
              value: kimiThinkingConfig
            }
          ],
          cwd: production.cwd,
          initializeParams: production.initializeParams,
          mcpServers: production.mcpServers,
          spawnProcess: () => {
            // Build the CLI model arg the same way every other Kimi path does:
            // kimiCliModelArg omits `--model` for the default (kimi-code uses its
            // config default_model) and maps the Fast/standard service tier to the
            // real kimi-for-coding[-highspeed] alias. Passing the display id directly
            // would send a non-existent CLI alias and never engage Fast mode. The
            // root `--model` flag precedes the `acp` subcommand.
            const modelArgs: string[] = []
            appendKimiModelArgs(modelArgs, model, payload.serviceTier)
            const args = [...modelArgs, 'acp']
            return spawn(admittedBinaryPath, args, {
              cwd: production.cwd,
              env: buildKimiContainedProcessEnv(
                createCliEnv(
                  {
                    ...home.env,
                    HOME: home.home,
                    USERPROFILE: home.home,
                    TASKWRAITH_PARENT_PROVIDER: 'kimi',
                    TASKWRAITH_RUN_ID: route.appRunId || '',
                    TASKWRAITH_CHAT_ID: route.appChatId || ''
                  },
                  admittedBinaryPath
                ),
                production.cwd
              )
            }) as unknown as import('./kimi/KimiAcpClient').AcpChildProcess
          },
          onProcess: (child) => {
            const proc = child as unknown as ChildProcess
            runManager.attachProcess(route.appRunId!, proc)
            cliProviderProcesses.set('kimi', proc)
          },
          beforeInitialize: async (child) => {
            const proc = child as unknown as ChildProcess
            await home.noteProviderProcess(proc.pid || 0)
          },
          onPermissionRequest: kimiPermissionHandler,
          onEvent: (evt) => applyKimiAcpRunEvent(state, evt as NormalizedGrokRunEvent),
          onRawFrame: (direction, message) => {
            const flag = String(process.env.TASKWRAITH_KIMI_ACP_DEBUG || '').toLowerCase()
            if (flag === '1' || flag === 'true' || flag === 'yes') {
              try {
                process.stderr.write(formatKimiProductionAcpDebugFrame(direction, message))
              } catch {
                /* ignore */
              }
            }
          },
          onClose: async (code, turnComplete, terminalStatus) => {
            // The provider slot must remain live until credential/config/cwd cleanup
            // finishes. Releasing it earlier lets a back-to-back turn materialize a
            // new durable seat while the old teardown is still deleting that home.
            if (state.completed) return
            state.completed = true
            let finishStatus: 'failed' | 'completed' = 'failed'
            try {
              await finalizeKimiRunAfterCleanup({
                cleanup: teardown,
                projectTerminal: (cleanupError) => {
                  flushKimiAcpThinking(state)
                  const status = turnComplete ? terminalStatus || 'success' : 'failed'
                  const transportFailed = typeof code === 'number' && code !== 0
                  const failed =
                    Boolean(cleanupError) ||
                    transportFailed ||
                    !turnComplete ||
                    (status !== 'success' && status !== 'end_turn')
                  finishStatus = failed ? 'failed' : 'completed'
                  if (cleanupError) {
                    sendAgentCompatError(
                      event.sender,
                      'kimi',
                      `Kimi terminal cleanup failed after retry: ${
                        cleanupError instanceof Error ? cleanupError.message : String(cleanupError)
                      }`,
                      state
                    )
                  }
                  const stats = estimateKimiAcpTokenUsage({
                    inputChars: state.kimiUsageInputChars || 0,
                    outputChars: state.kimiUsageOutputChars || 0,
                    model,
                    serviceTier: payload.serviceTier,
                    durationMs: Date.now() - state.startedAt,
                    totalTokenLimit: home.modelContextWindow
                  })
                  state.tokenUsage = stats
                  let usageRecorded = false
                  if (!state.ensembleRun && route.appChatId && route.appRunId) {
                    const chat = AppStore.getChat(route.appChatId)
                    if (chat) {
                      try {
                        AppStore.recordUsage({
                          provider: 'kimi',
                          workspaceId:
                            chat.workspaceId ||
                            (chat.scope === 'global' ? '__taskwraith_global_chats__' : ''),
                          chatId: route.appChatId,
                          runId: route.appRunId,
                          usageKind: 'run',
                          model,
                          inputTokens: stats.input_tokens,
                          outputTokens: stats.output_tokens,
                          totalTokens: stats.total_tokens,
                          tokenCountConfidence: 'estimated',
                          costRateModel: stats._taskwraith_cost_rate_model,
                          durationMs: stats.duration_ms,
                          promptText: production.session.prompt,
                          responseText: state.assistantText
                        })
                        usageRecorded = true
                      } catch {
                        // Renderer recording remains the fallback when persistence fails.
                      }
                    }
                  }
                  if (usageRecorded) {
                    stats._taskwraith_usage_recorded = true
                  }
                  if (kimiNativeCompactionStartedAt !== null) {
                    emitContextCompactionCompatLine(
                      event.sender,
                      'kimi',
                      {
                        kind: failed ? 'failed' : 'completed',
                        telemetry: {
                          provider: 'kimi',
                          trigger: 'manual',
                          durationMs: Date.now() - kimiNativeCompactionStartedAt,
                          ...(failed
                            ? { error: 'Kimi Code did not complete native compaction.' }
                            : {})
                        }
                      },
                      state
                    )
                  }
                  sendAgentCompatLine(
                    event.sender,
                    'kimi',
                    {
                      type: 'result',
                      status: failed ? 'failed' : 'completed',
                      stats,
                      provider: 'kimi',
                      session_id: state.providerSessionId || ''
                    },
                    state
                  )
                  sendAgentCompatExit(
                    event.sender,
                    'kimi',
                    failed ? (transportFailed ? code : 1) : 0,
                    state
                  )
                },
                finish: () => runManager.finish(route.appRunId, finishStatus)
              })
            } catch (error) {
              try {
                sendAgentCompatError(
                  event.sender,
                  'kimi',
                  `Kimi terminal cleanup/projection failed: ${
                    error instanceof Error ? error.message : String(error)
                  }`,
                  state
                )
              } catch {
                /* terminal finish already ran in finally */
              }
            }
          }
        })
      }
    })
    handle = launched.handle
    runManager.attachAbortController(route.appRunId!, createAcpTurnAbortController(handle))
    // This adapter invocation and the registered transport operation remain
    // live through child close, gateway/private-cwd/home/OAuth cleanup, usage
    // projection, terminal transcript publication, and RunManager finish.
    await handle.closed
  } catch (error) {
    // A synchronous throw before the turn's onClose is wired (e.g. spawnProcess
    // throwing RuntimeProfileEnvironmentResolutionError inside runAcpTurn) would
    // otherwise leak the isolated home — a 0600 copy of the real OAuth token.
    // Tear it down and surface the failure.
    await home.cleanup().catch(() => undefined)
    sendAgentCompatError(
      event.sender,
      'kimi',
      error instanceof Error ? error.message : String(error),
      route
    )
    sendAgentCompatLine(event.sender, 'kimi', {
      type: 'result',
      status: 'failed',
      stats: {},
      provider: 'kimi'
    })
    sendAgentCompatExit(event.sender, 'kimi', 1, route)
    runManager.finish(route.appRunId, 'failed')
    return
  } finally {
    // Normal flow reaches this point only after handle.closed; pre-spawn
    // failures reach it after launchKimiProductionAcp and home cleanup. Either
    // way, a destructive-history receipt cannot precede owned cleanup.
    kimiTransportClose.markTransportClosed()
    await kimiTransportOperation
  }
}

async function runKimiProvider(event: Electron.IpcMainInvokeEvent, payload: AgentRunPayload) {
  const route = routeWithRunId('kimi', payload)
  const startingSession = registerRunSession(
    'kimi',
    event.sender,
    route,
    payload.scope === 'global' ? undefined : payload.workspace,
    undefined,
    payload.providerSessionId || null
  )
  if (!startingSession) return
  // 1.0.5-EW26 — Kimi compatibility filter. When enabled in
  // Settings, ensemble-mode Kimi participants get their prompt
  // pre-sanitised: sentences containing keywords known to trip
  // Moonshot's content filter (Tiananmen, Xinjiang, Hong Kong
  // protests, US-China relations, etc.) are replaced with a
  // redacted placeholder before Kimi spawns. Other participants
  // see the unfiltered prompt — we only modify Kimi's view.
  // Solo Kimi chats are NOT sanitised because the user is
  // typing directly; a content_filter rejection there is more
  // useful as immediate feedback than a silently-redacted view.
  if (payload.ensembleRun) {
    const settings = AppStore.getSettings()
    if (settings.kimiSanitiserEnabled && typeof payload.prompt === 'string') {
      const result = sanitiseForKimi(payload.prompt, {
        customKeywords: parseCustomKeywords(settings.kimiSanitiserCustomKeywords)
      })
      if (result.redacted) {
        payload.prompt = result.text
        const diagnostic = formatKimiSanitiserDiagnostic(result)
        sendAgentCompatLine(
          event.sender,
          'kimi',
          {
            type: 'provider_diagnostic',
            provider: 'kimi',
            message: diagnostic,
            source: 'kimi-compatibility-filter',
            matchCount: result.matches.length,
            triggers: result.matches.map((m) => m.trigger)
          },
          route
        )
      }
    }
  }

  const resolved = await resolveCliProviderBinary('kimi', payload.runtimeProfile)
  if (!resolved.binaryPath) {
    sendAgentCompatError(
      event.sender,
      'kimi',
      resolved.error || 'Kimi CLI is not configured.',
      route
    )
    sendAgentCompatLine(
      event.sender,
      'kimi',
      {
        type: 'result',
        status: 'failed',
        stats: {},
        provider: 'kimi',
        setupRequired: true
      },
      route
    )
    sendAgentCompatExit(event.sender, 'kimi', 1, route)
    runManager.finish(route.appRunId, 'failed')
    return
  }

  // Hash/platform/capability admission is the first operation allowed to
  // execute the resolved Kimi path. Its bounded inventory replaces the legacy
  // flavour probe; Wire and print fallbacks are outside the reviewed ACP scope.
  const admission = await admitKimiRuntime({
    binaryPath: resolved.binaryPath,
    isPackaged: app.isPackaged,
    environment: process.env
  })
  if (!admission.admitted || !kimiAcpEnabled()) {
    const message = admission.admitted
      ? 'Kimi ACP is disabled in this build; legacy Wire/print execution is not permitted.'
      : `Kimi runtime admission blocked execution: ${admission.message}`
    sendAgentCompatError(event.sender, 'kimi', message, route)
    sendAgentCompatLine(
      event.sender,
      'kimi',
      {
        type: 'result',
        status: 'failed',
        stats: {},
        provider: 'kimi',
        setupRequired: true
      },
      route
    )
    sendAgentCompatExit(event.sender, 'kimi', 1, route)
    runManager.finish(route.appRunId, 'failed')
    return
  }
  if (admission.mode === 'unattested-development') {
    sendAgentCompatLine(
      event.sender,
      'kimi',
      {
        type: 'provider_diagnostic',
        provider: 'kimi',
        source: 'kimi-runtime-admission',
        message:
          'Kimi is running under the explicit unattested-development bypass; this is not credentialed live-canary evidence.'
      },
      route
    )
  }
  await runKimiAcpProvider(event, payload, admission)
  return
}

function getCodexClient(runtimeProfile?: RuntimeProfile | null): CodexAppServerClient {
  if (!codexClient) {
    codexClient = new CodexAppServerClient()
  }
  if (arguments.length > 0) {
    codexClient.setRuntimeProfile(runtimeProfile ?? null)
  }
  // Phase I2: refresh the MCP config on every accessor call so the
  // toggle in Settings → MCP Bridge takes effect on the NEXT Codex
  // app-server start. A stale idle daemon is restarted below, while an
  // app-server with a transport-owned in-flight turn is never torn down.
  // The TaskWraith bridge mirrors the existing Gemini gate
  // (geminiMcpBridgeEnabled); user-managed stdio/HTTP servers can
  // attach independently through the MCP Servers settings page.
  const settings = AppStore.getSettings()
  const bridgeCommandStatus = taskwraithMcpBridgeCommandStatus()
  const userMcpServers = buildUserMcpLaunchServers(settings.userMcpServers, {
    supportedTransports: ['stdio', 'http'],
    allowlistPolicy: managedUserMcpLaunchAllowlistPolicy?.(),
    resolveSecretValues: (refs) => AppStore.resolveExtensionSecretValues(refs),
    validatePluginProvenance: validateUserMcpPluginProvenance
  })
  const taskWraithBridgeEnabled = Boolean(
    settings.geminiMcpBridgeEnabled && bridgeCommandStatus.available
  )
  if (taskWraithBridgeEnabled || userMcpServers.length > 0) {
    codexClient.setMcpConfig({
      enabled: taskWraithBridgeEnabled,
      bridgeBinaryPath: bridgeCommandStatus.command,
      bridgeArgs: taskwraithMcpBridgeArgs(geminiMcpSocketPath(), {
        gatewaySubset: true
      }),
      parentProvider: 'codex',
      userMcpServers
    })
  } else {
    codexClient.setMcpConfig(null)
  }
  const shouldRestart = shouldRestartCodexAppServerForMcpConfig({
    stale: codexClient.hasStaleMcpConfig(),
    startupLeaseCount: codexAppServerStartupLeaseCount,
    activeStates: runManager
      .getActiveByProvider('codex')
      .map((session) => session.state as Partial<CodexRunState> | null | undefined),
    // Manual compactions and native reviews hold admission lanes without a
    // RunManager session or startup lease; never dispose the daemon under one.
    admissionReservationCount: codexThreadAdmissionRegistry.activeLaneReservationCount
  })
  if (shouldRestart) {
    console.log('[codex] restarting idle app-server to apply MCP configuration changes')
    codexClient.dispose()
  }
  return codexClient
}

/**
 * 1.0.4-AD — pre-flight reachability probe for an ensemble participant.
 * Called by the orchestrator BEFORE each per-participant dispatch in
 * `runRound` so we never burn a runId on a participant whose provider
 * runtime is dead. Each provider has its own cheapest "is this
 * reachable?" surface:
 *
 *   - **Codex** — race `CodexAppServerClient.ensureStarted()` against
 *     a 1s timeout. When the proc is already alive (hot path)
 *     `ensureStarted` returns synchronously; when cold-starting it
 *     spawns the daemon, which we let race against the timeout.
 *   - **Claude / historical Gemini / Grok** — verify the CLI binary is
 *     resolvable via `resolveCliProviderBinary`.
 *   - **Kimi** — binary presence is insufficient. Resolve the path, then run
 *     descriptor-bound runtime admission; only an admitted ACP tuple is
 *     reachable. Packaged builds with an empty embedded roster fail closed.
 *
 * Any throw bubbles to the orchestrator's catch-and-classify path
 * which downgrades it to a generic unreachable signal — so the probe
 * is allowed to be defensive without a dedicated try/catch around
 * every adapter call.
 */

async function probeEnsembleParticipant(
  participant: EnsembleParticipant
): Promise<ParticipantProbeResult> {
  if (participant.provider === 'codex') {
    const runtimeProfile = participant.runtimeProfileId
      ? AppStore.getRuntimeProfiles('codex').find(
          (profile) => profile.id === participant.runtimeProfileId
        )
      : null
    return probeCodexParticipant(runtimeProfile)
  }
  return probeCliParticipant(participant)
}

async function probeCodexParticipant(
  runtimeProfile?: RuntimeProfile | null
): Promise<ParticipantProbeResult> {
  const client = getCodexClient(runtimeProfile ?? null)
  const ensure = client
    .ensureStarted(app.getVersion())
    .then<ParticipantProbeResult>(() => ({ reachable: true }))
    .catch<ParticipantProbeResult>((err: unknown) => {
      const message = err instanceof Error ? err.message : String(err)
      const code =
        typeof (err as { code?: unknown })?.code === 'string'
          ? ((err as { code?: string }).code as string)
          : 'ECONNREFUSED'
      // Surface a config.toml parse failure as the actionable message so the
      // ensemble unreachable reason isn't a cryptic serde dump.
      const stderr = (err as { codexStderr?: string } | null)?.codexStderr || message
      const reason = isCodexConfigParseError(stderr) ? codexConfigParseUserMessage(stderr) : message
      return { reachable: false, reason, underlyingCode: code }
    })
  const timeout = new Promise<ParticipantProbeResult>((resolve) =>
    setTimeout(
      () =>
        resolve({
          reachable: false,
          reason: `Codex app-server probe timed out after ${PROBE_TIMEOUT_MS}ms`,
          underlyingCode: 'ETIMEDOUT'
        }),
      PROBE_TIMEOUT_MS
    )
  )
  return Promise.race([ensure, timeout])
}

async function probeCliParticipant(
  participant: EnsembleParticipant
): Promise<ParticipantProbeResult> {
  const resolved = await resolveCliProviderBinary(participant.provider)
  if (participant.provider === 'kimi' && resolved.binaryPath) {
    const admission = await admitKimiRuntime({
      binaryPath: resolved.binaryPath,
      isPackaged: app.isPackaged,
      environment: process.env
    })
    return admission.admitted
      ? { reachable: true }
      : {
          reachable: false,
          reason: admission.message,
          underlyingCode: 'EACCES'
        }
  }
  if (resolved.binaryPath) {
    return { reachable: true }
  }
  return {
    reachable: false,
    reason:
      resolved.error || `${providerDisplayName(participant.provider)} CLI binary not found on PATH`,
    underlyingCode: 'ENOENT'
  }
}

function registerRunSession(
  provider: ProviderId,
  sender: Electron.WebContents,
  route: AgentRunRoute | null | undefined,
  workspacePath?: string,
  state?: any,
  providerSessionId?: string | null,
  requireExistingRun = false
) {
  const routed = routeWithRunId(provider, route)
  const expectedPersistenceAuthority = routed.appRunId
    ? providerRunPersistenceAuthorities.get(routed.appRunId)
    : undefined
  const currentPersistenceAuthority = routed.appChatId
    ? currentProviderRunPersistenceAuthority(routed.appChatId, workspacePath)
    : null
  if (
    !expectedPersistenceAuthority ||
    !currentPersistenceAuthority ||
    !historyClearAdmissionGate.authorizeRunPersistence(
      expectedPersistenceAuthority,
      currentPersistenceAuthority
    )
  ) {
    return undefined
  }
  if (runManager.getClaimedTerminalStatus(routed.appRunId)) return undefined
  const resolvedQueueIdentity = routed.appRunId ? AppStore.getRunQueueJob(routed.appRunId) : null
  if (
    resolvedQueueIdentity?.runId &&
    resolvedQueueIdentity.runId !== routed.appRunId &&
    executionGraphOwnsOrAnchorsRunId(routed.appRunId)
  ) {
    throw new Error('Provider session registration cannot use an alias of a graph-owned identity.')
  }
  const existing = runManager.get(routed.appRunId)
  const adapterContext = executionGraphAdapterContext.getStore()
  const graphQueueJobs = AppStore.getRunQueueJobs({ includeTerminal: true }).filter(
    (job) => job.runId === routed.appRunId && Boolean(job.executionGraph)
  )
  const graphClaims = executionGraphCoordinatorRef
    ? executionGraphCoordinatorRef.listExecutions({ includeTerminal: true }).flatMap((projection) =>
        Object.values(projection.attempts)
          .filter((attempt) => attempt.providerRunRef === routed.appRunId)
          .map((attempt) => ({ projection, attempt }))
      )
    : []
  const graphAnchorClaims = executionGraphCoordinatorRef
    ? executionGraphCoordinatorRef
        // Anchor identities remain reserved even after their Stack projection
        // terminalizes: cancelling a waiting Stack does not stop or rename the
        // independent provider transport it was observing.
        .listExecutions({ includeTerminal: true })
        .filter((projection) => projection.anchorRunRef === routed.appRunId)
    : []
  if (graphAnchorClaims.length > 0) {
    let sameInvocation = false
    try {
      sameInvocation = Boolean(
        routed.appRunId &&
        existing &&
        adapterContext?.appRunId === routed.appRunId &&
        providerAdapterInvocationTokens.get(routed.appRunId) === adapterContext.token &&
        existing.provider === provider &&
        existing.appChatId === routed.appChatId &&
        existing.workspacePath &&
        workspacePath &&
        canonicalPath(existing.workspacePath) === canonicalPath(workspacePath)
      )
    } catch {
      sameInvocation = false
    }
    if (!sameInvocation) {
      throw new Error('Provider session registration cannot reuse a live Stack anchor identity.')
    }
  }
  if (graphQueueJobs.length > 0 || graphClaims.length > 0) {
    const admission = routed.appRunId
      ? executionGraphAdapterAdmissions.get(routed.appRunId)
      : undefined
    const job = graphQueueJobs.length === 1 ? graphQueueJobs[0] : undefined
    const claim = graphClaims.length === 1 ? graphClaims[0] : undefined
    const binding = job?.executionGraph
    let workspaceMatches = false
    try {
      workspaceMatches = Boolean(
        workspacePath &&
        admission?.payload.workspace &&
        canonicalPath(workspacePath) === canonicalPath(admission.payload.workspace)
      )
    } catch {
      workspaceMatches = false
    }
    let existingIdentityMatches = true
    if (existing) {
      try {
        existingIdentityMatches = Boolean(
          existing.provider === provider &&
          existing.appChatId === routed.appChatId &&
          existing.workspacePath &&
          workspacePath &&
          canonicalPath(existing.workspacePath) === canonicalPath(workspacePath)
        )
      } catch {
        existingIdentityMatches = false
      }
    }
    const lifecycleMatches = existing
      ? job?.status === 'active' &&
        (existing.status === 'starting' || existing.status === 'running')
      : job?.status === 'starting'
    if (
      !routed.appRunId ||
      !admission ||
      adapterContext?.appRunId !== routed.appRunId ||
      adapterContext.admission !== admission ||
      !executionGraphDispatchesInFlight.has(routed.appRunId) ||
      !executionGraphCoordinatorRef ||
      !job ||
      !lifecycleMatches ||
      !claim ||
      binding?.executionId !== admission.executionId ||
      binding.activationId !== admission.activationId ||
      binding.attemptId !== admission.attemptId ||
      binding.runTemplateRef !== admission.runTemplateRef ||
      claim.projection.executionId !== admission.executionId ||
      claim.attempt.id !== admission.attemptId ||
      provider !== job.provider ||
      routed.appChatId !== job.chatId ||
      !workspaceMatches ||
      !existingIdentityMatches
    ) {
      throw new Error('Provider session registration collided with a graph-owned run identity.')
    }
    if (!existing) executionGraphCoordinatorRef.assertQueueJobDispatchable(routed.appRunId)
  }
  const graphOwnedRegistration = graphQueueJobs.length > 0 || graphClaims.length > 0
  if (existing) {
    if (isTerminalRunSessionStatus(existing.status)) return undefined
    runManager.update(existing.runId, {
      sender,
      workspacePath,
      appChatId: routed.appChatId,
      providerSessionId: providerSessionId || existing.providerSessionId,
      state,
      status: 'running'
    })
    if (graphOwnedRegistration) {
      runManager.requireTerminalConfirmation(existing.runId)
      armExecutionGraphTerminalJoinWatchdog(existing.runId)
    }
    return runManager.get(existing.runId)!
  }
  if (requireExistingRun) return undefined
  const created = runManager.create({
    runId: routed.appRunId!,
    provider,
    appChatId: routed.appChatId,
    workspacePath,
    providerSessionId: providerSessionId || undefined,
    sender,
    state,
    status: 'running'
  })
  if (graphOwnedRegistration) {
    runManager.requireTerminalConfirmation(created.runId)
    armExecutionGraphTerminalJoinWatchdog(created.runId)
  }
  return created
}

function getRuntimeSession(provider: ProviderId, route?: AgentRunRoute | null) {
  return runManager.resolve(provider, route)
}

function getSingleActiveProviderSession(provider: ProviderId) {
  const sessions = runManager.getActiveByProvider(provider)
  return sessions.length === 1 ? sessions[0] : undefined
}

function getCodexStateFromSession(
  session: ReturnType<typeof getRuntimeSession> | undefined
): CodexRunState | null {
  const state = session?.state
  return state && typeof state === 'object' && (state as CodexRunState).threadId
    ? (state as CodexRunState)
    : null
}

function isEnsembleCodexRunSession(
  session: ReturnType<typeof runManager.get> | undefined
): boolean {
  if (!session) return false
  const state = getCodexStateFromSession(session)
  if (state?.ensembleRun) return true
  return session.appChatId ? AppStore.getChat(session.appChatId)?.chatKind === 'ensemble' : false
}

function allowsTerminalCodexNativeGoalSession(
  session: ReturnType<typeof runManager.get> | undefined
): boolean {
  if (!session || session.provider !== 'codex' || session.status !== 'completed') return false
  if (executionGraphOwnsAttemptRunId(session.runId)) return false
  const chat = session.appChatId ? AppStore.getChat(session.appChatId) : null
  return Boolean(
    chat &&
    chat.chatKind !== 'ensemble' &&
    chat.activeGoal?.mode === 'codex_native' &&
    (chat.activeGoal.status === 'active' || chat.activeGoal.status === 'blocked')
  )
}

function getActiveCodexRunState(): CodexRunState | null {
  const activeCodexSessions = runManager.getActiveByProvider('codex')
  const managedStates = activeCodexSessions
    .map((session) => getCodexStateFromSession(session))
    .filter((state): state is CodexRunState => Boolean(state))
  if (managedStates.length > 1) {
    return null
  }
  const managed = managedStates[0]
  if (managed) return managed
  if (!activeCodexRunState?.appRunId) return activeCodexRunState
  const session = runManager.get(activeCodexRunState.appRunId)
  return session && (session.status === 'starting' || session.status === 'running')
    ? activeCodexRunState
    : null
}

function setActiveCodexRunState(state: CodexRunState | null): void {
  activeCodexRunState = state
}

// Residual 1 — threadIds whose run was asked to cancel BEFORE turn/started set a
// turnId. cancelProviderRun records the threadId here when it can't yet issue
// turn/interrupt; handleCodexNotification flushes it the instant the turn starts.
// Without this, a cancel/budget-kill landing between registerRunSession and
// turn/started skips the interrupt and the Codex server turn runs on. Keyed by
// threadId (the only id stable across that window + the id turn/interrupt needs).
const pendingCodexInterrupts = new Set<string>()
const pendingCodexMcpRouteHints = new Map<string, CodexMcpRouteHint>()
const CODEX_MCP_ROUTE_HINT_MAX_AGE_MS = 15_000

/** Issue a Codex turn/interrupt; best-effort, never throws. */
async function issueCodexTurnInterrupt(threadId: string, turnId: string): Promise<void> {
  if (!codexClient) return
  await codexClient.request('turn/interrupt', { threadId, turnId }, 10_000).catch(() => {})
}

function pruneCodexMcpRouteHints(nowMs: number): void {
  for (const [hintId, hint] of pendingCodexMcpRouteHints) {
    if (nowMs - hint.startedAtMs > CODEX_MCP_ROUTE_HINT_MAX_AGE_MS) {
      pendingCodexMcpRouteHints.delete(hintId)
    }
  }
}

function resolveCodexMcpRouteFromHints(toolName: string, rawArgs: unknown): AgentRunRoute | null {
  const nowMs = Date.now()
  pruneCodexMcpRouteHints(nowMs)
  return resolveCodexMcpRouteHint({
    hints: [...pendingCodexMcpRouteHints.values()],
    nowMs,
    toolName,
    args: rawArgs,
    maxAgeMs: CODEX_MCP_ROUTE_HINT_MAX_AGE_MS
  })
}

function isCodexTerminalProjectionNotification(method: unknown): boolean {
  return (
    method === 'turn/completed' ||
    method === 'turn/failed' ||
    method === 'review/completed' ||
    method === 'review/failed' ||
    method === 'error'
  )
}

function findCodexRunStateForMessage(message: any): CodexRunState | null {
  const params = message?.params || {}
  const threadId =
    params.threadId || params.thread?.id || params.item?.threadId || params.turn?.threadId
  if (threadId) {
    const session = runManager.getByProviderSession('codex', String(threadId))
    const byThread = getCodexStateFromSession(session)
    const terminalProjectionRoutable = Boolean(
      byThread?.terminalProjectionOperation &&
        session &&
        isTerminalRunSessionStatus(session.status) &&
        providerTransportOperations.get(session.runId) &&
        isCodexTerminalProjectionNotification(message?.method)
    )
    const exactSessionRoutable = Boolean(
      terminalProjectionRoutable ||
        (byThread &&
          session &&
          shouldRouteCodexRunSession({
            ensemble: isEnsembleCodexRunSession(session),
            status: session.status,
            stateCompleted: byThread.completed,
            allowTerminalNativeGoal: allowsTerminalCodexNativeGoalSession(session)
          }))
    )
    const childOwner = !session ? findCodexMultiAgentOwnerState(String(threadId)) : null
    const explicitRoute = resolveCodexExplicitThreadRoute({
      hasExplicitThreadId: true,
      exactSessionRoutable,
      registeredChildOwner: Boolean(childOwner)
    })
    if (explicitRoute === 'session') return byThread
    if (explicitRoute === 'child_owner') return childOwner
    // An explicit thread id is authoritative. Never route an orphaned or
    // terminal ensemble event into some other active Codex participant.
    return null
  }
  const active = getActiveCodexRunState()
  if (active || !isCodexTerminalProjectionNotification(message?.method)) return active
  const terminalProjectionStates = runManager
    .getByProvider('codex')
    .filter(
      (session) =>
        isTerminalRunSessionStatus(session.status) &&
        providerTransportOperations.get(session.runId)
    )
    .map((session) => getCodexStateFromSession(session))
    .filter(
      (state): state is CodexRunState => Boolean(state?.terminalProjectionOperation)
    )
  return terminalProjectionStates.length === 1 ? terminalProjectionStates[0] : null
}

function getGeminiToolContext(route?: AgentRunRoute | null): GeminiToolContext | null {
  const session = getRuntimeSession('gemini', route)
  const state = session?.state
  if (state && typeof state === 'object' && (state as GeminiToolContext).sender) {
    const context = state as GeminiToolContext
    return {
      ...context,
      scope: context.scope === 'global' ? 'global' : 'workspace',
      cwd: context.cwd || context.workspacePath || globalRunCwd()
    }
  }
  const hasExplicitRoute = Boolean(route?.appRunId || route?.appChatId)
  if (!hasExplicitRoute && activeGeminiToolContext?.appRunId) {
    const activeSession = getSingleActiveProviderSession('gemini')
    if (activeSession?.runId === activeGeminiToolContext.appRunId) {
      return activeGeminiToolContext
    }
  }
  return !hasExplicitRoute && !activeGeminiToolContext?.appRunId ? activeGeminiToolContext : null
}

/**
 * Phase I2: provider-aware MCP tool context resolver. The TaskWraith
 * MCP server is shared across Gemini / Codex / Claude / Kimi (each CLI
 * registers it via `-c mcp_servers.TaskWraith.*`), and the bridge
 * subprocess stamps `parentProvider` on every broker request based on
 * the `TASKWRAITH_PARENT_PROVIDER` env var. This helper consumes that
 * stamp and returns the right run-context for the parent provider:
 *
 *  - For Gemini we still go through `getGeminiToolContext` so the
 *    Phase F3 + I1 flow (which stores the `GeminiToolContext` in the
 *    runManager session.state) is preserved.
 *  - For Codex / Claude / Kimi we derive sender + workspace + chat
 *    from the runManager directly. Their session.state shapes are
 *    provider-specific (CodexRunState etc.), but every session has a
 *    `sender`, `workspacePath`, `appChatId`, `runId` at the top level.
 *
 * Returns null when no active run exists, or when multiple active runs
 * exist and the bridge did not provide an appRunId/appChatId. In the
 * latter case we fail closed rather than guessing a run.
 */
function getAgentToolContext(
  parentProvider: ProviderId,
  route?: AgentRunRoute | null
): GeminiToolContext | null {
  if (parentProvider === 'gemini') {
    const context = getGeminiToolContext(route)
    if (context && historyClearAdmissionBlocked(context.appRunId, context.workspacePath)) {
      return null
    }
    return context
  }
  const session = getRuntimeSession(parentProvider, route)
  if (
    session &&
    (historyClearAdmissionBlocked(session.runId, session.workspacePath) ||
      (isTerminalRunSessionStatus(session.status) &&
        !allowsTerminalCodexNativeGoalSession(session)) ||
      runManager.getClaimedTerminalStatus(session.runId))
  ) {
    return null
  }
  const sender = session?.sender as Electron.WebContents | undefined
  if (!sender || !session) {
    return null
  }
  const workspacePath = session.workspacePath ? resolve(session.workspacePath) : undefined
  const state =
    session.state && typeof session.state === 'object'
      ? (session.state as Partial<GeminiToolContext>)
      : {}
  return {
    sender,
    scope: workspacePath ? 'workspace' : 'global',
    cwd: workspacePath || globalRunCwd(),
    workspacePath,
    appRunId: session.runId,
    appChatId: session.appChatId,
    providerSessionId: session.providerSessionId,
    approvalMode: state.approvalMode,
    workflowMode: state.workflowMode,
    sessionTrust: state.sessionTrust,
    externalPathGrants: state.externalPathGrants,
    taskWraithMcpProfileId: state.taskWraithMcpProfileId,
    effectivePermissions: state.effectivePermissions,
    effectivePermissionsSignature: state.effectivePermissionsSignature,
    ensembleRun: state.ensembleRun,
    runtimeProfileId: state.runtimeProfileId
  }
}

function enrichAgentPayload(provider: ProviderId, payload: any, route?: AgentRunRoute | null) {
  const inferredRoute: any =
    route ||
    getRuntimeSession(provider, payload) ||
    (provider === 'codex'
      ? getActiveCodexRunState()
      : provider === 'gemini'
        ? getGeminiToolContext(null)
        : null)
  const resolvedRoute = normalizeRunRoute({
    appRunId: inferredRoute?.runId || inferredRoute?.appRunId || payload?.appRunId,
    appChatId: inferredRoute?.appChatId || payload?.appChatId
  })
  return {
    ...payload,
    provider,
    ...resolvedRoute
  }
}

/**
 * Convenience wrapper around `runEventBus.publish`. Used by the three
 * `sendAgentCompat*` helpers below and by the few direct call sites that
 * previously bypassed them. Keeping the sender parameter optional means
 * non-IPC publish paths (telemetry, scheduled tasks, future remote sinks)
 * can publish too.
 */
function publishRunEvent(
  channel: RunEventChannel,
  provider: ProviderId,
  payload: unknown,
  sender?: Electron.WebContents,
  options: { suppressElectronIpc?: boolean } = {}
): void {
  materializeBridgeRunFromPublish(channel, provider, payload)
  runEventBus.publish({ channel, provider, payload, sender, ...options })
}

function sendAgentCompatLine(
  sender: Electron.WebContents,
  provider: ProviderId,
  payload: any,
  route?: AgentRunRoute | null,
  canvasEvalApproval?: CanvasEvalApprovalReceipt
) {
  const initialRoute = enrichAgentPayload(provider, payload, route)
  const canvasEvalScope = `${provider}:${initialRoute.appRunId || initialRoute.appChatId || 'unrouted'}`
  // Native providers echo MCP calls/results on their own event streams. Keep
  // the full main-owned MCP return on the provider transport, but project any
  // Canvas echo to metadata-only before the durable ledger or renderer sees it.
  // The sanitizer also correlates result-only frames by opaque tool-call id.
  payload = nativeCanvasCompatSanitizer.sanitize(payload, canvasEvalScope)
  payload = canvasEvalCompatSanitizer.sanitize(payload, canvasEvalApproval, canvasEvalScope)
  const routed = enrichAgentPayload(provider, payload, initialRoute)
  if (!providerRunPersistenceAuthorized(provider, routed)) return
  const runItemEvents = runItemEventsForCompatPayload(provider, routed, payload)
  if (runItemEvents.length > 0) {
    appendDurableRunItemEvents(runItemEvents)
  }
  // Some provider internals are useful for the raw run ledger but too noisy
  // for the chat transcript. Keep those durable, then stop before renderer /
  // bridge / ensemble materialization can turn them into visible tool rows.
  const transcriptVisible = payload?.transcriptVisible !== false
  const durableKind = !transcriptVisible
    ? 'provider_raw'
    : payload?.type === 'tool_use' || payload?.type === 'tool_result'
      ? 'tool'
      : payload?.type === 'compaction_event'
        ? 'context_compaction'
        : 'provider_raw'
  appendDurableRunEventForRoute(
    provider,
    routed,
    durableKind,
    'raw',
    !transcriptVisible && payload?.tool_name === 'ollama_thinking'
      ? 'Ollama thinking trace'
      : payload?.type === 'compaction_event' && payload?.compaction?.telemetry
        ? formatContextCompactionSummary(payload.compaction)
        : `Provider output${payload?.type ? `: ${payload.type}` : ''}`,
    payload,
    'provider'
  )
  if (!transcriptVisible) return
  // Chronological thinking segmentation (1.0.7): any transcript-visible,
  // non-reasoning line marks a chronology break on the emitting CLI stream
  // state (threaded here as `route` by every CLI-provider emit site). The
  // NEXT thinking chunk then opens a fresh trace activity at the current
  // transcript position (see emitCliProviderThinkingEvent) instead of growing
  // the run's first trace in place. Routes that aren't stream states just
  // carry an unread flag — harmless.
  if (route && shouldBreakThinkingChronology(payload)) {
    ;(route as { thinkingChronoBreak?: boolean }).thinkingChronoBreak = true
  }
  materializeBackgroundSubThreadProviderOutput(provider, routed, payload)
  materializeBridgeRunProviderOutput(provider, routed, payload, { trustedCompatLane: true })
  const handledByEnsemble =
    ensembleOrchestratorRef?.handleProviderOutput(provider, routed, payload) === true
  // Audit completion bridge — settles a tracked audit role-run on its terminal
  // `result` event (lifting token/cost/duration). No-ops for non-audit runs.
  auditRunTracker.handleProviderOutput(routed.appRunId, payload)

  // EnsembleOrchestrator is the canonical transcript projection for an
  // Ensemble seat. Once it accepts this event, sending the full compat JSON
  // through Electron IPC as well is redundant: renderer participants do not
  // register individual run contexts, so the event falls into the raw-log
  // fallback and updates root React state even with that inspector closed.
  // Tool-result previews can be tens of KiB and arrive in bursts, making that
  // duplicate, unacknowledged lane capable of starving the visible transcript.
  //
  // Keep a compact bus signal so remote snapshot and git invalidation sinks
  // still observe progress. The complete provider event is already durable,
  // and the canonical chat update carries the user-visible projection.
  if (handledByEnsemble) {
    const ensembleSignal = {
      provider,
      appRunId: routed.appRunId,
      appChatId: routed.appChatId,
      compatLine: true,
      ensembleMaterialized: true
    }
    publishRunEvent('agent-output', provider, ensembleSignal, sender, {
      suppressElectronIpc: true
    })
    if (provider === 'gemini') {
      publishRunEvent('gemini-output', provider, ensembleSignal, sender, {
        suppressElectronIpc: true
      })
    }
    return
  }

  const routedForWire = runItemEvents.length > 0 ? { ...routed, runItemEvents } : routed
  const line = `${JSON.stringify(routedForWire)}\n`
  const outputPayload = {
    provider,
    data: line,
    appRunId: routed.appRunId,
    appChatId: routed.appChatId,
    // Compat lines were already materialized into bridge-run transcripts
    // by the direct call above — the publish hook must skip them or every
    // streamed token lands twice (three times for the gemini mirror).
    compatLine: true
  }
  publishRunEvent('agent-output', provider, outputPayload, sender)
  if (provider === 'gemini') {
    publishRunEvent('gemini-output', provider, outputPayload, sender)
  }
}

function sendAgentCompatError(
  sender: Electron.WebContents,
  provider: ProviderId,
  error: string,
  route?: AgentRunRoute | null
) {
  const safeError = sanitizeCanvasEvalProviderText(error)
  const routed = enrichAgentPayload(provider, { error: safeError }, route)
  if (!providerRunPersistenceAuthorized(provider, routed)) return
  ensembleOrchestratorRef?.noteProviderFailureText(provider, routed, safeError)
  appendDurableRunEventForRoute(
    provider,
    routed,
    'provider_error',
    'raw',
    'Provider stderr/error',
    { error: safeError },
    'provider'
  )
  if (routed.appRunId) {
    // Stderr can be advisory while the provider keeps running (Codex version
    // warnings are the common case). Let result/exit decide terminal status.
    const bridgeState = bridgeRunTranscripts.get(routed.appRunId)
    if (
      bridgeState &&
      bridgeState.status === 'running' &&
      bridgeRunRouteMatches(bridgeState, provider, routed.appChatId)
    ) {
      bridgeState.errorMessage = safeError
    }
  }
  // Auto-failover: classify the provider's error channel for a quota wall (429)
  // and stash the signal keyed by run; the terminal exit decides whether to act.
  if (routed.appRunId && AppStore.getSettings().autoFailoverEnabled) {
    const verdict = classifyProviderQuotaWall(provider, error)
    if (verdict.hit) {
      quotaWallSignalByRun.set(routed.appRunId, { provider, resetHintAt: verdict.resetHintAt })
    }
  }
  publishRunEvent('agent-error', provider, routed, sender)
  if (provider === 'gemini') {
    publishRunEvent('gemini-error', provider, routed, sender)
  }
}

function sendAgentCompatExit(
  sender: Electron.WebContents,
  provider: ProviderId,
  code: number | null,
  route?: AgentRunRoute | null
) {
  const exitStats = buildAgentExitStats(provider, route)
  const routed = enrichAgentPayload(
    provider,
    exitStats ? { code, stats: exitStats } : { code },
    route
  )
  const scheduledSoloOwner =
    routed.appRunId && routed.appChatId
      ? scheduledOccurrenceOwners.lookupSoloExit({
          appRunId: routed.appRunId,
          provider,
          chatId: routed.appChatId
        })
      : undefined
  const claimedTerminalStatus = runManager.getClaimedTerminalStatus(routed.appRunId)
  const pendingLifecycleStatus = runManager.getTerminalJoinState(routed.appRunId).lifecycleStatus
  const runCancelled = Boolean(
    claimedTerminalStatus === 'cancelled' ||
    pendingLifecycleStatus === 'cancelled' ||
    (routed.appRunId && runManager.get(routed.appRunId)?.status === 'cancelled')
  )
  const runFailed = claimedTerminalStatus === 'failed' || pendingLifecycleStatus === 'failed'
  const graphExitState = routed.appRunId ? bridgeRunTranscripts.get(routed.appRunId) : undefined
  const authorizedGraphExit = Boolean(
    graphExitState?.owner === 'execution_graph' &&
    bridgeRunRouteMatches(graphExitState, provider, routed.appChatId)
  )
  const graphTerminalStatus: 'completed' | 'failed' | 'cancelled' = runCancelled
    ? 'cancelled'
    : !runFailed && (code ?? -1) === 0
      ? 'completed'
      : 'failed'
  if (!providerRunPersistenceAuthorized(provider, routed)) {
    if (authorizedGraphExit && graphExitState) {
      recordExecutionGraphProviderTerminalCandidate(graphExitState, graphTerminalStatus)
    }
    if (routed.appRunId) {
      const bridgeState = bridgeRunTranscripts.get(routed.appRunId)
      if (bridgeState?.flushTimer) clearTimeout(bridgeState.flushTimer)
      bridgeRunTranscripts.delete(routed.appRunId)
      const subThreadState = backgroundSubThreadTranscripts.get(routed.appRunId)
      if (subThreadState?.flushTimer) clearTimeout(subThreadState.flushTimer)
      backgroundSubThreadTranscripts.delete(routed.appRunId)
      quotaWallSignalByRun.delete(routed.appRunId)
      workflowBudgetRegistry.onExit(routed.appRunId)
      runManager.finish(routed.appRunId, graphTerminalStatus)
      releaseProviderSessionPersistenceDecision(routed.appRunId)
      releaseProviderRunPersistenceAuthority(routed.appRunId)
    }
    cleanupRunItemEventState(routed.appRunId)
    return
  }
  const exitRunItemEvents = runItemEventsForDrafts(provider, routed, [
    {
      kind: 'run/completed',
      itemKind: 'run',
      itemId: routed.appRunId ? `${routed.appRunId}:run` : undefined,
      status: !runFailed && !runCancelled && (code ?? -1) === 0 ? 'success' : 'failed',
      exitCode: code,
      ...(exitStats ? { stats: exitStats } : {}),
      source: 'taskwraith'
    }
  ])
  if (exitRunItemEvents.length > 0) {
    appendDurableRunItemEvents(exitRunItemEvents)
  }
  const routedForWire =
    exitRunItemEvents.length > 0 ? { ...routed, runItemEvents: exitRunItemEvents } : routed
  appendDurableRunEventForRoute(
    provider,
    routed,
    'provider_exit',
    'raw',
    `Provider exited with code ${typeof code === 'number' ? code : 'unknown'}`,
    { code },
    'provider'
  )
  ensembleOrchestratorRef?.markRunExited(routed.appRunId, typeof code === 'number' ? code : -1)
  // Drop the solo working-telemetry snapshot for this run. Self-gating: only
  // yields a clear for a run the solo registry actually tracked, so ensemble
  // seats (cleared by the orchestrator's finalizeRun) are never touched.
  const soloClearEvent = soloWorkingTokenTelemetry.clear(routed.appRunId)
  if (soloClearEvent) broadcastParticipantWorkingTelemetry(soloClearEvent)
  // Audit completion bridge — resolve a tracked audit role-run that ended
  // without a terminal `result` event (crash/kill). No-ops for non-audit runs
  // and once already settled by a result. Mirrors the markRunExited hook.
  auditRunTracker.handleExit(routed.appRunId, typeof code === 'number' ? code : -1)
  if (routed.appRunId) {
    if (graphExitState?.owner !== 'execution_graph' || authorizedGraphExit) {
      finalizeBridgeRunTranscript(
        routed.appRunId,
        graphTerminalStatus === 'completed'
          ? 'success'
          : graphTerminalStatus === 'cancelled'
            ? 'cancelled'
            : 'failed'
      )
    }
    // Auto-failover: on a terminal FAILED exit with a stashed quota-wall signal,
    // pause the throttled provider and re-dispatch the request to a healthy one.
    if (!runCancelled && !scheduledSoloOwner) {
      maybeTriggerProviderAutoFailover(routed.appRunId, provider, routed.appChatId, code)
    }
    // Per-occurrence budget kill: cleanup on EVERY exit (clear the armed timer +
    // drop per-run state so a late timer can't fire on a finished/reused run). The
    // terminal mark already happened at the kill decision (triggerKill); this is
    // cleanup-only and a no-op for unregistered runs.
    // Residual 2 — POST-HOC token/cost budget for grok/cursor (no live token
    // signal): their final tokenUsage rides the route here (the stream state is
    // passed as the route arg; buildAgentExitStats above reads it the same way).
    // Evaluate BEFORE onExit drops the registration; onTerminalUsage marks the
    // task failed iff the final usage breached + no-ops for already-killed runs.
    const terminalUsage = (
      route as
        | { tokenUsage?: { total_tokens?: number; total_cost_usd?: number } }
        | null
        | undefined
    )?.tokenUsage
    if (terminalUsage) workflowBudgetRegistry.onTerminalUsage(routed.appRunId, terminalUsage)
    const budgetKilled = workflowBudgetRegistry.isKilled(routed.appRunId)
    workflowBudgetRegistry.onExit(routed.appRunId)
    if (scheduledSoloOwner) {
      // Capture exact ownership before budget callbacks: a successful budget mark
      // releases the owner, while a failed store write deliberately leaves it live
      // for this terminal retry. Budget failure outranks the cancellation emitted by
      // the abort path, so it cannot be misreported as a user cancellation.
      if (scheduledOccurrenceOwners.lookupByOwnerRunId(routed.appRunId) === scheduledSoloOwner) {
        const failed = budgetKilled || (code ?? -1) !== 0
        const status = budgetKilled
          ? 'failed'
          : runCancelled
            ? 'cancelled'
            : failed
              ? 'failed'
              : 'completed'
        settleScheduledOccurrence(scheduledSoloOwner, status, {
          completedAt: new Date().toISOString(),
          ...(failed
            ? {
                lastError: budgetKilled
                  ? 'Scheduled run exceeded its workflow budget.'
                  : `Scheduled provider exited with code ${code ?? 'unknown'}.`
              }
            : {})
        })
      }
      recordWorkflowRunHarvest(scheduledSoloOwner.taskId, routed.appRunId, route)
    }
  }
  publishRunEvent('agent-exit', provider, routedForWire, sender)
  if (provider === 'gemini') {
    publishRunEvent('gemini-exit', provider, routedForWire, sender)
  }
  if (authorizedGraphExit && routed.appRunId) {
    runManager.finish(routed.appRunId, graphTerminalStatus)
  }
  // Renderer-owned solo runs do not use a main transcript finalizer. Drop their
  // in-memory suppression decision after the terminal event; ChatService also
  // rejects any reroute target session carried by the renderer's saved ChatRun.
  // Main-owned bridge/sub-thread finalizers release only after their async
  // terminal flush so the target session remains suppressed until persistence.
  if (
    routed.appRunId &&
    !bridgeRunTranscripts.has(routed.appRunId) &&
    !backgroundSubThreadTranscripts.has(routed.appRunId)
  ) {
    releaseProviderSessionPersistenceDecision(routed.appRunId)
  }
  cleanupRunItemEventState(routed.appRunId)
}

function codexApprovalPolicyForMode(
  approvalMode?: string,
  settings: AppSettings = AppStore.getSettings()
): 'never' | 'on-request' {
  if (approvalMode === 'plan') {
    return 'never'
  }
  if (approvalMode === 'auto_edit' && !codexNeedsApprovalGate(settings)) return 'never'
  return 'on-request'
}

function normalizeExternalPathGrants(grants?: ExternalPathGrant[]): ExternalPathGrant[] {
  if (!Array.isArray(grants)) return []
  const normalized: ExternalPathGrant[] = []
  // Phase J1 composer-unification: accept grants for ANY known
  // provider (was previously codex-only). The signature check via
  // `isMainIssuedExternalPathGrant` still guards integrity; the
  // provider field is part of the signed payload so a grant for one
  // provider cannot be smuggled in as another.
  // Only currently dispatchable providers may carry executable grants. Signed
  // historical Cursor records remain decodable in storage but are dropped from
  // run authority here.
  const allowedProviders = EXTERNAL_PATH_GRANT_DISPATCH_PROVIDERS
  for (const grant of grants) {
    if (!grant || typeof grant.path !== 'string') continue
    if (!allowedProviders.has(grant.provider)) continue
    if (!isMainIssuedExternalPathGrant(grant)) continue
    const grantPath = grant.path.trim()
    if (!grantPath || !isAbsolute(grantPath)) continue
    if (isSymlinkPath(grantPath)) continue
    const resolvedPath = canonicalExternalGrantPath(grantPath)
    if (!resolvedPath) continue
    if (grant.bindingVersion === EXTERNAL_PATH_GRANT_BINDING_VERSION) {
      // Every authority-bearing v2 field is part of the HMAC. Normalization may
      // validate but must never "repair" a signed grant into a different object.
      if (grant.path !== resolvedPath) continue
      if (grant.access !== 'read' && grant.access !== 'write') continue
      if (grant.kind !== 'file' && grant.kind !== 'directory') continue
      if (!isExecutableExternalPathGrantDuration(grant.duration)) continue
      normalized.push(grant)
      continue
    }
    normalized.push({
      ...grant,
      path: resolvedPath,
      access: grant.access === 'write' ? 'write' : 'read',
      kind: grant.kind === 'directory' ? 'directory' : 'file',
      duration: grant.duration || 'thisThread'
    })
  }
  return coalesceExternalPathGrants(normalized)
}

function externalPathGrantMetadataLists(chat: ChatRecord | null | undefined): ExternalPathGrant[] {
  return collectExternalPathGrantsFromMetadata(chat?.providerMetadata)
}

/**
 * Main-owned execution view of a chat's durable external-path grants.
 *
 * `normalizeExternalPathGrants` is intentionally suitable for decoding and UI
 * display, so its context-free signature check is not an authorization
 * boundary. Every host-side filesystem consumer must come through this helper:
 * it resolves the chat's canonical PRIMARY workspace and rejects grants copied
 * from another chat/workspace. With no run id, `thisRun` grants also fail
 * closed; durable host-media and desktop Git surfaces use thread grants only.
 */
function executableExternalPathGrantsForChat(
  chat: ChatRecord | null | undefined,
  provider?: ProviderId
): ExternalPathGrant[] {
  if (!chat || chatScope(chat) === 'global') return []
  const primaryWorkspace = resolveChatPrimaryWorkspace(
    chat,
    AppStore.getWorkspaces(),
    canonicalPath
  )
  if (!primaryWorkspace) return []
  return normalizeExternalPathGrants(externalPathGrantMetadataLists(chat)).filter(
    (grant) =>
      (!provider || grant.provider === provider) &&
      isMainIssuedExternalPathGrant(grant, {
        provider: grant.provider,
        appChatId: chat.appChatId,
        workspacePath: primaryWorkspace.path
      })
  )
}

/**
 * Resolve the capabilities carried by one live provider run. Unlike renderer
 * metadata, the RunManager state was created from the main-normalized dispatch
 * payload, so it is the authority source for exact `thisRun` attachment grants.
 */
function executableExternalPathGrantsForRun(
  chat: ChatRecord | null | undefined,
  appRunId: string | null | undefined
): ExternalPathGrant[] {
  const runId = typeof appRunId === 'string' ? appRunId.trim() : ''
  if (!chat || !runId || chatScope(chat) === 'global') return []
  const session = runManager.get(runId)
  if (
    !session ||
    session.appChatId !== chat.appChatId ||
    (session.status !== 'starting' && session.status !== 'running')
  ) {
    return []
  }
  const primaryWorkspace = resolveChatPrimaryWorkspace(
    chat,
    AppStore.getWorkspaces(),
    canonicalPath
  )
  if (!primaryWorkspace || !session.workspacePath) return []
  try {
    if (canonicalPath(session.workspacePath) !== canonicalPath(primaryWorkspace.path)) return []
  } catch {
    return []
  }

  const state = asRecord(session.state)
  const effectivePermissions = asRecord(state?.effectivePermissions)
  const stateGrants = Array.isArray(state?.externalPathGrants)
    ? (state.externalPathGrants as ExternalPathGrant[])
    : []
  const effectiveGrants = Array.isArray(effectivePermissions?.externalPathGrants)
    ? (effectivePermissions.externalPathGrants as ExternalPathGrant[])
    : []
  return normalizeExternalPathGrants([
    ...effectiveGrants,
    ...stateGrants,
    ...externalPathGrantMetadataLists(chat)
  ]).filter(
    (grant) =>
      grant.provider === session.provider &&
      isMainIssuedExternalPathGrant(grant, {
        provider: session.provider,
        appChatId: chat.appChatId,
        appRunId: runId,
        workspacePath: primaryWorkspace.path
      })
  )
}

function detectExternalPathForProviderApproval(input: {
  provider: ProviderId
  appChatId?: string
  appRunId?: string
  toolName: string
  method?: string
  params: unknown
  workspacePath?: string
}): PendingExternalPathDetection | undefined {
  const chat = input.appChatId ? AppStore.getChat(input.appChatId) : null
  const grants = input.appRunId
    ? executableExternalPathGrantsForRun(chat, input.appRunId)
    : executableExternalPathGrantsForChat(chat, input.provider)
  const detection = detectExternalPath({
    toolName: input.toolName,
    method: input.method,
    params: input.params,
    workspacePath: input.workspacePath,
    existingGrants: grants.map((grant) => ({
      path: grant.path,
      kind: grant.kind,
      access: grant.access
    }))
  })
  if (!detection.needsPrompt || !detection.path || !detection.access) return undefined
  return {
    provider: input.provider,
    path: detection.path,
    access: detection.access,
    basename: detection.basename,
    appChatId: input.appChatId
  }
}

function externalPathApprovalTitle(): string {
  return 'Grant access to a file outside this workspace?'
}

function externalPathApprovalBody(detection: PendingExternalPathDetection): string {
  const label = providerLabel(detection.provider)
  return detection.access === 'write'
    ? `${label} wants to edit a file outside the workspace.`
    : `${label} wants to read a file outside the workspace.`
}

function externalPathApprovalPreview(detection: PendingExternalPathDetection): {
  path: string
  basename?: string
  access: 'read' | 'write'
} {
  return {
    path: detection.path,
    basename: detection.basename,
    access: detection.access
  }
}

/**
 * Opaque provider CLIs cannot express TaskWraith's signed per-path
 * read-vs-write capability or revalidate it at every native file open. Never
 * widen them with `--add-dir`: external workspace access stays on the brokered
 * TaskWraith tools, where chat/run binding and canonical paths are checked for
 * every operation.
 */
function externalPathGrantsToCliAddDirArgs(_grants?: ExternalPathGrant[]): string[] {
  return []
}

/**
 * 1.0.5-EW42c — Gemini CLI variant. Gemini doesn't recognise the
 * `--add-dir` flag that Claude / Kimi use; its equivalent is
 * `--include-directories` (plural — the same flag already in use
 * for image-attachment parent dirs at the `runGeminiProvider` call
 * site). Pre-EW42c we were emitting `--add-dir` to Gemini via
 * `externalPathGrantsToCliAddDirArgs`, which Gemini silently
 * ignored — so `ExternalPathGrant`s for Gemini-routed turns were
 * cosmetic only. Gemini is now retired; this historical helper deliberately
 * follows the live providers' broker-only fail-closed posture.
 */
function externalPathGrantsToGeminiIncludeDirArgs(_grants?: ExternalPathGrant[]): string[] {
  return []
}

function codexSandboxPolicyForMode(
  approvalMode: string | undefined,
  workspace: string,
  _externalPathGrants?: ExternalPathGrant[],
  settings: AppSettings = AppStore.getSettings(),
  scope: ChatScope = 'workspace',
  _fullAccessGranted = false
) {
  const workspaceRoot = resolve(workspace)
  const hostRoot = parse(workspaceRoot).root || sep
  const gitMetadataRoots =
    scope === 'global' ? [] : codexGitMetadataRootsForWorkspace(workspaceRoot)
  const readableRoots =
    scope === 'global' ? [hostRoot] : uniqueRoots([workspaceRoot, ...gitMetadataRoots])
  const writableRoots =
    scope === 'global' ? [hostRoot] : uniqueRoots([workspaceRoot, ...gitMetadataRoots])
  if (approvalMode === 'plan') {
    return { type: 'readOnly', readableRoots, networkAccess: false }
  }
  return {
    type: 'workspaceWrite',
    writableRoots,
    readableRoots,
    networkAccess: settings.agenticServices?.networkAccess !== 'deny',
    excludeTmpdirEnvVar: false,
    excludeSlashTmp: false
  }
}

function uniqueRoots(roots: string[]): string[] {
  return [...new Set(roots.map((root) => resolve(root)))]
}

function createCodexRunState(
  sender: Electron.WebContents,
  threadId: string,
  model: string,
  cwd: string,
  workspacePath?: string,
  scope: ChatScope = 'workspace',
  route?: AgentRunRoute | null,
  payload?: AgentRunPayload
): CodexRunState {
  return {
    sender,
    threadId,
    startedAt: Date.now(),
    scope,
    cwd,
    workspacePath,
    model,
    ...(payload
      ? { reasoningEffort: resolveCodexOutboundReasoning(model, payload.reasoningEffort).effort }
      : {}),
    approvalMode: payload?.approvalMode,
    workflowMode: payload?.workflowMode,
    sessionTrust: Boolean(payload?.sessionTrust),
    externalPathGrants: payload?.externalPathGrants,
    runtimeProfileId: payload?.runtimeProfileId,
    taskWraithMcpProfileId: payload?.taskWraithMcpProfileId,
    effectivePermissions: payload?.effectivePermissions,
    ensembleRun: payload?.ensembleRun,
    ...normalizeRunRoute(route),
    assistantTextByItemId: new Map(),
    timelineStartedItemIds: new Set(),
    reasoningTextByItemId: new Map(),
    reasoningSummaryGroupIdByItemId: new Map(),
    reasoningSummaryItemIdsByGroupId: new Map(),
    commandOutputByItemId: new Map(),
    filePatchByItemId: new Map(),
    hostRerunRequestedItemIds: new Set(),
    completed: false
  }
}

/** Register the exact Codex app-server turn completion before its run state is
 * exposed or a turn/review admission request is sent. The app-server daemon is
 * shared and long-lived, so its process lifetime cannot prove that this turn
 * stopped. */
function trackCodexAppServerTurnOperation(state: CodexRunState): Promise<void> {
  const runId = state.appRunId?.trim()
  if (!runId) throw new Error('Codex app-server turn requires an exact run id.')
  const completion = createProviderTerminalProjectionOperation()
  state.terminalProjectionOperation = completion
  return providerTransportOperations.track(runId, completion.operation)
}

/** Settle only after every synchronous main-owned terminal projection and the
 * RunManager transition have completed. Idempotence covers defensive duplicate
 * terminal notifications without weakening the exact first completion. */
function completeCodexAppServerTurnProjection(state: CodexRunState): void {
  const completion = state.terminalProjectionOperation
  state.terminalProjectionOperation = undefined
  completion?.markTerminalProjectionComplete()
  if (state.turnId) state.admissionReservation?.releaseAfterExactTerminal(state.turnId)
}

const codexThreadAdmissionRegistry = new CodexThreadAdmissionRegistry()

function bindCodexRunExactOperationId(state: CodexRunState, rawOperationId: unknown): boolean {
  const operationId = codexString(rawOperationId)
  if (!operationId) return false
  if (state.turnId) return state.turnId === operationId
  const reservation = state.admissionReservation
  if (!reservation?.bindExactOperationId(operationId)) return false
  state.turnId = operationId
  if (state.appRunId) runManager.registerProviderRun(state.appRunId, operationId)
  return true
}

function codexNotificationBelongsToRunState(state: CodexRunState, message: any): boolean {
  const method = String(message?.method || '')
  const operationId = codexProviderOperationId(message)
  const isRetryableError = method === 'error' && message?.params?.willRetry === true
  const isTerminal = isCodexTerminalProjectionNotification(method) && !isRetryableError
  if (isTerminal) {
    if (!state.admissionKind || !codexTerminalMethodMatchesAdmission(state.admissionKind, method)) {
      return false
    }
    // A thread-scoped error/terminal frame cannot settle a per-operation join.
    // A terminal frame is never first-admission evidence: it may be a delayed
    // duplicate from the predecessor. Only turn/started or the RPC response can
    // bind; terminal projection requires that already-bound exact id.
    return Boolean(operationId && state.admissionReservation?.matchesExactOperationId(operationId))
  }
  if (method === 'turn/started') {
    return Boolean(operationId && bindCodexRunExactOperationId(state, operationId))
  }
  if (operationId && state.turnId && operationId !== state.turnId) return false
  return true
}

function sendCodexSyntheticToolUse(
  state: CodexRunState,
  itemId: string,
  toolName: string,
  parameters: Record<string, unknown>
) {
  sendAgentCompatLine(
    state.sender,
    'codex',
    {
      type: 'tool_use',
      tool_id: itemId,
      tool_name: toolName,
      parameters,
      provider: 'codex'
    },
    state
  )
}

function sendCodexSyntheticToolResult(
  state: CodexRunState,
  itemId: string,
  output: string,
  status: 'running' | 'success' | 'warning' | 'error' = 'success',
  // ±stat evidence riding the result: the timeline tool_use is emitted ONCE
  // per item (often before any patch content exists), so growing patch
  // updates can only reach diff derivation through their results.
  extras?: { changes?: unknown[]; kind?: string; toolName?: string }
) {
  sendAgentCompatLine(
    state.sender,
    'codex',
    {
      type: 'tool_result',
      tool_id: itemId,
      output,
      status: status === 'running' ? 'warning' : status,
      provider: 'codex',
      ...(extras?.toolName ? { tool_name: extras.toolName } : {}),
      ...(extras?.changes ? { changes: extras.changes } : {}),
      ...(extras?.kind ? { kind: extras.kind } : {})
    },
    state
  )
}

function ensureCodexTimelineTool(
  state: CodexRunState,
  itemId: string,
  toolName: string,
  parameters: Record<string, unknown>
) {
  if (state.timelineStartedItemIds.has(itemId)) return
  state.timelineStartedItemIds.add(itemId)
  sendCodexSyntheticToolUse(state, itemId, toolName, parameters)
}

function emitCodexReasoningDelta(state: CodexRunState, params: any, label: string) {
  const sourceItemId = codexTimelineItemId(params, 'codex-reasoning')
  const delta = codexReasoningSummaryText(
    params?.delta ?? params?.text ?? params?.summary ?? params?.part
  )
  if (!delta) return
  const activityId = codexReasoningSummaryActivityId(state, state.model, sourceItemId)
  const previousRaw = state.reasoningTextByItemId.get(sourceItemId) || ''
  const previousGroupText = codexReasoningSummaryGroupDisplayText(
    state,
    activityId,
    state.reasoningTextByItemId
  )
  const nextRaw = previousRaw + delta
  state.reasoningTextByItemId.set(sourceItemId, nextRaw)
  const nextGroupText = codexReasoningSummaryGroupDisplayText(
    state,
    activityId,
    state.reasoningTextByItemId
  )
  if (!nextGroupText || nextGroupText === previousGroupText) return
  ensureCodexTimelineTool(state, activityId, 'codex_reasoning', {
    title: label,
    kind: 'reasoning'
  })
  sendCodexSyntheticToolResult(state, activityId, nextGroupText, 'running', {
    toolName: 'codex_reasoning',
    kind: 'reasoning'
  })
}

function emitCodexProviderMediaRefs(state: CodexRunState, raw: unknown): void {
  const blocks = extractProviderImageBlocksFromRawEvent(raw)
  if (blocks.length === 0) return
  const store = getTranscriptMediaAssetStore()
  const refs = persistAuthorizedProviderMedia({
    isAuthorized: () => providerRunPersistenceAuthorized('codex', state),
    persist: () =>
      createOwnedToolResultMediaRefs({
        store,
        appChatId: state.appChatId,
        messageId: state.appRunId || state.turnId || state.threadId,
        runId: state.appRunId || state.turnId || undefined,
        toolName: 'codex output',
        source: 'generated',
        blocks
      }),
    revokeOnLostAuthority: async () => {
      const chatIds = [state.appChatId].filter((id): id is string => Boolean(id))
      if (chatIds.length > 0) await store.revokeChatOwnershipStrict(chatIds)
    }
  })
  if (refs.length === 0) return
  const seen = state.providerMediaRefKeys ?? new Set<string>()
  state.providerMediaRefKeys = seen
  const fresh = refs.filter((ref) => {
    const key = ref.sha256 || ref.assetId || ref.id
    if (!key || seen.has(key)) return false
    seen.add(key)
    return true
  })
  if (fresh.length === 0) return
  sendAgentCompatLine(
    state.sender,
    'codex',
    {
      type: 'media_refs',
      mediaRefs: fresh,
      provider: 'codex'
    },
    state
  )
}

function emitCodexCommandOutputDelta(state: CodexRunState, params: any) {
  const itemId = codexTimelineItemId(params, 'codex-command')
  const delta = codexString(
    params?.delta ?? params?.output ?? params?.stdout ?? params?.stderr ?? params?.content
  )
  if (!delta) return
  const command = codexCommandText(params?.command || params?.item?.command || '')
  const next = (state.commandOutputByItemId.get(itemId) || '') + delta
  state.commandOutputByItemId.set(itemId, next)
  const editMetadata = codexCommandFileEditMetadata(command, next)
  if (editMetadata) {
    ensureCodexTimelineTool(state, itemId, editMetadata.toolName, editMetadata.parameters)
  } else {
    ensureCodexTimelineTool(state, itemId, 'run_shell_command', {
      command,
      cwd: codexString(params?.cwd || params?.item?.cwd || '')
    })
  }
  sendCodexSyntheticToolResult(state, itemId, next, 'running')
}

function emitCodexPatchUpdate(state: CodexRunState, params: any) {
  const itemId = codexTimelineItemId(params, 'codex-file-change')
  const item = params?.item || {}
  const changes = params?.changes || item?.changes || params?.patch?.changes || []
  const preview = codexPatchPreviewFromValue(
    params?.patch ?? params?.diff ?? params?.changes ?? item
  )
  state.filePatchByItemId.set(itemId, { changes, preview, params })
  const firstChange = Array.isArray(changes) ? changes[0] : undefined
  const kind = firstChange?.kind || firstChange?.type || firstChange?.operation || 'update'
  const filePath =
    firstChange?.path || firstChange?.filePath || firstChange?.file_path || item?.path || ''
  ensureCodexTimelineTool(state, itemId, 'edit_file', {
    path: filePath,
    changes,
    kind,
    patchPreview: preview
  })
  sendCodexSyntheticToolResult(
    state,
    itemId,
    preview || summarizeCodexFileChanges(Array.isArray(changes) ? changes : []),
    'running',
    { ...(Array.isArray(changes) && changes.length > 0 ? { changes } : {}), kind: String(kind) }
  )
}

function emitCodexPlanItem(state: CodexRunState, item: any) {
  const itemId = codexTimelineItemId({ item }, 'codex-plan')
  const steps = item?.steps || item?.plan || item?.content || item?.text || item?.summary || item
  const output = codexString(steps)
  // Codex's native plan now feeds the unified PlanRail: parse the steps and
  // carry them in `parameters.todos` ('codex_plan' is a recognized todo tool).
  // emitCodexPlanItem fires per plan update with a stable item id, so re-emit
  // the tool-use with the refreshed steps — the once-only timeline guard would
  // otherwise freeze the plan at its initial all-pending state.
  const todos = parseTodoItemsFromUnknown(steps)
  const parameters: Record<string, unknown> = { title: 'Plan update', kind: 'plan' }
  if (todos.length > 0) {
    parameters.todos = todos
    parameters.merge = false
  }
  if (!state.timelineStartedItemIds.has(itemId)) {
    ensureCodexTimelineTool(state, itemId, 'codex_plan', parameters)
  } else if (todos.length > 0) {
    sendCodexSyntheticToolUse(state, itemId, 'codex_plan', parameters)
  }
  if (output) {
    sendCodexSyntheticToolResult(
      state,
      itemId,
      output,
      item?.status === 'failed' ? 'error' : 'success'
    )
  }
}

// ── Provider context compaction (Codex lane) ────────────────────────────────
// Codex compactions arrive as `contextCompaction` thread items riding their own
// turn (probe-verified on 0.139.0: `thread/compact/start` resolves immediately,
// then turn/started → item/started → thread/tokenUsage/updated → item/completed
// → turn/completed). Auto-compactions (the 850k `model_auto_compact_token_limit`
// TaskWraith already configures for long-context models) use the same item lane.

const maintenanceCompactionRegistry = new MaintenanceCompactionRegistry((input) => {
  const chat = AppStore.getChat(input.chatId)
  return Boolean(
    chat &&
    !historyClearAdmissionBlocked(undefined, chat.workspacePath, input.chatId) &&
    (!input.workspaceId || !chat.workspaceId || input.workspaceId === chat.workspaceId)
  )
})

function codexCurrentContextTokens(state: CodexRunState): number | undefined {
  const usage = state.tokenUsage
  const candidate =
    typeof usage?.last?.totalTokens === 'number'
      ? usage.last.totalTokens
      : typeof usage?.totalTokens === 'number'
        ? usage.totalTokens
        : undefined
  return Number.isFinite(candidate) ? candidate : undefined
}

function emitCodexContextCompaction(
  state: CodexRunState,
  kind: 'started' | 'completed',
  opts: { itemId?: string; dedupeKey?: string; onlyIfNoneAnnounced?: boolean } = {}
): void {
  const announced = state.contextCompactionAnnouncedIds ?? new Set<string>()
  state.contextCompactionAnnouncedIds = announced
  // The deprecated `thread/compacted` notification is a fallback for servers
  // that predate the item lane — skip it whenever the item lane already spoke.
  if (opts.onlyIfNoneAnnounced && announced.size > 0) return
  const key = `${kind}:${opts.itemId || opts.dedupeKey || 'compaction'}`
  if (announced.has(key)) return
  announced.add(key)
  const pendingManual = state.threadId
    ? pendingCodexManualCompactions.get(state.threadId)
    : undefined
  const telemetry: ContextCompactionTelemetry = {
    provider: 'codex',
    trigger: pendingManual ? 'manual' : 'auto'
  }
  if (opts.itemId) telemetry.eventUuid = opts.itemId
  if (kind === 'completed') {
    if (state.contextCompactionPreTokens !== undefined) {
      telemetry.preTokens = state.contextCompactionPreTokens
    }
    const post = codexCurrentContextTokens(state)
    // The compaction turn's own tokenUsage update lands BEFORE item/completed
    // (probe-observed); if it didn't, `post` still reads the pre value — omit
    // it rather than card a no-op "shrink".
    if (post !== undefined && post !== telemetry.preTokens) telemetry.postTokens = post
    if (state.contextCompactionStartedAtMs) {
      telemetry.durationMs = Date.now() - state.contextCompactionStartedAtMs
    }
    state.contextCompactionPreTokens = undefined
    state.contextCompactionStartedAtMs = undefined
    // A manual compaction can race a freshly-dispatched turn: once a run state
    // exists, notifications route HERE instead of the pending registry, so the
    // awaiting IPC would phantom-timeout (and card a spurious failure). Settle
    // it — the manual lane's card append dedupes against this lane's via the
    // shared deterministic message id (the contextCompaction item id).
    if (pendingManual) {
      pendingManual.itemId = opts.itemId || pendingManual.itemId
      pendingManual.settle({ ok: true })
    }
  }
  if (!pendingManual || maintenanceCompactionRegistry.canWrite(pendingManual.reservation)) {
    emitContextCompactionCompatLine(state.sender, 'codex', { kind, telemetry }, state)
  }
}

/**
 * A user-triggered `thread/compact/start` issued BETWEEN turns has no live
 * TaskWraith run state, so its notifications would otherwise be dropped by
 * `handleCodexNotification`'s state guard. Registered per threadId while the
 * host-side compaction IPC awaits completion.
 */
interface PendingCodexManualCompaction {
  chatId: string
  threadId: string
  startedAtMs: number
  itemId?: string
  postTokens?: number
  itemSeen?: boolean
  turnId?: string
  nativeActivityStarted?: boolean
  nativeActivityEnded?: boolean
  settled?: boolean
  reservation: MaintenanceCompactionReservation
  admissionReservation: CodexThreadAdmissionReservation
  settle: (result: { ok: boolean; error?: string }) => void
  /** Resolves when the compaction settles — the dispatch path awaits this so
   * a turn started mid-compaction can't have the compaction turn's lifecycle
   * frames (turn/started → turn/completed) drive the NEW run's state. */
  completion?: Promise<{ ok: boolean; error?: string }>
}
const pendingCodexManualCompactions = new Map<string, PendingCodexManualCompaction>()
const pendingCodexManualCompactionRequests = new Set<string>()

function bindCodexManualCompactionOperationId(
  pending: PendingCodexManualCompaction,
  rawOperationId: unknown
): boolean {
  const operationId = codexString(rawOperationId)
  if (!operationId) return false
  if (pending.turnId) return pending.turnId === operationId
  if (!pending.admissionReservation.bindExactOperationId(operationId)) return false
  pending.turnId = operationId
  return true
}

function codexNotificationBelongsToManualCompaction(
  pending: PendingCodexManualCompaction,
  message: any
): boolean {
  const method = String(message?.method || '')
  const operationId = codexProviderOperationId(message)
  if (method === 'turn/started') {
    return Boolean(operationId && bindCodexManualCompactionOperationId(pending, operationId))
  }
  if (
    method === 'turn/completed' ||
    method === 'turn/failed' ||
    method === 'error'
  ) {
    return Boolean(
      operationId && pending.admissionReservation.matchesExactOperationId(operationId)
    )
  }
  // App-server item/token frames carry turnId. Refuse thread-only attribution:
  // another accepted user/review operation may use the same long-lived thread.
  return Boolean(operationId && pending.turnId === operationId)
}

function handleCodexManualCompactionNotification(message: any): void {
  const params = message?.params || {}
  const threadId = params.threadId || params.thread?.id
  if (!threadId) return
  const pending = pendingCodexManualCompactions.get(threadId)
  if (!pending) return
  if (!codexNotificationBelongsToManualCompaction(pending, message)) return
  if (message.method === 'error' && params.willRetry === true) return
  if (message.method === 'turn/started') {
    const turnId = pending.turnId
    if (pending.reservation.signal.aborted && turnId) {
      void issueCodexTurnInterrupt(threadId, turnId)
    }
    return
  }
  if (message.method === 'thread/tokenUsage/updated') {
    const lastTotal = params.tokenUsage?.last?.totalTokens
    if (typeof lastTotal === 'number' && Number.isFinite(lastTotal)) {
      pending.postTokens = lastTotal
    }
    return
  }
  if (
    (message.method === 'item/started' || message.method === 'item/completed') &&
    isCodexContextCompactionItem(params.item)
  ) {
    pending.itemId = codexContextCompactionItemId(params.item) || pending.itemId
    if (message.method === 'item/completed') pending.itemSeen = true
    return
  }
  if (message.method === 'thread/compacted') {
    pending.itemSeen = true
    return
  }
  if (message.method === 'turn/completed' || message.method === 'turn/failed') {
    if (pending.nativeActivityStarted && !pending.nativeActivityEnded) {
      pending.nativeActivityEnded = true
      maintenanceCompactionRegistry.endNativeActivity(pending.reservation)
    }
    const status = codexString(params.turn?.status)
    const turnError = params.turn?.error
    if (pending.itemSeen && message.method !== 'turn/failed' && status !== 'failed') {
      pending.settle({ ok: true })
    } else {
      const detail = codexString(turnError?.message ?? turnError)
      pending.settle({
        ok: false,
        error: detail || `Codex compaction turn ${status || 'ended'} without compacting.`
      })
    }
    if (pending.settled) pendingCodexManualCompactions.delete(threadId)
    pending.admissionReservation.releaseAfterExactTerminal(pending.turnId)
    return
  }
  if (message.method === 'error') {
    if (pending.nativeActivityStarted && !pending.nativeActivityEnded) {
      pending.nativeActivityEnded = true
      maintenanceCompactionRegistry.endNativeActivity(pending.reservation)
    }
    const detail = codexString(params.error?.message ?? params.message ?? params)
    pending.settle({ ok: false, error: detail || 'Codex reported an error during compaction.' })
    if (pending.settled) pendingCodexManualCompactions.delete(threadId)
    pending.admissionReservation.releaseAfterExactTerminal(pending.turnId)
  }
}

/**
 * Append the persisted "Context compacted" system card to a chat, keyed by a
 * deterministic message id (the idempotency mechanism — replays and duplicate
 * signals converge on the same id and no-op). Main-authored so it also reaches
 * chats with no renderer in the foreground (bridge/iOS via `chat-updated`).
 * Returns true when a new card was appended.
 */
function appendContextCompactionMessageToChat(
  chatId: string,
  signal: ContextCompactionSignal,
  idFallbackScope: string,
  extraMetadata?: Record<string, unknown>
): boolean {
  const chat = AppStore.getChat(chatId)
  if (!chat) return false
  const messageId = contextCompactionMessageId(signal.telemetry, idFallbackScope)
  if (chat.messages.some((message) => message.id === messageId)) return false
  const provider = (signal.telemetry.provider || chat.provider) as ProviderId | undefined
  const participantLabel =
    typeof extraMetadata?.displayParticipantLabel === 'string'
      ? extraMetadata.displayParticipantLabel
      : undefined
  const summary = formatContextCompactionSummary(
    signal,
    participantLabel || (provider ? providerLabel(provider) : undefined)
  )
  const updated: ChatRecord = {
    ...chat,
    messages: [
      ...chat.messages,
      {
        id: messageId,
        role: 'system',
        content: summary,
        timestamp: new Date().toISOString(),
        metadata: {
          kind: CONTEXT_COMPACTION_MESSAGE_KIND,
          contextCompaction: {
            kind: signal.kind,
            telemetry: signal.telemetry
          },
          ...(provider ? { provider } : {}),
          ...(extraMetadata || {})
        }
      }
    ],
    updatedAt: Date.now()
  }
  AppStore.saveChat(updated)
  broadcastChatUpdated(updated)
  return true
}

function broadcastContextCompactionSignalProgress(input: {
  chatId: string
  provider: ProviderId
  signal: ContextCompactionSignal
  cardMetadata?: Record<string, unknown>
  trigger?: 'auto' | 'manual'
}): void {
  const participantId =
    typeof input.cardMetadata?.ensembleParticipantId === 'string'
      ? input.cardMetadata.ensembleParticipantId
      : undefined
  broadcastContextCompactionProgress({
    chatId: input.chatId,
    ...(participantId ? { participantId } : {}),
    provider: input.provider,
    status: input.signal.kind,
    trigger: input.trigger || input.signal.telemetry.trigger || 'manual',
    ...(typeof input.cardMetadata?.displayParticipantLabel === 'string'
      ? { label: input.cardMetadata.displayParticipantLabel }
      : {}),
    ...(typeof input.cardMetadata?.displayHueClass === 'string'
      ? { hueClass: input.cardMetadata.displayHueClass }
      : {})
  })
}

function invalidateEnsemblePromptReceiptsForSession(input: {
  chatId: string
  participantId?: string
  provider: ProviderId
  linkedProviderSessionId: string
}): boolean {
  if (!input.participantId) return false
  const fresh = AppStore.getChat(input.chatId)
  if (!fresh) return false
  const next = invalidatePromptReceiptsForMatchingEnsembleSession(fresh, {
    participantId: input.participantId,
    provider: input.provider,
    linkedProviderSessionId: input.linkedProviderSessionId
  })
  if (!next) return false
  if (next !== fresh) {
    const updated = { ...next, updatedAt: Date.now() }
    AppStore.saveChat(updated)
    broadcastChatUpdated(updated)
  }
  return true
}

/**
 * Host-triggered Codex context compaction ("compact now"). Claude's manual
 * compaction is dispatched renderer-side as a normal `/compact` run (the CLI
 * executes the slash command with `--resume`; probe-verified) — Codex instead
 * exposes a first-class `thread/compact/start` RPC on the persistent
 * app-server, which this drives end to end: register a pending record (so the
 * between-turns notifications aren't dropped), fire the RPC, await the
 * compaction turn, then persist the transcript card + durable run event.
 */
async function compactCodexProviderContext(payload: {
  chatId: string
  providerSessionId?: string
  participantId?: string
  model?: string
  reasoningEffort?: string | null
  /** Frozen ensemble-participant presentation for the card (see
   * resolveEnsembleCompactionTarget); absent on solo chats. */
  cardMetadata?: Record<string, unknown>
  reservation: MaintenanceCompactionReservation
}): Promise<{ ok: boolean; error?: string }> {
  const chat = AppStore.getChat(payload.chatId)
  if (!chat) return { ok: false, error: 'Chat not found.' }
  const threadId = payload.providerSessionId || chat.linkedProviderSessionId
  if (!threadId || !isCodexAppServerThreadId(threadId)) {
    // Review fix: card the failure — a stale renderer can offer the button on
    // a chat whose session id turned out to be a codex-exec fallback id, and a
    // silent no-op contradicts the "failure feedback arrives as the card"
    // contract the renderer relies on.
    const error = 'This chat has no resumable Codex thread yet — send a message first.'
    appendContextCompactionMessageToChat(
      payload.chatId,
      { kind: 'failed', telemetry: { provider: 'codex', trigger: 'manual', error } },
      `manual-invalid-${Date.now()}`
    )
    return { ok: false, error }
  }
  const soloMetadata = payload.participantId
    ? undefined
    : ((chat.providerMetadata || {}) as Record<string, unknown>)
  const lastSoloCodexRun = payload.participantId
    ? undefined
    : [...(chat.runs || [])].reverse().find((run) => run.provider === 'codex')
  const persistedSoloModel = resolvePersistedCodexModelSelection({
    selectedModelType: soloMetadata?.selectedModelType,
    customModel: soloMetadata?.customModel,
    lastRunActualModel: lastSoloCodexRun?.actualModel,
    lastRunRequestedModel: lastSoloCodexRun?.requestedModel,
    chatLastActualModel: chat.lastActualModel,
    chatRequestedModel: chat.requestedModel
  })
  const persistedSoloReasoning =
    typeof soloMetadata?.codexReasoningEffort === 'string'
      ? soloMetadata.codexReasoningEffort
      : providerSeatMetadataString(lastSoloCodexRun?.providerMetadata, 'reasoningEffort')
  const codexReasoning = resolveCodexOutboundReasoning(
    payload.model || persistedSoloModel,
    payload.reasoningEffort !== undefined ? payload.reasoningEffort : persistedSoloReasoning
  )
  // Reject duplicate compact-now requests synchronously, but do not publish a
  // pending provider operation until this request actually owns the shared
  // thread admission lane. Publishing a queued request would deadlock an
  // earlier normal/review owner that observes the pending map.
  if (
    pendingCodexManualCompactionRequests.has(threadId) ||
    pendingCodexManualCompactions.has(threadId)
  ) {
    return { ok: false, error: 'A compaction is already in progress for this chat.' }
  }
  pendingCodexManualCompactionRequests.add(threadId)
  let resolveCompactionInvocation!: () => void
  const compactionInvocationCompletion = new Promise<void>((resolve) => {
    resolveCompactionInvocation = resolve
  })
  const admissionReservation = codexThreadAdmissionRegistry.reserve({
    threadId,
    kind: 'manual_compaction',
    scope: {
      appChatId: payload.chatId,
      workspaceId: chat.workspaceId,
      joinAfterRelease: () => compactionInvocationCompletion
    }
  })
  let pendingRecord: PendingCodexManualCompaction | null = null
  let providerAdmissionMayBeLive = false
  try {
    const admissionAcquired = await admissionReservation.waitUntilAcquired()
    if (!admissionAcquired) {
      return { ok: false, error: 'Compaction admission was cancelled.' }
    }
    if (!maintenanceCompactionRegistry.canWrite(payload.reservation)) {
      admissionReservation.releaseBeforeAdmission()
      return { ok: false, error: 'Compaction was cancelled for history deletion.' }
    }
  const startedAtMs = Date.now()
  broadcastContextCompactionSignalProgress({
    chatId: payload.chatId,
    provider: 'codex',
    signal: { kind: 'started', telemetry: { provider: 'codex', trigger: 'manual' } },
    cardMetadata: payload.cardMetadata
  })
  let settled = false
  const completion = new Promise<{ ok: boolean; error?: string }>((resolve) => {
    const finish = (result: { ok: boolean; error?: string }) => {
      if (settled) return
      settled = true
      if (pendingRecord) pendingRecord.settled = true
      if (!pendingRecord?.nativeActivityStarted || pendingRecord.nativeActivityEnded) {
        pendingCodexManualCompactions.delete(threadId)
      }
      resolve(result)
    }
    const timer = setTimeout(
      () => finish({ ok: false, error: 'Timed out waiting for Codex to compact.' }),
      180_000
    )
    pendingRecord = {
      chatId: payload.chatId,
      threadId,
      startedAtMs,
      reservation: payload.reservation,
      admissionReservation,
      settle: (result) => {
        clearTimeout(timer)
        finish(result)
      }
    }
    pendingCodexManualCompactions.set(threadId, pendingRecord)
  })
  const pending = pendingCodexManualCompactions.get(threadId)!
  pending.completion = completion
  payload.reservation.signal.addEventListener(
    'abort',
    () => {
      if (pending.turnId) void issueCodexTurnInterrupt(threadId, pending.turnId)
    },
    { once: true }
  )
  const client = getCodexClient()
  // Review fix: the notification handler is normally attached by the RUN path
  // (runCodexAppServer) — a manual compaction issued before the first codex
  // run of the app session would otherwise stream its notifications into the
  // void and phantom-timeout despite succeeding server-side.
  client.setNotificationHandler(handleCodexNotification)
  try {
    await client.ensureStarted(app.getVersion())
  } catch (error) {
    pending.settle({
      ok: false,
      error: `Codex app-server unavailable: ${error instanceof Error ? error.message : String(error)}`
    })
  }
  if (!maintenanceCompactionRegistry.canWrite(payload.reservation)) {
    pending.settle({ ok: false, error: 'Compaction was cancelled for history deletion.' })
  }
  let compactionLaunchMayBeLive = false
  try {
    if (maintenanceCompactionRegistry.canWrite(payload.reservation)) {
      if (!maintenanceCompactionRegistry.beginNativeActivity(payload.reservation)) {
        throw new Error('Compaction was cancelled before its provider turn started.')
      }
      pending.nativeActivityStarted = true
      providerAdmissionMayBeLive = true
    }
    if (pending.nativeActivityStarted) {
      try {
        await client.request('thread/compact/start', { threadId }, 30_000)
        compactionLaunchMayBeLive = updateCodexCompactionLaunchEvidence(
          compactionLaunchMayBeLive,
          'accepted'
        )
      } catch (firstError) {
        // A timeout is ambiguous: the server may have accepted the turn before
        // its response was lost. A JSON-RPC rejection is definitive pre-start
        // evidence unless a turn/started notification independently arrived.
        if (isCodexAppServerRequestTimeout(firstError, 'thread/compact/start')) {
          compactionLaunchMayBeLive = updateCodexCompactionLaunchEvidence(
            compactionLaunchMayBeLive,
            'timeout'
          )
          // Timeout is admission-ambiguous. A retry could create a second
          // compaction turn while the first is live, so retain the lane and
          // await delayed start/terminal evidence instead.
          throw firstError
        } else {
          compactionLaunchMayBeLive = updateCodexCompactionLaunchEvidence(
            compactionLaunchMayBeLive,
            'rejected'
          )
        }
        // A cold app-server may not have the thread loaded — resume, retry once.
        if (!maintenanceCompactionRegistry.canWrite(payload.reservation)) throw firstError
        await client.request(
          'thread/resume',
          buildCodexThreadResumeRequest(threadId, codexReasoning),
          30_000
        )
        if (!maintenanceCompactionRegistry.canWrite(payload.reservation)) throw firstError
        try {
          await client.request('thread/compact/start', { threadId }, 30_000)
          compactionLaunchMayBeLive = updateCodexCompactionLaunchEvidence(
            compactionLaunchMayBeLive,
            'accepted'
          )
        } catch (secondError) {
          if (isCodexAppServerRequestTimeout(secondError, 'thread/compact/start')) {
            compactionLaunchMayBeLive = updateCodexCompactionLaunchEvidence(
              compactionLaunchMayBeLive,
              'timeout'
            )
          } else {
            compactionLaunchMayBeLive = updateCodexCompactionLaunchEvidence(
              compactionLaunchMayBeLive,
              'rejected'
            )
          }
          throw secondError
        }
      }
    }
  } catch (error) {
    if (
      pending.nativeActivityStarted &&
      !pending.nativeActivityEnded &&
      codexCompactionFailureProvesNoLiveTurn({
        launchMayBeLive: compactionLaunchMayBeLive,
        observedTurnId: pending.turnId
      })
    ) {
      // Every compact/start attempt was synchronously rejected before a turn
      // existed. Balance the reservation now; ambiguous timeouts deliberately
      // remain active until a terminal notification (or recovery-required).
      pending.nativeActivityEnded = true
      providerAdmissionMayBeLive = false
      maintenanceCompactionRegistry.endNativeActivity(payload.reservation)
      admissionReservation.releaseBeforeAdmission()
    }
    pending.settle({
      ok: false,
      error: `Codex rejected the compaction request: ${
        error instanceof Error ? error.message : String(error)
      }`
    })
  }
  const result = await completion
  if (!maintenanceCompactionRegistry.canWrite(payload.reservation)) return result
  const telemetry: ContextCompactionTelemetry = {
    provider: 'codex',
    trigger: 'manual',
    durationMs: Date.now() - startedAtMs
  }
  if (pending.itemId) telemetry.eventUuid = pending.itemId
  if (pending.postTokens !== undefined) telemetry.postTokens = pending.postTokens
  if (!result.ok && result.error) telemetry.error = result.error
  const signal: ContextCompactionSignal = {
    kind: result.ok ? 'completed' : 'failed',
    telemetry
  }
  if (result.ok) {
    invalidateEnsemblePromptReceiptsForSession({
      chatId: payload.chatId,
      participantId: payload.participantId,
      provider: 'codex',
      linkedProviderSessionId: threadId
    })
  }
  appendContextCompactionMessageToChat(
    payload.chatId,
    signal,
    `manual-${threadId}-${startedAtMs}`,
    payload.cardMetadata
  )
  broadcastContextCompactionSignalProgress({
    chatId: payload.chatId,
    provider: 'codex',
    signal,
    cardMetadata: payload.cardMetadata
  })
  const lastRunId = [...(chat.runs || [])].reverse().find((run) => run?.runId)?.runId
  if (lastRunId) {
    appendDurableRunEventForRoute(
      'codex',
      { appRunId: lastRunId, appChatId: payload.chatId },
      'context_compaction',
      'control',
      formatContextCompactionSummary(signal, providerLabel('codex')),
      { compaction: signal, manual: true }
    )
  }
  return result
  } finally {
    pendingCodexManualCompactionRequests.delete(threadId)
    if (!providerAdmissionMayBeLive) admissionReservation.releaseBeforeAdmission()
    resolveCompactionInvocation()
  }
}

/**
 * Host-triggered Claude context compaction for sessions that can't ride a
 * normal run — ensemble participant seats. A maintenance-lane SDK call, NOT an
 * agent run: no run registry, no transcript streaming, tools hard-denied
 * (plan permission mode + deny-all canUseTool; `/compact` is provider-internal
 * and never calls tools). Emits only the compaction card + durable event.
 * Solo Claude chats keep the visible `/compact` run lane instead.
 */
const activeClaudeManualCompactions = new Set<string>()
async function compactClaudeProviderContext(payload: {
  chatId: string
  providerSessionId: string
  participantId?: string
  model?: string
  cardMetadata?: Record<string, unknown>
  reservation: MaintenanceCompactionReservation
}): Promise<{ ok: boolean; error?: string }> {
  const chat = AppStore.getChat(payload.chatId)
  if (!chat) return { ok: false, error: 'Chat not found.' }
  const participant = payload.participantId
    ? chat.ensemble?.participants.find((candidate) => candidate.id === payload.participantId)
    : undefined
  if (
    payload.participantId &&
    (!participant ||
      participant.provider !== 'claude' ||
      participant.linkedProviderSessionId !== payload.providerSessionId)
  ) {
    return { ok: false, error: 'The Claude participant session changed before compaction.' }
  }
  if (
    !payload.participantId &&
    (chat.provider !== 'claude' || chat.linkedProviderSessionId !== payload.providerSessionId)
  ) {
    return { ok: false, error: 'The Claude chat session changed before compaction.' }
  }
  if (activeClaudeManualCompactions.has(payload.providerSessionId)) {
    return { ok: false, error: 'A compaction is already in progress for this session.' }
  }
  const sdk = await loadOptionalClaudeSdk()
  if (!maintenanceCompactionRegistry.canWrite(payload.reservation)) {
    return { ok: false, error: 'Compaction was cancelled for history deletion.' }
  }
  if (!sdk?.query) {
    return { ok: false, error: 'Claude Agent SDK is unavailable — cannot compact this seat.' }
  }
  const profileResolution = resolveTaskWraithMcpProfile({
    provider: 'claude',
    modelId: payload.model,
    providerSessionId: payload.providerSessionId,
    storeProviderSessionId: payload.providerSessionId,
    receipt: payload.participantId
      ? participant?.taskWraithMcpProfileReceipt
      : chat.taskWraithMcpProfileReceipt,
    coreProfileOptIn: false
  })
  const storedCompactionReceipt = payload.participantId
    ? participant?.taskWraithMcpProfileReceipt
    : chat.taskWraithMcpProfileReceipt
  const sessionWasBornWithTaskWraithMcp = isTaskWraithMcpProfileReceiptForSession(
    storedCompactionReceipt,
    { provider: 'claude', providerSessionId: payload.providerSessionId }
  )
  const compactionRoute: AgentRunRoute = { appChatId: payload.chatId }
  const compactionMcpInput = claudeTaskWraithMcpInput(
    compactionRoute,
    chat.workspacePath,
    profileResolution.profileId,
    sessionWasBornWithTaskWraithMcp || Boolean(AppStore.getSettings().geminiMcpBridgeEnabled)
  )
  const compactionMcpServers = buildClaudeTaskWraithMcpServers(compactionMcpInput)
  if (sessionWasBornWithTaskWraithMcp && !compactionMcpInput.enabled) {
    return {
      ok: false,
      error:
        'This Claude session was born with TaskWraith MCP, but that exact MCP surface cannot be reattached for compaction.'
    }
  }
  if (compactionMcpInput.enabled) {
    try {
      await startGeminiMcpBroker()
      if (!maintenanceCompactionRegistry.canWrite(payload.reservation)) {
        return { ok: false, error: 'Compaction was cancelled for history deletion.' }
      }
    } catch (error) {
      return {
        ok: false,
        error: `TaskWraith MCP could not start for Claude compaction: ${
          error instanceof Error ? error.message : String(error)
        }`
      }
    }
  }
  activeClaudeManualCompactions.add(payload.providerSessionId)
  const startedAtMs = Date.now()
  broadcastContextCompactionSignalProgress({
    chatId: payload.chatId,
    provider: 'claude',
    signal: { kind: 'started', telemetry: { provider: 'claude', trigger: 'manual' } },
    cardMetadata: payload.cardMetadata
  })
  const controller = new AbortController()
  const abortForHistoryDeletion = (): void => controller.abort()
  payload.reservation.signal.addEventListener('abort', abortForHistoryDeletion, { once: true })
  const timer = setTimeout(() => controller.abort(), 180_000)
  let observed: ContextCompactionSignal | null = null
  let streamError: string | undefined
  let compactionSessionId = payload.providerSessionId
  const seenCompactionSessionIds = new Set([compactionSessionId])
  let compactionExpectedStoreIdentity = taskWraithMcpProfileStoreIdentity({
    providerSessionId: compactionSessionId,
    receipt: storedCompactionReceipt
  })
  let compactionIdentityFailed = false
  let pathToClaudeCodeExecutable: string | undefined
  let nativeActivityStarted = false
  try {
    const model = normalizeCliProviderModel('claude', payload.model)
    if (app.isPackaged) {
      const resolvedClaude = await resolveCliProviderBinary('claude', undefined)
      if (!resolvedClaude.binaryPath) {
        throw new Error(resolvedClaude.error || 'Claude Code CLI was not found.')
      }
      pathToClaudeCodeExecutable = resolvedClaude.binaryPath
    }
    if (!maintenanceCompactionRegistry.canWrite(payload.reservation)) {
      throw new Error('Compaction was cancelled for history deletion.')
    }
    nativeActivityStarted = maintenanceCompactionRegistry.beginNativeActivity(payload.reservation)
    if (!nativeActivityStarted) {
      throw new Error('Compaction was cancelled before its provider process started.')
    }
    const stream = sdk.query({
      prompt: '/compact',
      options: {
        cwd: chat.workspacePath || globalRunCwd(),
        ...(model && model !== 'default' ? { model } : {}),
        permissionMode: 'plan',
        resume: payload.providerSessionId,
        abortController: controller,
        canUseTool: async () => ({
          behavior: 'deny' as const,
          message: 'Compaction turns run tool-free.'
        }),
        ...(compactionMcpServers ? { mcpServers: compactionMcpServers } : {}),
        ...(pathToClaudeCodeExecutable ? { pathToClaudeCodeExecutable } : {})
      }
    })
    for await (const message of stream) {
      if (!maintenanceCompactionRegistry.canWrite(payload.reservation)) {
        controller.abort()
        break
      }
      const nextSessionId = extractProviderSessionId(message)
      if (nextSessionId && nextSessionId !== compactionSessionId) {
        if (
          !shouldAcceptTaskWraithMcpSessionId({
            nextProviderSessionId: nextSessionId,
            currentProviderSessionId: compactionSessionId,
            seenProviderSessionIds: seenCompactionSessionIds
          })
        ) {
          streamError = 'Claude replayed a stale session identity during compaction.'
          compactionIdentityFailed = true
          controller.abort()
          break
        }
        if (activeClaudeManualCompactions.has(nextSessionId)) {
          streamError = 'A compaction is already in progress for the rotated Claude session.'
          compactionIdentityFailed = true
          controller.abort()
          break
        }
        const currentChat = AppStore.getChat(payload.chatId)
        const currentParticipant = payload.participantId
          ? currentChat?.ensemble?.participants.find(
              (candidate) => candidate.id === payload.participantId
            )
          : undefined
        const ownerSessionId = payload.participantId
          ? currentParticipant?.linkedProviderSessionId
          : currentChat?.linkedProviderSessionId
        const ownerReceipt = payload.participantId
          ? currentParticipant?.taskWraithMcpProfileReceipt
          : currentChat?.taskWraithMcpProfileReceipt
        const ownerMatches = Boolean(
          currentChat &&
          (payload.participantId
            ? currentParticipant?.provider === 'claude'
            : currentChat.provider === 'claude') &&
          ownerSessionId === compactionSessionId
        )
        const transition = ownerMatches
          ? transitionTaskWraithMcpProfileReceipt({
              provider: 'claude',
              profileId: profileResolution.profileId,
              mcpAdvertised: compactionMcpInput.enabled,
              nextProviderSessionId: nextSessionId,
              previousRunProviderSessionId: compactionSessionId,
              expectedStoreIdentity: compactionExpectedStoreIdentity,
              currentStoreSessionId: ownerSessionId,
              currentReceipt: ownerReceipt
            })
          : { accepted: false as const, reason: 'stale_store_identity' as const }
        if (!transition.accepted || !currentChat) {
          streamError = 'The Claude session changed while compaction was rotating its identity.'
          compactionIdentityFailed = true
          controller.abort()
          break
        }
        const updatedChat: ChatRecord = payload.participantId
          ? {
              ...currentChat,
              ensemble: {
                ...currentChat.ensemble!,
                participants: currentChat.ensemble!.participants.map((candidate) =>
                  candidate.id === payload.participantId
                    ? {
                        ...candidate,
                        linkedProviderSessionId: nextSessionId,
                        taskWraithMcpProfileReceipt: transition.receipt
                      }
                    : candidate
                )
              },
              updatedAt: Date.now()
            }
          : {
              ...currentChat,
              linkedProviderSessionId: nextSessionId,
              taskWraithMcpProfileReceipt: transition.receipt,
              updatedAt: Date.now()
            }
        saveAndBroadcastChat(updatedChat)
        compactionExpectedStoreIdentity = taskWraithMcpProfileStoreIdentity({
          providerSessionId: nextSessionId,
          receipt: transition.receipt
        })
        seenCompactionSessionIds.add(nextSessionId)
        activeClaudeManualCompactions.add(nextSessionId)
        compactionSessionId = nextSessionId
      }
      const signal = normalizeClaudeContextCompactionEvent(message)
      if (!signal) continue
      if (signal.kind === 'completed') observed = signal
      else if (signal.kind === 'failed' && !observed) observed = signal
    }
  } catch (error) {
    streamError ||= error instanceof Error ? error.message : String(error)
  } finally {
    clearTimeout(timer)
    payload.reservation.signal.removeEventListener('abort', abortForHistoryDeletion)
    if (nativeActivityStarted) {
      maintenanceCompactionRegistry.endNativeActivity(payload.reservation)
    }
    for (const sessionId of seenCompactionSessionIds) {
      activeClaudeManualCompactions.delete(sessionId)
    }
  }
  const signal: ContextCompactionSignal = compactionIdentityFailed
    ? {
        kind: 'failed',
        telemetry: {
          error: streamError || 'Claude did not report a compaction for this session.'
        }
      }
    : observed && observed.kind === 'completed'
      ? observed
      : (observed ?? {
          kind: 'failed',
          telemetry: {
            error: streamError || 'Claude did not report a compaction for this session.'
          }
        })
  signal.telemetry = {
    ...signal.telemetry,
    provider: 'claude',
    trigger: signal.telemetry.trigger || 'manual',
    durationMs: signal.telemetry.durationMs ?? Date.now() - startedAtMs
  }
  if (!maintenanceCompactionRegistry.canWrite(payload.reservation)) {
    return { ok: false, error: 'Compaction was cancelled for history deletion.' }
  }
  if (signal.kind === 'completed') {
    invalidateEnsemblePromptReceiptsForSession({
      chatId: payload.chatId,
      participantId: payload.participantId,
      provider: 'claude',
      linkedProviderSessionId: compactionSessionId
    })
  }
  appendContextCompactionMessageToChat(
    payload.chatId,
    signal,
    `manual-claude-${payload.providerSessionId}-${startedAtMs}`,
    payload.cardMetadata
  )
  broadcastContextCompactionSignalProgress({
    chatId: payload.chatId,
    provider: 'claude',
    signal,
    cardMetadata: payload.cardMetadata
  })
  const lastRunId = [...(chat.runs || [])].reverse().find((run) => run?.runId)?.runId
  if (lastRunId) {
    appendDurableRunEventForRoute(
      'claude',
      { appRunId: lastRunId, appChatId: payload.chatId },
      'context_compaction',
      'control',
      formatContextCompactionSummary(signal, providerLabel('claude')),
      { compaction: signal, manual: true }
    )
  }
  return signal.kind === 'completed' ? { ok: true } : { ok: false, error: signal.telemetry.error }
}

/** Kimi Code native compaction for an ensemble seat. Solo Kimi chats dispatch
 * the same `/compact` command through the visible normal-run lane; ensemble
 * seats need this detached maintenance lane so no extra participant answer is
 * appended to the active round. The command resumes the exact ACP session,
 * hard-denies tools, and never falls back to a fresh empty session. */
const activeKimiNativeCompactions = new Set<string>()
async function compactKimiProviderContext(payload: {
  chatId: string
  providerSessionId: string
  participantId: string
  model?: string
  cardMetadata?: Record<string, unknown>
  trigger?: 'auto' | 'manual'
  reservation: MaintenanceCompactionReservation
}): Promise<{ ok: boolean; error?: string }> {
  const chat = AppStore.getChat(payload.chatId)
  if (!chat?.ensemble) return { ok: false, error: 'Ensemble chat not found.' }
  const participant = chat.ensemble.participants.find(
    (candidate) => candidate.id === payload.participantId
  )
  if (
    !participant ||
    participant.provider !== 'kimi' ||
    participant.linkedProviderSessionId !== payload.providerSessionId ||
    participant.kimiAcpNativeSession !== true ||
    !isKimiAcpProductionPosture(participant.kimiAcpPostureVersion)
  ) {
    return { ok: false, error: 'The Kimi native session changed before compaction.' }
  }
  if (activeKimiNativeCompactions.has(payload.providerSessionId)) {
    return { ok: false, error: 'A compaction is already in progress for this Kimi session.' }
  }
  const workspace = chat.workspacePath
  const resolved = await resolveCliProviderBinary('kimi', undefined)
  if (!maintenanceCompactionRegistry.canWrite(payload.reservation)) {
    return { ok: false, error: 'Compaction was cancelled for history deletion.' }
  }
  if (!resolved.binaryPath) {
    return { ok: false, error: resolved.error || 'Kimi Code CLI was not found.' }
  }
  const admission = await admitKimiRuntime({
    binaryPath: resolved.binaryPath,
    isPackaged: app.isPackaged,
    environment: process.env
  })
  if (!maintenanceCompactionRegistry.canWrite(payload.reservation)) {
    return { ok: false, error: 'Compaction was cancelled for history deletion.' }
  }
  if (!admission.admitted || !kimiAcpEnabled()) {
    return {
      ok: false,
      error: admission.admitted
        ? 'Kimi ACP is disabled; native compaction cannot use a legacy transport.'
        : `Kimi runtime admission blocked native compaction: ${admission.message}`
    }
  }
  const home = await prepareKimiIsolatedHome({
    runId: `compact-${payload.chatId}-${payload.participantId}`,
    homeDir: kimiAcpSeatHomeDirForIdentity(payload.chatId, payload.participantId),
    boundaryRoot: kimiAcpSeatStateRoot(app.getPath('userData')),
    sourceHome: join(os.homedir(), '.kimi-code'),
    thinkingEnabled: participant.thinkingEnabled ?? true,
    preserveSessionState: true,
    strictCleanup: true,
    fs: kimiHomeFsAdapter
  })
  if (!home.ok) return { ok: false, error: home.message }
  if (!maintenanceCompactionRegistry.canWrite(payload.reservation)) {
    await home.cleanup()
    return { ok: false, error: 'Compaction was cancelled for history deletion.' }
  }

  let privateCwd: KimiPrivateRunCwd
  try {
    privateCwd = await prepareKimiPrivateRunCwd({
      isolatedHome: home.home,
      fs: kimiPrivateCwdFsAdapter
    })
  } catch (error) {
    await home.cleanup()
    return {
      ok: false,
      error: `Kimi's private compaction cwd could not be created. ${
        error instanceof Error ? error.message : String(error)
      }`
    }
  }
  if (!maintenanceCompactionRegistry.canWrite(payload.reservation)) {
    await createJoinedKimiCleanup(
      () => privateCwd.cleanup(),
      () => home.cleanup()
    )()
    return { ok: false, error: 'Compaction was cancelled for history deletion.' }
  }

  const compactionRoute: AgentRunRoute = {
    appChatId: payload.chatId,
    appRunId: `kimi-compact-${randomUUID()}`
  }
  const trigger = payload.trigger || 'manual'
  const startedAtMs = Date.now()
  activeKimiNativeCompactions.add(payload.providerSessionId)
  broadcastContextCompactionSignalProgress({
    chatId: payload.chatId,
    provider: 'kimi',
    signal: { kind: 'started', telemetry: { provider: 'kimi', trigger } },
    cardMetadata: payload.cardMetadata,
    trigger
  })

  let lastWarning: string | undefined
  let handle: ReturnType<typeof runKimiAcpTurn> | null = null
  let child: import('./kimi/KimiAcpClient').AcpChildProcess | null = null
  let nativeActivityStarted = false
  let deletionForceKillTimer: ReturnType<typeof setTimeout> | null = null
  const cancelForHistoryDeletion = (): void => {
    handle?.cancel()
    try {
      child?.kill()
    } catch {
      // Close evidence, not kill()'s return value, settles native activity.
    }
    deletionForceKillTimer = setTimeout(() => {
      try {
        child?.kill('SIGKILL')
      } catch {
        // The exact close callback remains the join authority.
      }
    }, 5_000)
    deletionForceKillTimer.unref?.()
  }
  payload.reservation.signal.addEventListener('abort', cancelForHistoryDeletion, { once: true })
  let teardown = createJoinedKimiCleanup(
    () => privateCwd.cleanup(),
    () => home.cleanup()
  )
  const outcome = await new Promise<{ ok: boolean; error?: string; quarantined?: boolean }>(
    (resolveOutcome) => {
      let settled = false
      let timedOut = false
      let quarantined = false
      let timer: ReturnType<typeof setTimeout> | null = null
      let forceTimer: ReturnType<typeof setTimeout> | null = null
      let quarantineTimer: ReturnType<typeof setTimeout> | null = null
      const clearTimers = (): void => {
        if (timer) clearTimeout(timer)
        if (forceTimer) clearTimeout(forceTimer)
        if (quarantineTimer) clearTimeout(quarantineTimer)
      }
      const finish = (result: { ok: boolean; error?: string; quarantined?: boolean }): void => {
        if (settled) return
        settled = true
        clearTimers()
        resolveOutcome(result)
      }
      void launchKimiProductionAcp({
        taskWraithMcpAdvertised: true,
        privateCwd,
        assertRuntimeReadyForSpawn: admission.assertReadyForSpawn,
        startGateway: async () => {
          const bridge = await startKimiHttpMcpBridge({
            dispatch: createKimiMcpDispatch({
              route: compactionRoute,
              workspace,
              appVersion: app.getVersion(),
              brokerToken: geminiMcpBrokerToken,
              getMcpToolDefinitions: () => mcpToolDefinitions(),
              dispatchBrokerRequest: (request) =>
                mcpBridgeRuntime.handleGeminiMcpBrokerRequest(request)
            })
          })
          return {
            server: {
              name: 'taskwraith',
              type: 'http',
              url: bridge.url,
              headers: [{ name: bridge.headerName, value: bridge.headerValue }]
            },
            close: () => bridge.close()
          }
        },
        snapshot: {
          appVersion: app.getVersion(),
          prompt: '/compact',
          requestedResumeSessionId: payload.providerSessionId,
          persistedPostureVersion: participant.kimiAcpPostureVersion
        },
        launch: (production, transportCleanup, admittedBinaryPath) => {
          if (!production.session.resumeSessionId) {
            throw new Error('The Kimi native session is not eligible for safe resume.')
          }
          teardown = createJoinedKimiCleanup(transportCleanup, () => home.cleanup())
          handle = runKimiAcpTurn({
            prompt: production.session.prompt,
            resumeSessionId: production.session.resumeSessionId,
            allowResumeFallback: false,
            cwd: production.cwd,
            initializeParams: production.initializeParams,
            mcpServers: production.mcpServers,
            spawnProcess: () => {
              const modelArgs: string[] = []
              appendKimiModelArgs(
                modelArgs,
                normalizeCliProviderModel('kimi', payload.model || participant.model),
                participant.fastModeEnabled ? 'fast' : 'standard'
              )
              nativeActivityStarted = maintenanceCompactionRegistry.beginNativeActivity(
                payload.reservation
              )
              if (!nativeActivityStarted) {
                throw new Error('Compaction was cancelled before Kimi ACP spawn.')
              }
              try {
                child = spawn(admittedBinaryPath, [...modelArgs, 'acp'], {
                  cwd: production.cwd,
                  env: buildKimiContainedProcessEnv(
                    createCliEnv(
                      {
                        ...home.env,
                        HOME: home.home,
                        USERPROFILE: home.home,
                        TASKWRAITH_PARENT_PROVIDER: 'kimi',
                        TASKWRAITH_RUN_ID: compactionRoute.appRunId || '',
                        TASKWRAITH_CHAT_ID: payload.chatId
                      },
                      admittedBinaryPath
                    ),
                    production.cwd
                  )
                }) as unknown as import('./kimi/KimiAcpClient').AcpChildProcess
                return child
              } catch (error) {
                maintenanceCompactionRegistry.endNativeActivity(payload.reservation)
                nativeActivityStarted = false
                throw error
              }
            },
            beforeInitialize: async (providerChild) => {
              const proc = providerChild as unknown as ChildProcess
              await home.noteProviderProcess(proc.pid || 0)
            },
            // Native compaction is provider-internal and must remain tool-free.
            onPermissionRequest: () => 'deny',
            onEvent: (event) => {
              if (event.type === 'provider_warning' && event.text) lastWarning = event.text
            },
            onClose: (_code, turnComplete, terminalStatus) => {
              if (deletionForceKillTimer) {
                clearTimeout(deletionForceKillTimer)
                deletionForceKillTimer = null
              }
              if (quarantined) {
                // The provider process has finally closed, so the quarantined
                // resources can be removed. Keep the seat reserved if strict
                // cleanup still fails after retry; releasing it would allow a
                // new compaction to overlap credential-bearing residue.
                void (async () => {
                  try {
                    try {
                      await teardown()
                    } catch {
                      await teardown()
                    }
                    if (nativeActivityStarted) {
                      maintenanceCompactionRegistry.endNativeActivity(payload.reservation)
                      nativeActivityStarted = false
                    }
                    activeKimiNativeCompactions.delete(payload.providerSessionId)
                  } catch (error) {
                    console.warn(
                      '[Kimi ACP] quarantined compaction cleanup failed after retry:',
                      error instanceof Error ? error.message : String(error)
                    )
                  }
                })()
                return
              }
              if (nativeActivityStarted) {
                maintenanceCompactionRegistry.endNativeActivity(payload.reservation)
                nativeActivityStarted = false
              }
              const succeeded =
                !timedOut &&
                turnComplete &&
                (terminalStatus === 'success' || terminalStatus === 'end_turn')
              finish({
                ok: succeeded,
                ...(succeeded
                  ? {}
                  : { error: lastWarning || 'Kimi Code did not complete native compaction.' })
              })
            }
          })
          return handle
        }
      })
        .then((launched) => {
          handle = launched.handle
          if (payload.reservation.signal.aborted) {
            handle.cancel()
            child?.kill()
          }
          if (settled) return
          timer = setTimeout(() => {
            timedOut = true
            lastWarning = 'Timed out waiting for Kimi Code to compact.'
            handle?.cancel()
            forceTimer = setTimeout(() => child?.kill('SIGKILL'), 5_000)
            quarantineTimer = setTimeout(() => {
              quarantined = true
              finish({
                ok: false,
                error:
                  'Kimi compaction did not close after forced termination; its seat resources remain quarantined.',
                quarantined: true
              })
            }, 15_000)
          }, 180_000)
        })
        .catch((error) => {
          finish({ ok: false, error: error instanceof Error ? error.message : String(error) })
        })
    }
  )

  if (!outcome.quarantined) {
    let cleanupError: unknown
    try {
      await teardown()
    } catch {
      try {
        await teardown()
      } catch (error) {
        cleanupError = error
      }
    }
    activeKimiNativeCompactions.delete(payload.providerSessionId)
    if (cleanupError) {
      outcome.ok = false
      outcome.error = `Kimi compaction cleanup failed after retry: ${
        cleanupError instanceof Error ? cleanupError.message : String(cleanupError)
      }`
    }
  }
  const telemetry: ContextCompactionTelemetry = {
    provider: 'kimi',
    trigger,
    durationMs: Date.now() - startedAtMs,
    ...(outcome.error ? { error: outcome.error } : {})
  }
  const signal: ContextCompactionSignal = {
    kind: outcome.ok ? 'completed' : 'failed',
    telemetry
  }
  if (!maintenanceCompactionRegistry.canWrite(payload.reservation)) {
    return { ok: false, error: 'Compaction was cancelled for history deletion.' }
  }
  if (outcome.ok) {
    invalidateEnsemblePromptReceiptsForSession({
      chatId: payload.chatId,
      participantId: payload.participantId,
      provider: 'kimi',
      linkedProviderSessionId: payload.providerSessionId
    })
  }
  appendContextCompactionMessageToChat(
    payload.chatId,
    signal,
    `native-kimi-${payload.providerSessionId}-${startedAtMs}`,
    payload.cardMetadata
  )
  broadcastContextCompactionSignalProgress({
    chatId: payload.chatId,
    provider: 'kimi',
    signal,
    cardMetadata: payload.cardMetadata,
    trigger
  })
  const lastRunId = [...(chat.runs || [])].reverse().find((run) => run?.runId)?.runId
  if (lastRunId) {
    appendDurableRunEventForRoute(
      'kimi',
      { appRunId: lastRunId, appChatId: payload.chatId },
      'context_compaction',
      'control',
      formatContextCompactionSummary(signal, providerLabel('kimi')),
      { compaction: signal, manual: trigger === 'manual', native: true }
    )
  }
  return outcome
}

/**
 * Host-side SEAT compaction for ensemble Grok participants (wave 3). A
 * maintenance-lane one-shot
 * CLI spawn OUTSIDE the run registry (mirrors compactClaudeProviderContext):
 *  - grok: sequential fresh read-only children carry bounded transcript
 *    material in-prompt, chain and checkpoint the rolling summary after every
 *    exact-prefix advance, and stop at the shared deadline/source cap. Grok's
 *    persistent ACP seat is disposed only after fresh complete-coverage proof.
 * Bounded provenance is progress metadata only and never authorizes transcript
 * pruning.
 * The pending registry is awaited by the orchestrator's dispatch path so a
 * round started mid-compaction can't race the session reset.
 */
const pendingSeatCompactions = new Map<string, Promise<{ ok: boolean; error?: string }>>()

function seatCompactionKey(chatId: string, participantId: string): string {
  return `${chatId}:${participantId}`
}

function seatRunPreTokens(chat: ChatRecord, participantId: string): number | undefined {
  const run = [...(chat.runs || [])]
    .reverse()
    .find((candidate) => candidate?.ensembleParticipantId === participantId && candidate?.stats)
  const stats = run?.stats as Record<string, unknown> | undefined
  const input = typeof stats?.input_tokens === 'number' ? stats.input_tokens : 0
  const output = typeof stats?.output_tokens === 'number' ? stats.output_tokens : 0
  const total = input + output
  return Number.isFinite(total) && total > 0 ? total : undefined
}

async function runHostSeatSummaryProcess(input: {
  provider: 'grok'
  binaryPath: string
  args: string[]
  timeoutMs: number
  reservation: MaintenanceCompactionReservation
}): Promise<HostSeatCompactionChunkResult> {
  let summaryText = ''
  let timedOut = false
  let processError: string | undefined
  let exitCode = -1
  try {
    const plan = createCliSpawnPlan(input.binaryPath, input.args)
    exitCode = await new Promise<number>((resolve) => {
      if (!maintenanceCompactionRegistry.beginNativeActivity(input.reservation)) {
        processError = 'Compaction was cancelled before its provider process started.'
        resolve(-1)
        return
      }
      let child: ReturnType<typeof spawn>
      try {
        child = spawn(plan.command, plan.args, {
          shell: plan.shell,
          stdio: ['ignore', 'pipe', 'pipe'],
          env: createCliEnv({}, input.binaryPath)
        })
      } catch (error) {
        maintenanceCompactionRegistry.endNativeActivity(input.reservation)
        processError = error instanceof Error ? error.message : String(error)
        resolve(-1)
        return
      }
      // Provider banners/warnings are not summary material, but the pipe must
      // still be drained or a noisy CLI can backpressure itself into a hang.
      child.stderr?.resume()
      let settled = false
      const settle = (code: number): void => {
        if (settled) return
        settled = true
        clearTimeout(killTimer)
        resolve(code)
      }
      let nativeClosed = false
      const recordNativeClose = (): void => {
        if (nativeClosed) return
        nativeClosed = true
        maintenanceCompactionRegistry.endNativeActivity(input.reservation)
      }
      let deletionForceKillTimer: ReturnType<typeof setTimeout> | null = null
      const cancelForHistoryDeletion = (): void => {
        try {
          child.kill()
        } catch {
          // Exact close remains the only native termination evidence.
        }
        deletionForceKillTimer = setTimeout(() => {
          try {
            child.kill('SIGKILL')
          } catch {
            // Exact close remains the only native termination evidence.
          }
        }, 5_000)
        deletionForceKillTimer.unref?.()
      }
      input.reservation.signal.addEventListener('abort', cancelForHistoryDeletion, {
        once: true
      })
      if (input.reservation.signal.aborted) cancelForHistoryDeletion()
      const killTimer = setTimeout(
        () => {
          timedOut = true
          try {
            child.kill()
          } catch {
            // Already gone.
          }
          // A wedged child may never emit `close` after SIGTERM. End the accepted
          // maintenance request at its hard deadline; timedOut prevents another
          // chunk from spawning, and a later close is ignored by settle().
          settle(-1)
        },
        Math.max(1, Math.trunc(input.timeoutMs))
      )
      let buffer = ''
      const handleLine = (line: string): void => {
        const trimmed = line.trim()
        if (!trimmed) return
        let parsed: Record<string, unknown> | null = null
        try {
          parsed = JSON.parse(trimmed)
        } catch {
          return // banners / non-JSON noise — never summary material
        }
        for (const event of grokEventToRunEvents({ json: parsed ?? undefined })) {
          if (event.type === 'content' && event.text) summaryText += event.text
        }
      }
      child.stdout?.on('data', (chunk: Buffer) => {
        buffer += chunk.toString('utf8')
        const lines = buffer.split('\n')
        buffer = lines.pop() || ''
        for (const line of lines) handleLine(line)
      })
      child.on('error', (error) => {
        processError = error instanceof Error ? error.message : String(error)
        settle(-1)
      })
      child.on('close', (code) => {
        input.reservation.signal.removeEventListener('abort', cancelForHistoryDeletion)
        if (deletionForceKillTimer) clearTimeout(deletionForceKillTimer)
        recordNativeClose()
        if (buffer.trim()) handleLine(buffer)
        settle(typeof code === 'number' ? code : -1)
      })
    })
  } catch (error) {
    processError = error instanceof Error ? error.message : String(error)
  }
  return {
    ok: exitCode === 0 && !timedOut,
    text: summaryText,
    ...(timedOut ? { timedOut: true } : {}),
    ...(exitCode !== 0 || timedOut
      ? {
          error: timedOut
            ? 'Timed out waiting for the seat summarize turn.'
            : processError || `Seat summarize turn failed (exit ${exitCode}).`
        }
      : {})
  }
}

function persistHostSeatCompactionCheckpoint(input: {
  chatId: string
  identity: HostSeatCompactionIdentity
  snapshotEligibleRows: ReturnType<typeof conversationCompactionEligibleRows>
  expectedPreviousSummary: HostSeatContextSummary | undefined
  nextSummary: HostSeatContextSummary
  claimedMessageIds?: readonly string[]
  clearProviderSession?: boolean
  reservation: MaintenanceCompactionReservation
}): { ok: true } | { ok: false; error: string } {
  if (!maintenanceCompactionRegistry.canWrite(input.reservation)) {
    return { ok: false, error: 'Compaction was cancelled for history deletion.' }
  }
  const fresh = AppStore.getChat(input.chatId)
  if (!fresh?.ensemble) return { ok: false, error: 'The chat or ensemble no longer exists.' }
  const currentWorkspace = fresh.workspacePath || globalRunCwd()
  const freshness = validateHostSeatCheckpointFreshness({
    chat: fresh,
    currentWorkspace,
    identity: input.identity,
    snapshotEligibleRows: input.snapshotEligibleRows,
    expectedPreviousSummary: input.expectedPreviousSummary,
    nextSummary: input.nextSummary,
    ...(input.claimedMessageIds ? { claimedMessageIds: input.claimedMessageIds } : {})
  })
  if (!freshness.ok) return freshness

  const participants = fresh.ensemble.participants.map((participant) => {
    if (participant.id !== input.identity.participantId) return participant
    const next: EnsembleParticipant = {
      ...participant,
      // Keep the controller's expected-next summary detached from the object
      // handed to AppStore, preserving the next chunk's exact-summary CAS even
      // if a downstream cache mutates its stored record in place.
      contextCompactionSummary: structuredClone(input.nextSummary),
      ...(input.clearProviderSession ? { linkedProviderSessionId: null } : {})
    }
    delete next.promptShellVersion
    delete next.promptDynamicStateVersion
    return next
  })
  const updated: ChatRecord = {
    ...fresh,
    ensemble: { ...fresh.ensemble, participants },
    updatedAt: Date.now()
  }
  AppStore.saveChat(updated)
  broadcastChatUpdated(updated)
  return { ok: true }
}

async function compactCliSeatContext(payload: {
  chatId: string
  participantId: string
  provider: 'grok'
  providerSessionId?: string | null
  model?: string
  cardMetadata?: Record<string, unknown>
  trigger?: 'auto' | 'manual'
  reservation: MaintenanceCompactionReservation
}): Promise<{ ok: boolean; error?: string }> {
  const pendingKey = seatCompactionKey(payload.chatId, payload.participantId)
  const existing = pendingSeatCompactions.get(pendingKey)
  if (existing) return { ok: false, error: 'A compaction is already in progress for this seat.' }
  const work = (async (): Promise<{ ok: boolean; error?: string }> => {
    const chat = AppStore.getChat(payload.chatId)
    if (!chat) return { ok: false, error: 'Chat not found.' }
    const seat = chat.ensemble?.participants?.find(
      (participant) => participant.id === payload.participantId
    )
    if (!seat) return { ok: false, error: 'Participant not found on this ensemble.' }
    if (seat.provider !== payload.provider) {
      return { ok: false, error: 'Participant provider does not match the compaction request.' }
    }
    const startedAtMs = Date.now()
    const trigger = payload.trigger || 'manual'
    const preTokens = seatRunPreTokens(chat, payload.participantId)
    const workspace = chat.workspacePath || globalRunCwd()
    // Freeze every input that gives the maintenance turn authority. The
    // controller never re-selects from a moving transcript, and checkpoint CAS
    // compares against this detached summary rather than an AppStore alias.
    const snapshotEligibleRows = conversationCompactionEligibleRows(chat.messages || [])
    const snapshotMessages: ChatMessage[] = snapshotEligibleRows.map((row) => ({
      ...row,
      timestamp: ''
    }))
    const previousSummary = seat.contextCompactionSummary
      ? (structuredClone(seat.contextCompactionSummary) as HostSeatContextSummary)
      : undefined
    const identity: HostSeatCompactionIdentity = {
      participantId: payload.participantId,
      provider: payload.provider,
      model: seat.model,
      linkedProviderSessionId: seat.linkedProviderSessionId,
      workspace
    }
    const progressBase: Omit<ContextCompactionProgressEvent, 'status'> = {
      chatId: payload.chatId,
      participantId: payload.participantId,
      provider: payload.provider,
      trigger,
      ...(typeof payload.cardMetadata?.displayParticipantLabel === 'string'
        ? { label: payload.cardMetadata.displayParticipantLabel }
        : {}),
      ...(typeof payload.cardMetadata?.displayHueClass === 'string'
        ? { hueClass: payload.cardMetadata.displayHueClass }
        : {})
    }
    const resolved = await resolveCliProviderBinary(payload.provider, undefined)
    if (!maintenanceCompactionRegistry.canWrite(payload.reservation)) {
      return { ok: false, error: 'Compaction was cancelled for history deletion.' }
    }
    if (!resolved.binaryPath) {
      return {
        ok: false,
        error: resolved.error || `${providerLabel(payload.provider)} CLI was not found.`
      }
    }
    broadcastContextCompactionProgress({ ...progressBase, status: 'started' })
    let succeeded = false
    let failureError: string | undefined
    let checkpointCount = 0
    let coverageComplete = false
    let maintenanceStopReason = 'no_progress'

    const convergence = await convergeHostSeatCompaction({
      provider: payload.provider,
      snapshotMessages,
      initialSummary: previousSummary,
      preTokens,
      startedAtMs,
      now: () => Date.now(),
      nowIso: () => new Date().toISOString(),
      summarize: async ({ prompt, timeoutMs }) => {
        if (!maintenanceCompactionRegistry.canWrite(payload.reservation)) {
          return {
            ok: false,
            text: '',
            error: 'Compaction was cancelled for history deletion.'
          }
        }
        const args = buildGrokCliArgs({
          prompt,
          workspace,
          model: identity.model,
          approvalMode: 'plan'
        })
        return runHostSeatSummaryProcess({
          provider: payload.provider,
          binaryPath: resolved.binaryPath!,
          args,
          timeoutMs,
          reservation: payload.reservation
        })
      },
      checkpoint: ({ expectedPreviousSummary, nextSummary, claimedMessageIds }) =>
        persistHostSeatCompactionCheckpoint({
          chatId: payload.chatId,
          identity,
          snapshotEligibleRows,
          expectedPreviousSummary,
          nextSummary,
          claimedMessageIds,
          reservation: payload.reservation
        })
    })
    checkpointCount = convergence.checkpointCount
    coverageComplete = convergence.coverageComplete
    const finalSummary = convergence.finalSummary
    maintenanceStopReason = convergence.stopReason
    const maintenanceStopError = convergence.error
    succeeded = hostSeatCompactionRequestSucceeded(convergence)
    if (!succeeded) failureError = convergence.error || 'The seat summary made no durable progress.'

    if (coverageComplete && finalSummary) {
      // Re-read after the controller returns. No await occurs between this
      // exact-current-coverage fence and registry disposal, so a new eligible
      // row, seat relink, or summary replacement blocks destructive reset.
      const fresh = maintenanceCompactionRegistry.canWrite(payload.reservation)
        ? AppStore.getChat(payload.chatId)
        : null
      if (
        fresh &&
        canDisposeGrokSeatAfterCompaction({
          chat: fresh,
          currentWorkspace: fresh.workspacePath || globalRunCwd(),
          identity,
          snapshotEligibleRows,
          finalSummary
        })
      ) {
        grokSeatSessionRegistry.disposeSeat(`${payload.chatId}:${payload.participantId}`)
      }
    }

    const telemetry: ContextCompactionTelemetry = {
      provider: payload.provider,
      trigger,
      durationMs: Date.now() - startedAtMs,
      ...(preTokens !== undefined ? { preTokens } : {}),
      ...(!succeeded && failureError ? { error: failureError } : {})
    }
    const signal: ContextCompactionSignal = {
      kind: succeeded ? 'completed' : 'failed',
      telemetry
    }
    if (!maintenanceCompactionRegistry.canWrite(payload.reservation)) {
      return { ok: false, error: 'Compaction was cancelled for history deletion.' }
    }
    appendContextCompactionMessageToChat(
      payload.chatId,
      signal,
      `seat-${payload.participantId}-${startedAtMs}`,
      payload.cardMetadata
    )
    broadcastContextCompactionProgress({
      ...progressBase,
      status: signal.kind === 'completed' ? 'completed' : 'failed'
    })
    const lastSeatRunId = [...(chat.runs || [])]
      .reverse()
      .find((run) => run?.ensembleParticipantId === payload.participantId && run?.runId)?.runId
    const lastRunId = lastSeatRunId || [...(chat.runs || [])].reverse().find((r) => r?.runId)?.runId
    if (lastRunId) {
      appendDurableRunEventForRoute(
        payload.provider,
        { appRunId: lastRunId, appChatId: payload.chatId },
        'context_compaction',
        'control',
        formatContextCompactionSummary(signal, providerLabel(payload.provider)),
        {
          compaction: signal,
          seat: payload.participantId,
          checkpointCount,
          coverageComplete,
          maintenanceStopReason,
          ...(maintenanceStopError ? { maintenanceStopError } : {})
        }
      )
    }
    return signal.kind === 'completed' ? { ok: true } : { ok: false, error: signal.telemetry.error }
  })()
  pendingSeatCompactions.set(pendingKey, work)
  try {
    return await work
  } finally {
    pendingSeatCompactions.delete(pendingKey)
  }
}

/**
 * Unified entry for the `compact-provider-context` IPC. Solo chats compact
 * the chat's own linked session; ensemble requests name a participant, whose
 * seat session + frozen presentation labels are resolved here (rounds must be
 * idle — compacting under a live round would race the orchestrator's
 * dispatch/flush cycle).
 */
async function compactProviderContextForRequest(payload: {
  chatId: string
  provider: 'claude' | 'codex' | 'cursor' | 'kimi' | 'grok'
  providerSessionId?: string
  participantId?: string
  /** 'auto' only from the orchestrator's post-round trigger; IPC = manual. */
  trigger?: 'auto' | 'manual'
}): Promise<{ ok: boolean; error?: string }> {
  if (payload.provider === 'cursor') {
    return {
      ok: false,
      error:
        'Cursor host-seat compaction is not implemented for Path-B sandbox runs yet; start a fresh Cursor turn instead of compacting the seat.'
    }
  }
  const admissionChat = AppStore.getChat(payload.chatId)
  if (!admissionChat) return { ok: false, error: 'Chat not found.' }
  let reservation: MaintenanceCompactionReservation
  try {
    // This is deliberately before the request's first await. A durable or
    // process-local deletion fence therefore wins without a TOCTOU window.
    reservation = maintenanceCompactionRegistry.reserve({
      chatId: payload.chatId,
      ...(admissionChat.workspaceId ? { workspaceId: admissionChat.workspaceId } : {}),
      provider: payload.provider,
      ...(payload.participantId ? { participantId: payload.participantId } : {})
    })
  } catch (error) {
    return {
      ok: false,
      error:
        error instanceof MaintenanceCompactionAdmissionError
          ? error.message
          : 'Provider context compaction could not reserve maintenance authority.'
    }
  }
  try {
    return await compactProviderContextForReservedRequest(payload, reservation)
  } finally {
    maintenanceCompactionRegistry.finish(reservation)
  }
}

async function compactProviderContextForReservedRequest(
  payload: {
    chatId: string
    provider: 'claude' | 'codex' | 'cursor' | 'kimi' | 'grok'
    providerSessionId?: string
    participantId?: string
    trigger?: 'auto' | 'manual'
  },
  reservation: MaintenanceCompactionReservation
): Promise<{ ok: boolean; error?: string }> {
  if (payload.provider === 'cursor') {
    return {
      ok: false,
      error:
        'Cursor host-seat compaction is not implemented for Path-B sandbox runs yet; start a fresh Cursor turn instead of compacting the seat.'
    }
  }
  let providerSessionId = payload.providerSessionId
  let model: string | undefined
  let reasoningEffort: string | null | undefined
  let cardMetadata: Record<string, unknown> | undefined
  let kimiNativeSession = false
  const isHostSeatProvider = payload.provider === 'kimi' || payload.provider === 'grok'
  // Kimi/Grok host seats compact only as ENSEMBLE seats here. Cursor remains in
  // the request union for historical decoding but is rejected above. Solo Kimi
  // compacts through the renderer's summarize-run lane (wave 2);
  // solo grok has no host lever yet (its ACP default reinjects the transcript,
  // so a solo grok chat cannot overflow from accumulation).
  if (isHostSeatProvider && !payload.participantId) {
    return {
      ok: false,
      error: `Solo ${providerLabel(payload.provider)} chats compact via /compact in the chat itself.`
    }
  }
  if (payload.participantId) {
    const chat = AppStore.getChat(payload.chatId)
    if (!chat?.ensemble) {
      return { ok: false, error: 'Participant compaction requires an ensemble chat.' }
    }
    if (payload.trigger !== 'auto' && isEnsembleRoundDispatchLive(chat.ensemble.activeRound)) {
      return {
        ok: false,
        error: 'A round is live — wait for the panel to finish before compacting a seat.'
      }
    }
    const participant = (chat.ensemble.participants || []).find(
      (candidate) => candidate.id === payload.participantId
    )
    if (!participant) return { ok: false, error: 'Participant not found on this ensemble.' }
    if (participant.provider !== payload.provider) {
      return { ok: false, error: 'Participant provider does not match the request.' }
    }
    // Kimi and Grok seats carry their material in-prompt (no re-openable
    // session to resume against), so a session token is optional; every other
    // provider needs a resumable session to compact.
    if (
      !participant.linkedProviderSessionId &&
      payload.provider !== 'kimi' &&
      payload.provider !== 'grok'
    ) {
      return {
        ok: false,
        error: 'This participant has no provider session yet — it must speak first.'
      }
    }
    providerSessionId = participant.linkedProviderSessionId || undefined
    kimiNativeSession =
      participant.kimiAcpNativeSession === true &&
      isKimiAcpProductionPosture(participant.kimiAcpPostureVersion)
    model = participant.model
    reasoningEffort = participant.reasoningEffort
    const presentation = resolveHealthEntryPresentation(
      participant.provider,
      participant.model,
      providerLabel(participant.provider)
    )
    const role = (participant.role || 'Participant').trim()
    cardMetadata = {
      ensembleParticipantId: participant.id,
      displayParticipantLabel: `${presentation.displayProviderLabel} / ${role}`,
      displayHueClass: presentation.displayHueClass
    }
  }
  if (
    payload.provider === 'kimi' &&
    kimiNativeSession &&
    payload.participantId &&
    providerSessionId
  ) {
    const pendingKey = seatCompactionKey(payload.chatId, payload.participantId)
    const existing = pendingSeatCompactions.get(pendingKey)
    if (existing) return existing
    const work = compactKimiProviderContext({
      chatId: payload.chatId,
      participantId: payload.participantId,
      providerSessionId,
      model,
      cardMetadata,
      trigger: payload.trigger || 'manual',
      reservation
    })
    pendingSeatCompactions.set(pendingKey, work)
    try {
      return await work
    } finally {
      pendingSeatCompactions.delete(pendingKey)
    }
  }
  if (payload.provider === 'kimi') {
    return {
      ok: false,
      error:
        'This Kimi seat does not have an exact admitted native ACP session eligible for compaction; host-summary Kimi execution is retired.'
    }
  }
  if (payload.provider === 'grok') {
    return compactCliSeatContext({
      chatId: payload.chatId,
      participantId: payload.participantId!,
      provider: payload.provider,
      providerSessionId,
      model,
      cardMetadata,
      trigger: payload.trigger || 'manual',
      reservation
    })
  }
  if (payload.provider === 'claude') {
    if (!providerSessionId) {
      return { ok: false, error: 'This chat has no Claude session to compact yet.' }
    }
    return compactClaudeProviderContext({
      chatId: payload.chatId,
      providerSessionId,
      participantId: payload.participantId,
      model,
      cardMetadata,
      reservation
    })
  }
  return compactCodexProviderContext({
    chatId: payload.chatId,
    providerSessionId,
    participantId: payload.participantId,
    model,
    reasoningEffort,
    cardMetadata,
    reservation
  })
}

/** Emit the current Multi-agent episode telemetry onto its synthesized anchor
 * (`multi_agent_event` compat line — same side-channel pattern as
 * `review_event`/`workflow_event`, so it never renders as a generic tool row
 * and is durably persisted by sendAgentCompatLine's raw lane). */
function emitCodexMultiAgentEvent(state: CodexRunState): void {
  if (!state.multiAgentActivityId || !state.multiAgentTelemetry) return
  sendAgentCompatLine(
    state.sender,
    'codex',
    {
      type: 'multi_agent_event',
      tool_id: state.multiAgentActivityId,
      multiAgent: state.multiAgentTelemetry,
      provider: 'codex'
    },
    state
  )
}

/** Lazily synthesize the `codex_multi_agent` anchor activity on the FIRST
 * explicit Multi-agent provider event of a turn (Codex emits no natural anchor
 * tool-call for the episode — mirrors the `codex_review` anchor). Returns false
 * when a native review owns this run: the review card semantically outranks a
 * standalone Multi-agent card for the same episode, so no second anchor is
 * created (the raw events remain durably persisted either way). */
function ensureCodexMultiAgentEpisode(state: CodexRunState, atMs: number): boolean {
  if (state.reviewActivityId) return false
  if (state.multiAgentActivityId && state.multiAgentTelemetry) return true
  const activityId = `codex-multi-agent-${randomUUID()}`
  state.multiAgentActivityId = activityId
  state.multiAgentTelemetry = codexMultiAgentStartTelemetry({
    episodeId: codexMultiAgentEpisodeId(state.threadId, state.turnId),
    startedAtMs: atMs
  })
  sendAgentCompatLine(
    state.sender,
    'codex',
    {
      type: 'tool_use',
      tool_id: activityId,
      tool_name: CODEX_MULTI_AGENT_TOOL_NAME,
      parameters: {},
      provider: 'codex'
    },
    state
  )
  emitCodexMultiAgentEvent(state)
  return true
}

/** Fold a parent-thread Multi-agent coordination item (`subAgentActivity` /
 * `collabAgentToolCall`) into the episode telemetry. Detection is strictly
 * event-driven — never inferred from model or reasoning-effort choice. */
function handleCodexMultiAgentItem(
  state: CodexRunState,
  params: any,
  phase: 'started' | 'completed'
): void {
  const item = params?.item
  if (!item || typeof item !== 'object') return
  const atMs = Number(params?.completedAtMs) || Date.now()
  if (!ensureCodexMultiAgentEpisode(state, atMs)) return
  const telemetry = state.multiAgentTelemetry!
  state.multiAgentTelemetry =
    item.type === 'subAgentActivity'
      ? applyCodexSubAgentActivity(telemetry, item, atMs)
      : applyCodexCollabToolCall(telemetry, item, phase)
  emitCodexMultiAgentEvent(state)
}

/** Find the run state whose in-flight Multi-agent episode REGISTERED this
 * child threadId — the correct owner for subagent lifecycle events, which
 * arrive under the subagent's own (never session-registered) threadId. Scans
 * ALL managed Codex runs: with more than one codex run active the
 * single-active-run heuristic in getActiveCodexRunState resolves nothing (or
 * the wrong run), so relying on it would orphan every subagent of a concurrent
 * run and leave the settled card claiming its subagents never ran. */
function findCodexMultiAgentOwnerState(childThreadId: string): CodexRunState | null {
  if (!childThreadId) return null
  const candidates = runManager
    .getActiveByProvider('codex')
    .map((session) => getCodexStateFromSession(session))
    .filter((candidate): candidate is CodexRunState => Boolean(candidate))
  if (activeCodexRunState && !candidates.includes(activeCodexRunState)) {
    candidates.push(activeCodexRunState)
  }
  for (const candidate of candidates) {
    if (!candidate.multiAgentActivityId || !candidate.multiAgentTelemetry) continue
    const subagents = candidate.multiAgentTelemetry.subagents ?? []
    if (subagents.some((agent) => agent.agentThreadId === childThreadId)) return candidate
  }
  return null
}

/** Tee a foreign-thread notification into the Multi-agent episode when the
 * thread is a REGISTERED subagent's own thread — the only way a subagent's
 * lifecycle is observable (no terminal subAgentActivity kind is emitted).
 * Anything else from a foreign thread stays dropped, exactly as before. */
function handleCodexMultiAgentChildEvent(
  state: CodexRunState,
  message: any,
  childThreadId: string
): void {
  const telemetry = state.multiAgentTelemetry
  if (!state.multiAgentActivityId || !telemetry) return
  if (!(telemetry.subagents || []).some((agent) => agent.agentThreadId === childThreadId)) return
  const params = message?.params || {}
  let kind: 'started' | 'completed' | 'failed' | 'interrupted'
  if (message.method === 'turn/started') {
    kind = 'started'
  } else if (message.method === 'turn/completed' || message.method === 'turn/failed') {
    const status = codexString(params.turn?.status || params.status).toLowerCase()
    kind =
      message.method === 'turn/failed' || status === 'failed' || status === 'error'
        ? 'failed'
        : status === 'interrupted' || status === 'cancelled'
          ? 'interrupted'
          : 'completed'
  } else {
    return
  }
  const next = applyCodexChildTurnEvent(telemetry, {
    agentThreadId: childThreadId,
    kind,
    atMs: Date.now()
  })
  if (next === telemetry) return
  state.multiAgentTelemetry = next
  emitCodexMultiAgentEvent(state)
}

/** Finalize + settle the Multi-agent anchor when the parent turn (or the run
 * itself) reaches a terminal state. Clears the per-turn episode fields. */
function settleCodexMultiAgentEpisode(
  state: CodexRunState,
  input: { rawStatus?: unknown; durationMs?: number; error?: unknown }
): void {
  if (!state.multiAgentActivityId || !state.multiAgentTelemetry) return
  const rawStatus = codexString(input.rawStatus).toLowerCase()
  const outcome =
    rawStatus === 'failed' || rawStatus === 'error'
      ? 'failed'
      : rawStatus === 'interrupted' || rawStatus === 'cancelled'
        ? 'interrupted'
        : 'completed'
  const stats = codexUsageToStats(state.tokenUsage, input.durationMs || 0)
  state.multiAgentTelemetry = finalizeCodexMultiAgent(state.multiAgentTelemetry, {
    outcome,
    durationMs: input.durationMs,
    totalTokens: Number(stats.total_tokens) || undefined,
    error: codexString((input.error as any)?.message ?? input.error)
  })
  emitCodexMultiAgentEvent(state)
  sendAgentCompatLine(
    state.sender,
    'codex',
    {
      type: 'tool_result',
      tool_id: state.multiAgentActivityId,
      status: outcome === 'completed' ? 'success' : 'error',
      output: '',
      provider: 'codex'
    },
    state
  )
  state.multiAgentActivityId = undefined
  state.multiAgentTelemetry = undefined
}

function handleCodexNotification(message: any) {
  const state = findCodexRunStateForMessage(message)
  const notificationThreadId = String(
    message?.params?.threadId ||
      message?.params?.thread?.id ||
      message?.params?.item?.threadId ||
      message?.params?.turn?.threadId ||
      ''
  )
  const maintenanceCompaction = notificationThreadId
    ? pendingCodexManualCompactions.get(notificationThreadId)
    : undefined
  // A manual compaction and an ordinary/review run can share a persistent
  // thread over time. Route by the exact operation id (or current admission
  // ownership for its first turn/started), never merely by thread id.
  if (
    maintenanceCompaction &&
    codexNotificationBelongsToManualCompaction(maintenanceCompaction, message)
  ) {
    handleCodexManualCompactionNotification(message)
    return
  }
  // Manual compactions are keyed strictly by threadId, and they must win over
  // findCodexRunStateForMessage's ACTIVE-STATE FALLBACK: compacting idle chat A
  // while a different codex chat B is running resolves to B's state, whose
  // thread-mismatch guard below would silently swallow A's compaction frames —
  // stranding the awaiting IPC into a phantom timeout + spurious failure card.
  // (When a run state DOES match the thread — a turn dispatched mid-compact —
  // the state lane handles the frames and settles the pending record itself.)
  if (
    notificationThreadId &&
    pendingCodexManualCompactions.has(notificationThreadId) &&
    (!state || state.threadId !== notificationThreadId)
  ) {
    handleCodexManualCompactionNotification(message)
    return
  }
  const exactThreadSession = notificationThreadId
    ? runManager.getByProviderSession('codex', notificationThreadId)
    : undefined
  const fenceDecision = decideCodexEnsembleFence({
    taskWraithSteeredThread: Boolean(
      notificationThreadId && taskWraithSteeredCodexThreadIds.has(notificationThreadId)
    ),
    sessionStatus: exactThreadSession?.status,
    sessionIsEnsemble: isEnsembleCodexRunSession(exactThreadSession),
    method: String(message?.method || ''),
    turnId: String(message?.params?.turn?.id || message?.params?.turnId || '') || undefined
  })
  if (fenceDecision.action !== 'route') {
    if (fenceDecision.action === 'interrupt' && notificationThreadId) {
      // Defense in depth: clearing the native goal before every ensemble turn
      // prevents this scheduler path. If a stale/racing goal still starts a
      // turn after the app run ended, interrupt it before any tool item lands.
      void issueCodexTurnInterrupt(notificationThreadId, fenceDecision.turnId)
    } else if (
      fenceDecision.action === 'clear_native_goal' &&
      notificationThreadId &&
      codexClient
    ) {
      void codexClient
        .request(CODEX_THREAD_GOAL_CLEAR_METHOD, { threadId: notificationThreadId }, 15_000)
        .catch(() => {})
    }
    return
  }
  if (!state) {
    // Multi-agent subagent lifecycle events carry the SUBAGENT's own threadId,
    // which is never a registered run session — and with >1 codex run active
    // the single-active fallback above resolves nothing. Route them to the
    // episode that registered the child before the compaction fallback.
    const childOwner = findCodexMultiAgentOwnerState(notificationThreadId)
    if (childOwner) {
      handleCodexMultiAgentChildEvent(childOwner, message, notificationThreadId)
      return
    }
    // Between-turns manual compactions still stream item/turn notifications —
    // route them to the pending manual-compaction registry instead of
    // dropping them with the state guard.
    handleCodexManualCompactionNotification(message)
    return
  }

  const params = message.params || {}
  const messageThreadId = params.threadId || params.thread?.id
  if (messageThreadId && params.threadId !== state.threadId && messageThreadId !== state.threadId) {
    // Multi-agent subagents stream their own turn lifecycle over the same
    // connection under their OWN threadId — tee registered child threads'
    // turn events into the OWNING episode's telemetry before the drop. The
    // owner scan (not `state`) matters: with concurrent codex runs the active
    // fallback above can resolve a different run than the one that spawned
    // this subagent.
    const childOwner = findCodexMultiAgentOwnerState(String(messageThreadId))
    if (childOwner) {
      handleCodexMultiAgentChildEvent(childOwner, message, String(messageThreadId))
    }
    return
  }

  if (
    message.method === 'turn/started' &&
    state.appRunId &&
    allowsTerminalCodexNativeGoalSession(runManager.get(state.appRunId))
  ) {
    // A provider-native goal may start another turn after TaskWraith's exact
    // run operation completed. That autonomous turn has no fresh RunManager
    // identity or history-join authority, so explicitly fence it instead of
    // silently adopting it into the predecessor state.
    const autonomousTurnId = codexProviderOperationId(message)
    if (autonomousTurnId) void issueCodexTurnInterrupt(state.threadId, autonomousTurnId)
    return
  }

  if (!codexNotificationBelongsToRunState(state, message)) {
    return
  }

  if (syncCodexNativeGoalNotification(state, message)) {
    return
  }

  if (message.method === 'turn/started') {
    // Exact binding already occurred in codexNotificationBelongsToRunState.
    if (state.turnId) {
      const turnEvents = runItemEventsForDrafts('codex', state, [
        {
          kind: 'turn/started',
          turnId: state.turnId,
          source: 'provider'
        }
      ])
      if (turnEvents.length > 0) appendDurableRunItemEvents(turnEvents)
    }
    // Residual 1 — a cancel/budget-kill that fired before this turn started
    // recorded the threadId; now that we have a turnId, interrupt immediately.
    if (
      shouldFlushPendingInterrupt(pendingCodexInterrupts, state) &&
      state.threadId &&
      state.turnId
    ) {
      pendingCodexInterrupts.delete(state.threadId)
      void issueCodexTurnInterrupt(state.threadId, state.turnId)
    }
    return
  }

  if (message.method === 'thread/tokenUsage/updated') {
    state.tokenUsage = params.tokenUsage || params.usage || params
    // Per-occurrence budget kill: Codex's live token signal.
    if (state.appRunId) workflowBudgetRegistry.onUsage(state.appRunId, state.tokenUsage)
    const codexStats = codexUsageToStats(state.tokenUsage)
    ensembleOrchestratorRef?.reportParticipantTokenUsage(state.appRunId, codexStats, {
      provider: 'codex',
      chatId: state.appChatId
    })
    // Solo Codex runs: surface the same live snapshot the ensemble seats get.
    if (!state.ensembleRun) {
      const soloEvent = soloWorkingTokenTelemetry.report({
        runId: state.appRunId,
        chatId: state.appChatId,
        provider: 'codex',
        startedAtMs: state.startedAt,
        stats: codexStats,
        nowMs: Date.now()
      })
      if (soloEvent) broadcastParticipantWorkingTelemetry(soloEvent)
    }
    return
  }

  if (message.method === 'thread/compacted') {
    // Deprecated legacy compaction notification (0.139 emits contextCompaction
    // items instead) — announce only when the item lane hasn't already.
    emitCodexContextCompaction(state, 'completed', {
      dedupeKey: `legacy:${params.turnId || params.turn?.id || 'turn'}`,
      onlyIfNoneAnnounced: true
    })
    return
  }

  if (message.method === 'item/agentMessage/delta') {
    const itemId = codexTimelineItemId(params, 'codex-agent-message')
    const delta = codexString(params.delta ?? params.text ?? params.content)
    const nextText = (state.assistantTextByItemId.get(itemId) || '') + delta
    state.assistantTextByItemId.set(itemId, nextText)
    sendAgentCompatLine(
      state.sender,
      'codex',
      {
        type: 'content',
        text: delta,
        provider: 'codex',
        itemId
      },
      state
    )
    return
  }

  if (message.method === 'item/reasoning/textDelta') {
    return
  }

  if (
    message.method === 'item/reasoning/summaryTextDelta' ||
    message.method === 'item/reasoning/summaryPartAdded'
  ) {
    emitCodexReasoningDelta(state, params, 'Reasoning summary')
    return
  }

  if (message.method === 'item/commandExecution/outputDelta') {
    emitCodexCommandOutputDelta(state, params)
    return
  }

  if (message.method === 'item/fileChange/outputDelta') {
    const itemId = codexTimelineItemId(params, 'codex-file-output')
    const delta = codexString(params.delta ?? params.output ?? params.content)
    if (delta) {
      ensureCodexTimelineTool(state, itemId, 'edit_file', {
        path: codexString(params.path || params.item?.path || '')
      })
      sendCodexSyntheticToolResult(state, itemId, delta, 'running')
    }
    return
  }

  if (message.method === 'item/fileChange/patchUpdated') {
    emitCodexPatchUpdate(state, params)
    return
  }

  if (message.method === 'item/started') {
    const item = params.item
    if (isCodexContextCompactionItem(item)) {
      // Snapshot the pre-compaction occupancy now; the compaction turn's own
      // tokenUsage update overwrites `state.tokenUsage` before item/completed.
      state.contextCompactionPreTokens = codexCurrentContextTokens(state)
      state.contextCompactionStartedAtMs = Date.now()
      emitCodexContextCompaction(state, 'started', {
        itemId: codexContextCompactionItemId(item)
      })
      return
    }
    if (item?.type === 'reasoning') {
      return
    }
    if (item?.type === 'plan') {
      emitCodexPlanItem(state, item)
      return
    }
    if (item?.type === 'subAgentActivity' || item?.type === 'collabAgentToolCall') {
      // Native Multi-agent coordination — routed to the orchestration card,
      // never to the generic tool viewport. (Distinct from the legacy
      // 'collabToolCall' item type below.)
      handleCodexMultiAgentItem(state, params, 'started')
      return
    }
    if (item?.type === 'collabToolCall') {
      const itemId = codexTimelineItemId(params, 'codex-collab-tool-call')
      state.timelineStartedItemIds.add(itemId)
      sendAgentCompatLine(
        state.sender,
        'codex',
        {
          type: 'tool_use',
          tool_id: itemId,
          tool_name: 'collabToolCall',
          parameters: {
            title: item.name || item.agentName || item.agentType || 'Codex subagent',
            prompt: codexString(item.prompt || item.input || item.description || ''),
            summary: codexString(item.summary || item.status || ''),
            providerThreadId: params.threadId || params.thread?.id,
            childThreadId: item.newThreadId || item.receiverThreadId || item.threadId,
            parentToolCallId: item.parentToolCallId || item.parent_tool_call_id,
            raw: item
          },
          provider: 'codex'
        },
        state
      )
      return
    }
    const toolUse = codexToolUseFromItem(item)
    if (toolUse) {
      if (item?.type === 'mcpToolCall' && state.appRunId) {
        pendingCodexMcpRouteHints.set(String(toolUse.tool_id), {
          itemId: String(toolUse.tool_id),
          toolName: codexString(toolUse.tool_name || item.tool || ''),
          args: item.arguments || {},
          route: {
            appRunId: state.appRunId,
            appChatId: state.appChatId
          },
          startedAtMs: Date.now()
        })
        pruneCodexMcpRouteHints(Date.now())
      }
      state.timelineStartedItemIds.add(String(toolUse.tool_id))
      sendAgentCompatLine(state.sender, 'codex', toolUse, state)
    }
    return
  }

  if (message.method === 'item/completed') {
    const item = params.item
    if (isCodexContextCompactionItem(item)) {
      emitCodexContextCompaction(state, 'completed', {
        itemId: codexContextCompactionItemId(item)
      })
      return
    }
    if (item?.type === 'agentMessage') {
      const itemId = codexTimelineItemId(params, 'codex-agent-message')
      // Phase K1 — token-omission fix. Previously this block only used
      // `text` as a truthiness gate and emitted a `text: ''` completion
      // sentinel. When Codex finalises an `agentMessage` whose `item.text`
      // is LONGER than the concatenated stream (late-tightened reasoning
      // or an unstreamed summary item), the missing tail never reached
      // the renderer — raw events contained it but the rendered transcript
      // dropped it. Fix: if the final text exceeds what we streamed, emit
      // ONE more delta with the missing tail BEFORE the completion sentinel.
      const streamed = state.assistantTextByItemId.get(itemId) || ''
      const finalText = codexString(item.text || item.content || item.message || '')
      const effectiveFinal = finalText || streamed
      if (effectiveFinal) {
        if (finalText && finalText.length > streamed.length) {
          sendAgentCompatLine(
            state.sender,
            'codex',
            {
              type: 'content',
              text: finalText.slice(streamed.length),
              provider: 'codex',
              itemId,
              complete: false
            },
            state
          )
          // Update the cache so repeated `item/completed` for the same
          // itemId (defensive — shouldn't happen but cheap) doesn't
          // re-emit the same tail.
          state.assistantTextByItemId.set(itemId, finalText)
        }
        emitCodexProviderMediaRefs(state, item)
        sendAgentCompatLine(
          state.sender,
          'codex',
          {
            type: 'content',
            text: '',
            provider: 'codex',
            itemId,
            complete: true
          },
          state
        )
      }
      emitCodexProviderMediaRefs(state, item)
      return
    }
    if (item?.type === 'plan') {
      emitCodexPlanItem(state, item)
      return
    }
    if (item?.type === 'reasoning') {
      const sourceItemId = codexTimelineItemId(params, 'codex-reasoning')
      const streamed = codexReasoningSummaryDisplayText(
        state.reasoningTextByItemId.get(sourceItemId) || ''
      )
      const summary = codexReasoningSummaryDisplayText(codexReasoningSummaryText(item.summary))
      const text = summary && summary.length >= streamed.length ? summary : streamed
      if (!text.trim()) return
      state.reasoningTextByItemId.set(sourceItemId, text)
      const activityId = codexReasoningSummaryActivityId(state, state.model, sourceItemId)
      const groupText = codexReasoningSummaryGroupDisplayText(
        state,
        activityId,
        state.reasoningTextByItemId
      )
      ensureCodexTimelineTool(state, activityId, 'codex_reasoning', {
        title: 'Reasoning summary',
        kind: 'reasoning'
      })
      if (groupText)
        sendCodexSyntheticToolResult(
          state,
          activityId,
          groupText,
          item.status === 'failed' ? 'error' : 'success',
          { toolName: 'codex_reasoning', kind: 'reasoning' }
        )
      return
    }
    if (item?.type === 'commandExecution') {
      const itemId = codexTimelineItemId(params, 'codex-command')
      const output = [
        state.commandOutputByItemId.get(itemId),
        codexString(item.output || item.stdout),
        codexString(item.stderr),
        codexString(item.error || item.errorMessage)
      ]
        .filter(Boolean)
        .join('\\n')
      const command = codexCommandText(item.command || '')
      const editMetadata = codexCommandFileEditMetadata(command, output)
      if (editMetadata) {
        ensureCodexTimelineTool(state, itemId, editMetadata.toolName, editMetadata.parameters)
      } else {
        ensureCodexTimelineTool(state, itemId, 'run_shell_command', {
          command,
          cwd: codexString(item.cwd || '')
        })
      }
      sendCodexSyntheticToolResult(
        state,
        itemId,
        output || 'Command exited with ' + (item.exitCode ?? item.status ?? 'unknown') + '.',
        item.status === 'failed' || item.exitCode ? 'error' : 'success'
      )
      maybeRequestCodexHostRerun(state, item, itemId, output)
      return
    }
    if (item?.type === 'fileChange') {
      emitCodexPatchUpdate(state, { ...params, item, changes: item.changes })
      const itemId = codexTimelineItemId(params, 'codex-file-change')
      const cached = state.filePatchByItemId.get(itemId)
      sendCodexSyntheticToolResult(
        state,
        itemId,
        cached?.preview || summarizeCodexFileChanges(item.changes || []),
        item.status === 'failed' ? 'error' : 'success'
      )
      return
    }
    if (item?.type === 'subAgentActivity' || item?.type === 'collabAgentToolCall') {
      // Spawn markers land via item/completed (kind:'started'); wait/send
      // settle here too. Same routing as item/started — card, not tool row.
      handleCodexMultiAgentItem(state, params, 'completed')
      return
    }
    if (item?.type === 'collabToolCall') {
      const itemId = codexTimelineItemId(params, 'codex-collab-tool-call')
      sendAgentCompatLine(
        state.sender,
        'codex',
        {
          type: 'tool_result',
          tool_id: itemId,
          tool_name: 'collabToolCall',
          status:
            item.status === 'failed'
              ? 'error'
              : item.status === 'cancelled'
                ? 'cancelled'
                : 'success',
          output: codexString(
            item.result || item.output || item.summary || item.error || item.errorMessage || ''
          ),
          result: item,
          provider: 'codex'
        },
        state
      )
      return
    }
    const toolResult = codexToolResultFromItem(item)
    if (toolResult) {
      if (item?.type === 'mcpToolCall' && toolResult.tool_id) {
        pendingCodexMcpRouteHints.delete(String(toolResult.tool_id))
      }
      sendAgentCompatLine(state.sender, 'codex', toolResult, state)
    }
    return
  }

  if (
    message.method === 'turn/completed' ||
    message.method === 'turn/failed' ||
    message.method === 'review/completed' ||
    message.method === 'review/failed'
  ) {
    if (state.completed) {
      completeCodexAppServerTurnProjection(state)
      return
    }
    state.completed = true
    // Residual 1 — the run ended; drop any deferred interrupt for its thread.
    if (state.threadId) pendingCodexInterrupts.delete(state.threadId)
    const turn = params.turn || params.review || {}
    const durationMs = Number(turn.durationMs || turn.duration_ms || 0)
    const providerFailed = message.method === 'turn/failed' || message.method === 'review/failed'
    const providerTerminalStatus = turn.status || params.status || (providerFailed ? 'failed' : '')
    // Seal main's own AppStore copy of a SOLO Codex run before we notify the
    // renderer: the app-server never exits per-run, so nothing else writes
    // status/endedAt/stats here and the frozen copy would otherwise clobber the
    // renderer's live seal on the next runManager broadcast. Reviews and
    // ensemble seats are finalized on their own paths, so scope to plain turns.
    if (
      (message.method === 'turn/completed' || message.method === 'turn/failed') &&
      !state.ensembleRun
    ) {
      sealSoloCodexRunOnCompletion({
        appChatId: state.appChatId,
        runId: state.appRunId,
        status: normalizeCodexTurnStatus(providerTerminalStatus),
        stats: codexUsageToStats(state.tokenUsage, durationMs),
        endedAt: new Date().toISOString()
      })
    }
    sendAgentCompatLine(
      state.sender,
      'codex',
      {
        type: 'result',
        subtype: normalizeCodexTurnStatus(providerTerminalStatus),
        // The renderer's stream adapter derives run_finished's status from
        // `status` (it never reads `subtype`, which is Claude-CLI vocabulary), so
        // mirror the normalized turn status here too. Without it the adapter falls
        // back to 'unknown' and a solo Codex run's in-memory status + close-out
        // prose read "unknown" even though the persisted run now seals success.
        status: normalizeCodexTurnStatus(providerTerminalStatus),
        stats: codexUsageToStats(state.tokenUsage, durationMs),
        provider: 'codex',
        providerThreadId: state.threadId,
        providerRunId: turn.id || state.turnId,
        codex: { turn, tokenUsage: state.tokenUsage }
      },
      state
    )
    if (state.reviewActivityId) {
      // Native review settled — emit terminal status onto the synthesized anchor
      // and settle it. Coarse status only (Codex ships no structured findings).
      const reviewStats = codexUsageToStats(state.tokenUsage, durationMs)
      const reviewTelemetry = codexReviewCompletionTelemetry({
        status: providerTerminalStatus,
        durationMs,
        totalTokens: reviewStats.total_tokens,
        error: turn.error || params.error
      })
      sendAgentCompatLine(
        state.sender,
        'codex',
        {
          type: 'review_event',
          tool_id: state.reviewActivityId,
          review: reviewTelemetry,
          provider: 'codex'
        },
        state
      )
      sendAgentCompatLine(
        state.sender,
        'codex',
        {
          type: 'tool_result',
          tool_id: state.reviewActivityId,
          status: reviewTelemetry.status === 'completed' ? 'success' : 'error',
          output: '',
          provider: 'codex'
        },
        state
      )
    }
    settleCodexMultiAgentEpisode(state, {
      rawStatus: providerTerminalStatus,
      durationMs,
      error: turn.error || params.error
    })
    sendAgentCompatExit(state.sender, 'codex', providerFailed ? 1 : 0, state)
    runManager.finish(state.appRunId, providerFailed ? 'failed' : 'completed')
    if (activeCodexRunState === state) {
      setActiveCodexRunState(getCodexStateFromSession(getSingleActiveProviderSession('codex')))
    }
    completeCodexAppServerTurnProjection(state)
    return
  }

  if (message.method === 'error') {
    if (params.willRetry === true) return
    const error = params.message || params.error || 'Codex app-server error.'
    state.completed = true
    if (state.threadId) pendingCodexInterrupts.delete(state.threadId)
    settleCodexMultiAgentEpisode(state, { rawStatus: 'failed', error })
    sendAgentCompatError(state.sender, 'codex', error, state)
    sendAgentCompatExit(state.sender, 'codex', 1, state)
    runManager.finish(state.appRunId, 'failed')
    if (activeCodexRunState === state) {
      setActiveCodexRunState(getCodexStateFromSession(getSingleActiveProviderSession('codex')))
    }
    completeCodexAppServerTurnProjection(state)
  }
}

function formatCodexApprovalRequest(method: string, params: any, state?: CodexRunState | null) {
  const kind = params?.approvalType || params?.type || params?.kind || method
  const command = codexCommandText(
    params?.command || params?.commandLine || params?.exec?.command || params?.item?.command || ''
  )
  const cwd = codexString(
    params?.cwd || params?.workdir || params?.exec?.cwd || params?.item?.cwd || ''
  )
  const itemId = params?.itemId || params?.item_id || params?.item?.id
  const cachedPatch = itemId && state ? state.filePatchByItemId.get(String(itemId)) : null
  const changes = params?.changes || params?.item?.changes || cachedPatch?.changes || []
  const patchPreview = codexPatchPreviewFromValue(
    params?.diff || params?.patch || params?.preview || cachedPatch?.preview || changes
  )
  const toolName = params?.toolName || params?.tool_name || params?.name || params?.mcpToolName
  const planArtifactRawPath =
    planArtifactRawPathFromToolInput(params) || planArtifactRawPathFromChanges(changes)

  if (command) {
    return {
      service: 'shellCommands' as AgenticServiceId,
      title: 'Approve Codex command',
      body: cwd ? command + '\\n' + cwd : command,
      preview: {
        kind: 'command',
        command,
        cwd,
        itemId,
        params,
        actions: ['accept', 'acceptForSession', 'decline', 'cancel']
      }
    }
  }

  if ((Array.isArray(changes) && changes.length > 0) || patchPreview) {
    return {
      service: 'fileChanges' as AgenticServiceId,
      title: 'Approve Codex file change',
      body: summarizeCodexFileChanges(Array.isArray(changes) ? changes : []),
      preview: {
        kind: 'fileChange',
        toolName,
        ...(planArtifactRawPath ? { planArtifactRawPath } : {}),
        changes,
        patchPreview,
        itemId,
        params,
        actions: ['accept', 'acceptForSession', 'decline', 'cancel']
      }
    }
  }

  if (
    toolName ||
    String(method).toLowerCase().includes('mcp') ||
    String(kind).toLowerCase().includes('tool')
  ) {
    // Phase J3: route Codex's elicitation/preview for `delegate_to_subthread`
    // to the `subThreadDelegation` service so a user-granted "Allow for
    // session" on the TaskWraith delegation modal silently absorbs the
    // Codex pre-flight too. Without this mapping the elicitation reads
    // out under the generic `mcpTools` policy and re-prompts every call
    // even after the user has clearly authorised cross-provider work.
    const canonicalToolName = canonicalTaskWraithToolName(String(toolName || ''))
    const resolvedService: AgenticServiceId =
      canonicalToolName && isTaskWraithMcpToolName(canonicalToolName)
        ? taskWraithToolAgenticService(canonicalToolName)
        : ('mcpTools' as AgenticServiceId)
    return {
      service: resolvedService,
      title:
        resolvedService === 'subThreadDelegation'
          ? 'Approve Codex sub-thread delegation'
          : 'Approve Codex tool call',
      body: codexString(toolName || kind),
      preview: {
        kind: 'tool',
        toolName,
        params,
        actions: ['accept', 'acceptForSession', 'decline', 'cancel']
      }
    }
  }

  return {
    service: undefined,
    title: 'Codex approval required',
    body: codexString(params?.message || params?.prompt || kind),
    preview: {
      kind: 'permission',
      params,
      actions: ['accept', 'acceptForSession', 'decline', 'cancel']
    }
  }
}

function handleCodexServerRequest(message: any) {
  const state = findCodexRunStateForMessage(message)
  if (!codexClient) return
  const requestOperationId = codexProviderOperationId(message)
  const liveCodexRun = state?.appRunId ? runManager.get(state.appRunId) : undefined
  if (
    !state ||
    !requestOperationId ||
    !state.admissionReservation?.matchesExactOperationId(requestOperationId) ||
    historyClearAdmissionBlocked(state.appRunId, state.workspacePath) ||
    !liveCodexRun ||
    !isActiveRunSessionStatus(liveCodexRun.status) ||
    runManager.getClaimedTerminalStatus(state.appRunId)
  ) {
    if (message?.id !== undefined && message?.id !== null) {
      codexClient.reject(
        message.id,
        'TaskWraith has no matching active Codex turn for this approval; request denied.'
      )
    }
    return
  }
  const method = message.method || 'approval/request'
  const params = message.params || {}
  const approvalId = Date.now() + '-' + Math.random().toString(36).slice(2)
  const formatted = formatCodexApprovalRequest(method, params, state)
  const service = formatted.service
  const isGlobalScope = state.scope === 'global'
  const workspacePathForCodexApproval = isGlobalScope ? undefined : state.workspacePath

  // Slice 5 of the external-path-redesign arc. Detect tool calls
  // referencing paths outside the workspace and override the generic
  // approval action triplet with the slice-4 external-path actions.
  // The slice-4 modal then renders path-specific copy + 3 buttons:
  // "Grant read access" / "Grant edit access" / "Deny once".
  //
  // Provider-specific registration sites share the same external-path
  // prompt shape so the renderer can issue signed grants consistently.
  const probedToolName =
    typeof (params as Record<string, unknown>)?.toolName === 'string'
      ? ((params as Record<string, unknown>).toolName as string)
      : typeof (params as Record<string, unknown>)?.tool_name === 'string'
        ? ((params as Record<string, unknown>).tool_name as string)
        : typeof (params as Record<string, unknown>)?.mcpToolName === 'string'
          ? ((params as Record<string, unknown>).mcpToolName as string)
          : typeof (params as Record<string, unknown>)?.tool === 'string'
            ? ((params as Record<string, unknown>).tool as string)
            : typeof (params as Record<string, unknown>)?.name === 'string'
              ? ((params as Record<string, unknown>).name as string)
              : typeof (formatted.preview as Record<string, unknown> | undefined)?.toolName ===
                  'string'
                ? ((formatted.preview as Record<string, unknown>).toolName as string)
                : ''
  const codexCanonicalToolName = canonicalTaskWraithToolName(probedToolName)
  // C2b-ii — best-effort tool-args for the exact reviewer-verdict exception;
  // fail-closed when the ACP approval params carry no plain-object args
  // (classifier sees undefined → no auto-allow / no read-only exemption).
  const codexToolArgs =
    (params as Record<string, unknown>)?.arguments ?? (params as Record<string, unknown>)?.input
  primeNativeCanvasCompatCorrelation({
    provider: 'codex',
    route: state,
    toolName: codexCanonicalToolName || probedToolName,
    source: { ...params, request_id: message.id }
  })
  if (
    isMcpAutoAllowedForRun(codexCanonicalToolName, state.effectivePermissions, codexToolArgs, {
      appRunId: state.appRunId,
      appChatId: state.appChatId
    })
  ) {
    if (method === 'mcpServer/elicitation/request' || method === 'mcp/elicitation/request') {
      codexClient.respond(message.id, { action: 'accept', content: null, _meta: null })
    } else if (method === 'tool/requestUserInput') {
      codexClient.respond(message.id, { answers: {} })
    } else {
      codexClient.respond(message.id, { decision: 'accept' })
    }
    return
  }
  let externalPathDetection: PendingExternalPathDetection | undefined
  try {
    const detection = detectExternalPathForProviderApproval({
      provider: 'codex',
      appChatId: state.appChatId,
      appRunId: state.appRunId,
      toolName: probedToolName,
      method,
      params,
      workspacePath: workspacePathForCodexApproval
    })
    if (detection) {
      externalPathDetection = detection
      formatted.title = externalPathApprovalTitle()
      formatted.body = externalPathApprovalBody(detection)
    }
  } catch (err) {
    // Detector is best-effort. If it throws, fall through to the
    // generic approval flow — the user still gets the standard
    // accept/decline buttons.
    console.warn('[ExternalPathDetector] codex registration probe failed', err)
  }
  const gateService =
    service === 'mcpTools' &&
    isReadOnlyBlockedTool(codexCanonicalToolName, state.effectivePermissions, codexToolArgs)
      ? ('shellCommands' as AgenticServiceId)
      : service
  const codexCanvasEvalApproval =
    gateService === 'canvasEval'
      ? createCanvasEvalApprovalReceiptFromCanonicalArgs(codexToolArgs, approvalId)
      : undefined
  if (gateService === 'canvasEval' && !codexCanvasEvalApproval) {
    codexClient.reject(
      message.id,
      'TaskWraith blocked canvas_eval because no canonical script receipt was available.'
    )
    return
  }
  if (codexCanvasEvalApproval) {
    primeNativeCanvasCompatCorrelation({
      provider: 'codex',
      route: state,
      toolName: 'canvas_eval',
      source: { ...params, request_id: message.id },
      canvasEvalApproval: codexCanvasEvalApproval
    })
  }
  const nativePreflight = resolveNativeApprovalPreflight({
    provider: 'codex',
    service: gateService,
    workspacePath: workspacePathForCodexApproval,
    runId: state.appRunId,
    externalPathDetection,
    toolName: codexCanonicalToolName || probedToolName
  })
  const policy = nativePreflight.kind === 'none' ? 'ask' : nativePreflight.policy
  const postureApprovalOnly = isPostureApprovalOnlyService(
    nativePreflight.kind === 'none' ? undefined : nativePreflight.effectivePermissions?.presetId,
    gateService
  )
  const actions: AgentApprovalAction[] = externalPathDetection
    ? ['grantExternalPathRead', 'grantExternalPathEdit', 'declineExternalPath']
    : gateService === 'canvasEval' || postureApprovalOnly
      ? ['accept', 'decline', 'cancel']
      : nativePreflight.kind === 'ask'
        ? approvalActionsForPolicy(
            nativePreflight.policy,
            workspacePathForCodexApproval,
            gateService
          )
        : ['accept', 'acceptForSession', 'decline', 'cancel']
  const previewForDecision = {
    ...(formatted.preview || {}),
    actions,
    ...(externalPathDetection && externalPathDetection.path
      ? {
          externalPathDetection: externalPathApprovalPreview(externalPathDetection)
        }
      : {})
  }
  const codexEnsembleApproval = gateService
    ? ensembleApprovalContext(state.ensembleRun, gateService, workspacePathForCodexApproval)
    : undefined
  const codexApprovalTitle = codexEnsembleApproval
    ? `${codexEnsembleApproval.label}: ${formatted.title}`
    : formatted.title
  const codexApprovalBody = codexEnsembleApproval
    ? `${codexEnsembleApproval.bodyPrefix}\n\n${formatted.body}`
    : formatted.body
  const codexApprovalPreview: any = {
    ...previewForDecision,
    ...(gateService === 'canvasEval'
      ? {
          toolName: 'canvas_eval',
          params: codexToolArgs,
          securityClass: 'signed-elevated',
          requiresExactDesktopReview: true,
          requestOnly: true,
          ...(codexCanvasEvalApproval ? { canvasEvalReceipt: codexCanvasEvalApproval } : {})
        }
      : {}),
    ...(postureApprovalOnly
      ? {
          requestOnly: true,
          requestOnlyReason: 'run-posture-approval-only'
        }
      : {}),
    ...(codexEnsembleApproval ? { ensembleParticipant: codexEnsembleApproval.preview } : {})
  }
  const codexPlanArtifactWriteMetadata =
    gateService && nativePreflight.kind === 'deny'
      ? planArtifactWriteApprovalMetadata({
          workflowMode: state.workflowMode,
          effectivePermissions: state.effectivePermissions,
          globalFileChangesPolicy: AppStore.getSettings().agenticServices?.fileChanges,
          service: gateService,
          workspacePath: workspacePathForCodexApproval,
          request: { preview: previewForDecision }
        })
      : null
  if (gateService && nativePreflight.kind === 'deny' && codexPlanArtifactWriteMetadata) {
    auditService.recordAutomaticApprovalDecision(
      'codex',
      { appRunId: state.appRunId, appChatId: state.appChatId },
      gateService,
      workspacePathForCodexApproval,
      {
        method,
        title: codexApprovalTitle,
        body: codexApprovalBody,
        preview: codexApprovalPreview
      },
      'autoAllow',
      'plan_artifact',
      'request',
      {
        policy: nativePreflight.policy,
        ...codexPlanArtifactWriteMetadata,
        ...(codexEnsembleApproval ? { ensembleParticipant: codexEnsembleApproval.preview } : {})
      }
    )
    stampPlanArtifactPathOnPendingPlan(state.appChatId, codexPlanArtifactWriteMetadata)
    if (method === 'mcpServer/elicitation/request' || method === 'mcp/elicitation/request') {
      codexClient.respond(message.id, { action: 'accept', content: null, _meta: null })
    } else if (method === 'item/permissions/requestApproval') {
      codexClient.respond(message.id, {
        permissions: params?.permissions || {},
        scope: 'turn'
      })
    } else if (method === 'tool/requestUserInput') {
      codexClient.respond(message.id, { answers: {} })
    } else {
      codexClient.respond(message.id, { decision: 'accept' })
    }
    return
  }
  if (gateService && nativePreflight.kind === 'deny') {
    auditService.recordAutomaticApprovalDecision(
      'codex',
      { appRunId: state.appRunId, appChatId: state.appChatId },
      gateService,
      workspacePathForCodexApproval,
      {
        method,
        title: codexApprovalTitle,
        body: codexApprovalBody,
        preview: codexApprovalPreview
      },
      'autoDeny',
      'policy',
      'request',
      {
        policy: nativePreflight.policy,
        ...(codexEnsembleApproval ? { ensembleParticipant: codexEnsembleApproval.preview } : {}),
        ...(externalPathDetection ? { externalPathDetected: true } : {})
      }
    )
    codexClient.reject(message.id, agenticServiceDisabledMessage(gateService))
    sendAgentCompatError(state.sender, 'codex', agenticServiceBlockedMessage(gateService), state)
    return
  }
  if (gateService && nativePreflight.kind === 'allow') {
    auditService.recordAutomaticApprovalDecision(
      'codex',
      { appRunId: state.appRunId, appChatId: state.appChatId },
      gateService,
      workspacePathForCodexApproval,
      {
        method,
        title: codexApprovalTitle,
        body: codexApprovalBody,
        preview: codexApprovalPreview
      },
      'autoAllow',
      nativePreflight.reason,
      nativePreflight.scope,
      {
        policy: nativePreflight.policy,
        ...(codexEnsembleApproval ? { ensembleParticipant: codexEnsembleApproval.preview } : {}),
        ...(nativePreflight.reason === 'session_yolo'
          ? { yoloEnabledAt: sessionYoloState.enabledAt }
          : {})
      }
    )
    if (method === 'mcpServer/elicitation/request' || method === 'mcp/elicitation/request') {
      codexClient.respond(message.id, { action: 'accept', content: null, _meta: null })
    } else if (method === 'item/permissions/requestApproval') {
      codexClient.respond(message.id, {
        permissions: params?.permissions || {},
        scope:
          nativePreflight.scope === 'session' || nativePreflight.scope === 'workspace'
            ? 'session'
            : 'turn'
      })
    } else if (method === 'tool/requestUserInput') {
      codexClient.respond(message.id, { answers: {} })
    } else {
      codexClient.respond(message.id, { decision: 'accept' })
    }
    return
  }

  formatted.preview = codexApprovalPreview

  const registered = approvalService?.registerCodex(approvalId, {
    rpcId: message.id,
    method,
    params,
    service: gateService,
    workspacePath: workspacePathForCodexApproval,
    runId: state.appRunId,
    allowedActions: actions,
    externalPathDetection
  })
  if (registered !== true) {
    codexClient.reject(message.id, 'TaskWraith is not accepting new approval requests.')
    return
  }
  runManager.registerApproval(state.appRunId, approvalId)
  scheduleApprovalTimeout({
    approvalId,
    provider: 'codex',
    route: { appRunId: state.appRunId, appChatId: state.appChatId },
    kind: method
  })
  const approvalPayload = {
    provider: 'codex',
    appRunId: state.appRunId,
    appChatId: state.appChatId,
    id: approvalId,
    approvalId,
    requestId: message.id,
    method,
    params: gateService === 'canvasEval' ? codexToolArgs : params,
    title: codexApprovalTitle,
    body: codexApprovalBody,
    preview: formatted.preview,
    actions
  }
  appendDurableRunEventForRoute(
    'codex',
    { appRunId: state.appRunId, appChatId: state.appChatId },
    'approval_request',
    'control',
    codexApprovalTitle,
    approvalPayload,
    undefined,
    codexCanvasEvalApproval
  )
  recordApprovalLedgerRequest(
    'codex',
    { appRunId: state.appRunId, appChatId: state.appChatId },
    approvalPayload,
    {
      service: gateService,
      workspacePath: workspacePathForCodexApproval,
      metadata: {
        policy,
        ...(codexEnsembleApproval ? { ensembleParticipant: codexEnsembleApproval.preview } : {})
      },
      canvasEvalApproval: codexCanvasEvalApproval
    }
  )
  safeSendToSender(state.sender, 'agent-approval-request', approvalPayload)
  // Fan out a wake-push to any paired iOS device. Summary uses
  // formatted.title (already curated for the user-facing approval
  // modal); falls back to `method` for unfamiliar Codex shapes.
  notifyPairedDevicesOfApproval({
    approvalId,
    workspaceId: workspaceIdForApprovalPush(workspacePathForCodexApproval),
    threadId: state.threadId ?? state.appChatId,
    summary: codexApprovalTitle || `Codex approval: ${method}`
  })
}

function maybeRequestCodexHostRerun(
  state: CodexRunState,
  item: any,
  itemId: string,
  output: string
): void {
  const settings = AppStore.getSettings()
  if (settings.codexSandboxFallback === 'off') return
  if (state.hostRerunRequestedItemIds.has(itemId)) return
  if (!state.threadId) return
  if (state.scope !== 'global' && !state.workspacePath) return
  const failed =
    item?.status === 'failed' || (typeof item?.exitCode === 'number' && item.exitCode !== 0)
  if (!failed) return
  if (!isCodexSandboxToolingFailure(output)) return

  const policy = getAgenticServicePolicy('shellCommands', settings)
  if (policy === 'deny') return

  const command = item.command || ''
  const commandText = codexCommandText(command)
  const cwd = codexString(item.cwd || state.workspacePath || state.cwd)
  if (!commandText.trim()) return

  let normalizedCwd: string
  try {
    normalizedCwd =
      state.scope === 'global'
        ? resolveHostDirectory(state.cwd, cwd)
        : resolveWorkspaceDirectory(state.workspacePath!, cwd)
  } catch {
    return
  }

  const hostRunId = state.appRunId?.trim()
  if (hostRunId && executionGraphOwnsOrAnchorsRunId(hostRunId)) {
    const reason =
      'Host-process command reruns are unavailable for graph-owned attempts and Stack anchors.'
    try {
      executionGraphCoordinatorRef?.requireActionForProviderRun(hostRunId, reason)
    } catch (error) {
      console.error('[ExecutionGraph] host-rerun attention gate failed:', error)
    }
    sendAgentCompatError(state.sender, 'codex', reason, state)
    return
  }

  state.hostRerunRequestedItemIds.add(itemId)
  const approvalId = `host-rerun-${Date.now()}-${Math.random().toString(36).slice(2)}`
  const swiftPmNestedSandbox = isSwiftPmNestedSandboxFailure(command, output)
  const reason = swiftPmNestedSandbox
    ? 'SwiftPM attempted to apply its own sandbox from inside the Codex command sandbox.'
    : 'Codex command failed in the command sandbox with a Swift/Xcode-style sandbox/tooling collision.'
  const registered = approvalService?.registerHostCommand(approvalId, {
    sender: state.sender,
    provider: 'codex',
    command,
    commandText,
    cwd: normalizedCwd,
    workspacePath: state.scope === 'global' ? undefined : state.workspacePath,
    threadId: state.threadId,
    model: state.model,
    reasoningEffort: state.reasoningEffort,
    appRunId: state.appRunId,
    appChatId: state.appChatId,
    allowedActions: ['accept', 'decline', 'cancel'],
    reason,
    output
  })
  if (registered !== true) {
    state.hostRerunRequestedItemIds.delete(itemId)
    return
  }
  runManager.registerApproval(state.appRunId, approvalId)
  scheduleApprovalTimeout({
    approvalId,
    provider: 'codex',
    route: { appRunId: state.appRunId, appChatId: state.appChatId },
    kind: 'hostCommand/rerun'
  })
  const hostRerunEnsembleApproval = ensembleApprovalContext(
    state.ensembleRun,
    'shellCommands',
    state.scope === 'global' ? undefined : state.workspacePath
  )
  const hostRerunBaseTitle = swiftPmNestedSandbox
    ? 'Rerun SwiftPM outside sandbox'
    : 'Rerun command outside sandbox'
  const hostRerunTitle = hostRerunEnsembleApproval
    ? `${hostRerunEnsembleApproval.label}: ${hostRerunBaseTitle}`
    : hostRerunBaseTitle
  const hostRerunBaseBody = `${reason}\n\n${commandText}\n${normalizedCwd}`
  const hostRerunBody = hostRerunEnsembleApproval
    ? `${hostRerunEnsembleApproval.bodyPrefix}\n\n${hostRerunBaseBody}`
    : hostRerunBaseBody
  const approvalPayload = {
    provider: 'codex',
    appRunId: state.appRunId,
    appChatId: state.appChatId,
    id: approvalId,
    approvalId,
    method: 'hostCommand/rerun',
    title: hostRerunTitle,
    body: hostRerunBody,
    preview: {
      kind: 'host-command-rerun',
      command: commandText,
      cwd: normalizedCwd,
      output: output.slice(0, 4000),
      swiftPmNestedSandbox,
      ...(hostRerunEnsembleApproval
        ? { ensembleParticipant: hostRerunEnsembleApproval.preview }
        : {}),
      actions: ['accept', 'decline'] as AgentApprovalAction[]
    },
    actions: ['accept', 'decline'] as AgentApprovalAction[]
  }
  appendDurableRunEventForRoute(
    'codex',
    { appRunId: state.appRunId, appChatId: state.appChatId },
    'approval_request',
    'control',
    hostRerunTitle,
    approvalPayload
  )
  recordApprovalLedgerRequest(
    'codex',
    { appRunId: state.appRunId, appChatId: state.appChatId },
    approvalPayload,
    {
      service: 'shellCommands',
      workspacePath: state.scope === 'global' ? undefined : state.workspacePath,
      metadata: {
        kind: 'host-command-rerun',
        policy,
        reason,
        swiftPmNestedSandbox,
        ...(hostRerunEnsembleApproval
          ? { ensembleParticipant: hostRerunEnsembleApproval.preview }
          : {})
      }
    }
  )
  safeSendToSender(state.sender, 'agent-approval-request', approvalPayload)
  // Fan out a wake-push to any paired iOS device so the user can decide
  // away from the desktop. No-op if APNs is un-configured.
  notifyPairedDevicesOfApproval({
    approvalId,
    workspaceId: workspaceIdForApprovalPush(
      state.scope === 'global' ? undefined : state.workspacePath
    ),
    threadId: state.threadId ?? state.appChatId,
    summary: `${hostRerunTitle}: ${commandText.slice(0, 120)}`
  })
}

/**
 * After an approved host-command rerun projects under approval run R0, start
 * an automatic Codex follow-up on a fresh independently reserved run R1.
 * R1 must resume the chat's existing Codex provider session — never a virgin
 * spawn and never a second life of R0 (history-join dual-ownership).
 */
async function continueCodexAfterHostRerun(
  approval: HostCommandApproval,
  result: HostCommandResult,
  resultText: string,
  approvalRequestId?: string
): Promise<void> {
  const approvalRunId = approval.appRunId?.trim()
  const approvalChatId = approval.appChatId?.trim()
  if (!approvalRunId || !approvalChatId) {
    sendAgentCompatError(
      approval.sender,
      'codex',
      `The approved host rerun finished with exit code ${
        result.exitCode ?? (result.timedOut ? 'timeout' : 'unknown')
      }, but TaskWraith could not start an automatic Codex continuation without a run/chat identity. Start a new turn to continue from the recorded output.`,
      approval
    )
    return
  }

  const correlation = createHostRerunContinuationCorrelation({
    parentRunId: approvalRunId,
    appChatId: approvalChatId,
    approvalId: approvalRequestId,
    hostResult: {
      exitCode: result.exitCode,
      timedOut: result.timedOut,
      durationMs: result.durationMs,
      resultText,
      error: result.error
    }
  })
  const continuationRunId = correlation.continuationRunId

  const approvalRunState = runManager.get(approvalRunId)
  const runChat = AppStore.getChat(approvalChatId)
  // Prefer durable chat-linked session, then live approval/thread evidence.
  const priorProviderSessionId =
    runChat?.linkedProviderSessionId?.trim() ||
    approval.threadId?.trim() ||
    approvalRunState?.state?.providerSessionId?.trim() ||
    null

  const sessionDecision = resolveHostRerunContinuationSession({
    appChatId: approvalChatId,
    priorProviderSessionId,
    parentRunId: approvalRunId,
    continuationRunId
  })
  if (!sessionDecision.ok) {
    sendAgentCompatError(approval.sender, 'codex', sessionDecision.reason, approval)
    return
  }
  const resumeProviderSessionId = sessionDecision.providerSessionId

  const scope =
    (runChat?.scope as ChatScope | undefined) ??
    (approval.workspacePath || runChat?.workspacePath ? 'workspace' : 'global')
  const workspace =
    approvalRunState?.state?.workspacePath || runChat?.workspacePath || approval.workspacePath

  const prompt = buildHostRerunContinuationPrompt({
    commandText: approval.commandText,
    resultText,
    exitCode: result.exitCode,
    timedOut: result.timedOut,
    reason: approval.reason,
    cwd: approval.cwd
  })

  const model = approvalRunState?.state?.model || approval.model || runChat?.requestedModel
  const reasoningEffort =
    approvalRunState?.state?.reasoningEffort || approval.reasoningEffort
  // Automatic host-rerun continuation is never Trusted Session.
  const sessionTrust = false
  const approvalMode = approvalRunState?.state?.approvalMode || 'default'
  const externalPathGrants = approvalRunState?.state?.externalPathGrants
  const effectivePermissions = approvalRunState?.state?.effectivePermissions

  const runPayload: AgentRunPayload = {
    provider: 'codex',
    scope,
    workspace,
    prompt,
    appRunId: continuationRunId,
    appChatId: approvalChatId,
    model,
    reasoningEffort,
    approvalMode,
    workflowMode: approvalRunState?.state?.workflowMode,
    externalPathGrants,
    runtimeProfileId: approvalRunState?.state?.runtimeProfileId,
    sessionTrust,
    providerSessionId: resumeProviderSessionId,
    handoffSourceRunId: approvalRunId,
    ...(effectivePermissions ? { effectivePermissions } : {})
  }
  runPayload.effectivePermissionsSignature = signRunPosture(
    runPayload.approvalMode,
    runPayload.effectivePermissions,
    runPostureContextFromPayload(runPayload)
  )

  if (!runCoordinatorRef) {
    sendAgentCompatError(
      approval.sender,
      'codex',
      'Host rerun continuation could not start because the provider dispatcher is unavailable. The host result remains on the original run; start a new turn to continue.',
      approval
    )
    return
  }

  try {
    try {
      appendDurableRunEventForRoute(
        'codex',
        { appRunId: continuationRunId, appChatId: approvalChatId },
        'host_rerun_continuation_dispatched',
        'control',
        'Dispatched Codex host-rerun continuation on independent appRunId (R1)',
        {
          parentRunId: correlation.parentRunId,
          continuationRunId: correlation.continuationRunId,
          hostResultKey: correlation.hostResultKey,
          approvalId: correlation.approvalId,
          source: correlation.source,
          kind: correlation.kind,
          providerSessionId: resumeProviderSessionId
        }
      )
    } catch {
      // Audit is observability; host projection on R0 remains authoritative.
    }

    const dispatchResult = await runCoordinatorRef.dispatch(runPayload, {
      sender: approval.sender
    })
    if (!dispatchResult.dispatched) {
      sendAgentCompatError(
        approval.sender,
        'codex',
        `The approved host rerun finished with exit code ${
          result.exitCode ?? (result.timedOut ? 'timeout' : 'unknown')
        }, but TaskWraith could not dispatch the automatic Codex continuation. The host result remains on the original run; start a new turn to continue from the recorded output.`,
        approval
      )
    }
  } catch (error) {
    sendAgentCompatError(
      approval.sender,
      'codex',
      `Host rerun continuation failed: ${error instanceof Error ? error.message : String(error)}. The host result remains on the original run.`,
      approval
    )
  }
}

async function runApprovedHostCommand(requestId: string): Promise<boolean> {
  const approval = approvalService?.getHostCommand(requestId)
  if (!approval) return false
  const approvalRunId = approval.appRunId?.trim()
  const approvalChatId = approval.appChatId?.trim()
  if (!approvalRunId || !approvalChatId) {
    approvalService?.deleteHostCommand(requestId)
    runManager.clearApproval(requestId)
    return false
  }
  if (executionGraphOwnsOrAnchorsRunId(approvalRunId)) {
    const reason =
      'Host-process command reruns are unavailable inside a durable Stack attempt; the execution requires review instead.'
    try {
      executionGraphCoordinatorRef?.requireActionForProviderRun(approvalRunId, reason)
    } catch (error) {
      console.error('[ExecutionGraph] approved host-rerun attention gate failed:', error)
    }
    approvalService?.deleteHostCommand(requestId)
    runManager.clearApproval(requestId)
    sendAgentCompatError(approval.sender, 'codex', reason, approval)
    return false
  }
  approvalService?.deleteHostCommand(requestId)
  runManager.clearApproval(requestId)
  const hostCommandProjection = createHostCommandProjectionScope({
    source: 'codex-host-rerun',
    appRunId: approvalRunId,
    appChatId: approvalChatId,
    workspacePath: approval.workspacePath
  })
  try {
    const toolId = `${requestId}-result`
    sendAgentCompatLine(
      approval.sender,
      'codex',
      {
        type: 'tool_use',
        tool_id: toolId,
        tool_name: 'run_shell_command',
        parameters: {
          command: approval.commandText,
          cwd: approval.cwd,
          hostRerun: true,
          reason: approval.reason
        },
        provider: 'codex'
      },
      approval
    )
    const result = await runWithHostCommandProjectionScope(hostCommandProjection, () =>
      runHostCommand(approval.command, approval.cwd, {
        releaseApproval: {
          allowReleaseCommand: true,
          approvalSource: 'approvedHostCommand'
        }
      })
    )
    const resultText = formatHostCommandResult(result)
    sendAgentCompatLine(
      approval.sender,
      'codex',
      {
        type: 'tool_result',
        tool_id: toolId,
        tool_name: 'run_shell_command',
        status:
          result.error || result.timedOut || (result.exitCode !== null && result.exitCode !== 0)
            ? 'error'
            : 'success',
        output: resultText,
        result: { exitCode: result.exitCode, durationMs: result.durationMs, hostRerun: true },
        provider: 'codex'
      },
      approval
    )
    await continueCodexAfterHostRerun(approval, result, resultText, requestId)
    return true
  } finally {
    completeHostCommandTerminalProjection(hostCommandProjection)
  }
}

function syncCodexGoalCapabilityMetadata(
  appChatId: string | undefined,
  nativeAvailable: boolean,
  goalOverride?: ChatRecord['activeGoal'] | null
) {
  if (!appChatId) return
  const chat = AppStore.getChat(appChatId)
  if (!chat || chat.provider !== 'codex') return
  const providerMetadata = {
    ...(chat.providerMetadata || {}),
    codexGoalNativeAvailable: nativeAvailable
  }
  const taskWraithOwnsGoal = chat.chatKind === 'ensemble'
  // Native goal notifications are untrusted scheduling input for an ensemble:
  // preserve the shared TaskWraith record even when Codex reports a clear or a
  // stale native update from a reused participant thread.
  const nativeGoalOverrideApplied = !taskWraithOwnsGoal && goalOverride !== undefined
  const activeGoalSource = taskWraithOwnsGoal
    ? chat.activeGoal
    : nativeGoalOverrideApplied
      ? goalOverride
      : chat.activeGoal
  const activeGoal = taskWraithOwnsGoal
    ? resolveActiveGoalForEnsemble(activeGoalSource)
    : activeGoalSource?.provider === 'codex'
      ? {
          ...activeGoalSource,
          mode: resolveActiveGoalMode('codex', { codexNativeAvailable: nativeAvailable })
        }
      : activeGoalSource
  const metadataUnchanged =
    Boolean(chat.providerMetadata?.codexGoalNativeAvailable) === nativeAvailable
  const goalUnchanged = !nativeGoalOverrideApplied
    ? activeGoal === chat.activeGoal || activeGoal?.mode === chat.activeGoal?.mode
    : JSON.stringify(activeGoal || null) === JSON.stringify(chat.activeGoal || null)
  if (metadataUnchanged && goalUnchanged) return
  const updated: ChatRecord = {
    ...chat,
    providerMetadata,
    updatedAt: Date.now()
  }
  if (activeGoal) updated.activeGoal = activeGoal
  else if (nativeGoalOverrideApplied) delete updated.activeGoal
  AppStore.saveChat(updated)
  broadcastChatUpdated(updated)
  try {
    bridgeBroadcasterRef?.broadcastThreadUpdated(updated.appChatId)
    pushRemoteThreadSnapshotForChat?.(updated)
    pushBridgeRunTaskCardDelta?.(updated.appChatId)
  } catch (err) {
    console.warn('[codex] native goal bridge broadcast failed:', err)
  }
}

class CodexEnsembleGoalIsolationError extends Error {
  override name = 'CodexEnsembleGoalIsolationError'
}

async function syncCodexNativeGoalForRun(
  client: CodexAppServerClient,
  appChatId: string | undefined,
  threadId: string,
  ensembleRun = false
): Promise<void> {
  if (!appChatId || !threadId) return
  const chat = AppStore.getChat(appChatId)
  if (!chat) return
  const intent = codexNativeGoalSyncIntent({
    threadId,
    chatKind: chat.chatKind,
    ensembleRun,
    activeGoal: chat.activeGoal
  })
  if (intent.preserveTaskWraithGoal) taskWraithSteeredCodexThreadIds.add(threadId)
  else taskWraithSteeredCodexThreadIds.delete(threadId)
  // A Codex seat may live in a Claude-canonical ensemble. Clearing the seat's
  // stale native scheduler must therefore happen before the canonical-provider
  // guard used by solo native-goal mirroring.
  if (!intent.preserveTaskWraithGoal && chat.provider !== 'codex') return
  try {
    if (intent.method === CODEX_THREAD_GOAL_SET_METHOD) {
      if (!chat.activeGoal) return
      const response: any = await client.request(intent.method, intent.params, 15_000)
      const nativeGoal = response?.goal
      syncCodexGoalCapabilityMetadata(
        appChatId,
        true,
        nativeGoal
          ? activeGoalFromCodexThreadGoal(nativeGoal, chat.activeGoal)
          : { ...chat.activeGoal, provider: 'codex', mode: 'codex_native' }
      )
      return
    }

    await client.request(intent.method, intent.params, 15_000)
    if (intent.preserveTaskWraithGoal) syncCodexGoalCapabilityMetadata(appChatId, true)
    else syncCodexGoalCapabilityMetadata(appChatId, true, null)
  } catch (error) {
    const unsupportedNativeGoalControl = isCodexNativeGoalUnsupportedError(error)
    if (unsupportedNativeGoalControl) {
      syncCodexGoalCapabilityMetadata(appChatId, false)
      return
    }
    console.warn(
      `[codex] native goal sync failed for thread ${threadId}: ${
        error instanceof Error ? error.message : String(error)
      }`
    )
    if (mustFailClosedAfterCodexGoalSyncError(intent, unsupportedNativeGoalControl)) {
      throw new CodexEnsembleGoalIsolationError(
        `Cannot start an Ensemble Codex turn while its provider-native goal may still be active: ${
          error instanceof Error ? error.message : String(error)
        }`
      )
    }
  }
}

async function syncCodexNativeGoalForSavedChat(
  appChatId: string,
  expectedThreadId: string,
  reason: string
): Promise<void> {
  const chat = AppStore.getChat(appChatId)
  if (!chat || chat.provider !== 'codex') return
  const threadId = chat.linkedProviderSessionId
  if (!threadId || threadId !== expectedThreadId || !isCodexAppServerThreadId(threadId)) return
  if (chat.providerMetadata?.codexGoalNativeAvailable !== true) return

  // Reuse the current Codex app-server client only. Creating or retargeting a
  // client here could silently switch a custom runtime profile during a UI edit.
  const client = codexClient ? getCodexClient() : null
  if (!client) return
  try {
    client.setNotificationHandler(handleCodexNotification)
    client.setRequestHandler(handleCodexServerRequest)
    await client.ensureStarted(app.getVersion())
    await syncCodexNativeGoalForRun(client, appChatId, threadId)
  } catch (error) {
    console.warn(
      `[codex] native goal background sync failed after ${reason}: ${
        error instanceof Error ? error.message : String(error)
      }`
    )
  }
}

function syncCodexNativeGoalNotification(state: CodexRunState, message: any): boolean {
  if (!state.appChatId) return false
  if (
    executionGraphOwnsAttemptRunId(state.appRunId) &&
    (message.method === 'thread/goal/updated' || message.method === 'thread/goal/cleared')
  ) {
    return true
  }
  const chat = AppStore.getChat(state.appChatId)
  const taskWraithOwnsGoal = Boolean(state.ensembleRun) || chat?.chatKind === 'ensemble'
  if (
    taskWraithOwnsGoal &&
    (message.method === 'thread/goal/updated' || message.method === 'thread/goal/cleared')
  ) {
    if (message.method === 'thread/goal/updated' && state.threadId && codexClient) {
      void codexClient
        .request(CODEX_THREAD_GOAL_CLEAR_METHOD, { threadId: state.threadId }, 15_000)
        .catch(() => {})
    }
    syncCodexGoalCapabilityMetadata(state.appChatId, true)
    return true
  }
  if (message.method === 'thread/goal/updated') {
    const nativeGoal = message.params?.goal
    if (!nativeGoal) return true
    if (!chat) return true
    syncCodexGoalCapabilityMetadata(
      state.appChatId,
      true,
      activeGoalFromCodexThreadGoal(nativeGoal, chat.activeGoal)
    )
    return true
  }
  if (message.method === 'thread/goal/cleared') {
    syncCodexGoalCapabilityMetadata(state.appChatId, true, null)
    return true
  }
  return false
}

async function runCodexAppServer(event: Electron.IpcMainInvokeEvent, payload: AgentRunPayload) {
  const codexTaskWraithMcpAdvertised = Boolean(
    AppStore.getSettings().geminiMcpBridgeEnabled && taskwraithMcpBridgeCommandStatus().available
  )
  if (!codexTaskWraithMcpAdvertised) {
    payload.taskWraithMcpAdvertised = false
    payload.prompt = sanitizeTaskWraithMcpPromptClaims(payload.prompt, {
      advertised: false,
      coreProfile: false
    })
  }
  const client = getCodexClient(payload.runtimeProfile ?? null)
  codexAppServerStartupLeaseCount += 1
  try {
    await runCodexAppServerWithClient(event, payload, client)
  } finally {
    codexAppServerStartupLeaseCount = Math.max(0, codexAppServerStartupLeaseCount - 1)
  }
}

async function runCodexAppServerWithClient(
  event: Electron.IpcMainInvokeEvent,
  payload: AgentRunPayload,
  client: CodexAppServerClient
) {
  const graphContextIsolated = isExecutionGraphIsolatedPayload(payload)
  client.setNotificationHandler(handleCodexNotification)
  client.setRequestHandler(handleCodexServerRequest)
  client.setStderrHandler((chunk) => {
    const state = getActiveCodexRunState()
    if (state?.sender) {
      sendAgentCompatError(state.sender, 'codex', chunk, state)
    }
  })

  const persistedChat = payload.appChatId ? AppStore.getChat(payload.appChatId) : null
  const taskWraithOwnsThisRun =
    Boolean(payload.ensembleRun) || persistedChat?.chatKind === 'ensemble'
  const resumableThreadId =
    payload.providerSessionId && isCodexAppServerThreadId(payload.providerSessionId)
      ? payload.providerSessionId
      : null
  if (persistedChat?.chatKind === 'ensemble') {
    for (const participant of persistedChat.ensemble?.participants || []) {
      if (
        participant.provider === 'codex' &&
        participant.linkedProviderSessionId &&
        isCodexAppServerThreadId(participant.linkedProviderSessionId)
      ) {
        taskWraithSteeredCodexThreadIds.add(participant.linkedProviderSessionId)
      }
    }
  }
  if (resumableThreadId && taskWraithOwnsThisRun) {
    // Mark before ensureStarted/thread-resume: app-server startup itself can
    // resume emitting an already-armed native goal before a RunManager owner exists.
    taskWraithSteeredCodexThreadIds.add(resumableThreadId)
  }

  let admissionReservation = resumableThreadId
    ? codexThreadAdmissionRegistry.reserve({
        threadId: resumableThreadId,
        kind: 'turn',
        scope: {
          appChatId: payload.appChatId || '',
          workspaceId: AppStore.getChat(payload.appChatId || '')?.workspaceId,
          joinAfterRelease: () =>
            payload.appRunId ? providerAdapterRunsInFlight.get(payload.appRunId) : undefined
        }
      })
    : undefined
  if (admissionReservation && !(await admissionReservation.waitUntilAcquired())) {
    admissionReservation.releaseBeforeAdmission()
    runManager.finish(payload.appRunId, 'cancelled')
    return
  }
  if (
    admissionReservation &&
    historyClearAdmissionBlocked(payload.appRunId, payload.workspace, payload.appChatId)
  ) {
    admissionReservation.releaseBeforeAdmission()
    runManager.finish(payload.appRunId, 'cancelled')
    return
  }
  try {
    await client.ensureStarted(app.getVersion())
  } catch (error) {
    admissionReservation?.releaseBeforeAdmission()
    throw error
  }
  if (!graphContextIsolated) {
    syncCodexGoalCapabilityMetadata(payload.appChatId, client.supportsNativeGoalControl())
  }

  const settings = runtimeSettings(AppStore.getSettings(), payload.runtimeProfile)
  const model = normalizeCodexModel(payload.model)
  const codexReasoning = resolveCodexOutboundReasoning(model, payload.reasoningEffort)
  const approvalPolicy =
    payload.scope === 'global'
      ? 'on-request'
      : codexApprovalPolicyForMode(payload.approvalMode, settings)
  const fullAccessGranted = isFullShellAccessGranted(payload.effectivePermissions)
  const sandbox = codexSandboxForMode(payload.approvalMode, fullAccessGranted)
  const startOrResumeParams = {
    cwd: payload.workspace!,
    model,
    config: codexReasoning.threadConfig,
    ...(payload.serviceTier ? { serviceTier: payload.serviceTier } : {}),
    approvalPolicy,
    sandbox,
    experimentalRawEvents: false,
    persistExtendedHistory: true
  }

  let threadResponse: any
  if (payload.providerSessionId && !resumableThreadId) {
    // A codex-exec fallback session id (`codex-exec-<ts>`) is not a valid
    // app-server thread UUID — resuming it throws "invalid thread id" and
    // wedges the chat into perpetual exec fallback. Start a fresh thread; its
    // UUID replaces the bad providerSessionId, self-healing the chat.
    console.warn(
      `[codex] non-UUID providerSessionId not resumable on app-server; starting a fresh thread (was: ${payload.providerSessionId})`
    )
  }
  // Last synchronous authority check before the RPC that creates or revives a
  // provider-native thread. A fresh (non-resumable) run holds no admission
  // reservation yet, so a history clear prepared during the ensureStarted
  // await cannot join it — without this recheck, thread/start would mint a
  // native rollout for the frozen scope that TaskWraith never erases.
  if (historyClearAdmissionBlocked(payload.appRunId, payload.workspace, payload.appChatId)) {
    admissionReservation?.releaseBeforeAdmission()
    runManager.finish(payload.appRunId, 'cancelled')
    return
  }
  try {
    if (resumableThreadId) {
      threadResponse = await client.request(
        'thread/resume',
        buildCodexThreadResumeRequest(resumableThreadId, codexReasoning),
        30_000
      )
    } else {
      threadResponse = await client.request('thread/start', startOrResumeParams, 30_000)
    }
  } catch (error) {
    admissionReservation?.releaseBeforeAdmission()
    throw error
  }

  const thread = threadResponse?.thread || {}
  const threadId = thread.id || payload.providerSessionId
  if (!threadId) {
    admissionReservation?.releaseBeforeAdmission()
    throw new Error('Codex app-server did not return a thread id.')
  }
  if (!admissionReservation) {
    admissionReservation = codexThreadAdmissionRegistry.reserve({
      threadId,
      kind: 'turn',
      scope: {
        appChatId: payload.appChatId || '',
        workspaceId: AppStore.getChat(payload.appChatId || '')?.workspaceId,
        joinAfterRelease: () =>
          payload.appRunId ? providerAdapterRunsInFlight.get(payload.appRunId) : undefined
      }
    })
    if (!(await admissionReservation.waitUntilAcquired())) {
      admissionReservation.releaseBeforeAdmission()
      runManager.finish(payload.appRunId, 'cancelled')
      return
    }
  } else if (admissionReservation.threadId !== threadId) {
    admissionReservation.releaseBeforeAdmission()
    admissionReservation = codexThreadAdmissionRegistry.reserve({
      threadId,
      kind: 'turn',
      scope: {
        appChatId: payload.appChatId || '',
        workspaceId: AppStore.getChat(payload.appChatId || '')?.workspaceId,
        joinAfterRelease: () =>
          payload.appRunId ? providerAdapterRunsInFlight.get(payload.appRunId) : undefined
      }
    })
    if (!(await admissionReservation.waitUntilAcquired())) {
      admissionReservation.releaseBeforeAdmission()
      runManager.finish(payload.appRunId, 'cancelled')
      return
    }
  }
  if (historyClearAdmissionBlocked(payload.appRunId, payload.workspace, payload.appChatId)) {
    admissionReservation.releaseBeforeAdmission()
    runManager.finish(payload.appRunId, 'cancelled')
    return
  }
  if (
    payload.ensembleRun?.promptMode === 'slim' &&
    resumableThreadId &&
    !isSameCodexAppServerThreadId(threadId, resumableThreadId)
  ) {
    invalidateEnsemblePromptReceiptsForSession({
      chatId: payload.appChatId || '',
      participantId: payload.ensembleRun.participantId,
      provider: 'codex',
      linkedProviderSessionId: resumableThreadId
    })
    admissionReservation.releaseBeforeAdmission()
    throw new Error(
      'Codex app-server returned a different thread for a slim resumed prompt; refusing a context-poor fresh-session turn.'
    )
  }

  if (!graphContextIsolated) {
    try {
      await syncCodexNativeGoalForRun(
        client,
        payload.appChatId,
        threadId,
        Boolean(payload.ensembleRun)
      )
    } catch (error) {
      admissionReservation.releaseBeforeAdmission()
      throw error
    }
  }

  const route = routeWithRunId('codex', payload)
  const codexState = createCodexRunState(
    event.sender,
    threadId,
    threadResponse?.model || model,
    payload.workspace!,
    payload.scope === 'global' ? undefined : payload.workspace,
    payload.scope,
    route,
    payload
  )
  codexState.admissionKind = 'turn'
  codexState.admissionReservation = admissionReservation
  const sessionBeforeTurnRegistration = runManager.get(route.appRunId)
  if (
    !providerTransportAdmissionStillAuthorized({
      historyBlocked: historyClearAdmissionBlocked(
        route.appRunId,
        payload.workspace,
        route.appChatId
      ),
      sessionExists: Boolean(sessionBeforeTurnRegistration),
      persistenceAuthorized: sessionBeforeTurnRegistration
        ? providerRunPersistenceAuthorized('codex', route)
        : false
    })
  ) {
    runManager.finish(route.appRunId, 'cancelled')
    admissionReservation.releaseBeforeAdmission()
    return
  }
  // Register the per-turn terminal-notification authority before RunManager
  // exposes the state and before turn/start can admit work on the shared
  // daemon. The adapter promise remains live until the terminal projection,
  // rather than resolving as soon as turn/start acknowledges admission.
  const turnOperation = trackCodexAppServerTurnOperation(codexState)
  try {
    const registeredSession = registerRunSession(
      'codex',
      event.sender,
      codexState,
      payload.scope === 'global' ? undefined : payload.workspace,
      codexState,
      threadId
    )
    if (!registeredSession) {
      admissionReservation.releaseBeforeAdmission()
      completeCodexAppServerTurnProjection(codexState)
      await turnOperation
      return
    }
    if (
      !providerTransportAdmissionStillAuthorized({
        historyBlocked: historyClearAdmissionBlocked(
          route.appRunId,
          payload.workspace,
          route.appChatId
        ),
        sessionExists: true,
        persistenceAuthorized: providerRunPersistenceAuthorized('codex', route)
      })
    ) {
      runManager.finish(route.appRunId, 'cancelled')
      admissionReservation.releaseBeforeAdmission()
      completeCodexAppServerTurnProjection(codexState)
      await turnOperation
      return
    }
    setActiveCodexRunState(codexState)
    void emitProviderCapabilityWarnings(
      event.sender,
      'codex',
      payload.workspace,
      payload.approvalMode,
      codexState
    )

    sendAgentCompatLine(
      event.sender,
      'codex',
      {
        type: 'init',
        session_id: threadId,
        model: threadResponse?.model || model,
        timestamp: new Date().toISOString(),
        provider: 'codex'
      },
      codexState
    )

    const turnStartResult = await client.request(
      'turn/start',
      buildCodexTurnStartRequest(
        {
          threadId,
          input: buildCodexUserInput(payload.prompt, payload.imagePaths),
          cwd: payload.workspace!,
          approvalPolicy,
          sandboxPolicy: codexSandboxPolicyForMode(
            payload.approvalMode,
            payload.workspace!,
            payload.externalPathGrants,
            settings,
            payload.scope,
            fullAccessGranted
          ),
          model,
          ...(payload.serviceTier ? { serviceTier: payload.serviceTier } : {})
        },
        codexReasoning
      ),
      60_000
    )
    const admittedTurnId = codexString(turnStartResult?.turn?.id || turnStartResult?.turnId)
    if (admittedTurnId && !bindCodexRunExactOperationId(codexState, admittedTurnId)) {
      throw new Error('Codex turn admission returned a conflicting exact turn id.')
    }
  } catch (error) {
    if (isCodexAppServerRequestTimeout(error, 'turn/start')) {
      // A request timeout is not a rejection: app-server may have admitted the
      // turn and delayed both its response and turn/started notification. Arm
      // an interrupt against the stable thread id, then retain the exact
      // operation until delayed start + terminal projection arrive. Never
      // launch exec fallback into that ambiguity window.
      pendingCodexInterrupts.add(codexState.threadId)
      await turnOperation
      return
    }
    if (codexState.turnId) {
      // A turn/started notification proves admission even when the matching
      // JSON-RPC acknowledgement fails. Interrupt and join its real terminal
      // notification instead of launching a second exec-fallback turn.
      await issueCodexTurnInterrupt(codexState.threadId, codexState.turnId)
      await turnOperation
      return
    }
    // No provider turn was admitted, so the rejected start request itself is
    // terminal evidence for this attempted transport. The outer provider path
    // may safely choose exec fallback after the registry releases this run id.
    admissionReservation.releaseBeforeAdmission()
    completeCodexAppServerTurnProjection(codexState)
    await turnOperation
    throw error
  }
  await turnOperation
}

async function runCodexExecFallback(
  event: Electron.IpcMainInvokeEvent,
  payload: AgentRunPayload,
  reason: string
) {
  const route = routeWithRunId('codex', payload)
  if (historyClearAdmissionBlocked(route.appRunId, payload.workspace, route.appChatId)) {
    runManager.finish(route.appRunId, 'cancelled')
    return
  }
  // The one-shot exec fallback does not own a route-stamped TaskWraith MCP
  // registration. Never retain gateway claims from the primary app-server path
  // or rely on a possibly stale user-global Codex MCP entry.
  payload.taskWraithMcpAdvertised = false
  payload.prompt = sanitizeTaskWraithMcpPromptClaims(payload.prompt, {
    advertised: false,
    coreProfile: false
  })
  const settings = runtimeSettings(AppStore.getSettings(), payload.runtimeProfile)
  if (payload.scope === 'global') {
    sendAgentCompatError(
      event.sender,
      'codex',
      `Codex app-server unavailable, so global chat execution is blocked. Global host tools require in-app approval prompts. Reason: ${reason}`,
      route
    )
    sendAgentCompatExit(event.sender, 'codex', 1, route)
    runManager.finish(route.appRunId, 'failed')
    return
  }
  if (codexNeedsApprovalGate(settings) || settings.agenticServices?.networkAccess === 'deny') {
    sendAgentCompatError(
      event.sender,
      'codex',
      `Codex app-server unavailable and agentic service gates are active, so exec fallback is blocked. Reason: ${reason}`,
      route
    )
    sendAgentCompatExit(event.sender, 'codex', 1, route)
    runManager.finish(route.appRunId, 'failed')
    return
  }

  const model = normalizeCodexModel(payload.model)
  const codexReasoning = resolveCodexOutboundReasoning(model, payload.reasoningEffort)
  const sandbox = codexSandboxForMode(
    payload.approvalMode,
    isFullShellAccessGranted(payload.effectivePermissions)
  )
  const args = [
    ...buildCodexFastServiceTierCompatibilityArgs(),
    ...codexReasoning.execConfigArgs,
    'exec',
    '--json',
    '--color',
    'never',
    '-C',
    payload.workspace!,
    '--skip-git-repo-check',
    '--sandbox',
    sandbox,
    '--model',
    model
  ]
  for (const imagePath of payload.imagePaths || []) {
    args.push('--image', imagePath)
  }
  args.push(payload.prompt)

  const resolvedCodex = await resolveCliProviderBinary('codex', payload.runtimeProfile)
  if (!resolvedCodex.binaryPath) {
    sendAgentCompatError(
      event.sender,
      'codex',
      resolvedCodex.error || 'Codex CLI was not found.',
      route
    )
    sendAgentCompatExit(event.sender, 'codex', -1, route)
    runManager.finish(route.appRunId, 'failed')
    return
  }
  const sessionAfterBinaryResolution = runManager.get(route.appRunId)
  if (
    !providerTransportAdmissionStillAuthorized({
      historyBlocked: historyClearAdmissionBlocked(
        route.appRunId,
        payload.workspace,
        route.appChatId
      ),
      sessionExists: Boolean(sessionAfterBinaryResolution),
      persistenceAuthorized: sessionAfterBinaryResolution
        ? providerRunPersistenceAuthorized('codex', route)
        : false
    })
  ) {
    runManager.finish(route.appRunId, 'cancelled')
    return
  }
  const codexCommand = resolvedCodex.binaryPath
  const codexSpawnPlan = createCliSpawnPlan(codexCommand, args)
  const codexExecStdoutSanitizer = createCanvasEvalJsonLineSanitizer(
    `codex:${route.appRunId || route.appChatId || 'unrouted'}`
  )
  const codexExecStderrSanitizer = createCanvasEvalJsonLineSanitizer(
    `codex:${route.appRunId || route.appChatId || 'unrouted'}:stderr`
  )
  const emitCodexExecStdout = (text: string): void => {
    if (!text) return
    appendDurableRunEventForRoute(
      'codex',
      route,
      'provider_raw',
      'raw',
      'Codex exec stdout',
      { data: text },
      'provider'
    )
    publishRunEvent(
      'agent-output',
      'codex',
      { provider: 'codex', data: text, ...route },
      event.sender
    )
  }
  const emitCodexExecStderr = (text: string): void => {
    if (!text) return
    sendAgentCompatError(event.sender, 'codex', sanitizeCanvasEvalProviderText(text), route)
  }

  let child: ChildProcess | null = null
  let terminalCode: number | null = null
  let spawnFailure: Error | null = null
  const transportClose = createProviderTransportCloseOperation(() => {
    // This callback is the provider-owned terminal projection. It runs only
    // after child close (or a synchronous spawn failure, where no child ever
    // existed), and the tracked operation remains live until it finishes.
    emitCodexExecStdout(codexExecStdoutSanitizer.flush())
    emitCodexExecStderr(codexExecStderrSanitizer.flush())
    if (spawnFailure) {
      sendAgentCompatError(
        event.sender,
        'codex',
        `Failed to start codex exec fallback: ${spawnFailure.message}`,
        route
      )
    }
    const exitCode = spawnFailure ? -1 : (terminalCode ?? -1)
    sendAgentCompatLine(
      event.sender,
      'codex',
      {
        type: 'result',
        status: exitCode === 0 ? 'success' : 'failed',
        stats: {},
        timestamp: new Date().toISOString(),
        provider: 'codex',
        fallback: true
      },
      route
    )
    sendAgentCompatExit(event.sender, 'codex', exitCode, route)
    if (child && codexExecProcess === child) codexExecProcess = null
    runManager.finish(route.appRunId, exitCode === 0 ? 'completed' : 'failed')
  })
  // Track before spawn: there is no interval in which RunManager can expose a
  // live child without an exact close+projection promise for history deletion.
  const transportOperation = providerTransportOperations.track(
    route.appRunId!,
    transportClose.operation
  )
  let registeredSession: ReturnType<typeof registerRunSession>
  try {
    registeredSession = registerRunSession(
      'codex',
      event.sender,
      route,
      payload.workspace,
      undefined
    )
  } catch (error) {
    spawnFailure = error instanceof Error ? error : new Error(String(error))
    transportClose.markTransportClosed()
    await transportOperation
    throw error
  }
  if (!registeredSession) {
    transportClose.markTransportClosed()
    await transportOperation
    return
  }
  void emitProviderCapabilityWarnings(
    event.sender,
    'codex',
    payload.workspace,
    payload.approvalMode,
    route
  )

  sendAgentCompatError(
    event.sender,
    'codex',
    `Codex app-server unavailable; falling back to codex exec --json for this one-shot run. Rich thread resume and approvals are unavailable. Reason: ${reason}`,
    route
  )
  if (normalizeExternalPathGrants(payload.externalPathGrants).length > 0) {
    sendAgentCompatError(
      event.sender,
      'codex',
      'Codex external path grants are not applied in exec fallback mode; app-server is required for scoped outside-workspace roots.',
      route
    )
  }
  sendAgentCompatLine(
    event.sender,
    'codex',
    {
      type: 'init',
      session_id: `codex-exec-${Date.now()}`,
      model,
      timestamp: new Date().toISOString(),
      provider: 'codex',
      fallback: true
    },
    route
  )
  if (
    !providerTransportAdmissionStillAuthorized({
      historyBlocked: historyClearAdmissionBlocked(
        route.appRunId,
        payload.workspace,
        route.appChatId
      ),
      sessionExists: true,
      persistenceAuthorized: providerRunPersistenceAuthorized('codex', route)
    })
  ) {
    runManager.finish(route.appRunId, 'cancelled')
    transportClose.markTransportClosed()
    await transportOperation
    return
  }
  try {
    child = spawn(codexSpawnPlan.command, codexSpawnPlan.args, {
      cwd: payload.workspace!,
      shell: codexSpawnPlan.shell,
      stdio: ['ignore', 'pipe', 'pipe'],
      env: createCliEnv({
        FORCE_COLOR: '0',
        NO_COLOR: '1',
        TASKWRAITH_RUNTIME_PROFILE_ID: payload.runtimeProfileId || '',
        // Audit role-run: advertise the audit_* MCP tools to this exec-fallback's
        // bridge child. NOTE (v1 gap): Codex's PRIMARY path is the shared
        // app-server daemon (runCodexAppServer), whose MCP bridge env is fixed at
        // daemon start — there is no per-role-run injection point there, and the
        // daemon does not stamp TASKWRAITH_RUN_ID, so audit tool calls from the
        // app-server path would not route back to the role-run's audit context.
        // Making Codex fully audit-capable needs daemon-scoped advertisement +
        // per-turn run-id correlation, deferred to a follow-up. This exec path is
        // only the fallback; threading the flag here is harmless and forward-looking.
        ...(payload.auditRun ? { TASKWRAITH_MCP_AUDIT: '1' } : {})
      })
    })
  } catch (error) {
    spawnFailure = error instanceof Error ? error : new Error(String(error))
    transportClose.markTransportClosed()
    await transportOperation
    return
  }
  codexExecProcess = child
  runManager.attachProcess(route.appRunId!, child)

  child.stdout?.on('data', (data) => {
    emitCodexExecStdout(codexExecStdoutSanitizer.push(data.toString()))
  })

  let execConfigErrorSurfaced = false
  child.stderr?.on('data', (data) => {
    const text = data.toString()
    // The exec fallback runs the SAME codex CLI, so a bad ~/.codex/config.toml
    // fails it too. Surface the actionable message once (not per chunk) so the
    // exec path isn't another dead-end with a cryptic deserialize dump.
    if (!execConfigErrorSurfaced && isCodexConfigParseError(text)) {
      execConfigErrorSurfaced = true
      sendAgentCompatError(event.sender, 'codex', codexConfigParseUserMessage(text), route)
    }
    emitCodexExecStderr(codexExecStderrSanitizer.push(text))
  })

  child.on('close', (code) => {
    terminalCode = code
    transportClose.markTransportClosed()
  })

  child.on('error', (error) => {
    // Error alone is not child-close evidence. Preserve it for the terminal
    // projection; history deletion continues to wait for the close event.
    spawnFailure = error
  })
  await transportOperation
}

/**
 * Other well-known codex install locations that are NOT on TaskWraith's PATH
 * search but that a user is likely to also have. Today this is the official
 * Codex.app bundle, whose CLI (e.g. 0.136.0-alpha.2) is frequently NEWER than
 * the homebrew `codex` (0.128.0) TaskWraith resolves — and writes config values
 * the older CLI rejects. We compare versions and, if one of these is newer
 * than the binary TaskWraith would spawn, emit a single non-blocking hint.
 *
 * Conservative by design: this DETECTS + WARNS only. We deliberately do NOT
 * auto-switch the binary — different codex versions ship different flags and
 * app-server behaviour, and silently spawning a different CLI than the one the
 * user configured is a far riskier failure mode than an upgrade nag.
 */

async function maybeWarnNewerCodexBinary(
  sender: Electron.WebContents,
  route: AgentRunRoute,
  runtimeProfile?: RuntimeProfile | null
): Promise<void> {
  if (codexNewerBinaryWarned) return
  try {
    const resolved = await resolveCliProviderBinary('codex', runtimeProfile)
    if (!resolved.binaryPath) return
    const usedVersion = await readResolvedCliVersion(resolved)

    let newest: { path: string; version: string } | null = null
    for (const candidate of KNOWN_OFF_PATH_CODEX_BINARIES) {
      // Skip the candidate if it IS the binary TaskWraith already uses (e.g. PATH
      // happens to point at it) — no point warning about itself.
      if (candidate === resolved.binaryPath) continue
      let exists = false
      try {
        const stat = await fs.stat(candidate)
        exists = stat.isFile() || stat.isSymbolicLink()
      } catch {
        exists = false
      }
      if (!exists) continue
      const candidateVersion = await readResolvedCliVersion({
        provider: 'codex',
        binaryPath: candidate,
        source: 'common'
      })
      // candidate strictly newer than the one TaskWraith uses?
      if (compareCodexVersions(candidateVersion, usedVersion) > 0) {
        // And the newest among multiple candidates.
        if (!newest || compareCodexVersions(candidateVersion, newest.version) > 0) {
          newest = { path: candidate, version: candidateVersion }
        }
      }
    }

    if (!newest) return
    codexNewerBinaryWarned = true
    sendAgentCompatLine(
      sender,
      'codex',
      {
        type: 'provider_warning',
        provider: 'codex',
        severity: 'warning',
        title: 'Newer Codex CLI detected',
        message:
          `A newer codex CLI (${newest.version.trim()}) is installed at ${newest.path} than the one TaskWraith uses ` +
          `(${usedVersion.trim()} at ${resolved.binaryPath}). The newer CLI can write ~/.codex/config.toml values the ` +
          'older one rejects (causing run failures). Either upgrade the CLI TaskWraith resolves, or create a Codex ' +
          `runtime profile that uses ${newest.path}.`
      },
      route
    )
  } catch {
    // Best-effort hint only; never let version detection break a codex run.
  }
}

async function runCodexProvider(
  event: Electron.IpcMainInvokeEvent,
  payload: AgentRunPayload
): Promise<void> {
  // One-time, best-effort hint when a NEWER codex CLI is installed than the one
  // TaskWraith will actually spawn (the exact mismatch that lets Codex.app write a
  // config the homebrew CLI rejects). Detection + warning only — never auto-switch.
  void maybeWarnNewerCodexBinary(
    event.sender,
    routeWithRunId('codex', payload),
    payload.runtimeProfile
  )
  try {
    await runCodexAppServer(event, payload)
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    if (error instanceof CodexEnsembleGoalIsolationError) {
      const route = routeWithRunId('codex', payload)
      sendAgentCompatError(event.sender, 'codex', message, route)
      sendAgentCompatExit(event.sender, 'codex', -1, route)
      runManager.finish(route.appRunId, 'failed')
      return
    }
    if (shouldBlockCodexExecFallbackForSlimEnsemblePrompt(payload)) {
      if (payload.providerSessionId) {
        invalidateEnsemblePromptReceiptsForSession({
          chatId: payload.appChatId || '',
          participantId: payload.ensembleRun?.participantId,
          provider: 'codex',
          linkedProviderSessionId: payload.providerSessionId
        })
      }
      const route = routeWithRunId('codex', payload)
      sendAgentCompatError(
        event.sender,
        'codex',
        `Codex app-server unavailable during a slim resumed Ensemble turn; one-shot exec fallback was blocked because it has no native session context. The next turn will send a full briefing. Reason: ${message}`,
        route
      )
      sendAgentCompatLine(
        event.sender,
        'codex',
        {
          type: 'result',
          status: 'failed',
          stats: {},
          timestamp: new Date().toISOString(),
          provider: 'codex',
          fallback: false
        },
        route
      )
      sendAgentCompatExit(event.sender, 'codex', -1, route)
      runManager.finish(route.appRunId, 'failed')
      return
    }
    // If the app-server failed because the codex CLI couldn't parse
    // ~/.codex/config.toml (e.g. a value only the newer Codex.app CLI accepts),
    // surface a clear, actionable message instead of only the cryptic
    // exec-fallback notice. The exec fallback below will likely hit the same
    // config error, but we still attempt it (and re-classify its stderr there).
    const stderr =
      (error as { codexStderr?: string } | null)?.codexStderr ||
      getCodexClient().getRecentStderr() ||
      message
    if (isCodexConfigParseError(stderr) || isCodexConfigParseError(message)) {
      const route = routeWithRunId('codex', payload)
      sendAgentCompatError(event.sender, 'codex', codexConfigParseUserMessage(stderr), route)
    }
    await runCodexExecFallback(event, payload, message)
  }
}

const ollamaMainRuntime = createOllamaMainRuntime({
  store: {
    getSettings: () => AppStore.getSettings(),
    updateSettings: (partial) => AppStore.updateSettings(partial),
    getChat: (chatId) => AppStore.getChat(chatId),
    saveChat: (chat) => AppStore.saveChat(chat),
    getRunQueueJob: (runId) => (runId ? AppStore.getRunQueueJob(runId) : null)
  },
  canonicalPath,
  canonicalExternalGrantPath,
  isPathInsideRoot,
  getAgentToolContext,
  resolveGrantAwarePath: resolveGeminiMcpGrantAwarePath,
  resolveGrantAwarePathAuthority: resolveGeminiMcpGrantAwarePathAuthority,
  externalPathGrantForTarget,
  workspaceToolExecutors,
  createHostCommandProjection: (request) =>
    hostCommandProjectionHandle(
      createHostCommandProjectionScope({
        source: 'ollama-local-tool',
        appRunId: request.appRunId,
        appChatId: request.appChatId,
        workspacePath: request.workspacePath
      })
    ),
  executeMcpTool: executeGeminiMcpTool,
  registerRunSession,
  appendDurableRunEventForRoute,
  sendAgentCompatLine,
  sendAgentCompatError,
  sendAgentCompatExit,
  runManager,
  emitProviderCapabilityWarnings,
  runProvider: runOllamaProvider
})
const runOllamaProviderAdapter = ollamaMainRuntime.runProviderAdapter

async function terminateExactProviderSession(
  provider: ProviderId,
  runId: string,
  terminalStatus: 'failed' | 'cancelled'
): Promise<boolean> {
  const session = runManager.get(runId)
  if (!session || session.provider !== provider || !isActiveRunSessionStatus(session.status)) {
    return false
  }

  const codexState = provider === 'codex' ? getCodexStateFromSession(session) : undefined
  const graphOwnedAttempt = executionGraphOwnsAttemptRunId(runId)
  const deferEagerTerminalization = shouldDeferEagerProviderTerminalization({
    graphOwnedAttempt,
    exactTransportOperationTracked: Boolean(providerTransportOperations.get(runId))
  })
  const exactAbortController = session.abortController
  const exactProcess = session.process
  if (
    graphOwnedAttempt &&
    !runManager.claimTerminalStatus(runId, terminalStatus, { requireConfirmation: true })
  ) {
    return false
  }
  try {
    try {
      exactAbortController?.abort()
    } catch {
      // Continue through every exact transport stop before terminalizing.
    }
    try {
      exactProcess?.kill()
    } catch {
      // A provider process may already have exited after publishing its handle.
    }
    if (cliProviderProcesses.get(provider) === exactProcess) {
      cliProviderProcesses.delete(provider)
    }
    if (cliProviderAbortControllers.get(provider) === exactAbortController) {
      cliProviderAbortControllers.delete(provider)
    }
    if (provider === 'gemini' && geminiProcess === exactProcess) {
      geminiProcess = null
    }
    if (provider === 'codex' && codexExecProcess === exactProcess) {
      codexExecProcess = null
    }
    if (provider === 'codex') {
      const decision = decideCancelInterrupt(codexState)
      if (decision.interruptNow && codexState?.threadId && codexState.turnId) {
        await issueCodexTurnInterrupt(codexState.threadId, codexState.turnId).catch(() => undefined)
      } else if (decision.deferThreadId) {
        pendingCodexInterrupts.add(decision.deferThreadId)
      }
    }
  } finally {
    // A graph cancellation request is not terminal evidence. Likewise, every
    // tracked exact transport owns its real close/projection callback. Retain
    // the active RunManager session so a deletion begun after ordinary cancel
    // can still discover, stop, and join that exact lifecycle authority.
    if (!deferEagerTerminalization) {
      runManager.finish(runId, terminalStatus)
    }
  }

  if (provider === 'gemini' && !geminiSessionProcess) {
    const latestGemini = getSingleActiveProviderSession('gemini')?.state as
      | GeminiToolContext
      | undefined
    activeGeminiToolContext = latestGemini?.sender ? latestGemini : null
  }
  return true
}

/** Abort the exact provider transport and join the adapter's close/cleanup
 * promise before a destructive-history receipt can be written. */
async function terminateProviderRunForHistory(
  provider: ProviderId,
  runId: string
): Promise<boolean> {
  const session = runManager.get(runId)
  const adapterOperation = providerAdapterRunsInFlight.get(runId)
  const transportOperation = providerTransportOperations.get(runId)
  const operations = [...new Set([adapterOperation, transportOperation].filter(Boolean))] as Array<
    Promise<void>
  >
  if (!session) {
    if (operations.length > 0) {
      const joined = await Promise.all(
        operations.map((operation) => waitForProviderOperationSettlement(operation, 10_000))
      )
      return joined.every(Boolean)
    }
    // A fresh process has lost the child PID/start-time identity needed to
    // prove that a CLI/ACP transport died with Electron. Never manufacture a
    // provider receipt from missing in-memory state; recovery remains fenced
    // until launch supervision can supply durable parent-death/exit evidence.
    return false
  }
  if (session.provider !== provider) return false

  const stopped = isActiveRunSessionStatus(session.status)
    ? await terminateExactProviderSession(provider, runId, 'cancelled')
    : true
  if (!stopped && isActiveRunSessionStatus(runManager.get(runId)?.status || 'cancelled')) {
    return false
  }

  if (operations.length > 0) {
    let settled = await Promise.all(
      operations.map((operation) => waitForProviderOperationSettlement(operation, 5_000))
    )
    if (!settled.every(Boolean)) {
      try {
        session.process?.kill('SIGKILL')
      } catch {
        // The first termination may already have reaped the exact child.
      }
      settled = await Promise.all(
        operations.map((operation) => waitForProviderOperationSettlement(operation, 5_000))
      )
    }
    if (!settled.every(Boolean)) return false
  }
  return !isActiveRunSessionStatus(runManager.get(runId)?.status || 'cancelled')
}

async function containExecutionGraphTerminalJoin(runId: string, reason: string): Promise<void> {
  clearExecutionGraphTerminalJoinWatchdog(runId)
  const session = runManager.get(runId)
  if (
    !session ||
    !isActiveRunSessionStatus(session.status) ||
    !executionGraphOwnsAttemptRunId(runId)
  ) {
    return
  }

  const boundedReason =
    boundedExecutionGraphTranscriptError(reason) ??
    'Provider terminal confirmation did not converge.'
  const transcript = bridgeRunTranscripts.get(runId)
  if (transcript?.owner === 'execution_graph') {
    transcript.errorMessage = boundedReason
    try {
      projectAndPersistExecutionGraphRunTranscript(transcript, 'running', boundedReason)
    } catch (error) {
      console.error(
        `[ExecutionGraph] terminal join evidence could not be projected for runId=${runId}:`,
        error
      )
    }
  }

  const claimedStatus = runManager.getClaimedTerminalStatus(runId) ?? 'failed'
  await terminateExactProviderSession(session.provider, runId, claimedStatus)
  const current = runManager.get(runId)
  if (!current || isTerminalRunSessionStatus(current.status)) return
  if (!runManager.containTerminalJoin(runId, 'failed')) {
    throw new Error('RunManager rejected bounded execution graph terminal containment.')
  }
}

function hasCommittedExecutionGraphTerminalReceipt(
  runId: string,
  status: 'completed' | 'failed' | 'cancelled'
): boolean {
  const job = AppStore.getRunQueueJob(runId)
  const binding = job?.executionGraph
  const chat = job?.chatId ? AppStore.getChat(job.chatId) : null
  const run = chat?.runs?.find((candidate) => candidate.runId === runId)
  const receipt = run?.providerMetadata?.executionGraphResultReceipt as
    | ExecutionGraphAttemptTerminalReceipt
    | undefined
  return Boolean(
    binding &&
    chat &&
    receipt &&
    receipt.status === status &&
    receipt.binding.executionId === binding.executionId &&
    receipt.binding.activationId === binding.activationId &&
    receipt.binding.attemptId === binding.attemptId &&
    verifyExecutionGraphAttemptReceiptOnChat(chat, receipt)
  )
}

async function cancelExecutionGraphProviderRun(
  provider: ProviderId,
  runId: string
): Promise<boolean> {
  const job = AppStore.getRunQueueJob(runId)
  if (!job?.executionGraph || job.provider !== provider || job.runId !== runId) return false

  let settle: (confirmed: boolean) => void = () => {}
  let settled = false
  let timeout: NodeJS.Timeout | undefined
  let unsubscribe: () => void = () => {}
  const finish = (confirmed: boolean): void => {
    if (settled) return
    settled = true
    if (timeout) clearTimeout(timeout)
    unsubscribe()
    settle(confirmed)
  }
  const terminal = new Promise<boolean>((resolve) => {
    settle = resolve
    unsubscribe = runManager.onChange((event) => {
      if (
        event.type !== 'removed' &&
        event.session.runId === runId &&
        (event.session.status === 'completed' ||
          event.session.status === 'failed' ||
          event.session.status === 'cancelled')
      ) {
        finish(hasCommittedExecutionGraphTerminalReceipt(runId, event.session.status))
      }
    })
    timeout = setTimeout(() => finish(false), 15_000)
  })

  try {
    const transcriptState = bridgeRunTranscripts.get(runId)
    const providerTerminalAlreadyObserved = Boolean(
      transcriptState?.owner === 'execution_graph' &&
      transcriptState.provider === provider &&
      transcriptState.chatId === job.chatId &&
      transcriptState.providerTerminalCandidate
    )
    if (!providerTerminalAlreadyObserved) {
      const requested = await cancelProviderRun(provider, runId)
      if (!requested) finish(false)
    }
    const current = runManager.get(runId)
    if (
      current &&
      (current.status === 'completed' ||
        current.status === 'failed' ||
        current.status === 'cancelled')
    ) {
      finish(hasCommittedExecutionGraphTerminalReceipt(runId, current.status))
    }
  } catch {
    finish(false)
  }
  return await terminal
}

async function cancelProviderRun(
  provider: ProviderId = 'gemini',
  runId?: string
): Promise<boolean> {
  const queuedJob = runId ? AppStore.getRunQueueJob(runId) : null
  if (queuedJob && (queuedJob.status === 'queued' || queuedJob.status === 'paused')) {
    if (queuedJob.provider !== provider) return false
    approvalService?.cancelForRun(queuedJob.runId, 'run-cancel-requested')
    cancelPendingAgentQuestionsForRun(queuedJob.runId, 'run-cancel-requested')
    getRunRepository().markCancelled({
      runId: queuedJob.runId,
      provider: queuedJob.provider,
      workspacePath: queuedJob.workspacePath,
      chatId: queuedJob.chatId,
      workspaceId: queuedJob.workspaceId,
      statusReason: 'Cancelled before the queued run started.'
    })
    return true
  }

  const session = runId ? runManager.get(runId) : getSingleActiveProviderSession(provider)
  // A supplied run id is an exact cancellation target. Never fall through to
  // provider-global process/controller state when that run is absent, and do
  // not let a mismatched provider label cancel a different provider's run.
  if (runId && (!session || session.provider !== provider)) return false
  if (session) {
    if (!runId && wasScheduledOccurrenceRunIdObserved(session.runId)) return false
    // Revoke pending approvals synchronously before the provider transport is
    // asked to stop. A slow/failed cancellation must not leave a desktop card
    // capable of resuming the run during that await window.
    if (!runManager.claimTerminalStatus(session.runId, 'cancelled')) return false
    approvalService?.cancelForRun(session.runId, 'run-cancel-requested')
    cancelPendingAgentQuestionsForRun(session.runId, 'run-cancel-requested')
    return terminateExactProviderSession(provider, session.runId, 'cancelled')
  }

  // Provider-global process/controller handles cannot prove chat or occurrence
  // authority. Exact run ids (or a unique RunManager session above) are required.
  return false
}

// Phase M1 Step 2: bundle the module-local helpers GeminiApiProvider
// needs into a deps object so it can stay self-contained (no runtime
// import from `index.ts`, just types). Built fresh per call so any
// future test wiring can override individual fields without touching
// the live closure.
//
// Phase M1 Step 3: extended with `getMcpToolDefinitions` and
// `executeMcpTool` so the API runtime can dispatch through the same
// host-side executor the CLI's MCP broker uses. Wrapping is minimal —
// we just close over `executeGeminiMcpTool` and force the parent
// provider to 'gemini' (since this factory is only used by the Gemini
// API path). The Step-3 deps still satisfy the Step-2 type, but tests
// covering tool calling must provide both new fields.
//
// Phase M1 Step 5: extended with `getChat` + `saveChatLinkedSessionId`.
// Together they let the provider replay multi-turn history (via
// GeminiApiHistoryAdapter) and pin a synthetic `api://<chatId>` id on
// the chat record so the renderer's session-continuity UI sees the
// chat as "linked" even though the API is stateless.
//
// `saveChatLinkedSessionId` enforces the field-level merge rules
// described in the GeminiApiProviderDeps doc: leave existing
// `api://...` ids alone (idempotent across turns), overwrite legacy
// `cli://...` ids (the chat just transitioned runtimes), set when
// missing. Read-modify-write through AppStore.saveChat is fine because
// these calls are serialised on the main thread.
//
// Phase M1 Step 8: extended with `recordUsage` so the provider can
// persist the API's `usageMetadata` directly (the renderer's mapping
// doesn't recognise the Gemini API's promptTokenCount/etc. key shape).
//
// Phase M1 Step 9: extended with `appendChatSystemMessage` so the
// provider can emit the one-time migration notice when a CLI-linked
// chat takes its first API-runtime turn. We broadcast the chat-updated
// event after the append so the renderer picks up the new message
// without a manual refresh.
function geminiApiProviderDeps() {
  return {
    sendAgentCompatLine,
    sendAgentCompatError,
    sendAgentCompatExit,
    runManager,
    getSettings: () => AppStore.getSettings(),
    getGeminiAuthProfiles,
    getDefaultGeminiAuthProfileId,
    decryptApiKey,
    getMcpToolDefinitions: mcpToolDefinitions,
    executeMcpTool: async (toolName: string, args: unknown, route: AgentRunRoute | null) => {
      const canonicalToolName = canonicalTaskWraithToolName(toolName)
      if (!isTaskWraithMcpToolName(canonicalToolName)) {
        return {
          text: `Unknown TaskWraith MCP tool: ${toolName}`,
          isError: true
        }
      }
      const result = await executeGeminiMcpTool(canonicalToolName, args, route, 'gemini')
      return { text: result.text, isError: result.isError }
    },
    prepareToolContext: (
      sender: Electron.WebContents,
      runPayload: AgentRunPayload,
      route: AgentRunRoute,
      sessionId: string
    ) => {
      installGeminiToolContextForRun(
        sender,
        runPayload.scope === 'global' ? globalRunCwd() : runPayload.workspace || globalRunCwd(),
        route,
        runPayload.scope,
        Boolean(runPayload.sessionTrust),
        {
          runPayload,
          providerSessionId: sessionId
        }
      )
    },
    getChat: (chatId: string) => AppStore.getChat(chatId),
    saveChatLinkedSessionId: (chatId: string, sessionId: string) => {
      const existing = AppStore.getChat(chatId)
      if (!existing) return
      const current = existing.linkedProviderSessionId || ''
      // Already pinned to an api://... id (typical follow-up turns): no-op.
      if (current.startsWith('api://')) return
      // Either empty or a legacy cli://... id from a prior CLI run.
      // Overwrite + persist.
      existing.linkedProviderSessionId = sessionId
      AppStore.saveChat(existing)
    },
    recordUsage: (entry: Omit<UsageRecord, 'id' | 'timestamp'>) => {
      AppStore.recordUsage(entry)
    },
    appendChatSystemMessage: (chatId: string, message: ChatMessage) => {
      const existing = AppStore.getChat(chatId)
      if (!existing) return
      const updated: ChatRecord = {
        ...existing,
        messages: [...existing.messages, message],
        updatedAt: Date.now()
      }
      AppStore.saveChat(updated)
      broadcastChatUpdated(updated)
    }
  }
}

async function runGeminiProvider(
  event: Electron.IpcMainInvokeEvent,
  payload: AgentRunPayload
): Promise<void> {
  const route = routeWithRunId('gemini', payload)
  // Phase M1 Step 2: try the in-process Gemini API path first. If it
  // handles the run (success or handled error), return; else fall
  // through to the legacy CLI path. Gating + auth-profile resolution
  // live inside the helper so this call site stays a one-liner.
  if (await tryRunGeminiApi(event, payload, route, geminiApiProviderDeps())) return
  const args: string[] = []
  const settings = runtimeSettings(AppStore.getSettings(), payload.runtimeProfile)
  const approvalMode = payload.approvalMode || 'default'
  const effectiveApprovalMode =
    payload.scope === 'global' && approvalMode !== 'plan'
      ? 'default'
      : resolveGeminiApprovalModeForServices(approvalMode, settings)
  const requiresGeminiWriteTools = geminiWriteModeRequiresBridge(
    payload.scope,
    effectiveApprovalMode
  )
  // 1.0.72 — flagged read-only MCP advertise (default OFF). Only a plan-mode
  // workspace run with the bridge already enabled; drops the seatbelt + advertises
  // the safe subset. Requires geminiMcpBridgeEnabled so the broker is started.
  const geminiReadOnlyAdvertise =
    geminiReadOnlyMcpAdvertiseEnabled() &&
    settings.geminiMcpBridgeEnabled &&
    !requiresGeminiWriteTools &&
    payload.scope !== 'global'
  if (effectiveApprovalMode !== approvalMode) {
    sendAgentCompatError(
      event.sender,
      'gemini',
      `Gemini approval mode changed from ${approvalMode} to ${effectiveApprovalMode} because TaskWraith service settings block write-capable Gemini modes.`,
      route
    )
  }
  // 1.0.5-EW21 — Pass `isEnsembleRun` so ensemble participants
  // always get a fresh session. The orchestrator rebuilds full
  // transcript context every turn (buildEnsembleParticipantPrompt),
  // so CLI session resume is redundant for ensemble participants;
  // attempting to resume a stale id (from a turn whose cwd no
  // longer matches the current spawn cwd) fails with exit 42
  // "Invalid session identifier". Solo Gemini keeps current
  // plan-mode resume behavior unaffected.
  const resumePolicy = resolveGeminiCliResumePolicy(
    effectiveApprovalMode,
    payload.providerSessionId,
    Boolean(payload.ensembleRun)
  )
  if (resumePolicy.skippedReason) {
    sendAgentCompatLine(
      event.sender,
      'gemini',
      {
        type: 'provider_warning',
        provider: 'gemini',
        severity: 'warning',
        title: 'Gemini session resume skipped',
        message: resumePolicy.skippedReason
      },
      route
    )
  }
  const argsError = appendGeminiCliSessionArgs(
    args,
    payload.model || 'cli-default',
    effectiveApprovalMode,
    Boolean(payload.sessionTrust),
    resumePolicy.resumeSessionId,
    settings.geminiCheckpointingEnabled,
    payload.geminiWorktree || null,
    requiresGeminiWriteTools,
    payload.externalPathGrants,
    geminiReadOnlyAdvertise
  )
  if (argsError) {
    sendAgentCompatError(event.sender, 'gemini', argsError, route)
    sendAgentCompatExit(event.sender, 'gemini', -1, route)
    return
  }

  const includeDirs = Array.from(
    (payload.imagePaths || []).reduce((acc, attachmentPath) => {
      const normalized = attachmentPath.trim()
      if (!normalized) return acc
      const pathToInclude = isAbsolute(normalized)
        ? dirname(normalized)
        : dirname(join(payload.workspace!, normalized))
      if (pathToInclude) {
        acc.add(pathToInclude)
      }
      return acc
    }, new Set<string>())
  )

  includeDirs.forEach((imageDir) => {
    args.push('--include-directories', imageDir)
  })

  args.push('--prompt', payload.prompt, '--output-format', 'stream-json')

  const resolved = await resolveCliProviderBinary('gemini', payload.runtimeProfile)
  if (!resolved.binaryPath) {
    sendAgentCompatError(
      event.sender,
      'gemini',
      resolved.error || 'Gemini CLI is not configured.',
      route
    )
    sendAgentCompatExit(event.sender, 'gemini', -1, route)
    return
  }

  try {
    await prepareGeminiMcpBridgeForRun(
      event.sender,
      payload.workspace!,
      route,
      payload.scope,
      Boolean(payload.sessionTrust),
      {
        requireWriteTools: requiresGeminiWriteTools,
        runPayload: payload
      }
    )
  } catch (error) {
    sendAgentCompatError(
      event.sender,
      'gemini',
      error instanceof Error ? error.message : String(error),
      route
    )
    sendAgentCompatExit(event.sender, 'gemini', -1, route)
    return
  }

  void emitProviderCapabilityWarnings(
    event.sender,
    'gemini',
    payload.workspace,
    effectiveApprovalMode,
    route
  )

  await ensureGeminiAuthProfileMaterialized(
    payload.geminiAuthProfileId || getDefaultGeminiAuthProfileId(),
    {
      includeMcp: settings.geminiMcpBridgeEnabled || requiresGeminiWriteTools
    }
  )

  const env = createCliEnv(
    {
      FORCE_COLOR: '0',
      NO_COLOR: '1',
      ...resolveGeminiAuthProfileEnv(payload.geminiAuthProfileId),
      TASKWRAITH_RUN_ID: route.appRunId || '',
      TASKWRAITH_CHAT_ID: route.appChatId || '',
      TASKWRAITH_WORKSPACE_PATH: payload.scope === 'global' ? '' : payload.workspace || '',
      TASKWRAITH_RUNTIME_PROFILE_ID: payload.runtimeProfileId || '',
      // Audit role-run: set the audit-tool advertisement flag for this run's
      // bridge child (inherited via the Gemini CLI env). NOTE (v1 gap): a
      // plan-mode Gemini run keeps the --sandbox seatbelt (geminiReadOnlyAdvertise
      // above does NOT OR-in audit runs), which blocks the bridge subprocess from
      // reaching the broker — so the audit tools are unreachable here. That's
      // exactly why the resolver restricts audit roles to AUDIT_ARTIFACT_CAPABLE_
      // PROVIDERS (claude/kimi) in v1, so Gemini is never assigned a recording
      // role. This flag is set forward-looking for when the security-gated
      // seatbelt swap lands and Gemini can be widened back in.
      ...(payload.auditRun ? { TASKWRAITH_MCP_AUDIT: '1' } : {}),
      // Phase I2: every CLI spawn now carries the parent provider so
      // the TaskWraith MCP bridge subprocess (inherited via env) stamps
      // broker requests with the right routing key. Codex's persistent
      // app-server sets this via `-c mcp_servers.TaskWraith.env` in
      // CodexAppServerClient.
      TASKWRAITH_PARENT_PROVIDER: 'gemini',
      // Recent Gemini CLI versions tightened the headless trust check:
      // even when the user has trusted the directory interactively, a
      // headless spawn fails with "Gemini CLI is not running in a
      // trusted directory" unless --skip-trust is passed OR this env
      // var is set. TaskWraith has already validated workspace trust
      // upstream (prepareGeminiMcpBridgeForRun + the run dispatcher's
      // approval gate), so passing this through is safe — we're only
      // bypassing Gemini's redundant second-layer check, not TaskWraith's
      // own trust enforcement. Docs:
      // https://geminicli.com/docs/cli/trusted-folders/#headless-and-automated-environments
      GEMINI_CLI_TRUST_WORKSPACE: 'true'
    },
    resolved.binaryPath
  )
  markGeminiAuthProfileUsed(payload.geminiAuthProfileId || getDefaultGeminiAuthProfileId())

  // 1.0.5-EW17 — In global-mode runs, swap the spawn cwd from
  // `$HOME` (what `globalRunCwd()` set on payload.workspace) to a
  // dedicated isolated dir. Gemini CLI scans its cwd recursively
  // at startup (ripgrep → GrepTool fallback). Scanning `$HOME`
  // hangs the process for 3+ minutes; scanning an empty TaskWraith-
  // managed dir completes instantly. We deliberately do NOT
  // overwrite `payload.workspace` itself — downstream sites
  // (MCP bridge setup, image-attachment dirname resolution,
  // `--include-directories` plumbing above) still want the user's
  // intended workspace path, and the global-mode case already
  // handles "no real workspace" by gating writes off and skipping
  // workspace-scoped tools. The only thing we change is where the
  // CLI process itself thinks it's standing.
  const spawnCwd = payload.scope === 'global' ? globalGeminiCwd() : payload.workspace!
  const child = spawn(resolved.binaryPath, args, {
    cwd: spawnCwd,
    shell: false,
    env
  })
  geminiProcess = child
  runManager.attachProcess(route.appRunId!, child)

  // Ensemble-mode orchestrator bridge for Gemini CLI events.
  //
  // The other providers (Codex/Claude/Kimi + the Gemini API runtime)
  // emit their events through `sendAgentCompatLine`, which calls
  // `ensembleOrchestratorRef.handleProviderOutput(...)` so the
  // orchestrator can accumulate `run.content` and persist the
  // assistant message via `flushRun`. The Gemini *CLI* path is a
  // legacy spawn that pipes raw JSON-lines stdout straight to the
  // renderer via `publishRunEvent('gemini-output', ...)` — it never
  // touches `sendAgentCompatLine`, so the orchestrator never sees
  // Gemini's deltas in ensemble mode. Result: `run.content` stays
  // empty, the assistant message append at `flushRun()` skips,
  // Gemini's bubble never lands. (Renderer-side display still
  // works because GeminiStreamAdapter parses the same stdout.)
  //
  // Gate strictly on `payload.ensembleRun` so solo Gemini chats
  // pay no extra cost. Mirrors the line-buffer pattern in the
  // renderer's `GeminiStreamAdapter.appendChunk`.
  let ensembleLineBuffer = ''
  // 1.0.5-EW7 + EW12 — Stuck-process detection for the Gemini CLI
  // in ensemble runs. The legacy CLI path has a failure mode where
  // the process emits stderr (`gemini-error`) + an `init` stdout
  // event (`{"type":"init", ...}`) + occasionally one or two more
  // small structured events, and then sits there FOREVER without
  // producing actual response content. The process never exits, so
  // EW6's close-handler markRunExited doesn't fire, and the
  // ensemble round stalls on "Thinking…" indefinitely.
  //
  // EW7 first attempt counted events and killed when count ≤ 1.
  // the maintainer's repro showed Gemini emits ≥ 2 events during the stuck
  // state — init + another small structured event — so the count
  // gate slipped past and the timer never fired the kill.
  //
  // EW12 — Switch from event-count to event-IDLE-time. Track
  // `lastOrchestratorEventAt`. A polling timer checks how long
  // it's been since the last event; if more than
  // GEMINI_STUCK_IDLE_MS without a single new event, declare the
  // process stuck and kill. This works regardless of how many
  // events Gemini emits during its initial burst — as long as the
  // burst stops cleanly and no further events arrive, we detect
  // it. Solo Gemini chats don't run this code path.
  // 1.0.5-EW15 — Bumped 30s → 180s. the maintainer caught: a global-chat
  // Gemini turn legitimately took 332s (5.5 minutes) to complete
  // because the CLI fell back from ripgrep to GrepTool for a
  // workspace scan. EW12's 30s threshold was killing healthy-but-
  // slow runs mid-progress. The new 180s threshold + counting
  // stderr as a heartbeat (EW15 below) only fires the kill when
  // Gemini is TRULY silent (no stdout, no stderr) for 3 minutes —
  // i.e. genuinely deadlocked, not just slow.
  const GEMINI_STUCK_IDLE_MS = 180_000
  const GEMINI_STUCK_POLL_MS = 10_000
  let lastOrchestratorEventAt = Date.now()
  let ensembleStuckTimer: ReturnType<typeof setInterval> | null = null
  // 1.0.5-EW13 — Capture Gemini's last few stderr lines so the
  // stuck-process timeout message can include the actual error
  // text. Pre-EW13 the user had to dig through the Inspector's raw
  // events panel to see what Gemini was complaining about; now the
  // tail is included inline in the kill notice.
  const ensembleStderrTail: string[] = []
  const ENSEMBLE_STDERR_TAIL_MAX = 6
  const feedOrchestrator = payload.ensembleRun
    ? (chunk: string): void => {
        ensembleLineBuffer += chunk
        const lines = ensembleLineBuffer.split('\n')
        ensembleLineBuffer = lines.pop() || ''
        for (const line of lines) {
          const trimmed = line.trim()
          if (!trimmed.startsWith('{')) continue
          try {
            const parsed = JSON.parse(trimmed)
            ensembleOrchestratorRef?.handleProviderOutput('gemini', route, parsed)
            lastOrchestratorEventAt = Date.now()
          } catch {
            // Not parseable JSON (e.g. a stray log line) — skip silently;
            // the orchestrator only needs the structured events.
          }
        }
      }
    : null
  const geminiStdoutSanitizer = createCanvasEvalJsonLineSanitizer(
    `gemini:${route.appRunId || route.appChatId || 'unrouted'}`
  )
  const geminiStderrSanitizer = createCanvasEvalJsonLineSanitizer(
    `gemini:${route.appRunId || route.appChatId || 'unrouted'}:stderr`
  )
  const emitGeminiStdout = (text: string): void => {
    if (!text) return
    appendDurableRunEventForRoute(
      'gemini',
      route,
      'provider_raw',
      'raw',
      'Gemini stdout',
      { data: text },
      'provider'
    )
    publishRunEvent(
      'gemini-output',
      'gemini',
      { provider: 'gemini', data: text, ...route },
      event.sender
    )
    feedOrchestrator?.(text)
    // Phase I3.x — detect-and-redirect heuristic. If Gemini emits an
    // invoke_agent tool_call when the user asked for cross-provider
    // delegation, surface a single non-blocking warning chip so the
    // user understands the call didn't reach TaskWraith's MCP bridge.
    maybeEmitGeminiCrossProviderWarning(event.sender, route, payload.prompt, text)
  }
  const emitGeminiStderr = (text: string): void => {
    if (!text) return
    const error = sanitizeCanvasEvalProviderText(text)
    if (payload.ensembleRun) {
      const trimmed = error.trim()
      if (trimmed) {
        ensembleStderrTail.push(trimmed)
        while (ensembleStderrTail.length > ENSEMBLE_STDERR_TAIL_MAX) {
          ensembleStderrTail.shift()
        }
      }
    }
    appendDurableRunEventForRoute(
      'gemini',
      route,
      'provider_error',
      'raw',
      'Gemini stderr',
      { error },
      'provider'
    )
    publishRunEvent('gemini-error', 'gemini', { provider: 'gemini', error, ...route }, event.sender)
  }
  // Audit role-runs (payload.auditRun) get the same stuck-process killer as
  // ensemble runs: a Gemini run can emit init then sit forever without exiting,
  // which would otherwise never settle the AuditRunTracker and hang the audit.
  if (payload.ensembleRun || payload.auditRun) {
    ensembleStuckTimer = setInterval(() => {
      const idleMs = Date.now() - lastOrchestratorEventAt
      if (idleMs < GEMINI_STUCK_IDLE_MS) return
      // 1.0.5-EW13 — Include the captured stderr tail in the
      // timeout notice so the user sees Gemini's actual complaint
      // (workspace path missing, auth failed, etc.) inline rather
      // than having to dig through the Inspector.
      const stderrTail = ensembleStderrTail.join('\n').trim()
      const seconds = Math.round(idleMs / 1000)
      const baseMessage =
        `Gemini stopped emitting events ${seconds} seconds ago. ` +
        'The CLI is still alive but unresponsive (often a workspace / cwd error ' +
        'in global ensemble chats). Terminating so the ensemble round can continue.'
      const fullMessage = stderrTail
        ? `${baseMessage}\n\nLast stderr output:\n${stderrTail}`
        : baseMessage
      appendDurableRunEventForRoute(
        'gemini',
        route,
        'provider_error',
        'raw',
        `Gemini stuck — no events for ${seconds}s, terminating`,
        { error: fullMessage },
        'provider'
      )
      publishRunEvent(
        'gemini-error',
        'gemini',
        {
          provider: 'gemini',
          error: fullMessage,
          ...route
        },
        event.sender
      )
      try {
        child.kill('SIGTERM')
      } catch {
        // Kill can fail if the process already died on its own;
        // the close handler will run either way.
      }
    }, GEMINI_STUCK_POLL_MS)
  }

  child.stdout?.on('data', (data) => {
    emitGeminiStdout(geminiStdoutSanitizer.push(data.toString()))
  })

  child.stderr?.on('data', (data) => {
    // Count raw stderr as liveness immediately, but do not persist or
    // forward it until the line sanitizer has ruled out canvas_eval data.
    if (payload.ensembleRun) {
      // 1.0.5-EW15 — Treat stderr as a "still alive" heartbeat.
      // EW12's idle-time detector only watched stdout JSON events,
      // so a Gemini turn that's slowly emitting progress on stderr
      // (e.g. "Falling back to GrepTool", workspace scan logs)
      // would trip the 180s kill even though the process is making
      // forward progress. Resetting the idle timer on any stderr
      // byte means the kill only fires during TRUE silence — no
      // stdout AND no stderr for the full window.
      lastOrchestratorEventAt = Date.now()
    }
    emitGeminiStderr(geminiStderrSanitizer.push(data.toString()))
  })

  child.on('close', (code) => {
    emitGeminiStdout(geminiStdoutSanitizer.flush())
    emitGeminiStderr(geminiStderrSanitizer.flush())
    // 1.0.5-EW7 / EW12 — Clear the stuck-process safety timer; we
    // no longer need it once the process actually closes. EW12
    // switched setTimeout → setInterval so use clearInterval.
    if (ensembleStuckTimer) {
      clearInterval(ensembleStuckTimer)
      ensembleStuckTimer = null
    }
    // Drain any partial-line tail through the ensemble bridge before
    // we tear down — guards against a final JSON event that lacks a
    // trailing newline (rare, but the renderer's adapter handles the
    // same case via its `end()` method).
    if (feedOrchestrator && ensembleLineBuffer.trim()) {
      feedOrchestrator('\n')
    }
    appendDurableRunEventForRoute(
      'gemini',
      route,
      'provider_exit',
      'raw',
      `Gemini exited with code ${typeof code === 'number' ? code : 'unknown'}`,
      { code },
      'provider'
    )
    // 1.0.5-EW6 — Mark the run exited on the ensemble orchestrator
    // so an ensemble Gemini participant gets finalised. Pre-EW6 the
    // legacy Gemini PTY/CLI path only called runManager.finish, not
    // the orchestrator's markRunExited — the per-participant
    // completion promise (set up in EnsembleOrchestrator.runRound)
    // never resolved, and the round stalled on "Thinking…"
    // indefinitely until cancelled. The agent-compat exit helper
    // (sendAgentCompatExit, ~line 7929) does this correctly for
    // every other provider; legacy Gemini PTY was the only path
    // missing the call.
    ensembleOrchestratorRef?.markRunExited(route.appRunId, typeof code === 'number' ? code : -1)
    // Audit completion bridge — the Gemini one-shot path finalises here rather
    // than through sendAgentCompatExit, so settle a tracked audit role-run on
    // this exit too (no-op for non-audit runs). v1: Gemini audit role-runs
    // settle on exit (ok/fail + duration); token/cost stats are NOT scraped
    // from the Gemini stream here — a v1 cut, the audit still completes and the
    // structured findings/verdicts flow via the artifact collector.
    auditRunTracker.handleExit(route.appRunId, typeof code === 'number' ? code : -1)
    publishRunEvent('gemini-exit', 'gemini', { provider: 'gemini', code, ...route }, event.sender)
    if (geminiProcess === child) {
      geminiProcess = null
    }
    runManager.finish(route.appRunId, code === 0 ? 'completed' : 'failed')
    if (route.appRunId) geminiCrossProviderWarningsFired.delete(route.appRunId)
    if (!geminiSessionProcess) {
      const latestGemini = getSingleActiveProviderSession('gemini')?.state as
        | GeminiToolContext
        | undefined
      activeGeminiToolContext = latestGemini?.sender ? latestGemini : null
    }
  })

  child.on('error', (err) => {
    emitGeminiStdout(geminiStdoutSanitizer.flush())
    emitGeminiStderr(geminiStderrSanitizer.flush())
    // 1.0.5-EW7 / EW12 — Clear the stuck-process safety timer;
    // nothing to monitor once the spawn itself failed.
    if (ensembleStuckTimer) {
      clearInterval(ensembleStuckTimer)
      ensembleStuckTimer = null
    }
    const error = `Failed to start process: ${err.message}`
    appendDurableRunEventForRoute(
      'gemini',
      route,
      'provider_error',
      'raw',
      'Gemini process failed to start',
      { error },
      'provider'
    )
    publishRunEvent('gemini-error', 'gemini', { provider: 'gemini', error, ...route }, event.sender)
    appendDurableRunEventForRoute(
      'gemini',
      route,
      'provider_exit',
      'raw',
      'Gemini process failed before exit',
      { code: -1 },
      'provider'
    )
    // 1.0.5-EW6 — Same orchestrator finalisation as the close
    // handler above. Spawn failures are the worst case for a
    // hang because the process never even produced output, so
    // feedOrchestrator never ran and there's no fallback signal.
    ensembleOrchestratorRef?.markRunExited(route.appRunId, -1)
    // Audit completion bridge — settle a tracked audit role-run whose Gemini
    // process failed before exit (no-op for non-audit runs).
    auditRunTracker.handleExit(route.appRunId, -1)
    publishRunEvent(
      'gemini-exit',
      'gemini',
      { provider: 'gemini', code: -1, ...route },
      event.sender
    )
    if (geminiProcess === child) {
      geminiProcess = null
    }
    runManager.finish(route.appRunId, 'failed')
    if (route.appRunId) geminiCrossProviderWarningsFired.delete(route.appRunId)
    if (!geminiSessionProcess) {
      const latestGemini = getSingleActiveProviderSession('gemini')?.state as
        | GeminiToolContext
        | undefined
      activeGeminiToolContext = latestGemini?.sender ? latestGemini : null
    }
  })
}

// Grok is a first-class provider — its adapter is always registered.
