async function verifyProductAuditBundle(
  request: ProductAuditBundleVerificationRequest = {}
): Promise<ProductAuditBundleVerificationResult> {
  let targetPath = request.path
  const recordVerification = (
    result: ProductAuditBundleVerificationResult
  ): ProductAuditBundleVerificationResult => {
    try {
      AppStore.recordAuditBundleVerificationReceipt(
        createAuditBundleVerificationReceipt(result, {
          id: `audit-bundle-verification-${Date.now()}-${randomUUID()}`,
          verifiedAt: new Date().toISOString()
        })
      )
    } catch (error) {
      console.warn('Failed to record audit bundle verification receipt', error)
    }
    return result
  }
  try {
    if (!targetPath) {
      if (!mainWindow) {
        throw new Error('No application window is available for audit bundle verification.')
      }
      const result = await dialog.showOpenDialog(mainWindow, {
        title: 'Verify TaskWraith Audit Bundle',
        properties: ['openFile'],
        filters: [{ name: 'JSON audit bundle', extensions: ['json'] }]
      })
      if (result.canceled || !result.filePaths?.[0]) {
        return { ok: false, error: 'Audit bundle verification cancelled.' }
      }
      targetPath = result.filePaths[0]
    }
    const raw = (
      await readBoundedRegularFile(targetPath, {
        maxBytes: PRODUCT_AUDIT_BUNDLE_MAX_VERIFY_BYTES,
        regularFileErrorMessage: 'Audit bundle verification requires a regular file.',
        sizeLimitErrorMessage: `Audit bundle exceeds the ${PRODUCT_AUDIT_BUNDLE_MAX_VERIFY_BYTES}-byte verification limit.`
      })
    ).toString('utf8')
    const snapshot = JSON.parse(raw) as ProductAuditBundleSnapshot
    const verification = verifyAuditBundleSnapshotSignature(snapshot)
    return recordVerification({
      ok: verification.ok,
      path: targetPath,
      verification,
      manifest: {
        generatedAt: snapshot.manifest.generatedAt,
        redactionMode: snapshot.manifest.redactionMode,
        filters: snapshot.manifest.filters,
        tamperEvidence: snapshot.manifest.validation.tamperEvidence
      }
    })
  } catch (error) {
    recordProductCrash({
      source: 'main',
      severity: 'warning',
      name: error instanceof Error ? error.name : 'AuditBundleVerificationError',
      message: error instanceof Error ? error.message : String(error),
      stack: error instanceof Error ? error.stack : undefined
    })
    return recordVerification({
      ok: false,
      ...(targetPath ? { path: targetPath } : {}),
      error: error instanceof Error ? error.message : String(error)
    })
  }
}

async function repairProductInstall(): Promise<ProductOperationsStatus> {
  await fs.mkdir(app.getPath('userData'), { recursive: true })
  const settings = AppStore.getSettings()
  if (settings.geminiMcpBridgeEnabled) {
    try {
      await installGeminiMcpBridge()
    } catch (error) {
      recordProductCrash({
        source: 'bridge',
        severity: 'warning',
        name: error instanceof Error ? error.name : 'GeminiBridgeRepairError',
        message: error instanceof Error ? error.message : String(error),
        stack: error instanceof Error ? error.stack : undefined
      })
    }
  }
  return getProductOperationsStatus()
}

async function resolveCapabilityWorkspace(workspace?: string): Promise<string | undefined> {
  if (typeof workspace !== 'string' || !workspace.trim()) {
    return undefined
  }

  const workspaceRoot = resolve(workspace)
  const workspaceStat = await fs.stat(workspaceRoot)
  if (!workspaceStat.isDirectory()) {
    throw new Error('Workspace path is not a directory.')
  }
  return workspaceRoot
}

async function readGeminiCapabilitySection(
  kind: GeminiCapabilityKind,
  cwd?: string
): Promise<GeminiCapabilitySection> {
  const baseCommand = [...GEMINI_CAPABILITY_COMMANDS[kind]]
  const jsonResult = await runGeminiCapabilityCommand([...baseCommand, '--json'], cwd)

  if (jsonResult.exitCode === 0 && jsonResult.stdout.trim()) {
    try {
      const parsed = JSON.parse(stripAnsi(jsonResult.stdout))
      return {
        kind,
        command: ['gemini', ...jsonResult.args],
        format: 'json',
        items: parseCapabilityJsonItems(parsed, kind),
        stdout: jsonResult.stdout,
        stderr: jsonResult.stderr,
        status: jsonResult.exitCode,
        timedOut: jsonResult.timedOut,
        error: jsonResult.error,
        truncated: jsonResult.truncated
      }
    } catch (error) {
      const rawResult = await runGeminiCapabilityCommand(baseCommand, cwd)
      return {
        kind,
        command: ['gemini', ...rawResult.args],
        format: rawResult.error || rawResult.timedOut ? 'error' : 'raw',
        items: rawResult.exitCode === 0 ? parseCapabilityRawItems(rawResult.stdout, kind) : [],
        stdout: rawResult.stdout,
        stderr: rawResult.stderr,
        status: rawResult.exitCode,
        timedOut: rawResult.timedOut,
        error: rawResult.error,
        parsingError: error instanceof Error ? error.message : String(error),
        truncated: rawResult.truncated
      }
    }
  }

  const rawResult = await runGeminiCapabilityCommand(baseCommand, cwd)
  return {
    kind,
    command: ['gemini', ...rawResult.args],
    format: rawResult.error || rawResult.timedOut ? 'error' : 'raw',
    items: rawResult.exitCode === 0 ? parseCapabilityRawItems(rawResult.stdout, kind) : [],
    stdout: rawResult.stdout,
    stderr: rawResult.stderr,
    status: rawResult.exitCode,
    timedOut: rawResult.timedOut,
    error: rawResult.error,
    truncated: rawResult.truncated
  }
}

