        if (!value) return {}
        const runAtMs = new Date(value).getTime()
        if (!Number.isFinite(runAtMs)) return { reason: 'Scheduled run time is invalid.' }
        if (runAtMs <= Date.now()) return { reason: 'Choose a future time for scheduled runs.' }
